def xeleria_tenant_dependency(request: Request):
    """Setea tenant por request para todas las llamadas sb.table(...) del ERP heredado.

    Prioridad:
    1) sesión temporal XelerIA, si viene x-session-token / Authorization Bearer xses_
    2) header x-xeleria-tenant / query tenant_id
    3) DEFAULT_TENANT_ID para compatibilidad legacy

    Importante: no exige sesión acá, porque /admin/health, /tenant/bootstrap y rutas
    legacy siguen teniendo su propia validación. La sesión se valida fuerte en
    require_session() dentro de cada endpoint sensible.
    """
    session_row = None
    try:
        if request is not None:
            # session_from_request se define más abajo, pero Python resuelve el nombre al ejecutar.
            session_row = session_from_request(request, required=False)
            if session_row is not None:
                try:
                    request.state.xeleria_session = dict(session_row)
                except Exception:
                    pass
    except Exception:
        session_row = None

    tenant_id = str(
        (session_row or {}).get("tenant_id")
        or tenant_id_from_request(request)
        or get_effective_tenant_id()
        or DEFAULT_TENANT_ID
    )
    ctx_token = set_current_tenant_id(tenant_id)
    try:
        yield tenant_id
    finally:
        reset_current_tenant_id(ctx_token)


router = APIRouter(dependencies=[Depends(xeleria_tenant_dependency)])

