def oauth_ml_prepare_options(request: Request):
    # Preflight explícito: evita que el navegador transforme un problema de endpoint en "Failed to fetch".
    return JSONResponse({"ok": True, "preflight": "oauth_ml_prepare", "version": APP_VERSION}, headers=_cors_headers_for_request(request))


@router.post("/oauth/ml/prepare")
async def oauth_ml_prepare(request: Request):
    # Endpoint deliberadamente manual:
    # - acepta JSON aunque el frontend mande text/plain para evitar preflight
    # - siempre intenta devolver JSON con CORS para ver el error real
    try:
        try:
            raw = await request.body()
            data = json.loads(raw.decode("utf-8") if isinstance(raw, (bytes, bytearray)) else str(raw or "{}"))
        except Exception:
            data = await request.json()
        payload = OAuthPrepareIn(**(data or {}))
        tenant_id = str(payload.tenant_id or "").strip()

        if not ML_CLIENT_ID:
            return JSONResponse(
                status_code=500,
                content={"ok": False, "error": "ml_client_id_missing", "detail": "ML_CLIENT_ID/ML_APP_ID no configurado", "version": APP_VERSION},
                headers=_cors_headers_for_request(request),
            )
        if not ML_CLIENT_SECRET:
            return JSONResponse(
                status_code=500,
                content={"ok": False, "error": "ml_client_secret_missing", "detail": "ML_CLIENT_SECRET/ML_APP_SECRET no configurado", "version": APP_VERSION},
                headers=_cors_headers_for_request(request),
            )

        _assert_oauth_session(tenant_id, payload.session_token)
        state = _create_oauth_state(tenant_id=tenant_id, channel="ml", next_path=payload.next or "admin_erp.html")
        url = "https://auth.mercadolibre.com.ar/authorization?" + urlencode({
            "response_type": "code",
            "client_id": ML_CLIENT_ID,
            "redirect_uri": ML_REDIRECT_URI,
            "state": state,
        })
        return JSONResponse({"ok": True, "authorization_url": url, "version": APP_VERSION}, headers=_cors_headers_for_request(request))

    except HTTPException as exc:
        return JSONResponse(
            status_code=exc.status_code,
            content={"ok": False, "error": "http_exception", "detail": exc.detail, "version": APP_VERSION},
            headers=_cors_headers_for_request(request),
        )
    except Exception as exc:
        return JSONResponse(
            status_code=500,
            content={"ok": False, "error": "internal_exception", "type": exc.__class__.__name__, "detail": str(exc), "version": APP_VERSION},
            headers=_cors_headers_for_request(request),
        )


