@router.get("/oauth/tn/callback")
def oauth_tn_callback(
    code: Optional[str] = Query(default=None),
    state: Optional[str] = Query(default=None),
    error: Optional[str] = Query(default=None),
    error_description: Optional[str] = Query(default=None),
):
    if error:
        return RedirectResponse(_frontend_url("admin_erp.html", {"oauth": "tn", "status": "error", "error": error_description or error}))
    if not code:
        raise HTTPException(status_code=400, detail="TN callback sin code")
    if not TN_CLIENT_ID or not TN_CLIENT_SECRET:
        raise HTTPException(status_code=500, detail="TN_CLIENT_ID/TN_CLIENT_SECRET no configurados")

    state_row = _consume_oauth_state(state or "", "tn")
    tenant_id = str(state_row.get("tenant_id") or "").strip()
    next_path = str(state_row.get("next_path") or "admin_erp.html")
    state_metadata = _dict_value(state_row.get("metadata"))
    login_mode = state_metadata.get("mode") == "channel_login"

    token_payload = {
        "client_id": TN_CLIENT_ID,
        "client_secret": TN_CLIENT_SECRET,
        "grant_type": "authorization_code",
        "code": code,
        "redirect_uri": TN_REDIRECT_URI,
    }
    try:
        r = requests.post(
            "https://www.tiendanube.com/apps/authorize/token",
            json=token_payload,
            headers={"Accept": "application/json", "Content-Type": "application/json"},
            timeout=45,
        )
    except Exception as exc:
        raise HTTPException(status_code=502, detail=f"Error conectando OAuth TN: {exc}") from exc

    try:
        body = r.json()
    except Exception:
        body = {"raw": r.text[:2000]}

    if r.status_code not in (200, 201):
        raise HTTPException(status_code=502, detail={"message": "TN token exchange falló", "status_code": r.status_code, "response": body})

    access_token = body.get("access_token")
    store_id = str(body.get("user_id") or "").strip()
    if not access_token:
        raise HTTPException(status_code=502, detail={"message": "TN no devolvió access_token", "response": body})
    if not store_id:
        raise HTTPException(status_code=502, detail={"message": "TN no devolvió user_id/store_id", "response": body})

    store_body: Dict[str, Any] = {}
    label = f"TN #{store_id}"
    try:
        store = requests.get(
            f"https://api.tiendanube.com/v1/{store_id}/store",
            headers={
                "Authentication": f"bearer {access_token}",
                "User-Agent": "XelerIA (soporte@xeleria.com.ar)",
            },
            timeout=30,
        )
        if store.status_code == 200:
            parsed = store.json()
            if isinstance(parsed, dict):
                store_body = parsed
                label = _tn_label_from_payload(store_body) or label
    except Exception:
        pass

    resolved = {"tenant_id": tenant_id, "created": False}
    if login_mode:
        resolved = _resolve_or_create_oauth_tenant(
            "tn", store_id, label, state_metadata, next_path
        )
        tenant_id = resolved["tenant_id"]

    _save_oauth_token(
        tenant_id=tenant_id,
        provider_key=f"tn:{tenant_id}",
        access_token=access_token,
        refresh_token=body.get("refresh_token"),
        expires_in=body.get("expires_in"),
        label=label,
    )
    _update_tn_oauth_settings(tenant_id=tenant_id, store_id=store_id, token_body=body, store_body=store_body)

    _persist_oauth_external_identity(tenant_id, "tn", store_id)
    if login_mode:
        _complete_oauth_login_state(state_row, tenant_id, store_id, bool(resolved.get("created")))
        return RedirectResponse(_frontend_url("inicio.html", {
            "oauth": "tn",
            "status": "identified",
            "login_state": state,
            "next": next_path,
        }))

    return RedirectResponse(_frontend_url(next_path, {"oauth": "tn", "status": "connected"}))


