# ============================================================
# HELPERS
# ============================================================

def now_iso() -> str:
    return datetime.now(timezone.utc).isoformat()


def norm_sku(s: str) -> str:
    return (s or "").strip()


def normalizar(txt: Any) -> str:
    txt = str(txt or "").lower()
    for a, b in {
        "á": "a", "é": "e", "í": "i", "ó": "o", "ú": "u", "ü": "u"
    }.items():
        txt = txt.replace(a, b)
    txt = re.sub(r"[^a-z0-9ñ_ -]", " ", txt)
    txt = re.sub(r"\s+", " ", txt).strip()
    return txt


def _clean_admin_token(value: Optional[str]) -> str:
    raw = str(value or "").strip()
    if raw.lower().startswith("bearer "):
        return raw[7:].strip()
    return raw


def require_admin(
    token: Optional[str] = Query(default=None),
    x_admin_token: Optional[str] = Header(default=None),
    authorization: Optional[str] = Header(default=None),
):
    supplied = _clean_admin_token(token) or _clean_admin_token(x_admin_token) or _clean_admin_token(authorization)
    if not ADMIN_TOKEN:
        raise HTTPException(status_code=500, detail="ADMIN_TOKEN no configurado")
    if supplied != ADMIN_TOKEN:
        raise HTTPException(status_code=401, detail="Token admin inválido")
    if not sb:
        raise HTTPException(status_code=500, detail="DATABASE_URL/AWS Postgres no configurado")


def _utcnow() -> datetime:
    return datetime.now(timezone.utc)


def _dt_from_db(value: Any) -> Optional[datetime]:
    if not value:
        return None
    try:
        txt = str(value).replace("Z", "+00:00")
        dt = datetime.fromisoformat(txt)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        return dt.astimezone(timezone.utc)
    except Exception:
        return None



# Cache local y retry corto para evitar que un fallo transitorio de AWS Postgres
# tumbe autocompletes o pantallas mientras el usuario escribe.
_SESSION_CACHE: Dict[str, Dict[str, Any]] = {}
_SESSION_CACHE_LOCK = threading.Lock()


def _transient_error_text(exc: Exception) -> str:
    try:
        return str(exc or "")
    except Exception:
        return ""


def _is_transient_backend_error(exc: Exception) -> bool:
    name = exc.__class__.__name__
    raw = _transient_error_text(exc)
    return (
        name in {"ReadError", "ConnectError", "TimeoutException", "ConnectTimeout", "ReadTimeout", "PoolTimeout"}
        or "[Errno 11]" in raw
        or "Resource temporarily unavailable" in raw
        or "Connection reset by peer" in raw
        or "temporarily unavailable" in raw.lower()
    )


def _execute_database_query(builder, *, context: str = "database", attempts: Optional[int] = None):
    tries = max(1, int(attempts or XELERIA_DB_RETRY_ATTEMPTS or 1))
    last_exc = None
    for idx in range(tries):
        try:
            return builder.execute()
        except HTTPException:
            raise
        except Exception as exc:
            last_exc = exc
            if not _is_transient_backend_error(exc) or idx >= tries - 1:
                raise
            time.sleep(float(XELERIA_DB_RETRY_BASE_SLEEP or 0.20) * (2 ** idx))
    raise last_exc


def _session_cache_get(token_hash: str) -> Optional[Dict[str, Any]]:
    if not token_hash or int(XELERIA_SESSION_CACHE_SECONDS or 0) <= 0:
        return None

    now_mono = time.monotonic()
    with _SESSION_CACHE_LOCK:
        cached = _SESSION_CACHE.get(token_hash)
        if not cached:
            return None
        if float(cached.get("valid_until_mono") or 0) <= now_mono:
            _SESSION_CACHE.pop(token_hash, None)
            return None
        row = dict(cached.get("row") or {})

    now = _utcnow()
    expires_at = _dt_from_db(row.get("expires_at"))
    absolute_expires_at = _dt_from_db(row.get("absolute_expires_at"))
    if (expires_at and expires_at <= now) or (absolute_expires_at and absolute_expires_at <= now):
        _session_cache_drop(token_hash)
        return None

    return row


def _session_cache_set(token_hash: str, row: Dict[str, Any]) -> None:
    if not token_hash or not row or int(XELERIA_SESSION_CACHE_SECONDS or 0) <= 0:
        return

    now_mono = time.monotonic()
    ttl = max(5, int(XELERIA_SESSION_CACHE_SECONDS or 45))
    with _SESSION_CACHE_LOCK:
        # Limpieza simple para evitar crecimiento eterno si hay muchos tokens.
        if len(_SESSION_CACHE) > 500:
            expired = [k for k, v in _SESSION_CACHE.items() if float(v.get("valid_until_mono") or 0) <= now_mono]
            for k in expired[:250]:
                _SESSION_CACHE.pop(k, None)
        _SESSION_CACHE[token_hash] = {
            "valid_until_mono": now_mono + ttl,
            "row": dict(row),
        }


def _session_cache_drop(token_hash: str) -> None:
    if not token_hash:
        return
    with _SESSION_CACHE_LOCK:
        _SESSION_CACHE.pop(token_hash, None)


def _sha256_text(value: str) -> str:
    return hashlib.sha256(str(value or "").encode("utf-8")).hexdigest()


def _new_session_token() -> str:
    return "xses_" + secrets.token_urlsafe(36)


def _session_hash(token: str) -> str:
    return _sha256_text("xeleria-session:" + str(token or ""))


def _clean_session_token(value: Optional[str]) -> str:
    return _clean_admin_token(value)


def _request_ip(request: Request) -> Optional[str]:
    try:
        xff = request.headers.get("x-forwarded-for") or ""
        if xff:
            return xff.split(",")[0].strip()[:64]
        return (request.client.host if request.client else None)
    except Exception:
        return None


def _safe_slug(prefix: str = "tenant") -> str:
    return (prefix.strip().lower() or "tenant") + "-" + secrets.token_hex(5)


def _validate_beta_access_code(beta_access_code: str) -> Dict[str, Any]:
    clean = str(beta_access_code or "").strip()
    if not clean:
        raise HTTPException(status_code=401, detail="Código beta requerido")

    supplied_hash = _sha256_text(clean)

    if XELERIA_BETA_ACCESS_CODE_HASH:
        if not hmac.compare_digest(supplied_hash, XELERIA_BETA_ACCESS_CODE_HASH):
            raise HTTPException(status_code=401, detail="Código beta inválido")
        return {"ok": True, "beta_access_code_hash": supplied_hash, "mode": "hash"}

    if XELERIA_BETA_ACCESS_CODE:
        if not hmac.compare_digest(clean, XELERIA_BETA_ACCESS_CODE):
            raise HTTPException(status_code=401, detail="Código beta inválido")
        return {"ok": True, "beta_access_code_hash": supplied_hash, "mode": "env"}

    if XELERIA_BOOTSTRAP_OPEN:
        # Sólo para laboratorio/onboarding controlado. No usar en producción pública.
        return {"ok": True, "beta_access_code_hash": supplied_hash, "mode": "open_dev"}

    raise HTTPException(
        status_code=500,
        detail="Bootstrap cerrado: falta XELERIA_BETA_ACCESS_CODE o XELERIA_BETA_ACCESS_CODE_HASH",
    )


def _create_session_for_tenant(tenant_id: str, request: Request, user_id: Optional[str] = None) -> Dict[str, Any]:
    if not _sb_raw:
        raise HTTPException(status_code=500, detail="DATABASE_URL/AWS Postgres no configurado")

    token_plain = _new_session_token()
    now = _utcnow()
    idle_seconds = max(60, int(XELERIA_SESSION_IDLE_SECONDS or 3600))
    absolute_seconds = max(idle_seconds, int(XELERIA_SESSION_ABSOLUTE_SECONDS or 43200))
    expires_at = now + timedelta(seconds=idle_seconds)
    absolute_expires_at = now + timedelta(seconds=absolute_seconds)

    row = {
        "tenant_id": tenant_id,
        "user_id": user_id,
        "token_hash": _session_hash(token_plain),
        "status": "active",
        "connection_snapshot": initial_connection_snapshot(tenant_id, now.isoformat(), APP_VERSION),
        "created_at": now.isoformat(),
        "last_seen_at": now.isoformat(),
        "expires_at": expires_at.isoformat(),
        "absolute_expires_at": absolute_expires_at.isoformat(),
        "idle_timeout_seconds": idle_seconds,
        "user_agent": (request.headers.get("user-agent") or "")[:500],
        "ip": _request_ip(request),
    }
    try:
        inserted = _sb_raw.table("tenant_sessions").insert(row).execute().data or []
    except Exception as exc:
        raise HTTPException(status_code=500, detail=f"No pude crear sesión. ¿Está aplicada la migración tenant_sessions? {exc}") from exc

    session_row = inserted[0] if inserted else row
    return {
        "token": token_plain,
        "tenant_id": tenant_id,
        "expires_at": session_row.get("expires_at") or expires_at.isoformat(),
        "absolute_expires_at": session_row.get("absolute_expires_at") or absolute_expires_at.isoformat(),
        "idle_timeout_seconds": idle_seconds,
    }


def session_from_request(
    request: Request,
    session_token: Optional[str] = None,
    x_session_token: Optional[str] = None,
    authorization: Optional[str] = None,
    required: bool = True,
) -> Optional[Dict[str, Any]]:
    if not _sb_raw:
        if required:
            raise HTTPException(status_code=500, detail="DATABASE_URL/AWS Postgres no configurado")
        return None

    supplied = (
        _clean_session_token(session_token)
        or _clean_session_token(x_session_token)
        or _clean_session_token(authorization)
        or _clean_session_token(request.headers.get("x-session-token"))
        or _clean_session_token(request.headers.get("authorization"))
    )
    if not supplied:
        if required:
            raise HTTPException(status_code=401, detail="Sesión requerida")
        return None

    try:
        request_cached = getattr(request.state, "xeleria_session", None)
        if request_cached and str(request_cached.get("token_plain") or "") == supplied:
            return dict(request_cached)
    except Exception:
        pass

    token_hash = _session_hash(supplied)
    cached = _session_cache_get(token_hash)
    if cached:
        cached["token_plain"] = supplied
        return cached

    try:
        rows = (
            _execute_database_query(
                _sb_raw.table("tenant_sessions")
                .select("*")
                .eq("token_hash", token_hash)
                .is_("revoked_at", "null")
                .limit(1),
                context="tenant_sessions.select",
            )
            .data
            or []
        )
    except Exception as exc:
        if _is_transient_backend_error(exc):
            if required:
                raise HTTPException(status_code=503, detail="AWS Postgres temporalmente no disponible validando sesión") from exc
            return None
        raise

    if not rows:
        _session_cache_drop(token_hash)
        if required:
            raise HTTPException(status_code=401, detail="Sesión inválida o expirada")
        return None

    row = rows[0]
    now = _utcnow()
    expires_at = _dt_from_db(row.get("expires_at"))
    absolute_expires_at = _dt_from_db(row.get("absolute_expires_at"))
    if (expires_at and expires_at <= now) or (absolute_expires_at and absolute_expires_at <= now):
        _session_cache_drop(token_hash)
        try:
            _execute_database_query(
                _sb_raw.table("tenant_sessions")
                .update({"status": "expired", "revoked_at": now.isoformat()})
                .eq("id", row.get("id")),
                context="tenant_sessions.expire",
                attempts=1,
            )
        except Exception:
            pass
        if required:
            raise HTTPException(status_code=401, detail="Sesión expirada")
        return None

    idle_seconds = max(60, int(row.get("idle_timeout_seconds") or XELERIA_SESSION_IDLE_SECONDS or 3600))
    next_expires = now + timedelta(seconds=idle_seconds)
    if absolute_expires_at and next_expires > absolute_expires_at:
        next_expires = absolute_expires_at

    try:
        _execute_database_query(
            _sb_raw.table("tenant_sessions").update({
                "last_seen_at": now.isoformat(),
                "expires_at": next_expires.isoformat(),
                "updated_at": now.isoformat(),
            }).eq("id", row.get("id")),
            context="tenant_sessions.touch",
            attempts=2,
        )
    except Exception:
        # Best-effort: no rompemos la request si sólo falló refrescar last_seen/expires_at.
        pass

    row["token_plain"] = supplied
    row["expires_at"] = next_expires.isoformat()
    _session_cache_set(token_hash, row)
    return row


def require_session(
    request: Request,
    session_token: Optional[str] = None,
    x_session_token: Optional[str] = None,
    authorization: Optional[str] = None,
) -> Dict[str, Any]:
    row = session_from_request(request, session_token, x_session_token, authorization, required=True)
    tenant_id = str(row.get("tenant_id") or DEFAULT_TENANT_ID)
    set_current_tenant_id(tenant_id)
    return row


def q_inventory_base():
    return """
        id,
        sku,
        name,
        variant_name,
        category,
        stock,
        active,
        item_type,
        cost,
        updated_at
    """


def get_item_by_sku(sku: str) -> Optional[Dict[str, Any]]:
    sku = norm_sku(sku)
    tenant_id = str(get_effective_tenant_id() or DEFAULT_TENANT_ID)
    data = (
        sb.table("inventory_items")
        .select(q_inventory_base())
        .eq("sku", sku)
        .eq("tenant_id", tenant_id)
        .limit(1)
        .execute()
        .data
        or []
    )
    return data[0] if data else None


def get_item_by_id(item_id: int) -> Optional[Dict[str, Any]]:
    data = (
        sb.table("inventory_items")
        .select(q_inventory_base())
        .eq("id", item_id)
        .limit(1)
        .execute()
        .data
        or []
    )
    return data[0] if data else None


def get_bundle_components_by_bundle_id(bundle_item_id: int) -> List[Dict[str, Any]]:
    rows = (
        sb.table("bundle_components")
        .select("id,bundle_item_id,component_item_id,quantity,created_at")
        .eq("bundle_item_id", bundle_item_id)
        .order("id")
        .execute()
        .data
        or []
    )

    if not rows:
        return []

    comp_ids = [r["component_item_id"] for r in rows]
    comps = (
        sb.table("inventory_items")
        .select(q_inventory_base())
        .in_("id", comp_ids)
        .execute()
        .data
        or []
    )
    comp_by_id = {c["id"]: c for c in comps}

    out = []
    for r in rows:
        comp = comp_by_id.get(r["component_item_id"])
        out.append({
            **r,
            "component": comp,
            "component_sku": comp.get("sku") if comp else None,
            "component_name": comp.get("name") if comp else None,
            "component_stock": comp.get("stock") if comp else None,
        })
    return out


def get_bundle_components_by_sku(bundle_sku: str) -> Dict[str, Any]:
    bundle = get_item_by_sku(bundle_sku)
    if not bundle:
        raise HTTPException(status_code=404, detail=f"No existe el SKU combo: {bundle_sku}")

    components = get_bundle_components_by_bundle_id(bundle["id"])
    return {
        "bundle": bundle,
        "components": components,
        "is_bundle": len(components) > 0,
        "available_to_sell": calc_bundle_available_from_components(components),
    }


def calc_bundle_available_from_components(components: List[Dict[str, Any]]) -> Optional[int]:
    if not components:
        return None

    posibles = []
    for row in components:
        comp = row.get("component") or {}
        stock = comp.get("stock")
        qty = float(row.get("quantity") or 0)
        if stock is None or qty <= 0:
            return 0
        posibles.append(int(float(stock) // qty))

    return min(posibles) if posibles else None


def mark_as_bundle_if_needed(item_id: int):
    # Conservador: solo escribe item_type='bundle' si está vacío, single o product.
    item = get_item_by_id(item_id)
    current = normalizar(item.get("item_type")) if item else ""
    if current in ["", "single", "product", "producto", "productos"]:
        sb.table("inventory_items").update({
            "item_type": "bundle",
            "updated_at": now_iso(),
        }).eq("id", item_id).execute()



def inventory_item_is_simple_active(item: Optional[Dict[str, Any]]) -> bool:
    if not item:
        return False
    if item.get("active") is False:
        return False
    item_type = normalizar(item.get("item_type"))
    return item_type in ["", "single", "standard", "product", "producto", "productos", "simple"]


def require_simple_active_component(item: Optional[Dict[str, Any]], component_sku: str) -> Dict[str, Any]:
    if not item:
        raise HTTPException(status_code=404, detail=f"No existe SKU componente: {component_sku}")
    if not inventory_item_is_simple_active(item):
        raise HTTPException(
            status_code=400,
            detail={
                "message": "El componente debe ser un producto simple activo, no un combo/kit ni un producto inactivo",
                "component_sku": component_sku,
                "item_type": item.get("item_type"),
                "active": item.get("active"),
            },
        )
    return item

def create_stock_movement(
    sku: str,
    movement_type: str,
    channel: str,
    quantity: float,
    previous_stock: float,
    new_stock: float,
    reference_id: str,
    reference_type: str,
    notes: str,
):
    tenant_id = str(get_effective_tenant_id() or DEFAULT_TENANT_ID)
    sb.table("stock_movements").insert({
        "tenant_id": tenant_id,
        "sku": sku,
        "movement_type": movement_type,
        "channel": channel,
        "quantity": quantity,
        "previous_stock": previous_stock,
        "new_stock": new_stock,
        "reference_id": reference_id,
        "reference_type": reference_type,
        "notes": notes,
        "created_at": now_iso(),
    }).execute()


def create_system_notification(
    *,
    type_: str,
    severity: str,
    title: str,
    body: str = "",
    target_view: Optional[str] = None,
    payload: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    tenant_id = str(get_effective_tenant_id() or DEFAULT_TENANT_ID)
    row = {
        "tenant_id": tenant_id,
        "type": str(type_ or "system"),
        "severity": str(severity or "info"),
        "title": str(title or "Notificacion")[:180],
        "body": str(body or "")[:1500],
        "target_view": target_view,
        "target_url": f"admin_erp.html#{target_view}" if target_view else None,
        "payload": payload or {},
        "created_at": now_iso(),
        "updated_at": now_iso(),
    }
    try:
        inserted = sb.table("system_notifications").insert(row).execute().data or []
        return {"ok": True, "item": inserted[0] if inserted else row}
    except Exception as exc:
        return {"ok": False, "error": str(exc)}


def notify_marketplace_sale(
    channel: str,
    order: Dict[str, Any],
    sold_lines: List[Dict[str, Any]],
    raw_payload: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    built = build_marketplace_sale_notification(
        channel,
        order,
        sold_lines,
        raw_payload,
        sale_at_ar=datetime.now(timezone(timedelta(hours=-3))).strftime("%d/%m/%Y %H:%M hs"),
    )
    if not built:
        return {"ok": True, "skipped": True}
    return create_system_notification(**built)


def build_sync_source_meta(
    channel: str,
    external_order_id: str,
    raw_payload: Optional[Dict[str, Any]] = None,
    customer_name: Optional[str] = None,
    customer_phone: Optional[str] = None,
    erp_order_id: Optional[str] = None,
) -> Dict[str, Any]:
    """Metadata de origen para rastrear de dónde salió cada sync_job."""
    raw = raw_payload or {}
    ch = norm_sku(channel).upper()
    external_id = norm_sku(external_order_id)

    if ch == "TN":
        visible = raw.get("tn_order_number") or external_id
        if visible and not str(visible).startswith("#"):
            visible = f"#{visible}"
        api_id = raw.get("tn_order_id") or external_id
        source_created = raw.get("tn_created_at") or raw.get("tn_updated_at") or now_iso()
        pack_id = None
        shipping_id = raw.get("tn_shipping_id") or raw.get("tn_shipping_status")
    elif ch == "ML":
        visible = raw.get("ml_order_id") or external_id
        api_id = raw.get("ml_order_id") or external_id
        source_created = raw.get("ml_date_created") or raw.get("ml_date_closed") or now_iso()
        pack_id = raw.get("ml_pack_id")
        shipping_id = raw.get("ml_shipping_id")
    else:
        visible = external_id
        api_id = erp_order_id or external_id
        source_created = now_iso()
        pack_id = None
        shipping_id = None

    return {
        "source_channel": ch,
        "source_order_id": external_id,
        "source_order_number": str(visible) if visible is not None else None,
        "source_order_api_id": str(api_id) if api_id is not None else None,
        "source_pack_id": str(pack_id) if pack_id is not None else None,
        "source_shipping_id": str(shipping_id) if shipping_id is not None else None,
        "source_customer_name": customer_name,
        "source_created_at": source_created,
        "source_meta": {
            "erp_order_id": erp_order_id,
            "customer_phone": customer_phone,
            "raw_source_keys": sorted(list(raw.keys()))[:50],
        },
    }


def _open_sync_job_for_listing(marketplace: str, listing_id: str, variant_id: Optional[str]) -> Optional[Dict[str, Any]]:
    tenant_id = str(get_effective_tenant_id() or DEFAULT_TENANT_ID)
    q = (
        sb.table("sync_jobs")
        .select("*")
        .eq("marketplace", marketplace)
        .eq("listing_id", str(listing_id))
        .eq("tenant_id", tenant_id)
        .in_("status", ["pending", "failed_retry", "manual_review"])
        .limit(1)
    )
    if variant_id is None or str(variant_id) == "":
        try:
            q = q.is_("variant_id", "null")
        except Exception:
            q = q.eq("variant_id", None)
    else:
        q = q.eq("variant_id", str(variant_id))
    rows = q.execute().data or []
    return rows[0] if rows else None


def create_sync_jobs_for_sku(sku: str, target_stock: int, source_meta: Optional[Dict[str, Any]] = None, skip_full_listings: bool = False):
    """
    Crea o actualiza jobs abiertos de sincronización.

    Regla nueva:
    - Si ya existe un job abierto para marketplace/listing/variant, NO falla por unique.
    - Actualiza target_stock al último stock master y refresca metadata de origen.
    - Si no existe, crea el job.
    """
    try:
        tenant_id = str(get_effective_tenant_id() or DEFAULT_TENANT_ID)
        listings = (
            sb.table("marketplace_listings")
            .select("sku,marketplace,external_product_id,external_variant_id,external_full_id,price,status")
            .eq("sku", sku)
            .eq("tenant_id", tenant_id)
            .execute()
            .data
            or []
        )

        created = 0
        updated = 0
        skipped = 0
        errors = []
        job_ids = []

        for l in listings:
            try:
                marketplace = l.get("marketplace") or ""
                external_product_id = l.get("external_product_id")
                external_full_id = l.get("external_full_id")
                if skip_full_listings and external_full_id and not external_product_id:
                    skipped += 1
                    continue
                listing_id = external_product_id or external_full_id
                variant_id = l.get("external_variant_id")

                if not marketplace or not listing_id:
                    skipped += 1
                    continue

                now = now_iso()
                base_payload = {
                    "job_type": "stock_update",
                    "marketplace": marketplace,
                    "listing_id": str(listing_id),
                    "variant_id": str(variant_id) if variant_id is not None and str(variant_id) != "" else None,
                    "sku": sku,
                    "target_stock": int(target_stock),
                    "status": "pending",
                    "attempts": 0,
                    "max_attempts": 5,
                    "last_error": None,
                    "updated_at": now,
                    "next_retry_at": now,
                    "target_price": None,
                    "sync_stock": True,
                    "sync_price": False,
                    "tenant_id": tenant_id,
                }
                if source_meta:
                    base_payload.update({k: v for k, v in source_meta.items() if v is not None})

                existing = _open_sync_job_for_listing(marketplace, str(listing_id), base_payload["variant_id"])
                if existing:
                    sb.table("sync_jobs").update(base_payload).eq("id", existing["id"]).execute()
                    if existing.get("id") and str(existing["id"]) not in job_ids:
                        job_ids.append(str(existing["id"]))
                    updated += 1
                else:
                    insert_payload = dict(base_payload)
                    insert_payload["created_at"] = now
                    inserted = sb.table("sync_jobs").insert(insert_payload).execute().data or []
                    created_job = inserted[0] if inserted else _open_sync_job_for_listing(
                        marketplace,
                        str(listing_id),
                        base_payload["variant_id"],
                    )
                    if created_job and created_job.get("id") and str(created_job["id"]) not in job_ids:
                        job_ids.append(str(created_job["id"]))
                    created += 1
            except Exception as e:
                skipped += 1
                errors.append(str(e))

        return {
            "ok": len(errors) == 0,
            "created": created,
            "updated": updated,
            "skipped": skipped,
            "job_ids": job_ids,
            "errors": errors[:5],
        }

    except Exception as e:
        return {
            "ok": False,
            "created": 0,
            "updated": 0,
            "skipped": 0,
            "job_ids": [],
            "errors": [str(e)],
        }


def bundles_that_use_component(component_item_id: int) -> List[Dict[str, Any]]:
    rows = (
        sb.table("bundle_components")
        .select("bundle_item_id")
        .eq("component_item_id", component_item_id)
        .execute()
        .data
        or []
    )
    bundle_ids = sorted({r["bundle_item_id"] for r in rows})
    if not bundle_ids:
        return []

    bundles = (
        sb.table("inventory_items")
        .select(q_inventory_base())
        .in_("id", bundle_ids)
        .execute()
        .data
        or []
    )
    return bundles


def recalc_and_sync_bundle(bundle_item: Dict[str, Any], dry_run: bool = False, source_meta: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
    comps = get_bundle_components_by_bundle_id(bundle_item["id"])
    available = calc_bundle_available_from_components(comps)
    if available is None:
        available = int(bundle_item.get("stock") or 0)

    old_stock = int(bundle_item.get("stock") or 0)
    result = {
        "sku": bundle_item.get("sku"),
        "old_stock": old_stock,
        "new_stock": int(available),
        "changed": old_stock != int(available),
        "dry_run": dry_run,
    }

    if not dry_run and result["changed"]:
        stock_write = apply_stock_change(
            sb,
            tenant_id=str(get_effective_tenant_id() or DEFAULT_TENANT_ID),
            sku=bundle_item["sku"],
            movement_type="bundle_recalc",
            channel="ERP",
            new_stock=int(available),
            reference_id=str(bundle_item["id"]),
            reference_type="bundle_recalc",
            notes="Stock de combo recalculado por componentes",
        )
        result["old_stock"] = int(stock_write.get("previous_stock") or 0)
        result["new_stock"] = int(stock_write.get("new_stock") or 0)
        result["changed"] = bool(stock_write.get("changed"))
        result["stock_write"] = stock_write
        if result["changed"]:
            result["sync_jobs"] = create_sync_jobs_for_sku(
                bundle_item["sku"],
                result["new_stock"],
                source_meta=source_meta,
            )

    return result


def affected_bundle_recalcs_for_component(component_item_id: int, dry_run: bool = False) -> List[Dict[str, Any]]:
    results = []
    for bundle in bundles_that_use_component(component_item_id):
        results.append(recalc_and_sync_bundle(bundle, dry_run=dry_run))
    return results


def safe_insert_order(channel: str, external_order_id: str, payload: Dict[str, Any]) -> Dict[str, Any]:
    # Usa el unique existente por tenant/canal/orden.
    tenant_id = str(get_effective_tenant_id() or DEFAULT_TENANT_ID)
    existing = (
        sb.table("orders")
        .select("*")
        .eq("channel", channel)
        .eq("external_order_id", external_order_id)
        .eq("tenant_id", tenant_id)
        .limit(1)
        .execute()
        .data
        or []
    )
    if existing:
        return {"inserted": False, "order": existing[0]}

    order_id = str(uuid.uuid4())
    row = {
        "id": order_id,
        "tenant_id": tenant_id,
        "channel": channel,
        "external_order_id": external_order_id,
        "status": "paid",
        "customer_name": payload.get("customer_name"),
        "customer_phone": payload.get("customer_phone"),
        "total": payload.get("total"),
        "raw_data": payload,
        "created_at": now_iso(),
        "updated_at": now_iso(),
    }
    inserted = sb.table("orders").insert(row).execute().data
    return {"inserted": True, "order": inserted[0] if inserted else row}


def decrement_item_stock(
    item: Dict[str, Any],
    qty_to_decrement: float,
    channel: str,
    reference_id: str,
    reference_type: str,
    notes: str,
    dry_run: bool,
    source_meta: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    old_stock = int(item.get("stock") or 0)
    new_stock = old_stock - int(qty_to_decrement)

    result = {
        "sku": item["sku"],
        "name": item.get("name"),
        "qty_decrement": int(qty_to_decrement),
        "old_stock": old_stock,
        "new_stock": new_stock,
        "insufficient_stock": new_stock < 0,
        "dry_run": dry_run,
    }

    if not dry_run:
        stock_write = adjust_stock(
            sb,
            tenant_id=str(get_effective_tenant_id() or DEFAULT_TENANT_ID),
            sku=item["sku"],
            quantity=-abs(int(qty_to_decrement)),
            movement_type="sale",
            channel=channel,
            reference_id=reference_id,
            reference_type=reference_type,
            notes=notes,
        )
        result["old_stock"] = int(stock_write.get("previous_stock") or 0)
        result["new_stock"] = int(stock_write.get("new_stock") or 0)
        result["insufficient_stock"] = result["new_stock"] < 0
        result["stock_write"] = stock_write
        result["sync_jobs"] = create_sync_jobs_for_sku(
            item["sku"],
            result["new_stock"],
            source_meta=source_meta,
        )

    return result


def comprobante_stock_direction(cbte_tipo: int) -> int:
    """
    Dirección de stock por tipo de comprobante ARCA.
    +1 reingresa, -1 descuenta, 0 sin movimiento.
    Códigos: 1/6/11 factura, 2/7/12 débito, 3/8/13 crédito.
    """
    try:
        t = int(cbte_tipo or 0)
    except Exception:
        t = 0
    if t in [1, 2, 6, 7, 11, 12]:
        return -1
    if t in [3, 8, 13]:
        return 1
    return 0


def apply_manual_comprobante_stock_movements(
    invoice: Dict[str, Any],
    payload: Dict[str, Any],
    dry_run: bool = False,
) -> Dict[str, Any]:
    """
    Aplica movimiento de stock opcional para comprobantes manuales.
    No se usa el flujo viejo de venta manual: esto queda asociado al comprobante.
    """
    raw_input = (((payload or {}).get("raw_data") or {}).get("input") or {})
    modifica_stock = bool(raw_input.get("modifica_stock"))
    if not modifica_stock:
        return {"enabled": False, "applied": [], "errors": [], "preview": []}

    direction = comprobante_stock_direction(int(payload.get("cbte_tipo") or 0))
    if direction == 0:
        raise HTTPException(status_code=400, detail="Este tipo de comprobante no tiene dirección de stock definida")

    reference_id = str((invoice or {}).get("id") or payload.get("source_order_id") or uuid.uuid4())
    reference_type = "arca_comprobante_manual"
    channel = norm_sku(payload.get("source_channel") or "ARCA_MANUAL").upper()
    reason = norm_sku(raw_input.get("stock_movement_reason") or "comprobante").lower() or "comprobante"
    if reason not in ["comprobante", "devolucion", "devolución", "ajuste", "no aplica"]:
        reason = "comprobante"

    lines = payload.get("lines") or []
    all_decrements = []
    stock_lines = []
    for idx, line in enumerate(lines, start=1):
        sku = norm_sku(line.get("sku") or "")
        if not sku or sku == "ARCA_MANUAL":
            raise HTTPException(status_code=400, detail=f"Línea {idx}: para modificar stock debe tener un SKU real")
        item = get_item_by_sku(sku)
        if not item:
            raise HTTPException(status_code=404, detail=f"Línea {idx}: no existe SKU en inventario: {sku}")
        qty = float(line.get("quantity") or 0)
        if qty <= 0:
            raise HTTPException(status_code=400, detail=f"Línea {idx}: cantidad inválida para stock")
        stock_lines.append({"line": line, "item": item, "qty": qty})
        if direction < 0:
            built = build_decrements_for_sold_item(item, qty)
            all_decrements.extend(built.get("decrements") or [])

    source_meta = build_sync_source_meta(
        channel=channel,
        external_order_id=str(payload.get("source_order_id") or reference_id),
        raw_payload={"source": "arca_manual_comprobante", "invoice_id": reference_id, "cbte_tipo": payload.get("cbte_tipo")},
        customer_name=payload.get("customer_name"),
        erp_order_id=reference_id,
    )

    applied = []
    affected_bundle_ids = set()

    if direction < 0:
        aggregated = aggregate_decrements(all_decrements)
        for d in aggregated:
            item = d["item"]
            qty = int(d.get("qty") or 0)
            old_stock = int(item.get("stock") or 0)
            preview_row = {
                "sku": item.get("sku"),
                "name": item.get("name"),
                "quantity": -abs(qty),
                "old_stock": old_stock,
                "new_stock": old_stock - qty,
                "source_skus": d.get("source_skus") or [],
            }
            if dry_run:
                applied.append(preview_row)
                continue
            res = decrement_item_stock(
                item=item,
                qty_to_decrement=qty,
                channel=channel,
                reference_id=reference_id,
                reference_type=reference_type,
                notes=f"Comprobante manual ARCA · {reason}",
                dry_run=False,
                source_meta=source_meta,
            )
            applied.append(res)
            for bundle in bundles_that_use_component(item["id"]):
                affected_bundle_ids.add(bundle["id"])
    else:
        for row in stock_lines:
            item = row["item"]
            qty = int(float(row["qty"]))
            old_stock = int(item.get("stock") or 0)
            new_stock = old_stock + qty
            if dry_run:
                applied.append({
                    "sku": item.get("sku"),
                    "name": item.get("name"),
                    "quantity": abs(qty),
                    "old_stock": old_stock,
                    "new_stock": new_stock,
                })
                continue
            stock_write = adjust_stock(
                sb,
                tenant_id=str(get_effective_tenant_id() or DEFAULT_TENANT_ID),
                sku=item["sku"],
                quantity=abs(qty),
                movement_type="return",
                channel=channel,
                reference_id=reference_id,
                reference_type=reference_type,
                notes=f"Comprobante manual ARCA · {reason}",
            )
            old_stock = int(stock_write.get("previous_stock") or 0)
            new_stock = int(stock_write.get("new_stock") or 0)
            applied.append({
                "sku": item.get("sku"),
                "name": item.get("name"),
                "quantity": abs(qty),
                "old_stock": old_stock,
                "new_stock": new_stock,
                "stock_write": stock_write,
                "sync_jobs": create_sync_jobs_for_sku(item["sku"], new_stock, source_meta=source_meta),
            })
            for bundle in bundles_that_use_component(item["id"]):
                affected_bundle_ids.add(bundle["id"])

    affected_bundle_results = []
    if affected_bundle_ids and not dry_run:
        bundles_to_recalc = (
            sb.table("inventory_items")
            .select(q_inventory_base())
            .in_("id", list(affected_bundle_ids))
            .execute()
            .data
            or []
        )
        for bundle in sorted(bundles_to_recalc, key=lambda b: b.get("sku") or ""):
            affected_bundle_results.append(recalc_and_sync_bundle(bundle, dry_run=False, source_meta=source_meta))

    return {
        "enabled": True,
        "direction": direction,
        "mode": "descuenta" if direction < 0 else "reingresa",
        "reason": reason,
        "dry_run": dry_run,
        "applied": applied,
        "affected_bundles": affected_bundle_results,
    }


