def is_test_order_row(row: Dict[str, Any]) -> bool:
    """Filtra pruebas/manuales accidentales de las pantallas de ventas reales."""
    raw = row.get("raw_data") or {}
    txt_parts = [
        row.get("external_order_id"),
        row.get("customer_name"),
        row.get("customer_phone"),
        row.get("status"),
    ]
    if isinstance(raw, dict):
        txt_parts += [
            raw.get("source"),
            raw.get("note"),
            raw.get("tn_order_number"),
            raw.get("ml_order_id"),
        ]
    txt = normalizar(" ".join([str(x or "") for x in txt_parts]))
    bad_tokens = [
        "test",
        "prueba",
        "dry run",
        "dry_run",
        "manual test",
        "dummy",
    ]
    return any(t in txt for t in bad_tokens)


def fetch_recent_order_rows(channel: str, limit: int, offset: int, exclude_tests: bool = True) -> Dict[str, Any]:
    """
    Devuelve filas de orders ya filtradas, con paginación lógica.
    Para esta etapa trae una ventana amplia y pagina en Python: más simple y evita
    que una venta ML partida por pack/envío rompa el paginado visual.
    """
    hard_cap = 5000
    rows = (
        sb.table("orders")
        .select("*")
        .eq("channel", channel)
        .order("created_at", desc=True)
        .limit(hard_cap)
        .execute()
        .data
        or []
    )
    if exclude_tests:
        rows = [r for r in rows if not is_test_order_row(r)]
    return {
        "rows": rows,
        "hard_cap": hard_cap,
    }


def row_raw_dict(row: Dict[str, Any]) -> Dict[str, Any]:
    raw = row.get("raw_data") or {}
    return raw if isinstance(raw, dict) else {}


def recent_order_search_blob(item: Dict[str, Any]) -> str:
    parts = []
    def add(v):
        if v is None:
            return
        if isinstance(v, (list, tuple, set)):
            for x in v:
                add(x)
        elif isinstance(v, dict):
            for x in v.values():
                add(x)
        else:
            parts.append(str(v))
    add(item.get("id"))
    add(item.get("channel"))
    add(item.get("external_order_id"))
    add(item.get("group_label"))
    add(item.get("sale_number"))
    add(item.get("ml_sale_number"))
    add(item.get("ml_pack_id"))
    add(item.get("ml_shipping_id"))
    add(item.get("tn_order_number"))
    add(item.get("customer_name"))
    add(item.get("customer_fiscal_name"))
    add(item.get("customer_doc_type"))
    add(item.get("customer_doc_number"))
    add(item.get("customer_iva_condition"))
    add(item.get("customer_city"))
    add(item.get("customer_province"))
    add(item.get("customer_phone"))
    add(item.get("status"))
    add(item.get("ml_status"))
    add(item.get("tn_status"))
    add(item.get("tn_payment_status"))
    add(item.get("shipping_option"))
    add(item.get("tn_shipping_status"))
    add(item.get("child_order_ids"))
    for line in item.get("sold_lines") or []:
        if isinstance(line, dict):
            add(line.get("sku"))
            add(line.get("name"))
            add(line.get("title"))
            add(line.get("product_name"))
        else:
            add(line)
    for mov in item.get("stock_movements") or []:
        if isinstance(mov, dict):
            add(mov.get("sku"))
            add(mov.get("notes"))
        else:
            add(mov)
    return normalizar(" ".join(parts))

def filter_recent_items(items: List[Dict[str, Any]], q: Optional[str]) -> List[Dict[str, Any]]:
    query = normalizar(q or "")
    if not query:
        return items
    terms = [t for t in query.split() if t]
    if not terms:
        return items
    out = []
    for item in items:
        blob = recent_order_search_blob(item)
        if all(t in blob for t in terms):
            out.append(item)
    return out


def report_customer_payload(c: Optional[Dict[str, Any]]) -> Dict[str, Any]:
    if not c:
        return {}
    return {
        "id": c.get("id"),
        "source_origin": c.get("source_origin"),
        "source_label": c.get("source_label"),
        "source_customer_id": c.get("source_customer_id"),
        "name": c.get("name"),
        "fiscal_name": c.get("fiscal_name") or c.get("name"),
        "doc_type": c.get("doc_type"),
        "doc_number": c.get("doc_number"),
        "iva_condition": c.get("iva_condition"),
        "email": c.get("email"),
        "phone": c.get("phone"),
        "address": c.get("address"),
        "city": c.get("city"),
        "province": c.get("province"),
        "zip": c.get("zip"),
        "ml_user_id": c.get("ml_user_id"),
        "tn_customer_id": c.get("tn_customer_id"),
    }


def pc_customer_for_order_row(
    row: Dict[str, Any],
    auto_enrich_missing: bool = True,
) -> Optional[Dict[str, Any]]:
    """Cliente canónico para reportes/facturación.

    Los reportes NO deben mostrar el nickname/nombre operativo del marketplace como
    receptor fiscal si existe erp_customers. Priorizamos ids de canal, luego vínculo
    exacto de última orden y finalmente documento si está disponible en el raw.
    """
    if not row:
        return None
    ch = str(row.get("channel") or "").upper()
    tenant_id = str(row.get("tenant_id") or get_effective_tenant_id() or DEFAULT_TENANT_ID)
    raw = row_raw_dict(row)
    ml_raw = raw.get("ml_raw") if isinstance(raw.get("ml_raw"), dict) else {}
    tn_raw = raw.get("tn_raw") if isinstance(raw.get("tn_raw"), dict) else {}

    searches = []
    if ch == "ML":
        buyer = ml_raw.get("buyer") if isinstance(ml_raw.get("buyer"), dict) else {}
        ml_user_id = pc_clean_str(buyer.get("id") or raw.get("ml_user_id"))
        if ml_user_id:
            searches.append(("ml_user_id", ml_user_id))
    if ch == "TN":
        customer = tn_raw.get("customer") if isinstance(tn_raw.get("customer"), dict) else {}
        tn_customer_id = pc_clean_str(customer.get("id") or tn_raw.get("customer_id") or raw.get("tn_customer_id"))
        if tn_customer_id:
            searches.append(("tn_customer_id", tn_customer_id))

    # Vínculo exacto por orden cuando el cliente quedó asociado a esa venta.
    if row.get("external_order_id"):
        try:
            exact = (
                sb.table("erp_customers")
                .select("*")
                .eq("tenant_id", tenant_id)
                .eq("last_order_channel", ch)
                .eq("last_order_id", str(row.get("external_order_id")))
                .limit(1)
                .execute()
                .data
                or []
            )
            if exact:
                return exact[0]
        except Exception:
            pass

    for field, value in searches:
        if not value:
            continue
        try:
            rows = (
                sb.table("erp_customers")
                .select("*")
                .eq("tenant_id", tenant_id)
                .eq(field, value)
                .order("updated_at", desc=True)
                .limit(1)
                .execute()
                .data
                or []
            )
            if rows:
                return rows[0]
        except Exception:
            continue

    # REPORTES_ARCA_COMPACTO_FACTURA_V6
    # Si una venta histórica ML quedó aplicada antes de la mejora ARCA-first, puede estar
    # en orders pero sin erp_customers. En ese caso los reportes mostrarían el nombre
    # operativo de ML en minúsculas. Para el vendedor y la factura, completamos el
    # cliente fiscal una sola vez desde ML billing_info + ARCA y volvemos a buscarlo.
    if (
        auto_enrich_missing
        and ch == "ML"
        and REPORT_AUTO_ENRICH_MISSING_ML_CUSTOMERS
        and isinstance(ml_raw, dict)
        and ml_raw.get("buyer")
    ):
        try:
            pc_enrich_ml_customer_arca_first_for_order(ml_raw, dry_run=False)
        except Exception:
            pass
        for field, value in searches:
            if not value:
                continue
            try:
                rows = (
                    sb.table("erp_customers")
                    .select("*")
                    .eq("tenant_id", tenant_id)
                    .eq(field, value)
                    .order("updated_at", desc=True)
                    .limit(1)
                    .execute()
                    .data
                    or []
                )
                if rows:
                    return rows[0]
            except Exception:
                continue
    return None




def pc_build_order_report_row_marker() -> str:
    """REPORTES_VENDEDOR_CLIENTE_FISCAL_V2 marker. La construcción real vive en build_recent_ml_items/build_recent_tn_items."""
    return "REPORTES_VENDEDOR_CLIENTE_FISCAL_V2"


def enrich_recent_order_rows_with_customer(
    rows: List[Dict[str, Any]],
    auto_enrich_missing: bool = True,
) -> List[Dict[str, Any]]:
    out = []
    for row in rows or []:
        r = dict(row or {})
        try:
            c = pc_customer_for_order_row(r, auto_enrich_missing=auto_enrich_missing)
            cp = report_customer_payload(c)
            if cp:
                r["customer_fiscal"] = cp
                r["customer_fiscal_name"] = cp.get("fiscal_name")
                r["customer_doc_type"] = cp.get("doc_type")
                r["customer_doc_number"] = cp.get("doc_number")
                r["customer_iva_condition"] = cp.get("iva_condition")
                r["customer_email"] = cp.get("email")
                r["customer_address"] = cp.get("address")
                r["customer_city"] = cp.get("city")
                r["customer_province"] = cp.get("province")
                r["customer_zip"] = cp.get("zip")
        except Exception as e:
            r["customer_report_error"] = str(e)[:250]
        out.append(r)
    return out


_ML_SHIPMENT_CACHE: Dict[str, Dict[str, Any]] = {}


def ml_get_shipment_info_safe(shipping_id: Any) -> Dict[str, Any]:
    sid = str(shipping_id or "").strip()
    if not sid:
        return {}
    if sid in _ML_SHIPMENT_CACHE:
        return _ML_SHIPMENT_CACHE[sid]
    try:
        r = ml_request("GET", f"https://api.mercadolibre.com/shipments/{sid}", timeout=30)
        if r.status_code == 200:
            data = r.json()
            if isinstance(data, dict):
                _ML_SHIPMENT_CACHE[sid] = data
                return data
        _ML_SHIPMENT_CACHE[sid] = {"_error": f"ML shipment {r.status_code}: {r.text[:250]}"}
        return _ML_SHIPMENT_CACHE[sid]
    except Exception as e:
        _ML_SHIPMENT_CACHE[sid] = {"_error": str(e)[:250]}
        return _ML_SHIPMENT_CACHE[sid]


def ml_deep_collect_values(obj: Any, keys: List[str], max_values: int = 30) -> List[Any]:
    """Recolecta valores candidatos dentro de respuestas crudas ML/shipment."""
    found = []
    wanted = {str(k).lower() for k in keys}

    def walk(x: Any):
        if len(found) >= max_values:
            return
        if isinstance(x, dict):
            for k, v in x.items():
                lk = str(k).lower()
                if lk in wanted and v not in [None, "", 0, "0"]:
                    found.append(v)
                if isinstance(v, (dict, list)):
                    walk(v)
        elif isinstance(x, list):
            for v in x:
                walk(v)

    walk(obj)
    return found


def ml_clean_id_candidate(value: Any) -> Optional[str]:
    if value in [None, "", 0, "0"]:
        return None
    txt = str(value).strip().replace("#", "")
    if not txt:
        return None
    # Preferimos ids numéricos largos de ML; descartamos textos de estado/modo.
    digits = re.sub(r"\D+", "", txt)
    if len(digits) >= 8:
        return digits
    return txt if len(txt) >= 8 else None


def ml_detect_sale_number_from_row(row: Dict[str, Any]) -> Optional[str]:
    raw = row_raw_dict(row)
    ml_raw = raw.get("ml_raw") or {}
    if not isinstance(ml_raw, dict):
        ml_raw = {}

    # Número operativo visible ML:
    # - Si hay pack_id, usamos pack_id porque representa la compra visible agrupada.
    # - Si no hay pack_id, usamos el order_id/API external_order_id.
    # Esto evita que ventas simples con shipping_id caigan en grupo "shipping:"
    # y el HTML termine mostrando "Venta ML sin número".
    candidates = [
        raw.get("ml_sale_number"),
        raw.get("ml_pack_id"),
        ml_raw.get("pack_id"),
        ml_raw.get("sale_id"),
        ml_raw.get("purchase_id"),
    ]
    candidates += ml_deep_collect_values(raw, ["pack_id", "sale_id", "purchase_id", "sale_number", "purchase_number"])
    for p in ml_raw.get("payments") or []:
        if isinstance(p, dict):
            # En algunas respuestas ML el número visible queda como pack/compra, no como order_id API.
            candidates += [p.get("pack_id"), p.get("sale_id"), p.get("purchase_id"), p.get("operation_id")]

    # Fallback correcto para venta simple sin pack: el número visible es el order_id/API.
    candidates += [
        raw.get("ml_order_id"),
        ml_raw.get("id"),
        row.get("external_order_id"),
    ]

    for c in candidates:
        cleaned = ml_clean_id_candidate(c)
        if cleaned:
            return cleaned
    return None


def ml_detect_sale_number_from_shipment(shipment: Dict[str, Any], child_order_ids: Optional[List[str]] = None) -> Optional[str]:
    if not isinstance(shipment, dict) or not shipment:
        return None
    child_ids = {str(x) for x in (child_order_ids or []) if x is not None}
    candidates = []
    candidates += [
        shipment.get("pack_id"),
        shipment.get("sale_id"),
        shipment.get("purchase_id"),
        shipment.get("order_pack_id"),
        shipment.get("order_id"),
        shipment.get("external_reference"),
    ]
    candidates += ml_deep_collect_values(
        shipment,
        ["pack_id", "sale_id", "purchase_id", "order_pack_id", "sale_number", "purchase_number", "external_reference", "order_id"],
    )
    for c in candidates:
        cleaned = ml_clean_id_candidate(c)
        if cleaned and cleaned not in child_ids:
            return cleaned
    return None


def get_stock_lines_for_order_id(order_id: str) -> List[Dict[str, Any]]:
    movs = (
        sb.table("stock_movements")
        .select("*")
        .eq("reference_id", order_id)
        .order("created_at", desc=False)
        .limit(100)
        .execute()
        .data
        or []
    )
    return [{
        "sku": m.get("sku"),
        "quantity": m.get("quantity"),
        "previous_stock": m.get("previous_stock"),
        "new_stock": m.get("new_stock"),
        "notes": m.get("notes"),
    } for m in movs]


def ml_group_key_for_recent_row(row: Dict[str, Any]) -> str:
    raw = row_raw_dict(row)
    ml_raw = raw.get("ml_raw") or {}
    if not isinstance(ml_raw, dict):
        ml_raw = {}
    sale_number = ml_detect_sale_number_from_row(row)
    if sale_number:
        return f"sale:{sale_number}"
    shipping_id = raw.get("ml_shipping_id")
    if not shipping_id:
        shipping = ml_raw.get("shipping") or {}
        if isinstance(shipping, dict):
            shipping_id = shipping.get("id")
    pack_id = raw.get("ml_pack_id") or ml_raw.get("pack_id")
    if pack_id:
        return f"pack:{pack_id}"
    if shipping_id:
        return f"shipping:{shipping_id}"
    return f"order:{row.get('external_order_id') or row.get('id')}"


def pc_deep_find_first(obj: Any, keys: List[str], max_depth: int = 6) -> Any:
    """Busca recursivamente el primer valor no vacío para claves logísticas.
    ML a veces devuelve substatus dentro de snapshots/raw anidados.
    """
    if max_depth < 0 or obj is None:
        return None
    if isinstance(obj, dict):
        for k in keys:
            v = obj.get(k)
            if v not in [None, "", [], {}]:
                return v
        for v in obj.values():
            found = pc_deep_find_first(v, keys, max_depth - 1)
            if found not in [None, "", [], {}]:
                return found
    elif isinstance(obj, list):
        for v in obj:
            found = pc_deep_find_first(v, keys, max_depth - 1)
            if found not in [None, "", [], {}]:
                return found
    return None



def pc_ml_shipping_ui_status_from_labels(labels: Dict[str, Any]) -> str:
    """Estado visual consolidado usando tokens exactos y reglas testeables."""
    return ml_shipping_ui_status(labels or {})

def ml_shipping_labels_from_row(row: Dict[str, Any]) -> Dict[str, Any]:
    """Labels logísticos ML para la vista de ventas.

    0.1.97: no llama a la API de ML desde la vista de ventas.
    La vista sólo lee lo ya guardado en orders.raw_data por el refresh/poller,
    para que /admin/ml/orders/recent nunca rompa por un shipment raro o token externo.
    """
    try:
        raw = row_raw_dict(row)
        ml_raw = raw.get("ml_raw") or {}
        if not isinstance(ml_raw, dict):
            ml_raw = {}
        shipping = ml_raw.get("shipping") or {}
        if not isinstance(shipping, dict):
            shipping = {}

        raw_snapshot = raw.get("ml_shipping_last_snapshot") if isinstance(raw.get("ml_shipping_last_snapshot"), dict) else {}

        shipping_id = (
            raw.get("ml_shipping_id")
            or raw_snapshot.get("id")
            or shipping.get("id")
            or raw.get("shipping_id")
            or raw.get("shipment_id")
        )

        status = (
            raw.get("ml_shipping_status")
            or raw_snapshot.get("status")
            or shipping.get("status")
            or raw.get("shipping_status")
        )
        substatus = (
            raw.get("ml_shipping_substatus")
            or raw.get("shipping_substatus")
            or raw_snapshot.get("substatus")
            or raw_snapshot.get("sub_status")
            or shipping.get("substatus")
            or shipping.get("sub_status")
        )
        logistic_type = (
            raw.get("ml_shipping_logistic_type")
            or raw_snapshot.get("logistic_type")
            or shipping.get("logistic_type")
        )
        mode = (
            raw.get("ml_shipping_mode")
            or raw_snapshot.get("mode")
            or shipping.get("mode")
        )
        tags = raw.get("ml_shipping_tags") or raw_snapshot.get("tags") or shipping.get("tags") or []
        if not isinstance(tags, list):
            tags = [tags]

        saved_ui_type = (
            raw.get("ml_shipping_ui_type")
            or raw_snapshot.get("ui_type")
            or raw.get("ml_shipping_type")
            or raw.get("shipping_type")
        )
        saved_ui_status = (
            raw.get("ml_shipping_ui_status")
            or raw_snapshot.get("ui_status")
            or raw.get("shipping_ui_status")
        )

        fulfilled = raw.get("ml_fulfilled")
        if fulfilled is None:
            fulfilled = raw_snapshot.get("fulfilled")
        if fulfilled is None:
            fulfilled = ml_raw.get("fulfilled")

        labels = {
            "ml_shipping_id": shipping_id,
            "ml_shipping_logistic_type": logistic_type,
            "ml_shipping_mode": mode,
            "ml_shipping_tags": tags,
            "ml_shipping_status": status,
            "ml_shipping_substatus": substatus,
            "shipping_substatus": substatus,
            "ml_shipping_refreshed_at": raw.get("ml_shipping_refreshed_at"),
            "ml_shipping_last_snapshot": raw_snapshot,
            "ml_fulfilled": bool(parse_boolish(fulfilled)),
            "fulfilled": fulfilled,
            "ml_shipment_error": raw.get("ml_shipping_refresh_error"),
            "ml_sale_number_from_shipment": raw.get("ml_sale_number_from_shipment"),
            "ml_shipping_ui_type": saved_ui_type,
            "ml_shipping_type": saved_ui_type,
            "shipping_type": saved_ui_type,
        }
        computed_ui_status = pc_ml_shipping_ui_status_from_labels(labels)
        if parse_boolish(fulfilled):
            labels["ml_shipping_status"] = labels.get("ml_shipping_status") or "delivered"
            labels["shipping_status"] = labels.get("shipping_status") or labels.get("ml_shipping_status")
            labels["ml_shipping_ui_status"] = "Entregado"
            labels["shipping_ui_status"] = "Entregado"
            labels["ml_shipping_is_final"] = True
        else:
            # Si ML ya informó movimiento real (picked_up/shipped/in_transit/etc.),
            # ese estado calculado gana sobre una etiqueta visual vieja guardada en raw_data.
            # Evita que una venta que ya está en camino siga apareciendo como pendiente.
            computed_priority = pc_clean_str(computed_ui_status).lower()
            authoritative = computed_priority in [
                "en camino",
                "entregado",
                "cancelado",
                "devuelto",
                "devuelto al remitente",
                "procesando en bodega",
            ]
            if computed_priority == "no entregado":
                authoritative = "not_delivered" in status_tokens(
                    status,
                    substatus,
                    raw_snapshot.get("status"),
                    raw_snapshot.get("substatus") or raw_snapshot.get("sub_status"),
                )
            if authoritative:
                labels["ml_shipping_ui_status"] = computed_ui_status
            else:
                labels["ml_shipping_ui_status"] = saved_ui_status or computed_ui_status
            labels["shipping_ui_status"] = labels["ml_shipping_ui_status"]
        return labels
    except Exception as e:
        return {
            "ml_shipping_ui_status": "",
            "shipping_ui_status": "",
            "ml_shipping_label_error": str(e)[:250],
        }

def build_recent_ml_items(rows: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    groups: Dict[str, Dict[str, Any]] = {}
    order_keys: List[str] = []
    build_errors: List[Dict[str, Any]] = []

    for row in rows or []:
        try:
            raw = row_raw_dict(row)
            ml_raw = raw.get("ml_raw") or {}
            if not isinstance(ml_raw, dict):
                ml_raw = {}
            key = ml_group_key_for_recent_row(row)
            if key not in groups:
                labels = ml_shipping_labels_from_row(row)
                prefix, value = key.split(":", 1) if ":" in key else ("order", key)
                sale_number = ml_detect_sale_number_from_row(row)
                if prefix in ["sale", "pack"]:
                    sale_number = value
                    group_label = f"#{value}"
                elif prefix == "shipping":
                    group_label = f"Envío ML {value}"
                else:
                    group_label = f"#{row.get('external_order_id') or ''}"
                groups[key] = {
                    "id": row.get("id"),
                    "channel": "ML",
                    "group_key": key,
                    "group_label": group_label,
                    "sale_number": sale_number,
                    "ml_sale_number": sale_number,
                    "ml_pack_id": raw.get("ml_pack_id") or (ml_raw.get("pack_id") if isinstance(ml_raw, dict) else None),
                    "external_order_id": row.get("external_order_id"),
                    "child_order_ids": [],
                    "created_at": row.get("created_at"),
                    "display_created_at": raw.get("ml_date_created") or raw.get("ml_date_closed") or (ml_raw.get("date_created") if isinstance(ml_raw, dict) else None) or row.get("created_at"),
                    "customer_name": row.get("customer_name"),
                    "customer_nickname": arca_order_row_user_label(row),
                    "customer_fiscal": row.get("customer_fiscal") or {},
                    "customer_fiscal_name": row.get("customer_fiscal_name"),
                    "customer_doc_type": row.get("customer_doc_type"),
                    "customer_doc_number": row.get("customer_doc_number"),
                    "customer_iva_condition": row.get("customer_iva_condition"),
                    "customer_email": row.get("customer_email"),
                    "customer_address": row.get("customer_address"),
                    "customer_city": row.get("customer_city"),
                    "customer_province": row.get("customer_province"),
                    "customer_zip": row.get("customer_zip"),
                    "customer_phone": row.get("customer_phone"),
                    "total": 0,
                    "status": row.get("status"),
                    "ml_status": raw.get("ml_status") or (ml_raw.get("status") if isinstance(ml_raw, dict) else None),
                    "ml_date_created": raw.get("ml_date_created") or (ml_raw.get("date_created") if isinstance(ml_raw, dict) else None),
                    "whatsapp_notified": bool(raw.get("ml_whatsapp_notified_at")),
                    "whatsapp_notified_at": raw.get("ml_whatsapp_notified_at"),
                    "ml_fiscal_documents_check": raw.get("ml_fiscal_documents_check"),
                    "sold_lines": [],
                    "stock_movements": [],
                    **labels,
                }
                if labels.get("ml_sale_number_from_shipment") and not groups[key].get("sale_number"):
                    groups[key]["sale_number"] = labels.get("ml_sale_number_from_shipment")
                    groups[key]["ml_sale_number"] = labels.get("ml_sale_number_from_shipment")
                    groups[key]["group_label"] = f"#{labels.get('ml_sale_number_from_shipment')}"
                order_keys.append(key)

            g = groups[key]
            fiscal_check = raw.get("ml_fiscal_documents_check")
            if isinstance(fiscal_check, dict) and fiscal_check.get("present") is True:
                g["ml_fiscal_documents_check"] = fiscal_check

            # Fusionar estados de filas hijas: picked_up manda, pero sin llamadas externas.
            row_labels = ml_shipping_labels_from_row(row)
            row_sub = str(row_labels.get("ml_shipping_substatus") or "").lower()
            row_ui = pc_clean_str(row_labels.get("ml_shipping_ui_status") or row_labels.get("shipping_ui_status")).lower()
            current_sub = str(g.get("ml_shipping_substatus") or "").lower()
            current_ui = pc_clean_str(g.get("ml_shipping_ui_status") or g.get("shipping_ui_status")).lower()
            if (row_sub and (not current_sub or row_sub == "picked_up")) or (row_ui == "en camino" and current_ui != "entregado"):
                for lk in [
                    "ml_shipping_id", "ml_shipping_status", "ml_shipping_substatus", "shipping_substatus",
                    "ml_shipping_logistic_type", "ml_shipping_mode", "ml_shipping_tags",
                    "ml_shipping_refreshed_at", "ml_shipping_last_snapshot",
                    "ml_shipping_ui_type", "ml_shipping_type", "shipping_type",
                    "ml_shipping_ui_status", "shipping_ui_status", "ml_shipment_error",
                ]:
                    if row_labels.get(lk) not in [None, "", [], {}]:
                        g[lk] = row_labels.get(lk)

            oid = str(row.get("external_order_id") or "").strip()
            if oid and oid not in g["child_order_ids"]:
                g["child_order_ids"].append(oid)

            try:
                g["total"] = float(g.get("total") or 0) + float(row.get("total") or 0)
            except Exception:
                pass
            if row.get("created_at") and (not g.get("created_at") or str(row.get("created_at")) < str(g.get("created_at"))):
                g["created_at"] = row.get("created_at")
            if not g.get("customer_name") and row.get("customer_name"):
                g["customer_name"] = row.get("customer_name")
            if not g.get("customer_phone") and row.get("customer_phone"):
                g["customer_phone"] = row.get("customer_phone")
            if not g.get("customer_fiscal") and row.get("customer_fiscal"):
                g["customer_fiscal"] = row.get("customer_fiscal") or {}
                g["customer_fiscal_name"] = row.get("customer_fiscal_name")
                g["customer_doc_type"] = row.get("customer_doc_type")
                g["customer_doc_number"] = row.get("customer_doc_number")
                g["customer_iva_condition"] = row.get("customer_iva_condition")
                g["customer_address"] = row.get("customer_address")
                g["customer_city"] = row.get("customer_city")
                g["customer_province"] = row.get("customer_province")
                g["customer_zip"] = row.get("customer_zip")
            row_sale_number = ml_detect_sale_number_from_row(row)
            if row_sale_number and not g.get("sale_number"):
                g["sale_number"] = row_sale_number
                g["ml_sale_number"] = row_sale_number
                if str(g.get("group_key") or "").startswith("shipping:"):
                    g["group_label"] = f"#{row_sale_number}"
            for line in raw.get("sold_lines") or []:
                g["sold_lines"].append(line if isinstance(line, dict) else {"name": str(line)})
            try:
                g["stock_movements"].extend(get_stock_lines_for_order_id(row.get("id")))
            except Exception as e:
                g.setdefault("stock_lookup_errors", []).append(str(e)[:250])
        except Exception as e:
            build_errors.append({
                "order_id": str((row or {}).get("external_order_id") or (row or {}).get("id") or ""),
                "error": str(e)[:250],
            })
            continue

    items = [groups[k] for k in order_keys]
    if build_errors and items:
        items[0]["ml_recent_build_errors"] = build_errors[:10]

    def _dt_sort_key(item: Dict[str, Any]) -> str:
        return str(
            item.get("display_created_at")
            or item.get("ml_date_created")
            or item.get("created_at")
            or ""
        )

    items.sort(key=_dt_sort_key, reverse=True)
    return items

def build_recent_tn_items(rows: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    items = []
    for row in rows:
        raw = row_raw_dict(row)
        tn_raw = raw.get("tn_raw") or {}
        if not isinstance(tn_raw, dict):
            tn_raw = {}
        shipping_option = raw.get("tn_shipping_option") or tn_raw.get("shipping_option")
        if isinstance(shipping_option, dict):
            shipping_option = shipping_option.get("name") or shipping_option.get("code") or str(shipping_option)
        # TN moto/manual: Tiendanube puede quedar en shipped aunque el ERP ya cerró la entrega.
        # Para la vista operativa, el estado explícito del ERP gana sobre lo que devuelva la API.
        tn_ui_status = raw.get("tn_shipping_ui_status") or raw.get("shipping_ui_status")
        if raw.get("tn_manual_delivered") or str(raw.get("delivery_status") or raw.get("tn_delivery_status") or "").lower() in ["delivered", "manual_delivered"]:
            tn_ui_status = "Entregado"
        if tn_closed_order_counts_as_delivered(raw):
            tn_ui_status = "Entregado"
        items.append({
            "id": row.get("id"),
            "channel": "TN",
            "group_key": f"order:{row.get('external_order_id') or row.get('id')}",
            "external_order_id": row.get("external_order_id"),
            "tn_order_number": raw.get("tn_order_number") or tn_raw.get("number"),
            "created_at": row.get("created_at"),
            "display_created_at": raw.get("tn_created_at") or raw.get("tn_paid_at") or raw.get("tn_updated_at") or tn_raw.get("created_at") or row.get("created_at"),
            "customer_name": row.get("customer_name"),
            "customer_fiscal": row.get("customer_fiscal") or {},
            "customer_fiscal_name": row.get("customer_fiscal_name"),
            "customer_doc_type": row.get("customer_doc_type"),
            "customer_doc_number": row.get("customer_doc_number"),
            "customer_iva_condition": row.get("customer_iva_condition"),
            "customer_email": row.get("customer_email"),
            "customer_address": row.get("customer_address"),
            "customer_city": row.get("customer_city"),
            "customer_province": row.get("customer_province"),
            "customer_zip": row.get("customer_zip"),
            "customer_phone": row.get("customer_phone"),
            "total": row.get("total"),
            "status": row.get("status"),
            "tn_status": raw.get("tn_status") or tn_raw.get("status"),
            "tn_payment_status": raw.get("tn_payment_status") or tn_raw.get("payment_status"),
            "tn_shipping_status": raw.get("tn_shipping_status") or tn_raw.get("shipping_status"),
            "tn_shipping_ui_status": tn_ui_status,
            "shipping_ui_status": tn_ui_status,
            "delivery_status": "delivered" if tn_closed_order_counts_as_delivered(raw) else (raw.get("delivery_status") or raw.get("tn_delivery_status")),
            "tn_delivery_status": "delivered" if tn_closed_order_counts_as_delivered(raw) else raw.get("tn_delivery_status"),
            "tn_manual_delivered": bool(raw.get("tn_manual_delivered")),
            "tn_manual_delivered_at": raw.get("tn_manual_delivered_at"),
            "tn_delivered_api_ok": raw.get("tn_delivered_api_ok"),
            "tn_status_closed_at": tn_raw.get("closed_at") or raw.get("tn_closed_at"),
            "tn_next_action": tn_raw.get("next_action") or raw.get("tn_next_action"),
            "shipping_option": shipping_option,
            "whatsapp_notified": bool(raw.get("tn_whatsapp_notified_at")),
            "whatsapp_notified_at": raw.get("tn_whatsapp_notified_at"),
            "sold_lines": raw.get("sold_lines") or [],
            "stock_movements": get_stock_lines_for_order_id(row.get("id")),
        })
    def _tn_sort_value(item):
        v = item.get("tn_order_number") or item.get("external_order_id") or "0"
        digits = re.sub(r"\D+", "", str(v))
        try:
            return int(digits or 0)
        except Exception:
            return 0
    items.sort(key=_tn_sort_value, reverse=True)
    return items


def paginate_items(items: List[Dict[str, Any]], limit: int, offset: int) -> Dict[str, Any]:
    limit = max(1, min(int(limit or 20), 50))
    offset = max(0, int(offset or 0))
    total = len(items)
    page = items[offset:offset + limit]
    return {
        "ok": True,
        "total": total,
        "limit": limit,
        "offset": offset,
        "has_more": offset + limit < total,
        "items": page,
    }


# ARCA_VENTAS_INVOICE_LOGISTICS_VIEW_V13
# Enriquecimiento de las vistas de ventas ML/TN con estado real de facturación.
# El reporte ARCA ya veía los comprobantes porque lee arca_invoices; ventas necesitaba
# la misma unión para no seguir mostrando "Sin factura" después de emitir.
def arca_recent_invoice_label(inv: Dict[str, Any]) -> str:
    try:
        p = str(inv.get("pto_vta") or "").zfill(4)
        n = str(inv.get("cbte_nro") or "").zfill(8) if inv.get("cbte_nro") else "BORRADOR"
        letter = inv.get("cbte_letra") or ("A" if int(inv.get("cbte_tipo") or 0) == 1 else "B")
        return f"FAC {letter} {p}-{n}"
    except Exception:
        return str(inv.get("cbte_tipo_label") or inv.get("status") or "Factura")


def arca_invoice_sort_score(inv: Dict[str, Any]) -> tuple:
    st = str(inv.get("status") or "").lower()
    issued = 1 if (st == "issued" or inv.get("cae")) else 0
    updated = str(inv.get("updated_at") or inv.get("created_at") or "")
    return (issued, updated)


def enrich_recent_items_with_invoice_status(items: List[Dict[str, Any]], channel: str) -> List[Dict[str, Any]]:
    """Agrega invoice_status/invoice_id a tarjetas de ventas.

    Para ML, la factura puede estar asociada al pack madre, al sale_number, a una hija
    o al source_order_api_id. Para TN se usa external_order_id / número TN.
    """
    if not items:
        return items
    ch = str(channel or "").upper()
    try:
        invs = (
            sb.table("arca_invoices")
            .select("id,source_channel,source_order_id,source_order_api_id,source_order_number,source_pack_id,cbte_tipo,cbte_letra,pto_vta,cbte_nro,cae,cae_vto,status,updated_at,created_at,raw_data")
            .eq("source_channel", ch)
            .limit(5000)
            .execute()
            .data
            or []
        )
    except Exception as e:
        for it in items:
            it["invoice_lookup_error"] = str(e)[:250]
        return items

    by_key: Dict[tuple, Dict[str, Any]] = {}
    for inv in invs:
        vals = [
            inv.get("source_order_id"),
            inv.get("source_order_api_id"),
            inv.get("source_order_number"),
            inv.get("source_pack_id"),
        ]
        for v in vals:
            if v in [None, "", 0, "0"]:
                continue
            key = (ch, str(v).lstrip("#"))
            prev = by_key.get(key)
            if not prev or arca_invoice_sort_score(inv) > arca_invoice_sort_score(prev):
                by_key[key] = inv

    def item_keys(it: Dict[str, Any]) -> List[tuple]:
        vals = []
        if ch == "ML":
            vals.extend([
                it.get("sale_number"),
                it.get("ml_sale_number"),
                it.get("ml_pack_id"),
                it.get("external_order_id"),
            ])
            vals.extend(it.get("child_order_ids") or [])
        else:
            vals.extend([
                it.get("tn_order_number"),
                it.get("external_order_id"),
                it.get("source_order_id"),
                it.get("id"),
            ])
        out = []
        seen = set()
        for v in vals:
            if v in [None, "", 0, "0"]:
                continue
            key = (ch, str(v).lstrip("#"))
            if key not in seen:
                out.append(key)
                seen.add(key)
        return out

    for it in items:
        matches = [by_key[k] for k in item_keys(it) if k in by_key]
        if not matches:
            fiscal_check = it.get("ml_fiscal_documents_check")
            if ch == "ML" and isinstance(fiscal_check, dict) and fiscal_check.get("present") is True:
                it["invoice_status"] = "external"
                it["invoice_ml_fiscal_document_present"] = True
                it["invoice_ml_document_count"] = int(fiscal_check.get("document_count") or 0)
                continue
            it["invoice_status"] = it.get("invoice_status") or "none"
            continue
        inv = sorted(matches, key=arca_invoice_sort_score, reverse=True)[0]
        it["invoice_id"] = inv.get("id")
        it["invoice_status"] = inv.get("status") or ("issued" if inv.get("cae") else "draft")
        it["invoice_cae"] = inv.get("cae")
        it["invoice_cae_vto"] = inv.get("cae_vto")
        it["invoice_number"] = arca_recent_invoice_label(inv)
        it["invoice_label"] = arca_recent_invoice_label(inv)
        it["invoice_source_order_id"] = inv.get("source_order_id")
        it["invoice_source_pack_id"] = inv.get("source_pack_id")
        # También dejamos el id fiscal_document de ML si ya quedó registrado en dispatch.
        try:
            raw = inv.get("raw_data") or {}
            dispatch = raw.get("post_issue_dispatch") if isinstance(raw, dict) else None
            ml_up = dispatch.get("ml_upload") if isinstance(dispatch, dict) else None
            if isinstance(ml_up, dict):
                it["invoice_ml_upload_ok"] = bool(ml_up.get("ok"))
                it["invoice_ml_fiscal_documents"] = ml_up.get("fiscal_documents") or ml_up.get("ids")
        except Exception:
            pass
    return items



# REPORTES_VENDEDOR_CLIENTE_FISCAL_V2
# Endpoints vivos del vendedor:
# - /admin/ml/orders/recent
# - /admin/tn/orders/recent
# Ambos enriquecen filas con erp_customers antes de renderizar.

@router.get("/admin/tn/orders/recent")
def recent_tn_sales(
    limit: int = 20,
    offset: int = 0,
    exclude_tests: bool = True,
    q: Optional[str] = Query(default=None),
    token: Optional[str] = Query(default=None),
    x_admin_token: Optional[str] = Header(default=None),
):
    require_admin(token, x_admin_token)
    fetched = fetch_recent_order_rows("TN", limit=limit, offset=offset, exclude_tests=exclude_tests)
    rows = enrich_recent_order_rows_with_customer(fetched["rows"])
    items = build_recent_tn_items(rows)
    items = enrich_recent_items_with_invoice_status(items, "TN")
    items = filter_recent_items(items, q)
    out = paginate_items(items, limit=limit, offset=offset)
    out["exclude_tests"] = exclude_tests
    return out


@router.post("/admin/tn/orders/{order_id}/notify")
def notify_tn_order_endpoint(
    order_id: str,
    force: bool = False,
    token: Optional[str] = Query(default=None),
    x_admin_token: Optional[str] = Header(default=None),
):
    require_admin(token, x_admin_token)

    row = get_order_row("TN", order_id)
    if not row:
        raise HTTPException(status_code=404, detail=f"No existe orden TN aplicada: {order_id}")

    raw = row.get("raw_data") or {}
    if not isinstance(raw, dict):
        raw = {}
    tn_order = raw.get("tn_raw") or {"id": order_id, "number": raw.get("tn_order_number")}

    if order_whatsapp_notified(row) and not force:
        return {"ok": True, "skipped": True, "reason": "Ya estaba notificada"}

    fake_result = {
        "order": row,
        "external_order_id": order_id,
        "sold_lines": raw.get("sold_lines") or [],
        "stock_applied": [],
    }

    # Para el reaviso, reconstruimos stock aplicado desde movimientos.
    movs = (
        sb.table("stock_movements")
        .select("*")
        .eq("reference_id", row.get("id"))
        .order("created_at", desc=False)
        .limit(50)
        .execute()
        .data
        or []
    )
    fake_result["stock_applied"] = [{
        "sku": m.get("sku"),
        "old_stock": m.get("previous_stock"),
        "new_stock": m.get("new_stock"),
        "qty_decrement": abs(int(m.get("quantity") or 0)),
    } for m in movs]

    msg = build_tn_sale_whatsapp_message(fake_result, tn_order)
    notify_result = send_whatsapp_admin(msg)
    if notify_result.get("ok"):
        mark_order_whatsapp_notified(row.get("id"), notify_result)

    return {"ok": bool(notify_result.get("ok")), "forced": force, "notify_result": notify_result}


# ============================================================
# MERCADO LIBRE - LECTURA Y PROCESO DE ÓRDENES
# ============================================================

def ml_headers():
    return {
        "Authorization": f"Bearer {ML_ACCESS_TOKEN}",
        "Content-Type": "application/json",
    }


def ml_can_refresh() -> bool:
    return bool(ML_REFRESH_TOKEN and ML_CLIENT_ID and ML_CLIENT_SECRET)


def ml_validate_config(require_user: bool = True):
    missing = []
    if not ML_ACCESS_TOKEN and not ml_can_refresh():
        missing.append("ML_ACCESS_TOKEN o ML_REFRESH_TOKEN+ML_CLIENT_ID+ML_CLIENT_SECRET")
    if require_user and not ML_USER_ID:
        missing.append("ML_USER_ID")
    if missing:
        raise HTTPException(status_code=500, detail="Faltan variables ML: " + ", ".join(missing))


def ml_refresh_access_token() -> Dict[str, Any]:
    """
    Refresca ML_ACCESS_TOKEN en memoria usando ML_REFRESH_TOKEN.
    No puede escribir variables de Render. Si ML devuelve un refresh_token nuevo,
    se usa en esta instancia hasta el próximo redeploy/restart.
    """
    global ML_ACCESS_TOKEN, ML_REFRESH_TOKEN

    if not ML_REFRESH_TOKEN:
        raise HTTPException(status_code=500, detail="ML_REFRESH_TOKEN no configurado")
    if not ML_CLIENT_ID:
        raise HTTPException(status_code=500, detail="ML_CLIENT_ID/ML_APP_ID no configurado")
    if not ML_CLIENT_SECRET:
        raise HTTPException(status_code=500, detail="ML_CLIENT_SECRET/ML_APP_SECRET no configurado")

    url = "https://api.mercadolibre.com/oauth/token"
    payload = {
        "grant_type": "refresh_token",
        "client_id": ML_CLIENT_ID,
        "client_secret": ML_CLIENT_SECRET,
        "refresh_token": ML_REFRESH_TOKEN,
    }
    headers = {
        "accept": "application/json",
        "content-type": "application/x-www-form-urlencoded",
    }

    try:
        r = requests.post(url, data=payload, headers=headers, timeout=45)
    except Exception as e:
        raise HTTPException(status_code=502, detail=f"Error refrescando token ML: {str(e)}")

    try:
        body = r.json()
    except Exception:
        body = {"raw": r.text[:2000]}

    if r.status_code not in (200, 201):
        raise HTTPException(status_code=502, detail={
            "message": "ML refresh token falló",
            "status_code": r.status_code,
            "response": body,
            "runtime": {
                "client_id_set": bool(ML_CLIENT_ID),
                "client_secret_set": bool(ML_CLIENT_SECRET),
                "refresh_token_set": bool(ML_REFRESH_TOKEN),
            },
        })

    access = body.get("access_token")
    if not access:
        raise HTTPException(status_code=502, detail={"message": "ML no devolvió access_token", "response": body})

    ML_ACCESS_TOKEN = access
    if body.get("refresh_token"):
        ML_REFRESH_TOKEN = body.get("refresh_token")

    return {
        "ok": True,
        "access_token": mask_secret(ML_ACCESS_TOKEN),
        "refresh_token": mask_secret(ML_REFRESH_TOKEN),
        "expires_in": body.get("expires_in"),
        "scope": body.get("scope"),
        "user_id": body.get("user_id"),
        "note": "Token actualizado en memoria de esta instancia Render. Si ML rotó refresh_token, actualizar variable en Render cuando corresponda.",
    }


def ml_request(
    method: str,
    url: str,
    params: Optional[Dict[str, Any]] = None,
    json: Any = None,
    data: Any = None,
    timeout: int = 45,
    extra_headers: Optional[Dict[str, str]] = None,
) -> requests.Response:
    ml_validate_config(require_user=False)
    method = (method or "GET").upper().strip()

    def build_headers() -> Dict[str, str]:
        headers = ml_headers()
        if extra_headers:
            headers.update(extra_headers)
        return headers

    def do_request() -> requests.Response:
        return requests.request(method, url, headers=build_headers(), params=params or {}, json=json, data=data, timeout=timeout)

    try:
        r = do_request()
    except Exception as e:
        raise HTTPException(status_code=502, detail=f"Error conectando con ML: {str(e)}")

    if r.status_code == 401 and ml_can_refresh():
        ml_refresh_access_token()
        try:
            r = do_request()
        except Exception as e:
            raise HTTPException(status_code=502, detail=f"Error conectando con ML luego de refresh: {str(e)}")

    return r


def ml_get_json(url: str, params: Optional[Dict[str, Any]] = None, timeout: int = 45) -> Any:
    r = ml_request("GET", url, params=params or {}, timeout=timeout)
    if r.status_code != 200:
        raise HTTPException(status_code=502, detail=f"ML GET {r.status_code}: {r.text}")
    return r.json()


def ml_get_json_for_active_tenant(
    url: str,
    params: Optional[Dict[str, Any]] = None,
    timeout: int = 60,
) -> Any:
    tenant_id = str(get_effective_tenant_id() or DEFAULT_TENANT_ID)
    if _tenant_token_row(tenant_id, "ml"):
        return _tenant_ml_get_json(tenant_id, url, params=params or {}, timeout=timeout)
    return ml_get_json(url, params=params or {}, timeout=timeout)


def ml_response_preview(r: requests.Response, max_chars: int = 5000) -> Dict[str, Any]:
    """
    Devuelve una vista segura/corta de una respuesta ML para debug.
    Incluye headers de respuesta no sensibles porque ML usa X-Version para stock.
    """
    content_type = r.headers.get("content-type", "")
    body_text = r.text or ""
    parsed: Any = None
    is_json = False

    safe_headers: Dict[str, str] = {}
    for hk, hv in (r.headers or {}).items():
        lk = str(hk).lower()
        if lk in {"authorization", "cookie", "set-cookie", "x-meli-session-id"}:
            continue
        # Guardamos headers útiles para debugging/versionado, sin secretos.
        if (
            "version" in lk
            or lk in {"etag", "last-modified", "date", "content-type", "x-request-id", "x-correlation-id"}
            or lk.startswith("x-")
        ):
            safe_headers[str(hk)] = str(hv)[:500]

    base = {
        "status_code": r.status_code,
        "ok": 200 <= r.status_code < 300,
        "content_type": content_type,
        "headers": safe_headers,
    }

    if "json" in content_type.lower() or body_text.strip().startswith(("{", "[")):
        try:
            parsed = r.json()
            is_json = True
        except Exception:
            parsed = None

    if is_json:
        base["json"] = parsed
        return base

    base["text"] = body_text[:max_chars]
    base["truncated"] = len(body_text) > max_chars
    return base


def ml_debug_get(path_or_url: str, params: Optional[Dict[str, Any]] = None, timeout: int = 45) -> Dict[str, Any]:
    """
    GET ML de diagnóstico: no falla si ML devuelve 4xx/5xx.
    Sirve para descubrir endpoints reales de stock sin romper el flujo.
    """
    if path_or_url.startswith("http://") or path_or_url.startswith("https://"):
        url = path_or_url
    else:
        url = "https://api.mercadolibre.com" + path_or_url

    try:
        r = ml_request("GET", url, params=params or {}, timeout=timeout)
        out = ml_response_preview(r)
        out["url"] = url
        if params:
            out["params"] = params
        return out
    except HTTPException as e:
        return {
            "url": url,
            "params": params or {},
            "ok": False,
            "exception": "HTTPException",
            "detail": e.detail,
        }
    except Exception as e:
        return {
            "url": url,
            "params": params or {},
            "ok": False,
            "exception": type(e).__name__,
            "detail": str(e),
        }


def ml_debug_write(
    path_or_url: str,
    method: str,
    payload: Dict[str, Any],
    timeout: int = 45,
    extra_headers: Optional[Dict[str, str]] = None,
) -> Dict[str, Any]:
    """
    Request ML de diagnóstico para escritura no-op.
    No falla ante 4xx/5xx: devuelve status/body para descubrir ruta/método real.
    Permite probar headers extra como X-Version sin alterar el flujo general.
    """
    if path_or_url.startswith("http://") or path_or_url.startswith("https://"):
        url = path_or_url
    else:
        url = "https://api.mercadolibre.com" + path_or_url

    method_clean = method.upper().strip()
    headers_extra = dict(extra_headers or {})

    try:
        if headers_extra:
            headers = ml_headers()
            headers.update(headers_extra)
            try:
                r = requests.request(method_clean, url, headers=headers, json=payload, timeout=timeout)
            except Exception as e:
                raise HTTPException(status_code=502, detail=f"Error conectando con ML: {str(e)}")

            if r.status_code == 401 and ml_can_refresh():
                ml_refresh_access_token()
                headers = ml_headers()
                headers.update(headers_extra)
                try:
                    r = requests.request(method_clean, url, headers=headers, json=payload, timeout=timeout)
                except Exception as e:
                    raise HTTPException(status_code=502, detail=f"Error conectando con ML luego de refresh: {str(e)}")
        else:
            r = ml_request(method_clean, url, json=payload, timeout=timeout)

        out = ml_response_preview(r, max_chars=2500)
        out["url"] = url
        out["method"] = method_clean
        out["payload"] = payload
        out["extra_headers_sent"] = headers_extra
        return out
    except HTTPException as e:
        return {
            "url": url,
            "method": method_clean,
            "payload": payload,
            "extra_headers_sent": headers_extra,
            "ok": False,
            "exception": "HTTPException",
            "detail": e.detail,
        }
    except Exception as e:
        return {
            "url": url,
            "method": method_clean,
            "payload": payload,
            "extra_headers_sent": headers_extra,
            "ok": False,
            "exception": type(e).__name__,
            "detail": str(e),
        }


def ml_extract_location_quantity(stock_json: Dict[str, Any], location_type: str = "selling_address") -> Optional[int]:
    """Devuelve quantity de una location en /user-products/{id}/stock."""
    if not isinstance(stock_json, dict):
        return None
    for loc in stock_json.get("locations") or []:
        if isinstance(loc, dict) and loc.get("type") == location_type:
            try:
                return int(loc.get("quantity"))
            except Exception:
                return None
    return None


def build_ml_stock_write_candidates_debug(
    item_id: str,
    user_product_id: Optional[str] = None,
    quantity: Optional[int] = None,
) -> Dict[str, Any]:
    """
    Prueba candidatos de escritura de stock ML con cantidad actual.

    Es un test no-op: por defecto usa el quantity actual de selling_address,
    para que si alguna ruta funciona no cambie stock operativo.
    """
    item_id = str(item_id or "").strip()
    user_product_id = str(user_product_id or "").strip() or None
    if not item_id and not user_product_id:
        raise HTTPException(status_code=400, detail="Falta item_id o user_product_id")

    item_res = None
    item_json = {}
    if item_id:
        item_res = ml_debug_get(f"/items/{item_id}", timeout=60)
        item_json = item_res.get("json") or {}
        if isinstance(item_json, dict):
            user_product_id = user_product_id or item_json.get("user_product_id")

    if not user_product_id:
        raise HTTPException(status_code=400, detail="No pude resolver user_product_id")

    stock_before_res = ml_debug_get(f"/user-products/{user_product_id}/stock", timeout=60)
    stock_before_json = stock_before_res.get("json") or {}
    current_qty = ml_extract_location_quantity(stock_before_json, "selling_address")
    meli_qty = ml_extract_location_quantity(stock_before_json, "meli_facility")

    if quantity is None:
        if current_qty is None:
            raise HTTPException(status_code=400, detail="No pude leer quantity actual de selling_address")
        quantity_to_send = int(current_qty)
    else:
        quantity_to_send = int(quantity)

    payloads = {
        "quantity_only": {"quantity": quantity_to_send},
        "type_quantity": {"type": "selling_address", "quantity": quantity_to_send},
        "locations_array": {"locations": [{"type": "selling_address", "quantity": quantity_to_send}]},
        "available_quantity": {"available_quantity": quantity_to_send},
    }

    paths = {
        "up_stock_type_selling_address": f"/user-products/{user_product_id}/stock/type/selling_address",
        "up_stock_locations_selling_address": f"/user-products/{user_product_id}/stock/locations/selling_address",
        "up_stock_selling_address": f"/user-products/{user_product_id}/stock/selling_address",
        "up_locations_selling_address_stock": f"/user-products/{user_product_id}/locations/selling_address/stock",
        "up_stock_locations": f"/user-products/{user_product_id}/stock/locations",
    }

    methods = ["PUT", "PATCH", "POST"]
    results = []

    for path_name, path in paths.items():
        for payload_name, payload in payloads.items():
            for method in methods:
                res = ml_debug_write(path, method=method, payload=payload, timeout=60)
                results.append({
                    "path_name": path_name,
                    "payload_name": payload_name,
                    "method": method,
                    "ok": res.get("ok"),
                    "status_code": res.get("status_code"),
                    "url": res.get("url"),
                    "payload": payload,
                    "response": res,
                })

                # Si alguno funciona, frenamos para minimizar escrituras repetidas.
                if res.get("ok"):
                    stock_after = ml_debug_get(f"/user-products/{user_product_id}/stock", timeout=60)
                    return {
                        "ok": True,
                        "version": APP_VERSION,
                        "mode": "noop_write_candidate_test",
                        "item_id": item_id,
                        "user_product_id": user_product_id,
                        "quantity_sent": quantity_to_send,
                        "selling_address_before": current_qty,
                        "meli_facility_before": meli_qty,
                        "stock_before": stock_before_res,
                        "first_success": results[-1],
                        "attempts": results,
                        "stock_after": stock_after,
                        "note": "Se frenó en el primer candidato OK. La cantidad enviada fue la misma que la actual para no cambiar stock.",
                    }

    stock_after = ml_debug_get(f"/user-products/{user_product_id}/stock", timeout=60)
    return {
        "ok": False,
        "version": APP_VERSION,
        "mode": "noop_write_candidate_test",
        "item_id": item_id,
        "user_product_id": user_product_id,
        "quantity_sent": quantity_to_send,
        "selling_address_before": current_qty,
        "meli_facility_before": meli_qty,
        "stock_before": stock_before_res,
        "attempts": results,
        "stock_after": stock_after,
        "note": "Ningún candidato devolvió 2xx. La cantidad enviada fue la misma que la actual para no cambiar stock.",
    }



def build_ml_stock_xversion_candidates_debug(
    item_id: str,
    user_product_id: Optional[str] = None,
    quantity: Optional[int] = None,
) -> Dict[str, Any]:
    """
    Segundo test no-op: MercadoLibre respondió "Missing X-Version header"
    para PUT /user-products/{id}/stock/type/selling_address.
    Probamos valores posibles de X-Version con la cantidad actual.
    """
    item_id = str(item_id or "").strip()
    user_product_id = str(user_product_id or "").strip() or None
    if not item_id and not user_product_id:
        raise HTTPException(status_code=400, detail="Falta item_id o user_product_id")

    if item_id:
        item_res = ml_debug_get(f"/items/{item_id}", timeout=60)
        item_json = item_res.get("json") or {}
        if isinstance(item_json, dict):
            user_product_id = user_product_id or item_json.get("user_product_id")

    if not user_product_id:
        raise HTTPException(status_code=400, detail="No pude resolver user_product_id")

    stock_before_res = ml_debug_get(f"/user-products/{user_product_id}/stock", timeout=60)
    stock_before_json = stock_before_res.get("json") or {}
    current_qty = ml_extract_location_quantity(stock_before_json, "selling_address")
    meli_qty = ml_extract_location_quantity(stock_before_json, "meli_facility")

    if quantity is None:
        if current_qty is None:
            raise HTTPException(status_code=400, detail="No pude leer quantity actual de selling_address")
        quantity_to_send = int(current_qty)
    else:
        quantity_to_send = int(quantity)

    path = f"/user-products/{user_product_id}/stock/type/selling_address"

    payloads = {
        "quantity_only": {"quantity": quantity_to_send},
        "type_quantity": {"type": "selling_address", "quantity": quantity_to_send},
        "locations_array": {"locations": [{"type": "selling_address", "quantity": quantity_to_send}]},
        "available_quantity": {"available_quantity": quantity_to_send},
    }

    # Integraly muestra columna "Stock (x-version)" y variable xVersion.
    # Probamos valores chicos y v2, porque en el DLL también aparece app_version=v2.
    x_versions = [
        "1",
        "2",
        "3",
        "v1",
        "v2",
        "2023-01-01",
        "2023-08-01",
        "2023-10-01",
    ]

    attempts = []
    for xver in x_versions:
        for payload_name, payload in payloads.items():
            res = ml_debug_write(
                path,
                method="PUT",
                payload=payload,
                timeout=60,
                extra_headers={"X-Version": xver},
            )
            attempts.append({
                "x_version": xver,
                "payload_name": payload_name,
                "method": "PUT",
                "ok": res.get("ok"),
                "status_code": res.get("status_code"),
                "url": res.get("url"),
                "payload": payload,
                "response": res,
            })

            if res.get("ok"):
                stock_after = ml_debug_get(f"/user-products/{user_product_id}/stock", timeout=60)
                return {
                    "ok": True,
                    "version": APP_VERSION,
                    "mode": "noop_xversion_candidate_test",
                    "item_id": item_id,
                    "user_product_id": user_product_id,
                    "quantity_sent": quantity_to_send,
                    "selling_address_before": current_qty,
                    "meli_facility_before": meli_qty,
                    "stock_before": stock_before_res,
                    "first_success": attempts[-1],
                    "attempts": attempts,
                    "stock_after": stock_after,
                    "note": "Se frenó en el primer candidato OK. La cantidad enviada fue la misma que la actual para no cambiar stock.",
                }

    stock_after = ml_debug_get(f"/user-products/{user_product_id}/stock", timeout=60)
    return {
        "ok": False,
        "version": APP_VERSION,
        "mode": "noop_xversion_candidate_test",
        "item_id": item_id,
        "user_product_id": user_product_id,
        "quantity_sent": quantity_to_send,
        "selling_address_before": current_qty,
        "meli_facility_before": meli_qty,
        "stock_before": stock_before_res,
        "attempts": attempts,
        "stock_after": stock_after,
        "note": "Ningún X-Version probado devolvió 2xx. La cantidad enviada fue la misma que la actual para no cambiar stock.",
    }


