# ============================================================
# ERP CUSTOMERS / ENRIQUECIMIENTO CLIENTES ML-TN
# ============================================================

def pc_digits(value: Any) -> str:
    return re.sub(r"\D+", "", str(value or ""))


def pc_clean_str(value: Any) -> Optional[str]:
    if value is None:
        return None
    s = str(value).strip()
    return s if s else None


def pc_phone_norm(value: Any) -> Optional[str]:
    d = pc_digits(value)
    if not d:
        return None
    # Normalización suave AR: no inventa, solo deja dígitos comparables.
    if d.startswith("00"):
        d = d[2:]
    return d or None


def pc_doc_norm(value: Any) -> Optional[str]:
    d = pc_digits(value)
    return d or None


def pc_email_norm(value: Any) -> Optional[str]:
    s = pc_clean_str(value)
    if not s or "@" not in s:
        return None
    return s.lower()


def pc_deep_values_by_key(obj: Any, wanted_keys: List[str], max_hits: int = 20) -> List[Any]:
    wanted = {normalizar(k) for k in wanted_keys}
    hits: List[Any] = []

    def walk(x: Any):
        if len(hits) >= max_hits:
            return
        if isinstance(x, dict):
            for k, v in x.items():
                if normalizar(k) in wanted and v not in [None, "", [], {}]:
                    hits.append(v)
                    if len(hits) >= max_hits:
                        return
                walk(v)
        elif isinstance(x, list):
            for it in x:
                walk(it)
                if len(hits) >= max_hits:
                    return

    walk(obj)
    return hits


def pc_first_nonempty(*values: Any) -> Optional[str]:
    for v in values:
        if isinstance(v, dict):
            # Algunos campos TN vienen multi idioma.
            v = v.get("es") or v.get("en") or v.get("pt") or next(iter(v.values()), None)
        s = pc_clean_str(v)
        if s:
            return s
    return None


def pc_first_email(*objects_or_values: Any) -> Optional[str]:
    for obj in objects_or_values:
        if isinstance(obj, (dict, list)):
            vals = pc_deep_values_by_key(obj, ["email", "contact_email", "billing_email", "customer_email"], max_hits=10)
            for v in vals:
                e = pc_email_norm(v)
                if e:
                    return e
        else:
            e = pc_email_norm(obj)
            if e:
                return e
    return None


def pc_first_phone(*objects_or_values: Any) -> Optional[str]:
    key_names = [
        "phone", "telephone", "contact_phone", "billing_phone", "customer_phone",
        "receiver_phone", "shipping_phone", "number", "phone_number"
    ]
    for obj in objects_or_values:
        if isinstance(obj, dict):
            # Prioridad a estructuras conocidas para no agarrar cualquier "number".
            for direct in [
                obj.get("contact_phone"), obj.get("billing_phone"), obj.get("shipping_phone"),
                obj.get("receiver_phone"), obj.get("phone"),
            ]:
                if isinstance(direct, dict):
                    p = pc_phone_norm("".join([str(direct.get("area_code") or ""), str(direct.get("number") or "")]))
                else:
                    p = pc_phone_norm(direct)
                if p:
                    return p
            vals = pc_deep_values_by_key(obj, key_names, max_hits=20)
            for v in vals:
                if isinstance(v, dict):
                    p = pc_phone_norm("".join([str(v.get("area_code") or ""), str(v.get("number") or "")]))
                else:
                    p = pc_phone_norm(v)
                if p and len(p) >= 8:
                    return p
        else:
            p = pc_phone_norm(obj)
            if p:
                return p
    return None


def pc_extract_doc_from_any(obj: Any) -> Dict[str, Optional[str]]:
    """Extrae documento con cuidado. No usa cualquier 'number' global salvo dentro de billing/documentos."""
    billing_candidates = []
    if isinstance(obj, dict):
        for k in ["billing_info", "billing", "invoice", "customer", "buyer"]:
            v = obj.get(k)
            if v:
                billing_candidates.append(v)
        billing_candidates.append(obj)
    else:
        billing_candidates.append(obj)

    doc_type = None
    doc_number = None
    for b in billing_candidates:
        if not isinstance(b, (dict, list)):
            continue
        for v in pc_deep_values_by_key(b, ["doc_number", "document_number", "identification_number", "tax_id", "cuit", "dni"], max_hits=10):
            n = pc_doc_norm(v)
            if n and len(n) >= 7:
                doc_number = n
                break
        if doc_number:
            for v in pc_deep_values_by_key(b, ["doc_type", "document_type", "identification_type", "taxpayer_type"], max_hits=10):
                s = pc_clean_str(v)
                if s:
                    doc_type = s.upper()
                    break
            break
    return {"doc_type": doc_type, "doc_number": doc_number}


def pc_guess_iva_condition(doc_type: Optional[str], doc_number: Optional[str], raw: Any) -> Optional[str]:
    # Si la plataforma lo trae explícito, se prioriza.
    vals = pc_deep_values_by_key(raw, ["iva_condition", "taxpayer_type", "tax_condition", "fiscal_condition", "condicion_iva"], max_hits=10)
    for v in vals:
        s = pc_clean_str(v)
        if s:
            return s
    dt = normalizar(doc_type)
    dn = pc_doc_norm(doc_number)
    if dt in ["cuit", "cu_it"] or (dn and len(dn) == 11):
        return "Responsable Inscripto / Monotributo a verificar"
    if dt in ["dni", "du"] or (dn and 7 <= len(dn) <= 8):
        return "Consumidor Final"
    return None


def pc_address_line_from_parts(*parts: Any) -> Optional[str]:
    vals = [pc_clean_str(p) for p in parts if pc_clean_str(p)]
    return " ".join(vals) if vals else None


def ml_get_shipment_safe(shipping_id: Any) -> Optional[Dict[str, Any]]:
    sid = pc_clean_str(shipping_id)
    if not sid:
        return None
    try:
        return ml_get_json_for_active_tenant(
            f"https://api.mercadolibre.com/shipments/{sid}",
            timeout=60,
        )
    except Exception as e:
        return {"_error": str(e), "id": sid}


def ml_billing_additional_map(billing_detail: Any) -> Dict[str, str]:
    """
    ML devuelve datos fiscales dentro de billing_info.additional_info:
    [{"type":"DOC_NUMBER","value":"..."}, ...]
    Los pasamos a dict para priorizar facturación.
    """
    out: Dict[str, str] = {}
    if not isinstance(billing_detail, dict):
        return out

    bi = billing_detail.get("billing_info")
    if isinstance(bi, dict):
        rows = bi.get("additional_info") or []
    else:
        rows = billing_detail.get("additional_info") or []

    if isinstance(rows, list):
        for row in rows:
            if not isinstance(row, dict):
                continue
            k = pc_clean_str(row.get("type"))
            v = pc_clean_str(row.get("value"))
            if k and v:
                out[k.upper()] = v
    return out


def ml_billing_info_core(billing_detail: Any) -> Dict[str, Any]:
    if not isinstance(billing_detail, dict):
        return {}
    bi = billing_detail.get("billing_info")
    return bi if isinstance(bi, dict) else billing_detail


def pc_normalize_ml_iva_condition(value: Any) -> Optional[str]:
    s0 = pc_clean_str(value)
    s = normalizar(s0)
    if not s:
        return None
    if "responsable" in s and "inscripto" in s:
        return "IVA Responsable Inscripto"
    if "monotrib" in s:
        return "Monotributo"
    if "consumidor" in s and "final" in s:
        return "Consumidor Final"
    if "exento" in s:
        return "IVA Exento"
    return s0


def ml_billing_id_from_order(order: Dict[str, Any]) -> Optional[str]:
    buyer = order.get("buyer") or {}
    candidates = [
        ((order.get("billing_info") or {}).get("id") if isinstance(order.get("billing_info"), dict) else None),
        ((buyer.get("billing_info") or {}).get("id") if isinstance(buyer.get("billing_info"), dict) else None),
    ]
    return pc_first_nonempty(*candidates)


def ml_get_billing_info_safe(order_id: Any, billing_id: Any = None) -> Optional[Dict[str, Any]]:
    oid = pc_clean_str(order_id)
    bid = pc_clean_str(billing_id)
    errors = []
    # ML cambió históricamente estos recursos; probamos ambos sin romper el flujo.
    endpoints = []
    if oid:
        endpoints.append(("order_billing_info", f"https://api.mercadolibre.com/orders/{oid}/billing_info"))
    if bid:
        endpoints.append(("billing_info_by_id", f"https://api.mercadolibre.com/billing_info/{bid}"))
    for source, ep in endpoints:
        try:
            data = ml_get_json_for_active_tenant(ep, timeout=60)
            if isinstance(data, dict):
                data["_ml_billing_source"] = source
            return data
        except Exception as e:
            errors.append({"source": source, "endpoint": ep, "error": str(e)})
    return {"_errors": errors, "id": bid, "order_id": oid} if errors else None


def pc_customer_from_ml_order(order: Dict[str, Any], shipment: Optional[Dict[str, Any]] = None, billing_detail: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
    buyer = order.get("buyer") or {}
    billing = order.get("billing_info") or buyer.get("billing_info") or {}
    billing_detail = billing_detail or {}
    shipping = order.get("shipping") or {}
    shipment = shipment or {}
    receiver_address = shipment.get("receiver_address") or {}

    billing_core = ml_billing_info_core(billing_detail)
    billing_extra = ml_billing_additional_map(billing_detail)
    billing_person_name = " ".join(
        x for x in [
            pc_clean_str(billing_extra.get("FIRST_NAME")),
            pc_clean_str(billing_extra.get("LAST_NAME")),
        ]
        if x
    ).strip() or None

    billing_fiscal_name = pc_first_nonempty(
        billing_extra.get("BUSINESS_NAME"),
        billing_person_name,
        billing_core.get("business_name"), billing_core.get("name"), billing_core.get("legal_name"),
        billing_detail.get("business_name"), billing_detail.get("name"), billing_detail.get("legal_name"),
        billing_detail.get("razon_social"), billing_detail.get("company_name"),
        billing.get("business_name"), billing.get("name"), billing.get("legal_name"),
    )
    fiscal_name = billing_fiscal_name
    display_name = billing_fiscal_name
    name_source = "billing" if billing_fiscal_name else "missing_billing_name"
    doc = pc_extract_doc_from_any({"billing_detail": billing_detail, "billing_info": billing, "buyer": buyer, "order": order})
    if not doc.get("doc_number"):
        doc = {
            "doc_type": pc_first_nonempty(billing_extra.get("DOC_TYPE"), billing_core.get("doc_type")),
            "doc_number": pc_doc_norm(pc_first_nonempty(billing_extra.get("DOC_NUMBER"), billing_core.get("doc_number"))),
        }

    # Para facturación, domicilio fiscal de billing_info tiene prioridad sobre dirección de envío.
    fiscal_address = pc_address_line_from_parts(
        pc_first_nonempty(billing_extra.get("STREET_NAME")),
        pc_first_nonempty(billing_extra.get("STREET_NUMBER")),
    )
    address = pc_first_nonempty(
        fiscal_address,
        receiver_address.get("address_line"),
        pc_address_line_from_parts(receiver_address.get("street_name"), receiver_address.get("street_number")),
        pc_address_line_from_parts(receiver_address.get("address"), receiver_address.get("comment")),
    )
    city = pc_first_nonempty(
        billing_extra.get("CITY_NAME"),
        (receiver_address.get("city") or {}).get("name") if isinstance(receiver_address.get("city"), dict) else receiver_address.get("city")
    )
    state = pc_first_nonempty(
        billing_extra.get("STATE_NAME"),
        (receiver_address.get("state") or {}).get("name") if isinstance(receiver_address.get("state"), dict) else receiver_address.get("state")
    )
    zip_code = pc_first_nonempty(billing_extra.get("ZIP_CODE"), receiver_address.get("zip_code"), receiver_address.get("zip"))

    phone = pc_first_phone(receiver_address, shipment, buyer, order)
    email = pc_first_email(billing_detail, buyer, billing, order)

    iva_condition = pc_normalize_ml_iva_condition(
        pc_first_nonempty(
            billing_extra.get("TAXPAYER_TYPE_ID"),
            billing_extra.get("TAX_CONDITION"),
            billing_extra.get("FISCAL_CONDITION"),
            billing_core.get("taxpayer_type"),
            billing_core.get("tax_condition"),
        )
    ) or pc_guess_iva_condition(doc.get("doc_type"), doc.get("doc_number"), {"billing_detail": billing_detail, "order": order, "shipment": shipment})

    return {
        "source_origin": "ML",
        "source_label": "MercadoLibre",
        "source_customer_id": pc_clean_str(buyer.get("id")),
        "name": display_name,
        "fiscal_name": fiscal_name,
        "doc_type": doc.get("doc_type"),
        "doc_number": doc.get("doc_number"),
        "iva_condition": iva_condition,
        "email": email,
        "phone": phone,
        "address": address,
        "city": city,
        "province": state,
        "zip": zip_code,
        "ml_user_id": pc_clean_str(buyer.get("id")),
        "tn_customer_id": None,
        "last_order_channel": "ML",
        "last_order_id": pc_clean_str(order.get("id")),
        "last_order_date": pc_clean_str(order.get("date_closed") or order.get("date_created")),
        "notes": "Origen: MercadoLibre",
        "raw_data": {
            "ml_order": order,
            "ml_shipment": shipment,
            "ml_billing_info": billing_detail,
            "customer_name_source": name_source,
        },
    }


def pc_as_dict(v: Any) -> Dict[str, Any]:
    return v if isinstance(v, dict) else {}


def pc_customer_from_tn_order(order: Dict[str, Any]) -> Dict[str, Any]:
    customer = pc_as_dict(order.get("customer"))
    billing = pc_as_dict(order.get("billing_address"))
    shipping = pc_as_dict(order.get("shipping_address"))

    contact_name = order.get("contact_name")
    contact_email = order.get("contact_email")
    contact_phone = order.get("contact_phone")
    contact_identification = order.get("contact_identification")
    contact_address = order.get("contact_address")

    doc = pc_extract_doc_from_any({
        "customer": customer,
        "billing": billing,
        "shipping": shipping,
        "order": order,
        "contact_identification": contact_identification,
    })
    if not doc.get("doc_number"):
        ci = pc_clean_str(contact_identification)
        ci_num = pc_doc_norm(ci)
        if ci_num:
            doc = {
                "doc_type": "CUIT" if len(ci_num) == 11 else ("DNI" if 7 <= len(ci_num) <= 8 else None),
                "doc_number": ci_num,
            }

    billing_fiscal_name = pc_first_nonempty(billing.get("name"))
    fiscal_name = billing_fiscal_name
    name = fiscal_name

    email = pc_first_email(customer, billing, shipping, contact_email, order)
    phone = pc_first_phone(customer, billing, shipping, contact_phone, order)

    address = pc_first_nonempty(
        billing.get("address"),
        billing.get("address1"),
        shipping.get("address"),
        shipping.get("address1"),
        contact_address,
        order.get("contact_address"),
    )
    city = pc_first_nonempty(
        billing.get("city"),
        shipping.get("city"),
        order.get("contact_city"),
    )
    province = pc_first_nonempty(
        billing.get("province"),
        billing.get("state"),
        shipping.get("province"),
        shipping.get("state"),
        order.get("contact_province"),
        order.get("contact_state"),
    )
    zip_code = pc_first_nonempty(
        billing.get("zipcode"),
        billing.get("zip"),
        shipping.get("zipcode"),
        shipping.get("zip"),
        order.get("contact_zipcode"),
        order.get("contact_zip"),
    )

    tn_customer_id = pc_first_nonempty(customer.get("id"), order.get("customer_id"))

    return {
        "source_origin": "TN",
        "source_label": "TiendaNube",
        "source_customer_id": pc_clean_str(tn_customer_id),
        "name": name,
        "fiscal_name": fiscal_name,
        "doc_type": doc.get("doc_type"),
        "doc_number": doc.get("doc_number"),
        "iva_condition": pc_guess_iva_condition(doc.get("doc_type"), doc.get("doc_number"), {"customer": customer, "billing": billing, "shipping": shipping, "order": order}),
        "email": email,
        "phone": phone,
        "address": address,
        "city": city,
        "province": province,
        "zip": zip_code,
        "ml_user_id": None,
        "tn_customer_id": pc_clean_str(tn_customer_id),
        "last_order_channel": "TN",
        "last_order_id": pc_clean_str(order.get("id")),
        "last_order_date": pc_clean_str(order.get("paid_at") or order.get("created_at") or order.get("completed_at") or order.get("updated_at")),
        "notes": "Origen: TiendaNube",
        "raw_data": {
            "tn_order": order,
            "customer_name_source": "billing" if billing_fiscal_name else "customer",
        },
    }


def pc_find_customer_existing(c: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    tenant_id = str(c.get("tenant_id") or get_effective_tenant_id() or DEFAULT_TENANT_ID)
    # Match prioritario por documento, después teléfono, después email.
    searches = []
    if c.get("doc_number"):
        searches.append(("doc_number", c.get("doc_number")))
    if c.get("phone"):
        searches.append(("phone", c.get("phone")))
    if c.get("email"):
        searches.append(("email", c.get("email")))
    for field, value in searches:
        rows = (
            sb.table("erp_customers")
            .select("*")
            .eq("tenant_id", tenant_id)
            .eq(field, value)
            .limit(1)
            .execute()
            .data
            or []
        )
        if rows:
            return rows[0]
    return None


def pc_customer_update_payload(existing: Dict[str, Any], incoming: Dict[str, Any]) -> Dict[str, Any]:
    payload: Dict[str, Any] = {}
    # Completa datos faltantes sin pisar datos mejores ya cargados.
    fill_if_empty = [
        "source_origin", "source_label", "source_customer_id", "name", "fiscal_name",
        "doc_type", "doc_number", "iva_condition", "email", "phone", "address", "city",
        "province", "zip", "ml_user_id", "tn_customer_id", "notes",
    ]
    for k in fill_if_empty:
        if incoming.get(k) not in [None, "", [], {}] and existing.get(k) in [None, "", [], {}]:
            payload[k] = incoming.get(k)

    # Billing/ARCA names are canonical and replace a previous marketplace contact name.
    incoming_raw = incoming.get("raw_data") or {}
    incoming_name_source = incoming_raw.get("customer_name_source") if isinstance(incoming_raw, dict) else None
    canonical_name = pc_first_nonempty(incoming.get("fiscal_name"), incoming.get("name"))
    if incoming_name_source in {"billing", "arca"} and canonical_name:
        if existing.get("name") != canonical_name:
            payload["name"] = canonical_name
        if existing.get("fiscal_name") != canonical_name:
            payload["fiscal_name"] = canonical_name

    # Estos sí se actualizan siempre porque representan última compra.
    for k in ["last_order_channel", "last_order_id", "last_order_date"]:
        if incoming.get(k) not in [None, ""]:
            payload[k] = incoming.get(k)

    raw_old = existing.get("raw_data") or {}
    if not isinstance(raw_old, dict):
        raw_old = {"previous": raw_old}
    raw_new = incoming.get("raw_data") or {}
    if isinstance(raw_new, dict):
        raw_old.setdefault("sources", [])
        raw_old["sources"].append(raw_new)
        raw_old["sources"] = raw_old["sources"][-20:]
        payload["raw_data"] = raw_old

    payload["updated_at"] = now_iso()
    return payload


def pc_upsert_customer(incoming: Dict[str, Any], dry_run: bool = True) -> Dict[str, Any]:
    # Limpieza previa para que los matches sean consistentes.
    incoming = dict(incoming or {})
    incoming["doc_number"] = pc_doc_norm(incoming.get("doc_number"))
    incoming["phone"] = pc_phone_norm(incoming.get("phone"))
    incoming["email"] = pc_email_norm(incoming.get("email"))
    tenant_id = str(incoming.get("tenant_id") or get_effective_tenant_id() or DEFAULT_TENANT_ID)
    incoming["tenant_id"] = tenant_id

    existing = pc_find_customer_existing(incoming)
    if existing:
        update_payload = pc_customer_update_payload(existing, incoming)
        if dry_run:
            return {"action": "would_update", "id": existing.get("id"), "match": existing, "update": update_payload, "customer": incoming}
        if update_payload:
            (
                sb.table("erp_customers")
                .update(update_payload)
                .eq("id", existing.get("id"))
                .eq("tenant_id", tenant_id)
                .execute()
            )
        return {"action": "updated", "id": existing.get("id"), "update": update_payload, "customer": incoming}

    row = {
        "id": str(uuid.uuid4()),
        "tenant_id": tenant_id,
        "company_id": "planetacasa",
        "source_origin": incoming.get("source_origin"),
        "source_label": incoming.get("source_label"),
        "source_customer_id": incoming.get("source_customer_id"),
        "name": incoming.get("name"),
        "fiscal_name": incoming.get("fiscal_name"),
        "doc_type": incoming.get("doc_type"),
        "doc_number": incoming.get("doc_number"),
        "iva_condition": incoming.get("iva_condition"),
        "email": incoming.get("email"),
        "phone": incoming.get("phone"),
        "address": incoming.get("address"),
        "city": incoming.get("city"),
        "province": incoming.get("province"),
        "zip": incoming.get("zip"),
        "ml_user_id": incoming.get("ml_user_id"),
        "tn_customer_id": incoming.get("tn_customer_id"),
        "last_order_channel": incoming.get("last_order_channel"),
        "last_order_id": incoming.get("last_order_id"),
        "last_order_date": incoming.get("last_order_date"),
        "notes": incoming.get("notes"),
        "marketing_email_opt_in": False,
        "marketing_whatsapp_opt_in": False,
        "raw_data": {"sources": [incoming.get("raw_data") or {}]},
        "created_at": now_iso(),
        "updated_at": now_iso(),
    }
    if dry_run:
        return {"action": "would_insert", "id": row["id"], "customer": row}
    sb.table("erp_customers").insert(row).execute()
    return {"action": "inserted", "id": row["id"], "customer": row}


def pc_update_order_raw_with_customer(channel: str, external_order_id: str, customer_result: Dict[str, Any], dry_run: bool = True) -> None:
    if dry_run:
        return
    try:
        row = get_order_row(channel, external_order_id)
        if not row:
            return
        raw = row.get("raw_data") or {}
        if not isinstance(raw, dict):
            raw = {"previous_raw_data": raw}
        raw["customer_enrichment"] = {
            "at": now_iso(),
            "customer_action": customer_result.get("action"),
            "customer_id": customer_result.get("id"),
        }
        customer = customer_result.get("customer") or {}
        canonical_name = pc_first_nonempty(customer.get("fiscal_name"), customer.get("name"))
        update_payload = {"raw_data": raw, "updated_at": now_iso()}
        if canonical_name and str(channel or "").upper() != "ML":
            update_payload["customer_name"] = canonical_name
        tenant_id = str(get_effective_tenant_id() or DEFAULT_TENANT_ID)
        (
            sb.table("orders")
            .update(update_payload)
            .eq("id", row.get("id"))
            .eq("tenant_id", tenant_id)
            .execute()
        )
    except Exception:
        return


def pc_exception_detail(e: Exception) -> Any:
    if isinstance(e, HTTPException):
        return {"status_code": e.status_code, "detail": e.detail}
    return str(e)


def arca_manual_debug_error(e: Exception, body: Any = None, stage: str = "manual_emit") -> Dict[str, Any]:
    """Detalle seguro para errores ARCA/manual. No incluye token/cert/key."""
    detail = pc_exception_detail(e)
    body_dump = None
    try:
        body_dump = body.model_dump() if hasattr(body, "model_dump") else body
    except Exception:
        body_dump = str(body)
    safe_body = {}
    if isinstance(body_dump, dict):
        for k in [
            "dry_run", "confirmar", "cbte_tipo", "invoice_date", "concept",
            "customer_name", "customer_doc_type", "customer_doc_number", "customer_iva_condition",
            "source_channel", "source_order_id", "associated_invoice_id",
            "associated_cbte_tipo", "associated_pto_vta", "associated_cbte_nro", "associated_invoice_date",
            "modifica_stock", "stock_movement_reason", "lines",
        ]:
            if k in body_dump:
                safe_body[k] = body_dump.get(k)
    return {
        "error": "ARCA/manual comprobante falló",
        "stage": stage,
        "version": APP_VERSION,
        "exception_type": type(e).__name__,
        "detail": detail,
        "message": str(e),
        "environment": "produccion",
        "pto_vta": ARCA_PTO_VTA,
        "safe_body": safe_body,
        "trace_tail": traceback.format_exc().splitlines()[-12:],
    }


def pc_enrich_ml_customer_arca_first_for_order(order: Dict[str, Any], dry_run: bool = True) -> Dict[str, Any]:
    """Crea/actualiza cliente ML con prioridad ARCA y fallback ML.

    Flujo definido:
    1) ML aporta documento y datos completos de respaldo.
    2) ARCA se consulta primero con ese documento.
    3) Si ARCA responde, se guarda ARCA.
    4) Si ARCA falla, se guarda ML como fallback para no perder cliente.
    """
    order_id = str((order or {}).get("id") or "").strip()
    if not order_id:
        return {"ok": False, "source": "NONE", "error": "Orden ML sin id"}

    sid = ml_order_shipping_id(order)
    shipment = ml_get_shipment_safe(sid)
    billing_id = ml_billing_id_from_order(order)
    billing_detail = ml_get_billing_info_safe(order.get("id"), billing_id)
    ml_customer = pc_customer_from_ml_order(order, shipment=shipment, billing_detail=billing_detail)

    doc_type = pc_clean_str(ml_customer.get("doc_type")) or "DNI"
    doc_number = pc_doc_norm(ml_customer.get("doc_number"))
    if doc_number:
        try:
            item = ArcaPadronFiscalOrderIn(
                channel="ML",
                external_order_id=order_id,
                doc_type=doc_type,
                doc_number=doc_number,
            )
            arca_result = arca_upsert_customer_from_padron_order(item, dry_run=dry_run)
            return {
                "ok": True,
                "source": "ARCA",
                "dry_run": dry_run,
                "order_id": order_id,
                "shipping_id": sid,
                "billing_id": billing_id,
                "ml_doc_type": doc_type,
                "ml_doc_number": doc_number,
                "arca_result": arca_result,
            }
        except Exception as e:
            # Fallback explícito a datos ML, dejando trazabilidad del fallo ARCA.
            ml_customer.setdefault("raw_data", {})
            if isinstance(ml_customer["raw_data"], dict):
                ml_customer["raw_data"]["arca_first_error"] = pc_exception_detail(e)
            result = pc_upsert_customer(ml_customer, dry_run=dry_run)
            pc_update_order_raw_with_customer("ML", order_id, result, dry_run=dry_run)
            return {
                "ok": True,
                "source": "ML_FALLBACK_AFTER_ARCA_ERROR",
                "dry_run": dry_run,
                "order_id": order_id,
                "shipping_id": sid,
                "billing_id": billing_id,
                "ml_doc_type": doc_type,
                "ml_doc_number": doc_number,
                "arca_error": pc_exception_detail(e),
                "customer": ml_customer,
                "result": result,
            }

    result = pc_upsert_customer(ml_customer, dry_run=dry_run)
    pc_update_order_raw_with_customer("ML", order_id, result, dry_run=dry_run)
    return {
        "ok": True,
        "source": "ML_FALLBACK_NO_DOCUMENT",
        "dry_run": dry_run,
        "order_id": order_id,
        "shipping_id": sid,
        "billing_id": billing_id,
        "customer": ml_customer,
        "result": result,
    }


def pc_enrich_recent_ml_customers(limit: int = 10, dry_run: bool = True) -> Dict[str, Any]:
    limit = max(1, min(int(limit or 10), 50))
    orders = ml_list_orders(limit=limit, offset=0)
    items = []
    errors = []
    for order in orders:
        try:
            enrich_result = pc_enrich_ml_customer_arca_first_for_order(order, dry_run=dry_run)
            items.append({"order_id": order.get("id"), "enrichment": enrich_result})
        except Exception as e:
            errors.append({"order_id": order.get("id"), "error": str(e)})
    return {"ok": len(errors) == 0, "channel": "ML", "dry_run": dry_run, "limit": limit, "processed": len(items), "errors": errors, "items": items}


def pc_enrich_recent_tn_customers(limit: int = 10, dry_run: bool = True) -> Dict[str, Any]:
    limit = max(1, min(int(limit or 10), 50))
    orders = tn_list_orders(page=1, per_page=limit)
    items = []
    errors = []
    for order in orders:
        try:
            c = pc_customer_from_tn_order(order)
            result = pc_upsert_customer(c, dry_run=dry_run)
            pc_update_order_raw_with_customer("TN", str(order.get("id")), result, dry_run=dry_run)
            items.append({"order_id": order.get("id"), "order_number": order.get("number"), "customer": c, "result": result})
        except Exception as e:
            errors.append({"order_id": order.get("id"), "error": str(e)})
    return {"ok": len(errors) == 0, "channel": "TN", "dry_run": dry_run, "limit": limit, "processed": len(items), "errors": errors, "items": items}


