@router.get("/admin/customers/recent")
def recent_customers_endpoint(
    request: Request,
    limit: int = 50,
    channel: Optional[str] = Query(default=None),
    q: Optional[str] = Query(default=None),
    token: Optional[str] = Query(default=None),
    x_admin_token: Optional[str] = Header(default=None),
    x_session_token: Optional[str] = Header(default=None),
    session_token: Optional[str] = Query(default=None),
    authorization: Optional[str] = Header(default=None),
):
    session = _inventory_auth_session_or_admin(
        request,
        token,
        x_admin_token,
        x_session_token,
        session_token,
        authorization,
    )
    tenant_id = str(
        (session or {}).get("tenant_id")
        or tenant_id_from_request(request)
        or get_effective_tenant_id()
        or DEFAULT_TENANT_ID
    )
    limit = max(1, min(int(limit or 50), 500))
    ch = norm_sku(channel).upper() if channel else ""
    search = normalizar(q or "")

    # IMPORTANTE:
    # No asumimos columnas fijas de erp_customers. En algunas bases/versiones la tabla
    # no tiene todos los campos fiscales/comerciales todavía, y un select con columnas
    # inexistentes rompe todo el menú de clientes con "Error clientes: {}".
    # Traemos filas completas y filtramos/ordenamos defensivamente en Python.
    fetch_limit = 2000 if search or not ch else max(500, limit * 6)
    rows = (
        sb.table("erp_customers")
        .select("*")
        .limit(fetch_limit)
        .execute()
        .data
        or []
    )
    rows = [c for c in rows if not c.get("tenant_id") or str(c.get("tenant_id")) == tenant_id]

    def customer_channel(c: Dict[str, Any]) -> str:
        vals = [
            c.get("last_order_channel"),
            c.get("channel"),
            c.get("source_channel"),
            c.get("source_origin"),
            c.get("source"),
            c.get("marketplace"),
        ]
        blob = normalizar(" ".join(str(v or "") for v in vals))
        if "mercado" in blob or "ml" in blob:
            return "ML"
        if "tienda" in blob or "tn" in blob or "nube" in blob:
            return "TN"
        if "manual" in blob or "arca" in blob:
            return "MANUAL"
        return (str(c.get("last_order_channel") or c.get("channel") or "").upper().strip())

    if ch in ["ML", "TN", "MANUAL"]:
        rows = [c for c in rows if customer_channel(c) == ch]

    if search:
        def haystack(c: Dict[str, Any]) -> str:
            vals = []
            for k in [
                "fiscal_name", "name", "display_name", "source_label", "nickname",
                "doc_type", "doc_number", "email", "phone", "address", "city", "province", "zip",
                "last_order_channel", "channel", "last_order_id", "ml_user_id", "tn_user_id", "tn_customer_id",
            ]:
                vals.append(c.get(k))
            return normalizar(" ".join(str(v or "") for v in vals))
        rows = [c for c in rows if search in haystack(c)]

    def customer_sort_key(c: Dict[str, Any]):
        name = (
            c.get("fiscal_name") or c.get("name") or c.get("display_name") or
            c.get("source_label") or c.get("nickname") or c.get("doc_number") or ""
        )
        return (normalizar(name), customer_channel(c), normalizar(c.get("doc_number") or ""))

    rows = sorted(rows, key=customer_sort_key)
    sliced = rows[:limit]
    return {
        "ok": True,
        "version": APP_VERSION,
        "limit": limit,
        "channel": ch or None,
        "query": q or "",
        "total": len(rows),
        "items": sliced,
    }


@router.post("/admin/customers/update")
def update_customer_endpoint(
    request: Request,
    body: CustomerUpdateIn,
    token: Optional[str] = Query(default=None),
    x_admin_token: Optional[str] = Header(default=None),
    x_session_token: Optional[str] = Header(default=None),
    session_token: Optional[str] = Query(default=None),
    authorization: Optional[str] = Header(default=None),
):
    session = _inventory_auth_session_or_admin(
        request,
        token,
        x_admin_token,
        x_session_token,
        session_token,
        authorization,
    )
    tenant_id = str(
        (session or {}).get("tenant_id")
        or tenant_id_from_request(request)
        or get_effective_tenant_id()
        or DEFAULT_TENANT_ID
    )
    existing_rows = sb.table("erp_customers").select("*").eq("id", body.id).limit(1).execute().data or []
    if not existing_rows:
        raise HTTPException(status_code=404, detail="Cliente no encontrado")
    existing = existing_rows[0]
    existing_cols = set(existing.keys())
    if existing.get("tenant_id") and str(existing.get("tenant_id")) != tenant_id:
        raise HTTPException(status_code=404, detail="Cliente no encontrado")

    allowed = ["name", "fiscal_name", "doc_type", "doc_number", "iva_condition", "email", "phone", "address", "city", "province", "zip"]
    payload = {}
    ignored_missing_columns = []
    for k in allowed:
        if getattr(body, k) is not None:
            if k in existing_cols:
                v = getattr(body, k)
                payload[k] = str(v).strip() if v is not None else None
            else:
                ignored_missing_columns.append(k)

    if not payload:
        return {
            "ok": True,
            "version": APP_VERSION,
            "item": existing,
            "unchanged": True,
            "ignored_missing_columns": ignored_missing_columns,
        }

    if "updated_at" in existing_cols:
        payload["updated_at"] = now_iso()

    update_q = sb.table("erp_customers").update(payload).eq("id", body.id)
    if "tenant_id" in existing_cols:
        update_q = update_q.eq("tenant_id", tenant_id)
    rows = update_q.execute().data or []
    item = rows[0] if rows else {**existing, **payload}
    return {
        "ok": True,
        "version": APP_VERSION,
        "item": item,
        "ignored_missing_columns": ignored_missing_columns,
    }



