# ============================================================
# ML SHIPPING REFRESH TENANT-AWARE
# ============================================================

def _ml_tenant_refresh_access_token(tenant_id: str, token_row: Dict[str, Any]) -> Dict[str, Any]:
    """Refresca token ML tenant-specific y persiste el nuevo access_token en api_tokens."""
    if not _sb_raw:
        raise HTTPException(status_code=500, detail="DATABASE_URL/AWS Postgres no configurado")
    refresh_token = pc_clean_str((token_row or {}).get("refresh_token"))
    if not refresh_token:
        raise HTTPException(status_code=401, detail="Token ML tenant sin refresh_token")
    if not ML_CLIENT_ID or not ML_CLIENT_SECRET:
        raise HTTPException(status_code=500, detail="ML_CLIENT_ID/ML_CLIENT_SECRET no configurados para refresh tenant-aware")

    try:
        r = requests.post(
            "https://api.mercadolibre.com/oauth/token",
            data={
                "grant_type": "refresh_token",
                "client_id": ML_CLIENT_ID,
                "client_secret": ML_CLIENT_SECRET,
                "refresh_token": refresh_token,
            },
            headers={"accept": "application/json", "content-type": "application/x-www-form-urlencoded"},
            timeout=45,
        )
    except Exception as exc:
        raise HTTPException(status_code=502, detail=f"Error refrescando token ML tenant: {exc}") from exc

    try:
        body = r.json()
    except Exception:
        body = {"raw": r.text[:2000]}

    if r.status_code not in (200, 201):
        raise HTTPException(status_code=502, detail={"message": "ML refresh tenant falló", "status_code": r.status_code, "response": body})

    access_token = body.get("access_token")
    if not access_token:
        raise HTTPException(status_code=502, detail={"message": "ML refresh tenant no devolvió access_token", "response": body})

    now = _utcnow()
    expires_at = None
    try:
        if body.get("expires_in"):
            expires_at = (now + timedelta(seconds=int(body.get("expires_in")))).isoformat()
    except Exception:
        expires_at = None

    payload = {
        "access_token": access_token,
        "refresh_token": body.get("refresh_token") or refresh_token,
        "expires_at": expires_at,
        "updated_at": now.isoformat(),
        "tenant_id": tenant_id,
    }
    _sb_raw.table("api_tokens").update(payload).eq("provider", f"ml:{tenant_id}").execute()
    merged = dict(token_row or {})
    merged.update(payload)
    return merged


_ML_TENANT_TOKEN_REFRESH_LOCK = threading.Lock()


def _ml_tenant_request_json(
    tenant_id: str,
    method: str,
    url: str,
    params: Optional[Dict[str, Any]] = None,
    timeout: int = 45,
) -> Any:
    token_row = _tenant_token_row(tenant_id, "ml")
    if not token_row or not token_row.get("access_token"):
        raise HTTPException(status_code=401, detail=f"Mercado Libre no conectado para tenant {tenant_id}")

    method_clean = (method or "GET").upper().strip()

    def do_request(row: Dict[str, Any]) -> requests.Response:
        return requests.request(
            method_clean,
            url,
            params=params or {},
            headers={"Authorization": f"Bearer {row.get('access_token')}", "accept": "application/json"},
            timeout=timeout,
        )

    try:
        r = do_request(token_row)
    except Exception as exc:
        raise HTTPException(status_code=502, detail=f"Error conectando con ML tenant: {exc}") from exc

    if r.status_code == 401 and token_row.get("refresh_token"):
        # Varias ventas visibles pueden responder 401 al mismo tiempo. Un único
        # hilo rota el refresh token; los demás reutilizan el token ya guardado.
        with _ML_TENANT_TOKEN_REFRESH_LOCK:
            latest = _tenant_token_row(tenant_id, "ml") or {}
            if latest.get("access_token") and latest.get("access_token") != token_row.get("access_token"):
                token_row = latest
            else:
                token_row = _ml_tenant_refresh_access_token(tenant_id, token_row)
        try:
            r = do_request(token_row)
        except Exception as exc:
            raise HTTPException(status_code=502, detail=f"Error conectando con ML tenant luego de refresh: {exc}") from exc

    if r.status_code < 200 or r.status_code >= 300:
        raise HTTPException(status_code=502, detail={"message": "ML tenant request falló", "status_code": r.status_code, "response": r.text[:2000], "url": url})

    try:
        return r.json()
    except Exception as exc:
        raise HTTPException(status_code=502, detail=f"ML devolvió respuesta no JSON: {exc}") from exc


def _tn_tenant_connection(tenant_id: str) -> Dict[str, str]:
    token_row = _tenant_token_row(tenant_id, "tn") or {}
    access_token = str(token_row.get("access_token") or "").strip()
    settings_row = _tenant_settings_row(tenant_id)
    settings = _settings_blob(settings_row)
    nested = settings.get("tiendanube") if isinstance(settings.get("tiendanube"), dict) else {}
    store_id = str(
        settings.get("tn_store_id")
        or settings.get("tn_user_id")
        or nested.get("store_id")
        or nested.get("user_id")
        or token_row.get("store_id")
        or token_row.get("user_id")
        or ""
    ).strip()
    if not access_token or not store_id:
        raise HTTPException(status_code=401, detail=f"Tienda Nube no conectada para tenant {tenant_id}")
    return {"access_token": access_token, "store_id": store_id}


def _tn_tenant_order_json(tenant_id: str, order_id: str, timeout: int = 45) -> Dict[str, Any]:
    connection = _tn_tenant_connection(tenant_id)
    url = f"https://api.tiendanube.com/v1/{connection['store_id']}/orders/{order_id}"
    try:
        response = requests.get(
            url,
            headers={
                "Authentication": f"bearer {connection['access_token']}",
                "User-Agent": "XelerIAApp (gongol1970@gmail.com)",
                "Content-Type": "application/json",
            },
            timeout=timeout,
        )
    except Exception as exc:
        raise HTTPException(status_code=502, detail=f"Error conectando con TN tenant: {exc}") from exc
    if response.status_code < 200 or response.status_code >= 300:
        raise HTTPException(
            status_code=502,
            detail={
                "message": "TN tenant request falló",
                "status_code": response.status_code,
                "response": response.text[:2000],
                "url": url,
            },
        )
    try:
        payload = response.json()
    except Exception as exc:
        raise HTTPException(status_code=502, detail=f"TN devolvió respuesta no JSON: {exc}") from exc
    if not isinstance(payload, dict):
        raise HTTPException(status_code=502, detail="TN devolvió una orden inválida")
    return payload




def _ml_live_auth_tenant(
    request: Request,
    token: Optional[str] = None,
    x_admin_token: Optional[str] = None,
    authorization: Optional[str] = None,
    session_token: Optional[str] = None,
    x_session_token: Optional[str] = None,
    tenant_id: Optional[str] = None,
) -> str:
    """Autorización de diagnóstico ML.

    Soporta el flujo viejo con ADMIN_TOKEN y también sesión XelerIA.
    No escribe ventas. Sólo puede refrescar/persistir token ML si ML devuelve 401.
    """
    supplied_admin = _clean_admin_token(token) or _clean_admin_token(x_admin_token)
    auth_clean = _clean_admin_token(authorization)

    # Si viene ADMIN_TOKEN por query/header viejo, lo usamos directo.
    # Authorization se trata como sesión cuando tiene forma xses_.
    if supplied_admin or (auth_clean and not auth_clean.startswith("xses_")):
        require_admin(token=token, x_admin_token=x_admin_token, authorization=authorization)
        return str(
            tenant_id
            or tenant_id_from_request(request)
            or get_effective_tenant_id()
            or DEFAULT_TENANT_ID
        )

    session = require_session(request, session_token, x_session_token, authorization)
    return str(session.get("tenant_id") or tenant_id_from_request(request) or get_effective_tenant_id() or DEFAULT_TENANT_ID)


def _ml_tenant_request_debug(
    tenant_id: str,
    method: str,
    url: str,
    params: Optional[Dict[str, Any]] = None,
    timeout: int = 45,
) -> Dict[str, Any]:
    """Consulta ML en vivo para diagnóstico.

    No levanta HTTPException por 404/400 de endpoints secundarios: devuelve status/body.
    Única escritura posible: refresh del access_token en api_tokens si ML devuelve 401.
    """
    token_row = _tenant_token_row(tenant_id, "ml")
    if not token_row or not token_row.get("access_token"):
        raise HTTPException(status_code=401, detail=f"Mercado Libre no conectado para tenant {tenant_id}")

    method_clean = (method or "GET").upper().strip()
    params = params or {}
    token_refreshed = False

    def do_request(row: Dict[str, Any]) -> requests.Response:
        return requests.request(
            method_clean,
            url,
            params=params,
            headers={"Authorization": f"Bearer {row.get('access_token')}", "accept": "application/json"},
            timeout=timeout,
        )

    try:
        r = do_request(token_row)
    except Exception as exc:
        return {
            "ok": False,
            "url": url,
            "params": params,
            "method": method_clean,
            "status_code": None,
            "error": str(exc),
        }

    if r.status_code == 401 and token_row.get("refresh_token"):
        token_row = _ml_tenant_refresh_access_token(tenant_id, token_row)
        token_refreshed = True
        try:
            r = do_request(token_row)
        except Exception as exc:
            return {
                "ok": False,
                "url": url,
                "params": params,
                "method": method_clean,
                "status_code": None,
                "token_refreshed": token_refreshed,
                "error": str(exc),
            }

    body: Any
    try:
        body = r.json()
    except Exception:
        body = r.text[:5000]

    return {
        "ok": 200 <= int(r.status_code or 0) < 300,
        "url": url,
        "params": params,
        "method": method_clean,
        "status_code": r.status_code,
        "token_refreshed": token_refreshed,
        "body": body,
    }


def _ml_live_body(result: Dict[str, Any]) -> Any:
    if isinstance(result, dict):
        return result.get("body")
    return None


def _ml_live_path_result(
    tenant_id: str,
    path: str,
    timeout: int = 45,
    params: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    path_clean = "/" + str(path or "").strip().lstrip("/")
    return _ml_tenant_request_debug(
        tenant_id,
        "GET",
        f"https://api.mercadolibre.com{path_clean}",
        params=params or {},
        timeout=timeout,
    )


def _ml_live_find_local_candidates(sale_id: str, max_scan: int = 500) -> Dict[str, Any]:
    """Resolución read-only desde orders para mapear número visible -> order/shipment real."""
    sale_clean = str(sale_id or "").strip()
    out = {
        "enabled": True,
        "scan_limit": max_scan,
        "matches_count": 0,
        "order_ids": [],
        "shipment_ids": [],
        "pack_ids": [],
        "matches": [],
    }
    if not sale_clean or not sb:
        return out

    try:
        rows = (
            sb.table("orders")
            .select("id,external_order_id,raw_data,created_at,updated_at")
            .eq("channel", "ML")
            .order("created_at", desc=True)
            .limit(max(1, min(int(max_scan or 500), 2000)))
            .execute()
            .data
            or []
        )
    except Exception as exc:
        out["error"] = str(exc)[:1000]
        return out

    order_ids: List[str] = []
    shipment_ids: List[str] = []
    pack_ids: List[str] = []
    matches: List[Dict[str, Any]] = []

    def add_unique(arr: List[str], value: Any):
        v = str(value or "").strip()
        if v and v not in arr:
            arr.append(v)

    for row in rows:
        raw = row_raw_dict(row)
        haystack_values: List[Any] = [
            row.get("external_order_id"),
            raw.get("sale_number"),
            raw.get("ml_sale_number"),
            raw.get("ml_sale_number_from_shipment"),
            raw.get("pack_id"),
            raw.get("ml_pack_id"),
        ]
        try:
            haystack_values.append(ml_detect_sale_number_from_row(row))
        except Exception:
            pass
        for child_id in raw.get("child_order_ids") or []:
            haystack_values.append(child_id)

        if sale_clean not in {str(x or "").strip() for x in haystack_values if x not in [None, "", [], {}]}:
            # Fallback defensivo: algunos dumps viejos sólo tienen el número dentro del raw JSON.
            try:
                if sale_clean not in json.dumps(raw, ensure_ascii=False):
                    continue
            except Exception:
                continue

        external_id = str(row.get("external_order_id") or "").strip()
        shipping_id = _ml_shipping_id_from_order_row(row)
        pack_id = str(raw.get("pack_id") or raw.get("ml_pack_id") or "").strip()

        add_unique(order_ids, external_id)
        for child_id in raw.get("child_order_ids") or []:
            add_unique(order_ids, child_id)
        add_unique(shipment_ids, shipping_id)
        add_unique(pack_ids, pack_id)

        matches.append({
            "db_order_row_id": row.get("id"),
            "external_order_id": external_id,
            "pack_id": pack_id or None,
            "shipping_id": shipping_id,
            "created_at": row.get("created_at"),
            "updated_at": row.get("updated_at"),
            "detected_sale_number": (ml_detect_sale_number_from_row(row) if callable(globals().get("ml_detect_sale_number_from_row")) else None),
            "raw_status": raw.get("ml_shipping_status") or raw.get("shipping_status"),
            "raw_substatus": raw.get("ml_shipping_substatus") or raw.get("shipping_substatus"),
            "raw_ui_status": raw.get("ml_shipping_ui_status") or raw.get("shipping_ui_status"),
        })

    out.update({
        "matches_count": len(matches),
        "order_ids": order_ids,
        "shipment_ids": shipment_ids,
        "pack_ids": pack_ids,
        "matches": matches[:50],
    })
    return out


def _ml_live_collect_shipment(
    tenant_id: str,
    shipping_id: str,
    timeout: int = 45,
) -> Dict[str, Any]:
    sid = str(shipping_id or "").strip()
    if not sid:
        return {}
    endpoints = {
        "shipment": f"/shipments/{sid}",
        "shipment_items": f"/shipments/{sid}/items",
        "shipment_costs": f"/shipments/{sid}/costs",
        "shipment_lead_time": f"/shipments/{sid}/lead_time",
        "shipment_history": f"/shipments/{sid}/history",
    }
    return {name: _ml_live_path_result(tenant_id, path, timeout=timeout) for name, path in endpoints.items()}


def _ml_live_collect_order(
    tenant_id: str,
    order_id: str,
    timeout: int = 45,
) -> Dict[str, Any]:
    oid = str(order_id or "").strip()
    if not oid:
        return {}
    results: Dict[str, Any] = {
        "order": _ml_live_path_result(tenant_id, f"/orders/{oid}", timeout=timeout),
        "billing_info": _ml_live_path_result(tenant_id, f"/orders/{oid}/billing_info", timeout=timeout),
    }

    order_body = _ml_live_body(results.get("order") or {})
    if isinstance(order_body, dict):
        pack_id = order_body.get("pack_id")
        if pack_id not in [None, "", [], {}]:
            results["pack"] = _ml_live_path_result(tenant_id, f"/packs/{pack_id}", timeout=timeout)

        shipping = order_body.get("shipping") if isinstance(order_body.get("shipping"), dict) else {}
        shipping_id = shipping.get("id") if isinstance(shipping, dict) else None
        if shipping_id not in [None, "", [], {}]:
            results["shipping_id_from_order"] = shipping_id
            results["shipping"] = _ml_live_collect_shipment(tenant_id, str(shipping_id), timeout=timeout)

    return results


@router.get("/admin/ml/live/sale/{sale_id}")
def admin_ml_live_sale_debug(
    sale_id: str,
    request: Request,
    resolve_db: bool = Query(default=True),
    max_scan: int = Query(default=500),
    timeout: int = Query(default=45),
    tenant_id: Optional[str] = Query(default=None),
    token: Optional[str] = Query(default=None),
    x_admin_token: Optional[str] = Header(default=None),
    authorization: Optional[str] = Header(default=None),
    session_token: Optional[str] = Query(default=None),
    x_session_token: Optional[str] = Header(default=None),
):
    """Dump read-only ML por número de venta/order.

    No modifica orders/raw_data/stock/sync_jobs. Sólo puede refrescar api_tokens si ML devuelve 401.
    """
    tenant = _ml_live_auth_tenant(
        request,
        token=token,
        x_admin_token=x_admin_token,
        authorization=authorization,
        session_token=session_token,
        x_session_token=x_session_token,
        tenant_id=tenant_id,
    )
    sale_clean = str(sale_id or "").strip()
    if not sale_clean:
        raise HTTPException(status_code=400, detail="sale_id vacío")

    local_resolution = _ml_live_find_local_candidates(sale_clean, max_scan=max_scan) if resolve_db else {"enabled": False}
    candidate_order_ids: List[str] = []
    candidate_shipment_ids: List[str] = []
    candidate_pack_ids: List[str] = []

    def add_unique(arr: List[str], value: Any):
        v = str(value or "").strip()
        if v and v not in arr:
            arr.append(v)

    add_unique(candidate_order_ids, sale_clean)
    for oid in local_resolution.get("order_ids") or []:
        add_unique(candidate_order_ids, oid)
    for sid in local_resolution.get("shipment_ids") or []:
        add_unique(candidate_shipment_ids, sid)
    for pid in local_resolution.get("pack_ids") or []:
        add_unique(candidate_pack_ids, pid)

    order_results = {oid: _ml_live_collect_order(tenant, oid, timeout=timeout) for oid in candidate_order_ids[:20]}

    # Agregamos shipment_ids que aparezcan en la orden viva de ML.
    for bundle in order_results.values():
        order_body = _ml_live_body((bundle or {}).get("order") or {})
        if isinstance(order_body, dict):
            shipping = order_body.get("shipping") if isinstance(order_body.get("shipping"), dict) else {}
            add_unique(candidate_shipment_ids, shipping.get("id") if isinstance(shipping, dict) else None)
            add_unique(candidate_pack_ids, order_body.get("pack_id"))

    shipment_results = {sid: _ml_live_collect_shipment(tenant, sid, timeout=timeout) for sid in candidate_shipment_ids[:20]}
    pack_results = {pid: _ml_live_path_result(tenant, f"/packs/{pid}", timeout=timeout) for pid in candidate_pack_ids[:20]}

    return {
        "ok": True,
        "version": APP_VERSION,
        "source": "mercadolibre_live_api",
        "sale_id_requested": sale_clean,
        "tenant_id": tenant,
        "writes_orders": False,
        "writes_stock": False,
        "writes_sync_jobs": False,
        "reads_orders_for_resolution": bool(resolve_db),
        "may_refresh_ml_token": True,
        "local_resolution": local_resolution,
        "candidate_order_ids": candidate_order_ids,
        "candidate_shipment_ids": candidate_shipment_ids,
        "candidate_pack_ids": candidate_pack_ids,
        "mercadolibre": {
            "orders": order_results,
            "shipments": shipment_results,
            "packs": pack_results,
        },
    }


