def _ml_shipping_id_from_order_row(row: Dict[str, Any]) -> Optional[str]:
    raw = row_raw_dict(row)
    ml_raw = raw.get("ml_raw") or {}
    if not isinstance(ml_raw, dict):
        ml_raw = {}
    shipping = ml_raw.get("shipping") or {}
    if not isinstance(shipping, dict):
        shipping = {}
    snapshot = raw.get("ml_shipping_last_snapshot") if isinstance(raw.get("ml_shipping_last_snapshot"), dict) else {}
    candidates = [
        raw.get("ml_shipping_id"),
        raw.get("shipping_id"),
        raw.get("shipment_id"),
        snapshot.get("id"),
        shipping.get("id"),
    ]
    for c in candidates:
        c = pc_clean_str(c)
        if c:
            return c
    return None


def _ml_shipping_snapshot_value(shipment: Dict[str, Any], key: str) -> Any:
    if not isinstance(shipment, dict):
        return None
    if shipment.get(key) not in [None, "", [], {}]:
        return shipment.get(key)
    shipping_option = shipment.get("shipping_option") if isinstance(shipment.get("shipping_option"), dict) else {}
    if shipping_option.get(key) not in [None, "", [], {}]:
        return shipping_option.get(key)
    return pc_deep_find_first(shipment, [key], max_depth=5)


def _ml_safe_lower(value: Any) -> str:
    cleaned = pc_clean_str(value)
    return cleaned.lower() if cleaned else ""


def _ml_shipping_class_from_snapshot(shipment: Optional[Dict[str, Any]], shipping_id: Optional[str]) -> str:
    if not shipping_id:
        return "A coordinar"
    shipment = shipment or {}
    logistic_type = _ml_safe_lower(_ml_shipping_snapshot_value(shipment, "logistic_type"))
    mode = _ml_safe_lower(_ml_shipping_snapshot_value(shipment, "mode"))
    tags = shipment.get("tags") if isinstance(shipment, dict) else []
    if not isinstance(tags, list):
        tags = [tags]
    tags_blob = " ".join(str(t or "") for t in tags).lower()
    blob = " ".join([logistic_type, mode, tags_blob]).lower()

    if any(x in blob for x in ["self_service", "self service", "flex"]):
        return "FLEX"
    if any(x in blob for x in ["fulfillment", "fulfillment_lite", "full", "meli_facility"]):
        return "FULL"
    return "Mercado Envíos"


def _ml_spanish_date_from_value(value: Any) -> Optional[str]:
    if value in [None, "", [], {}]:
        return None
    if isinstance(value, dict):
        candidates = [
            value.get("date"),
            value.get("from"),
            value.get("to"),
            value.get("estimated_date"),
            value.get("estimated_delivery_date"),
            value.get("handling_date"),
        ]
        for c in candidates:
            out = _ml_spanish_date_from_value(c)
            if out:
                return out
        return None
    if isinstance(value, list):
        for item in value:
            out = _ml_spanish_date_from_value(item)
            if out:
                return out
        return None
    txt = pc_clean_str(value)
    if not txt:
        return None
    try:
        dt = datetime.fromisoformat(txt.replace("Z", "+00:00"))
    except Exception:
        m = re.search(r"(\d{4}-\d{2}-\d{2})", txt)
        if not m:
            return None
        try:
            dt = datetime.fromisoformat(m.group(1))
        except Exception:
            return None
    meses = ["enero", "febrero", "marzo", "abril", "mayo", "junio", "julio", "agosto", "septiembre", "octubre", "noviembre", "diciembre"]
    return f"{dt.day} de {meses[dt.month - 1]}"


def _ml_promised_delivery_label(shipment: Dict[str, Any]) -> Optional[str]:
    if not isinstance(shipment, dict):
        return None

    # Para FULL, la pantalla de ML suele tomar fechas dentro de shipping_option,
    # no date_created/status_history. Evitamos buscar cualquier clave "date"
    # porque eso devolvía la fecha de creación del shipment.
    shipping_option = shipment.get("shipping_option") if isinstance(shipment.get("shipping_option"), dict) else {}
    priority = str((shipping_option.get("priority_class") or {}).get("id") or "") if isinstance(shipping_option.get("priority_class"), dict) else ""
    buffering_date = (shipping_option.get("buffering") or {}).get("date") if isinstance(shipping_option.get("buffering"), dict) else None
    estimated_date = (shipping_option.get("estimated_delivery_time") or {}).get("date") if isinstance(shipping_option.get("estimated_delivery_time"), dict) else None
    final_date = (shipping_option.get("estimated_delivery_final") or {}).get("date") if isinstance(shipping_option.get("estimated_delivery_final"), dict) else None
    limit_date = (shipping_option.get("estimated_delivery_limit") or {}).get("date") if isinstance(shipping_option.get("estimated_delivery_limit"), dict) else None
    extended_date = (shipping_option.get("estimated_delivery_extended") or {}).get("date") if isinstance(shipping_option.get("estimated_delivery_extended"), dict) else None

    if priority == "25":
        candidates = [buffering_date, estimated_date, final_date, limit_date, extended_date, shipment.get("estimated_delivery_time")]
    else:
        candidates = [estimated_date, final_date, limit_date, extended_date, buffering_date, shipment.get("estimated_delivery_time")]

    for c in candidates:
        found = _ml_spanish_date_from_value(c)
        if found:
            return f"Despacharemos el paquete el {found}"
    return None

def _ml_shipping_terminal_from_status(status: Any, substatus: Any) -> bool:
    return shipping_state_is_terminal("ML", status, substatus)



def _ml_shipping_has_real_movement(shipment: Optional[Dict[str, Any]]) -> bool:
    """Detecta movimiento real aunque ML siga devolviendo status=ready_to_ship.

    ML puede dejar el estado actual en ready_to_ship / in_hub / in_packing_list,
    pero el substatus_history muestra que el paquete ya fue dejado o tomado
    (dropped_off / picked_up). En esos casos la UI debe mostrar "En camino" y
    no volver a "Pendiente de colecta".
    """
    if not isinstance(shipment, dict):
        return False

    def clean(value: Any) -> str:
        return _ml_safe_lower(value)

    current_blob = f"{clean(shipment.get('status'))} {clean(shipment.get('substatus') or shipment.get('sub_status'))}"
    if any(x in current_blob for x in ["picked_up", "dropped_off", "in_hub", "shipped", "in_transit", "in_route", "on_the_way"]):
        return True

    status_history = shipment.get("status_history") if isinstance(shipment.get("status_history"), dict) else {}
    if status_history.get("date_shipped"):
        return True

    history = shipment.get("substatus_history")
    if not isinstance(history, list):
        return False

    movement_markers = {
        "dropped_off",
        "picked_up",
        "in_hub",
        "shipped",
        "in_transit",
        "in_route",
        "on_the_way",
    }
    for event in history:
        if not isinstance(event, dict):
            continue
        status = clean(event.get("status"))
        substatus = clean(event.get("substatus") or event.get("sub_status"))
        blob = f"{status} {substatus}"
        if any(marker in blob for marker in movement_markers):
            return True
    return False


def _ml_shipping_ui_status_from_snapshot(shipment: Optional[Dict[str, Any]], ui_type: str, shipping_id: Optional[str]) -> str:
    if not shipping_id:
        return "A coordinar con comprador"
    shipment = shipment or {}
    labels = {
        "ml_shipping_status": shipment.get("status"),
        "ml_shipping_substatus": shipment.get("substatus") or shipment.get("sub_status"),
        "ml_shipping_logistic_type": _ml_shipping_snapshot_value(shipment, "logistic_type"),
        "ml_shipping_mode": _ml_shipping_snapshot_value(shipment, "mode"),
        "ml_shipping_tags": shipment.get("tags") or [],
        "ml_shipping_last_snapshot": shipment,
    }
    status = _ml_safe_lower(labels.get("ml_shipping_status"))
    substatus = _ml_safe_lower(labels.get("ml_shipping_substatus"))
    if _ml_shipping_terminal_from_status(status, substatus):
        base = pc_ml_shipping_ui_status_from_labels(labels)
        return base or "Entregado"
    # ML puede mantener status=ready_to_ship aunque el paquete ya esté en circuito.
    # Si el snapshot actual o su historial muestran dropped_off/picked_up/in_hub,
    # no debe volver a "Pendiente de colecta".
    if _ml_shipping_has_real_movement(shipment):
        return "En camino"
    if ui_type == "FULL":
        promised = _ml_promised_delivery_label(shipment)
        if promised:
            return promised
        return "Procesando en bodega"
    if ui_type == "Mercado Envíos" and ("ready_to_ship" in f"{status} {substatus}" or "ready_to_print" in f"{status} {substatus}"):
        return "Pendiente de colecta o Punto de entrega"
    base = pc_ml_shipping_ui_status_from_labels(labels)
    if base:
        return base
    if ui_type == "FLEX":
        return "Gestionar logística FLEX"
    return ""


def _ml_shipping_payload_from_snapshot(shipping_id: Optional[str], shipment: Optional[Dict[str, Any]], source: str = "ml_api") -> Dict[str, Any]:
    shipment = shipment or {}
    now = _utcnow().isoformat()
    if not shipping_id:
        snapshot = {
            "status": "to_be_agreed",
            "substatus": "to_be_agreed",
            "ui_type": "A coordinar",
            "ui_status": "A coordinar con comprador",
            "source": source,
            "checked_at": now,
        }
        return {
            "ml_shipping_logistic_type": "",
            "ml_shipping_mode": "",
            "ml_shipping_status": "to_be_agreed",
            "ml_shipping_substatus": "to_be_agreed",
            "ml_shipping_tags": [],
            "ml_shipping_estimated_delivery_time": None,
            "ml_shipping_ui_type": "A coordinar",
            "ml_shipping_type": "A coordinar",
            "shipping_type": "A coordinar",
            "ml_shipping_ui_status": "A coordinar con comprador",
            "shipping_ui_status": "A coordinar con comprador",
            "shipping_status": "to_be_agreed",
            "shipping_substatus": "to_be_agreed",
            "ml_shipping_last_snapshot": snapshot,
            "ml_shipping_refreshed_at": now,
            "ml_shipping_tracking_done": True,
            "ml_shipping_refresh_error": None,
        }

    logistic_type = _ml_shipping_snapshot_value(shipment, "logistic_type")
    mode = _ml_shipping_snapshot_value(shipment, "mode")
    tags = shipment.get("tags") if isinstance(shipment.get("tags"), list) else []
    status = shipment.get("status")
    substatus = shipment.get("substatus") or shipment.get("sub_status")
    ui_type = _ml_shipping_class_from_snapshot(shipment, shipping_id)
    ui_status = _ml_shipping_ui_status_from_snapshot(shipment, ui_type, shipping_id)
    terminal = _ml_shipping_terminal_from_status(status, substatus)

    snapshot = dict(shipment)
    snapshot.update({
        "id": shipment.get("id") or shipping_id,
        "logistic_type": logistic_type,
        "mode": mode,
        "status": status,
        "substatus": substatus,
        "tags": tags,
        "ui_type": ui_type,
        "ui_status": ui_status,
        "source": source,
        "checked_at": now,
    })

    return {
        "ml_shipping_logistic_type": logistic_type,
        "ml_shipping_mode": mode,
        "ml_shipping_status": status,
        "ml_shipping_substatus": substatus,
        "ml_shipping_tags": tags,
        "ml_shipping_estimated_delivery_time": shipment.get("estimated_delivery_time"),
        "ml_shipping_ui_type": ui_type,
        "ml_shipping_type": ui_type,
        "shipping_type": ui_type,
        "ml_shipping_ui_status": ui_status,
        "shipping_ui_status": ui_status,
        "shipping_status": status,
        "shipping_substatus": substatus,
        "ml_shipping_last_snapshot": snapshot,
        "ml_shipping_refreshed_at": now,
        "ml_shipping_tracking_done": bool(terminal),
        "ml_shipping_refresh_error": None,
    }


def ml_existing_order_shipping_is_delivered(row: Dict[str, Any]) -> bool:
    """True sólo ante una señal logística exacta; nunca por texto visual parcial."""
    raw = row_raw_dict(row)
    labels = ml_shipping_labels_from_row(row)
    raw_snapshot = raw.get("ml_shipping_last_snapshot") if isinstance(raw.get("ml_shipping_last_snapshot"), dict) else {}
    raw_statuses = [
        labels.get("ml_shipping_status"),
        labels.get("ml_shipping_substatus"),
        labels.get("shipping_status"),
        labels.get("shipping_substatus"),
        raw.get("ml_shipping_status"),
        raw.get("ml_shipping_substatus"),
        raw.get("shipping_status"),
        raw.get("shipping_substatus"),
        raw_snapshot.get("status"),
        raw_snapshot.get("substatus") or raw_snapshot.get("sub_status"),
    ]
    # Una devolución/cancelación explícita gana incluso si quedó un fulfilled
    # histórico, porque no hubo entrega efectiva al comprador.
    if shipping_state_is_cancelled(raw_statuses) or shipping_state_is_returned(raw_statuses):
        return False
    if (
        parse_boolish(labels.get("ml_fulfilled"))
        or parse_boolish(labels.get("fulfilled"))
        or parse_boolish(raw.get("ml_fulfilled"))
        or parse_boolish(raw_snapshot.get("fulfilled"))
    ):
        return True
    return shipping_state_is_delivered(raw_statuses)


def ml_refresh_existing_order_shipping_if_needed(row: Dict[str, Any], force: bool = False) -> Dict[str, Any]:
    """Refresca envío ML de una orden ya capturada, sin duplicar venta ni tocar stock."""
    if not row:
        return {"ok": False, "skipped": True, "reason": "missing_order_row"}

    raw = row_raw_dict(row)
    order_id = str(row.get("external_order_id") or row.get("id") or "").strip()
    shipping_id = _ml_shipping_id_from_order_row(row)

    if not force and ml_existing_order_shipping_is_delivered(row):
        return {
            "ok": True,
            "skipped": True,
            "reason": "shipping_already_delivered",
            "order_id": order_id,
            "shipping_id": shipping_id,
        }

    if not shipping_id:
        return {
            "ok": True,
            "skipped": True,
            "reason": "no_shipping_id",
            "order_id": order_id,
        }

    shipment = ml_get_json(
        f"https://api.mercadolibre.com/shipments/{shipping_id}",
        timeout=60,
    )

    payload = _ml_shipping_payload_from_snapshot(
        shipping_id,
        shipment,
        source="ml_api_existing_order_refresh",
    )

    sale_from_shipment = ml_detect_sale_number_from_shipment(
        shipment,
        child_order_ids=[order_id] if order_id else [],
    )
    if sale_from_shipment:
        payload["ml_sale_number_from_shipment"] = sale_from_shipment

    merged_raw = dict(raw)
    merged_raw.update(payload)

    sb.table("orders").update({
        "raw_data": merged_raw,
        "updated_at": now_iso(),
    }).eq("id", row.get("id")).execute()

    return {
        "ok": True,
        "skipped": False,
        "order_id": order_id,
        "shipping_id": shipping_id,
        "ui_type": payload.get("ml_shipping_ui_type"),
        "ui_status": payload.get("ml_shipping_ui_status"),
        "status": payload.get("ml_shipping_status"),
        "substatus": payload.get("ml_shipping_substatus"),
        "tracking_done": payload.get("ml_shipping_tracking_done"),
    }


@router.post("/admin/ml/orders/refresh-pending-shipping")
def refresh_pending_ml_shipping_endpoint(
    request: Request,
    limit: int = 20,
    force: bool = False,
    session_token: Optional[str] = Query(default=None),
    x_session_token: Optional[str] = Header(default=None),
    authorization: Optional[str] = Header(default=None),
):
    session = require_session(request, session_token, x_session_token, authorization)
    tenant_id = str(session.get("tenant_id") or DEFAULT_TENANT_ID)
    limit = max(1, min(int(limit or 20), 50))
    hard_cap = max(100, limit * 10)

    rows = (
        sb.table("orders")
        .select("*")
        .eq("channel", "ML")
        .order("created_at", desc=True)
        .limit(hard_cap)
        .execute()
        .data
        or []
    )
    rows = [r for r in rows if not is_test_order_row(r)]

    processed: List[Dict[str, Any]] = []
    skipped: List[Dict[str, Any]] = []
    errors: List[Dict[str, Any]] = []

    for row in rows:
        if len(processed) >= limit:
            break
        raw = row_raw_dict(row)
        order_id = str(row.get("external_order_id") or row.get("id") or "").strip()
        sale_number = ml_detect_sale_number_from_row(row)
        shipping_id = _ml_shipping_id_from_order_row(row)

        if not force and ml_existing_order_shipping_is_delivered(row):
            skipped.append({"order_id": order_id, "sale_number": sale_number, "shipping_id": shipping_id, "reason": "shipping_already_delivered"})
            continue

        try:
            if shipping_id:
                shipment = _ml_tenant_request_json(
                    tenant_id,
                    "GET",
                    f"https://api.mercadolibre.com/shipments/{shipping_id}",
                    timeout=60,
                )
                payload = _ml_shipping_payload_from_snapshot(shipping_id, shipment, source="ml_api_tenant")
                sale_from_shipment = ml_detect_sale_number_from_shipment(shipment, child_order_ids=[order_id])
                if sale_from_shipment:
                    payload["ml_sale_number_from_shipment"] = sale_from_shipment
            else:
                # ML puede tener ventas "A coordinar" sin shipment. En ese caso
                # /shipments no existe y el refresh viejo no miraba nada vivo;
                # la verdad está en /orders/{id}.fulfilled.
                live_order = None
                live_shipping_id = ""
                if order_id:
                    live_order = _ml_tenant_request_json(
                        tenant_id,
                        "GET",
                        f"https://api.mercadolibre.com/orders/{order_id}",
                        timeout=60,
                    )
                    if isinstance(live_order, dict):
                        live_shipping = live_order.get("shipping") if isinstance(live_order.get("shipping"), dict) else {}
                        live_shipping_id = str((live_shipping or {}).get("id") or "").strip()

                if live_shipping_id:
                    shipping_id = live_shipping_id
                    shipment = _ml_tenant_request_json(
                        tenant_id,
                        "GET",
                        f"https://api.mercadolibre.com/shipments/{shipping_id}",
                        timeout=60,
                    )
                    payload = _ml_shipping_payload_from_snapshot(shipping_id, shipment, source="ml_api_tenant_from_order")
                    sale_from_shipment = ml_detect_sale_number_from_shipment(shipment, child_order_ids=[order_id])
                    if sale_from_shipment:
                        payload["ml_sale_number_from_shipment"] = sale_from_shipment
                else:
                    now = _utcnow().isoformat()
                    live_order = live_order if isinstance(live_order, dict) else {}
                    live_fulfilled = live_order.get("fulfilled") is True
                    live_status = live_order.get("status") or raw.get("ml_status") or raw.get("ml_shipping_status")
                    live_tags = live_order.get("tags") if isinstance(live_order.get("tags"), list) else []
                    ui_status = "Entregado" if live_fulfilled else (raw.get("ml_shipping_ui_status") or "A coordinar con comprador")
                    payload = {
                        "ml_raw": live_order or raw.get("ml_raw"),
                        "ml_status": live_status,
                        "ml_date_created": live_order.get("date_created") or raw.get("ml_date_created"),
                        "ml_date_closed": live_order.get("date_closed") or raw.get("ml_date_closed"),
                        "ml_fulfilled": bool(live_fulfilled),
                        "ml_shipping_id": None,
                        "ml_shipping_status": "delivered" if live_fulfilled else live_status,
                        "ml_shipping_substatus": None,
                        "ml_shipping_logistic_type": None,
                        "ml_shipping_mode": None,
                        "ml_shipping_tags": live_tags,
                        "ml_shipping_ui_type": raw.get("ml_shipping_ui_type") or raw.get("shipping_type") or "A coordinar",
                        "ml_shipping_ui_status": ui_status,
                        "shipping_ui_status": ui_status,
                        "ml_shipping_last_snapshot": {
                            "id": None,
                            "source": "orders",
                            "status": "delivered" if live_fulfilled else live_status,
                            "substatus": None,
                            "logistic_type": None,
                            "mode": None,
                            "fulfilled": bool(live_fulfilled),
                            "tags": live_tags,
                            "date_updated": live_order.get("last_updated") or live_order.get("date_last_updated"),
                        },
                        "ml_shipping_refreshed_at": now,
                    }
                    if live_fulfilled:
                        payload["ml_shipping_is_final"] = True
                        payload["ml_shipping_tracking_done"] = True

            merged_raw = dict(raw)
            merged_raw.update(payload)
            if merged_raw.get("ml_shipping_refresh_error") and payload.get("ml_shipping_refreshed_at"):
                merged_raw.pop("ml_shipping_refresh_error", None)
            sb.table("orders").update({"raw_data": merged_raw, "updated_at": _utcnow().isoformat()}).eq("id", row.get("id")).execute()
            updated_row = dict(row)
            updated_row["raw_data"] = merged_raw
            auto_invoice = None
            if arca_order_is_delivered_for_auto_invoice("ML", updated_row):
                invoice_source = str(merged_raw.get("ml_pack_id") or order_id)
                auto_invoice = arca_auto_invoice_order_safe("ML", invoice_source) if invoice_source else None

            processed.append({
                "order_id": order_id,
                "sale_number": sale_number or payload.get("ml_sale_number_from_shipment"),
                "shipping_id": shipping_id,
                "ui_type": payload.get("ml_shipping_ui_type"),
                "ui_status": payload.get("ml_shipping_ui_status"),
                "status": payload.get("ml_shipping_status"),
                "substatus": payload.get("ml_shipping_substatus"),
                "logistic_type": payload.get("ml_shipping_logistic_type"),
                "mode": payload.get("ml_shipping_mode"),
                "tracking_done": payload.get("ml_shipping_tracking_done"),
                "auto_invoice": auto_invoice,
            })
        except HTTPException as exc:
            err_payload = {
                "ml_shipping_refresh_error": exc.detail,
                "ml_shipping_refreshed_at": _utcnow().isoformat(),
            }
            try:
                merged_raw = dict(raw)
                merged_raw.update(err_payload)
                sb.table("orders").update({"raw_data": merged_raw, "updated_at": _utcnow().isoformat()}).eq("id", row.get("id")).execute()
            except Exception:
                pass
            errors.append({"order_id": order_id, "sale_number": sale_number, "shipping_id": shipping_id, "error": exc.detail})
        except Exception as exc:
            err_payload = {
                "ml_shipping_refresh_error": str(exc)[:1000],
                "ml_shipping_refreshed_at": _utcnow().isoformat(),
            }
            try:
                merged_raw = dict(raw)
                merged_raw.update(err_payload)
                sb.table("orders").update({"raw_data": merged_raw, "updated_at": _utcnow().isoformat()}).eq("id", row.get("id")).execute()
            except Exception:
                pass
            errors.append({"order_id": order_id, "sale_number": sale_number, "shipping_id": shipping_id, "error": str(exc)[:1000]})

    return {
        "ok": len(errors) == 0,
        "version": APP_VERSION,
        "tenant_id": tenant_id,
        "limit": limit,
        "processed_count": len(processed),
        "skipped_count": len(skipped),
        "errors_count": len(errors),
        "processed": processed,
        "skipped": skipped[:50],
        "errors": errors[:50],
    }



def _pc_normalize_ml_shipping_label(value: Any) -> Any:
    """Normaliza labels visibles de envío ML antes de devolver /recent."""
    txt = str(value or "").strip()
    if not txt:
        return value
    broken = txt.replace("EnvÃ­os", "Envíos").replace("Envios", "Envíos")
    low = broken.lower()
    if low == "full":
        return "FULL"
    if low == "flex":
        return "FLEX"
    if "coordinar" in low or "to_be_agreed" in low or "not_specified" in low:
        return "A coordinar"
    if "mercado" in low and ("env" in low or "shipping" in low):
        return "Mercado Envíos"
    return broken


def _pc_merge_ml_recent_shipping_fields(items: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    """Asegura que /admin/ml/orders/recent exponga top-level los campos de envío.

    El refresh tenant-aware guarda todo en orders.raw_data. Esta vista agrupa ventas,
    por eso no alcanza con tener el dato en DB: hay que copiarlo al item final que lee
    el frontend.
    """
    if not items:
        return items

    wanted_ids = []
    for it in items:
        vals = [it.get("external_order_id")]
        vals.extend(it.get("child_order_ids") or [])
        for v in vals:
            s = str(v or "").strip()
            if s and s not in wanted_ids:
                wanted_ids.append(s)

    rows_by_id: Dict[str, Dict[str, Any]] = {}
    if _sb_raw and wanted_ids:
        try:
            for i in range(0, len(wanted_ids), 100):
                chunk = wanted_ids[i:i + 100]
                rows = (
                    _sb_raw.table("orders")
                    .select("id,external_order_id,raw_data")
                    .eq("channel", "ML")
                    .in_("external_order_id", chunk)
                    .execute()
                    .data
                    or []
                )
                for r in rows:
                    oid = str(r.get("external_order_id") or "").strip()
                    if oid:
                        rows_by_id[oid] = r
        except Exception as exc:
            for it in items:
                it["ml_recent_shipping_merge_error"] = str(exc)[:250]

    keys = [
        "ml_shipping_id",
        "ml_shipping_ui_type",
        "ml_shipping_type",
        "shipping_type",
        "ml_shipping_ui_status",
        "shipping_ui_status",
        "ml_shipping_logistic_type",
        "ml_shipping_mode",
        "ml_shipping_status",
        "ml_shipping_substatus",
        "shipping_status",
        "shipping_substatus",
        "ml_shipping_tags",
        "ml_shipping_estimated_delivery_time",
        "ml_shipping_refreshed_at",
        "ml_shipping_tracking_done",
        "ml_shipping_last_snapshot",
        "ml_shipment_error",
        "ml_sale_number_from_shipment",
    ]

    for it in items:
        candidate_rows = []
        for v in [it.get("external_order_id")] + list(it.get("child_order_ids") or []):
            r = rows_by_id.get(str(v or "").strip())
            if r:
                candidate_rows.append(r)

        selected_labels = None
        for r in candidate_rows:
            labels = ml_shipping_labels_from_row(r)
            raw = row_raw_dict(r)
            if (
                labels.get("ml_shipping_ui_type")
                or labels.get("ml_shipping_logistic_type")
                or labels.get("ml_shipping_last_snapshot")
                or raw.get("ml_shipping_ui_type")
            ):
                selected_labels = labels
                break
        if selected_labels is None and candidate_rows:
            selected_labels = ml_shipping_labels_from_row(candidate_rows[0])

        labels = selected_labels or {}
        for k in keys:
            v = labels.get(k)
            if v not in [None, "", [], {}]:
                it[k] = v

        ui_type = _pc_normalize_ml_shipping_label(
            it.get("ml_shipping_ui_type")
            or it.get("shipping_type")
            or it.get("ml_shipping_type")
        )
        if ui_type not in [None, ""]:
            it["ml_shipping_ui_type"] = ui_type
            it["ml_shipping_type"] = ui_type
            it["shipping_type"] = ui_type

        if it.get("ml_shipping_id") not in [None, ""]:
            it["shipping_id"] = it.get("ml_shipping_id")
        if it.get("ml_pack_id") not in [None, ""]:
            it["pack_id"] = it.get("ml_pack_id")

        if it.get("ml_shipping_status") not in [None, ""]:
            it["shipping_status"] = it.get("ml_shipping_status")
        if it.get("ml_shipping_substatus") not in [None, ""]:
            it["shipping_substatus"] = it.get("ml_shipping_substatus")
        if it.get("ml_shipping_ui_status") not in [None, ""]:
            it["shipping_ui_status"] = it.get("ml_shipping_ui_status")

        if not it.get("shipping_type"):
            tmp = {
                "raw_data": {
                    "ml_shipping_logistic_type": it.get("ml_shipping_logistic_type"),
                    "ml_shipping_mode": it.get("ml_shipping_mode"),
                    "ml_shipping_status": it.get("ml_shipping_status"),
                    "ml_shipping_substatus": it.get("ml_shipping_substatus"),
                    "ml_shipping_tags": it.get("ml_shipping_tags"),
                    "ml_shipping_last_snapshot": it.get("ml_shipping_last_snapshot"),
                    "ml_shipping_id": it.get("ml_shipping_id"),
                }
            }
            labels2 = ml_shipping_labels_from_row(tmp)
            ui_type2 = _pc_normalize_ml_shipping_label(labels2.get("ml_shipping_ui_type"))
            if ui_type2:
                it["ml_shipping_ui_type"] = ui_type2
                it["ml_shipping_type"] = ui_type2
                it["shipping_type"] = ui_type2

    return items


@router.get("/admin/ml/orders/recent")
def recent_ml_sales(
    limit: int = 20,
    offset: int = 0,
    exclude_tests: bool = True,
    q: Optional[str] = Query(default=None),
    token: Optional[str] = Query(default=None),
    x_admin_token: Optional[str] = Header(default=None),
):
    require_admin(token, x_admin_token)
    stage = "fetch"
    try:
        fetched = fetch_recent_order_rows("ML", limit=limit, offset=offset, exclude_tests=exclude_tests)
        stage = "customer_enrich"
        rows = enrich_recent_order_rows_with_customer(fetched["rows"])
        stage = "build_items"
        items = build_recent_ml_items(rows)
        stage = "invoice_enrich"
        items = enrich_recent_items_with_invoice_status(items, "ML")
        stage = "shipping_recent_merge"
        items = _pc_merge_ml_recent_shipping_fields(items)
        stage = "filter"
        items = filter_recent_items(items, q)
        stage = "paginate"
        out = paginate_items(items, limit=limit, offset=offset)
        out["exclude_tests"] = exclude_tests
        out["version"] = APP_VERSION
        return out
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail={
            "ok": False,
            "version": APP_VERSION,
            "endpoint": "/admin/ml/orders/recent",
            "stage": stage,
            "error": str(e)[:1000],
        })


@router.post("/admin/ml/orders/{order_id}/notify")
def notify_ml_order_endpoint(
    order_id: str,
    force: bool = False,
    token: Optional[str] = Query(default=None),
    x_admin_token: Optional[str] = Header(default=None),
):
    require_admin(token, x_admin_token)
    row = get_order_row("ML", order_id)
    if not row:
        raise HTTPException(status_code=404, detail=f"No existe orden ML aplicada: {order_id}")
    raw = row.get("raw_data") or {}
    if not isinstance(raw, dict):
        raw = {}
    ml_order = raw.get("ml_raw") or {"id": order_id, "status": raw.get("ml_status")}
    if order_whatsapp_notified_ml(row) and not force:
        return {"ok": True, "skipped": True, "reason": "Ya estaba notificada"}

    movs = (
        sb.table("stock_movements")
        .select("*")
        .eq("reference_id", row.get("id"))
        .order("created_at", desc=False)
        .limit(50)
        .execute()
        .data
        or []
    )
    fake_result = {
        "order": row,
        "external_order_id": order_id,
        "sold_lines": raw.get("sold_lines") or [],
        "stock_applied": [{
            "sku": m.get("sku"),
            "old_stock": m.get("previous_stock"),
            "new_stock": m.get("new_stock"),
            "qty_decrement": abs(int(m.get("quantity") or 0)),
        } for m in movs],
    }
    msg = build_ml_sale_whatsapp_message(fake_result, ml_order)
    notify_result = send_whatsapp_admin(msg)
    if notify_result.get("ok"):
        mark_order_whatsapp_notified_ml(row.get("id"), notify_result)
    return {"ok": bool(notify_result.get("ok")), "forced": force, "notify_result": notify_result}





# ============================================================
# ARCA / FACTURACIÓN - V0 ERP
# ============================================================

def arca_today_local_date():
    # ARCA_DATE_LOCAL_UI_INVOICE_ICONS_V14
    # Render trabaja en UTC; para WSFE hay que usar fecha Argentina.
    # Si se factura cerca de medianoche, UTC puede quedar en el mes siguiente
    # y ARCA rechaza CbteFch con error 10152.
    return datetime.now(timezone(timedelta(hours=-3))).date()


def arca_prev_month_range() -> Dict[str, str]:
    today = arca_today_local_date()
    first_this = today.replace(day=1)
    last_prev = first_this - timedelta(days=1)
    first_prev = last_prev.replace(day=1)
    return {"from": first_prev.isoformat(), "to": last_prev.isoformat()}


def arca_safe_invoice_date(value: Any = None) -> str:
    # Fecha segura para comprobantes de productos.
    # Prioridad: fecha pedida explícitamente, pero nunca futura respecto de Argentina.
    today = arca_today_local_date()
    raw = str(value or "").strip()
    parsed = None
    try:
        if re.match(r"^\d{2}/\d{2}/\d{4}$", raw):
            d, m, y = raw.split("/")
            parsed = datetime(int(y), int(m), int(d)).date()
        elif re.match(r"^\d{4}-\d{2}-\d{2}", raw):
            parsed = datetime.fromisoformat(raw[:10]).date()
    except Exception:
        parsed = None
    if not parsed:
        parsed = today
    if parsed > today:
        parsed = today
    return parsed.isoformat()


def arca_float(value: Any, default: float = 0.0) -> float:
    try:
        if value is None:
            return default
        return float(str(value).replace(",", "."))
    except Exception:
        return default


def arca_money(value: Any) -> str:
    n = arca_float(value)
    return "$ " + f"{n:,.2f}".replace(",", "X").replace(".", ",").replace("X", ".")


def arca_digits(value: Any) -> str:
    return re.sub(r"\D+", "", str(value or ""))


def arca_deep_find(obj: Any, keys: List[str]) -> Optional[Any]:
    wanted = {normalizar(k) for k in keys}
    if isinstance(obj, dict):
        for k, v in obj.items():
            if normalizar(k) in wanted and v not in [None, ""]:
                return v
        for v in obj.values():
            found = arca_deep_find(v, keys)
            if found not in [None, ""]:
                return found
    elif isinstance(obj, list):
        for v in obj:
            found = arca_deep_find(v, keys)
            if found not in [None, ""]:
                return found
    return None


def arca_get_order(channel: str, order_id: str) -> Dict[str, Any]:
    # ARCA_DRAFT_SCHEMA_FIX_V10
    # Acepta:
    # - id interno UUID de orders
    # - external_order_id del canal
    # - pack_id de Mercado Libre, para facturar la venta completa agrupada
    # Evita consultar orders.id con strings no UUID porque PostgreSQL rompe con 22P02.
    ch = norm_sku(channel).upper()
    oid = norm_sku(order_id)

    rows = (
        sb.table("orders")
        .select("*")
        .eq("channel", ch)
        .eq("external_order_id", oid)
        .limit(1)
        .execute()
        .data
        or []
    )

    if not rows:
        try:
            uuid.UUID(str(oid))
            rows = (
                sb.table("orders")
                .select("*")
                .eq("channel", ch)
                .eq("id", oid)
                .limit(1)
                .execute()
                .data
                or []
            )
        except Exception:
            rows = []

    # Tienda Nube: puede llegar el número visible (#674) desde reportes,
    # pero orders.external_order_id guarda el ID interno/API (1987526384).
    # Resolvemos también por raw_data.tn_order_number / tn_raw.number.
    if not rows and ch == "TN":
        candidates = [oid]
        if str(oid).startswith("#"):
            candidates.append(str(oid).lstrip("#"))
        for cand in candidates:
            try:
                rows = (
                    sb.table("orders")
                    .select("*")
                    .eq("channel", "TN")
                    .contains("raw_data", {"tn_order_number": int(cand) if str(cand).isdigit() else cand})
                    .limit(1)
                    .execute()
                    .data
                    or []
                )
            except Exception:
                rows = []
            if rows:
                break
        if not rows:
            try:
                candidates_rows = (
                    sb.table("orders")
                    .select("*")
                    .eq("channel", "TN")
                    .order("created_at", desc=True)
                    .limit(500)
                    .execute()
                    .data
                    or []
                )
                wanted = {str(x).strip().lstrip("#") for x in candidates if str(x).strip()}
                rows = []
                for r in candidates_rows:
                    raw = row_raw_dict(r)
                    tn_raw = raw.get("tn_raw") or {}
                    vals = [raw.get("tn_order_number"), tn_raw.get("number")]
                    if any(str(v).strip().lstrip("#") in wanted for v in vals if v is not None):
                        rows = [r]
                        break
            except Exception:
                rows = []

    # Mercado Libre: si llega el número de pack/venta madre, elegimos una hija
    # y luego arca_consolidate_order_for_invoice agrupa todas las hijas por pack.
    if not rows and ch == "ML":
        pack_candidates = [oid]
        if str(oid).isdigit():
            try:
                pack_candidates.append(int(oid))
            except Exception:
                pass
        for pack_value in pack_candidates:
            try:
                rows = (
                    sb.table("orders")
                    .select("*")
                    .eq("channel", "ML")
                    .contains("raw_data", {"ml_pack_id": pack_value})
                    .order("created_at")
                    .limit(1)
                    .execute()
                    .data
                    or []
                )
            except Exception:
                rows = []
            if rows:
                break

    # Fallback defensivo para registros viejos con ml_pack_id anidado o tipado diferente.
    if not rows and ch == "ML":
        try:
            candidates = (
                sb.table("orders")
                .select("*")
                .eq("channel", "ML")
                .order("created_at")
                .limit(500)
                .execute()
                .data
                or []
            )
            rows = [r for r in candidates if arca_ml_pack_id_from_row(r) == str(oid)]
            rows = rows[:1]
        except Exception:
            rows = []

    if not rows:
        raise HTTPException(status_code=404, detail=f"No existe orden {ch} {oid}")
    return rows[0]



def arca_ml_pack_id_from_row(row: Dict[str, Any]) -> Optional[str]:
    raw = row_raw_dict(row)
    pack = raw.get("ml_pack_id")
    if pack in [None, ""] and isinstance(raw.get("ml_raw"), dict):
        pack = raw.get("ml_raw", {}).get("pack_id")
    if pack in [None, "", "null"]:
        return None
    return str(pack)


def arca_ml_shipping_id_from_row(row: Dict[str, Any]) -> Optional[str]:
    raw = row_raw_dict(row)
    shipping = raw.get("ml_shipping_id")
    if shipping in [None, ""] and isinstance(raw.get("ml_raw"), dict):
        ship_obj = raw.get("ml_raw", {}).get("shipping") or {}
        if isinstance(ship_obj, dict):
            shipping = ship_obj.get("id")
    if shipping in [None, "", "null"]:
        return None
    return str(shipping)


def arca_extract_ml_buyer_shipping_cost(shipping_id: Any) -> float:
    """
    Mercado Libre no siempre deja el envío cobrado al comprador dentro de order/payments.
    Para facturación, cuando existe shipping_id, consultamos shipment y tomamos un costo real
    de shipping_option. Si no hay dato confiable, devuelve 0 y no inventa envío.
    """
    sid = str(shipping_id or "").strip()
    if not sid:
        return 0.0

    shipment = ml_get_shipment_info_safe(sid)
    if not isinstance(shipment, dict) or shipment.get("_error"):
        return 0.0

    shipping_option = shipment.get("shipping_option") or {}
    if not isinstance(shipping_option, dict):
        shipping_option = {}

    # Prioridad conservadora: valores explícitos de la opción de envío.
    # En ML suele aparecer como list_cost/base_cost/cost según modalidad/respuesta.
    candidates = [
        shipping_option.get("list_cost"),
        shipping_option.get("base_cost"),
        shipping_option.get("cost"),
        shipping_option.get("gross_amount"),
        shipping_option.get("amount"),
        shipment.get("shipping_cost"),
        shipment.get("base_cost"),
        shipment.get("cost"),
    ]

    for value in candidates:
        amount = arca_float(value, 0)
        if amount > 0.50 and amount < 1000000:
            return round(amount, 2)

    return 0.0


def arca_get_ml_group_orders(row: Dict[str, Any]) -> List[Dict[str, Any]]:
    """
    Mercado Libre puede guardar una venta real como varias orders API.
    Para facturar hay que agrupar por pack_id; si no existe pack, por shipping_id.
    """
    if str(row.get("channel") or "").upper() != "ML":
        return [row]

    pack_id = arca_ml_pack_id_from_row(row)
    shipping_id = arca_ml_shipping_id_from_row(row)
    rows: List[Dict[str, Any]] = []

    try:
        if pack_id:
            rows = (
                sb.table("orders")
                .select("*")
                .eq("channel", "ML")
                .contains("raw_data", {"ml_pack_id": int(pack_id) if pack_id.isdigit() else pack_id})
                .order("created_at")
                .limit(100)
                .execute()
                .data
                or []
            )
    except Exception:
        rows = []

    # Fallback: algunos registros viejos podrían tener el pack solo dentro de ml_raw.
    if pack_id and not rows:
        try:
            candidates = (
                sb.table("orders")
                .select("*")
                .eq("channel", "ML")
                .eq("customer_name", row.get("customer_name") or "")
                .order("created_at")
                .limit(200)
                .execute()
                .data
                or []
            )
            rows = [r for r in candidates if arca_ml_pack_id_from_row(r) == pack_id]
        except Exception:
            rows = []

    # Si no hay pack, agrupamos por envío solo cuando encuentra más de una order asociada.
    if not rows and shipping_id:
        try:
            rows = (
                sb.table("orders")
                .select("*")
                .eq("channel", "ML")
                .contains("raw_data", {"ml_shipping_id": int(shipping_id) if shipping_id.isdigit() else shipping_id})
                .order("created_at")
                .limit(100)
                .execute()
                .data
                or []
            )
        except Exception:
            rows = []

    if not rows:
        return [row]

    # Evita duplicados por id/external_order_id conservando orden estable.
    seen = set()
    unique = []
    for r in rows:
        key = str(r.get("id") or r.get("external_order_id") or "")
        if key and key in seen:
            continue
        if key:
            seen.add(key)
        unique.append(r)
    return unique or [row]


def arca_line_from_sold_line(line: Dict[str, Any], source: str = "order_line") -> Optional[Dict[str, Any]]:
    if not isinstance(line, dict):
        return None
    qty = arca_float(line.get("quantity") or line.get("qty") or 1, 1)
    unit = arca_float(
        line.get("unit_price_gross") or line.get("unit_price") or line.get("price") or 0,
        0,
    )
    if unit <= 0:
        return None
    return {
        "sku": line.get("sku") or "",
        "description": line.get("description") or line.get("name") or line.get("title") or line.get("product_name") or line.get("sku") or "Producto",
        "quantity": qty,
        "unit_price_gross": unit,
        "discount_pct": arca_float(line.get("discount_pct") or 0),
        "iva_pct": ARCA_IVA_ALICUOTA,
        "source": source,
    }


def arca_build_lines_from_single_order(row: Dict[str, Any]) -> List[Dict[str, Any]]:
    raw = row_raw_dict(row)
    source_lines = raw.get("sold_lines") or []
    lines: List[Dict[str, Any]] = []
    for line in source_lines:
        normalized = arca_line_from_sold_line(line, "order_line")
        if normalized:
            lines.append(normalized)
    return lines


def arca_consolidate_order_for_invoice(row: Dict[str, Any]) -> Dict[str, Any]:
    """
    Devuelve una fila sintética facturable.
    Para ML, agrupa todas las orders del mismo pack/shipment para no facturar una sola order parcial.
    Para TN/manual, devuelve la fila original.
    """
    if str(row.get("channel") or "").upper() != "ML":
        return row

    group_rows = arca_get_ml_group_orders(row)
    if len(group_rows) <= 1:
        return row

    pack_id = arca_ml_pack_id_from_row(row) or arca_ml_pack_id_from_row(group_rows[0])
    shipping_id = arca_ml_shipping_id_from_row(row) or arca_ml_shipping_id_from_row(group_rows[0])
    child_ids = [str(r.get("external_order_id") or "") for r in group_rows if r.get("external_order_id")]

    sold_lines: List[Dict[str, Any]] = []
    total = 0.0
    customer_name = row.get("customer_name") or ""
    customer_phone = row.get("customer_phone")
    first_created = None

    for r in group_rows:
        total += arca_float(r.get("total"), 0)
        if not customer_name or normalizar(customer_name).startswith("mev"):
            customer_name = r.get("customer_name") or customer_name
        customer_phone = customer_phone or r.get("customer_phone")
        raw = row_raw_dict(r)
        if not first_created:
            first_created = raw.get("ml_date_created") or r.get("created_at")
        for ln in raw.get("sold_lines") or []:
            if isinstance(ln, dict):
                sold_lines.append(dict(ln))

    raw0 = row_raw_dict(row)
    grouped_raw = dict(raw0)
    grouped_raw.update({
        "source": "arca_ml_pack_grouped",
        "ml_pack_id": pack_id,
        "ml_shipping_id": shipping_id,
        "ml_order_id": str(pack_id or shipping_id or row.get("external_order_id") or ""),
        "ml_sale_number": str(pack_id or shipping_id or row.get("external_order_id") or ""),
        "ml_child_order_ids": child_ids,
        "sold_lines": sold_lines,
        "ml_date_created": first_created or raw0.get("ml_date_created"),
        "arca_group_rows_count": len(group_rows),
        "arca_group_total": round(total, 2),
    })

    out = dict(row)
    out.update({
        "external_order_id": str(pack_id or shipping_id or row.get("external_order_id") or ""),
        "customer_name": customer_name or row.get("customer_name"),
        "customer_phone": customer_phone,
        "total": round(total, 2),
        "raw_data": grouped_raw,
    })
    return out


def arca_source_number(row: Dict[str, Any]) -> str:
    raw = row_raw_dict(row)
    ch = str(row.get("channel") or "").upper()
    if ch == "TN":
        return str(raw.get("tn_order_number") or row.get("external_order_id") or "")
    if ch == "ML":
        return str(raw.get("ml_sale_number") or raw.get("ml_pack_id") or raw.get("ml_order_id") or row.get("external_order_id") or "")
    return str(row.get("external_order_id") or row.get("id") or "")


def arca_guess_customer(row: Dict[str, Any], override: Optional[ArcaCustomerOverrideIn] = None) -> Dict[str, Any]:
    raw = row_raw_dict(row)
    raw_all = raw.get("tn_raw") or raw.get("ml_raw") or raw

    canonical_customer = None
    try:
        canonical_customer = pc_customer_for_order_row(row)
    except Exception:
        canonical_customer = None

    if canonical_customer:
        fiscal_address_parts = [
            canonical_customer.get("address"),
            canonical_customer.get("city"),
            canonical_customer.get("province"),
            canonical_customer.get("zip"),
        ]
        fiscal_address = ", ".join([str(x).strip() for x in fiscal_address_parts if str(x or "").strip()])
        out = {
            "name": str(canonical_customer.get("fiscal_name") or canonical_customer.get("name") or row.get("customer_name") or "Consumidor Final").strip(),
            "doc_type": str(canonical_customer.get("doc_type") or "").upper(),
            "doc_number": arca_digits(canonical_customer.get("doc_number")),
            "iva_condition": str(canonical_customer.get("iva_condition") or "Consumidor Final").strip(),
            "address": fiscal_address,
            "email": str(canonical_customer.get("email") or "").strip(),
        }
        if override:
            if override.name is not None:
                out["name"] = override.name
            if override.doc_type is not None:
                out["doc_type"] = override.doc_type.upper()
            if override.doc_number is not None:
                out["doc_number"] = arca_digits(override.doc_number)
            if override.iva_condition is not None:
                out["iva_condition"] = override.iva_condition
            if override.address is not None:
                out["address"] = override.address
            if override.email is not None:
                out["email"] = override.email
        return out

    name = row.get("customer_name") or arca_deep_find(raw_all, ["billing_name", "contact_name", "name", "first_name"])
    doc_number = arca_deep_find(raw_all, [
        "billing_document", "document", "document_number", "doc_number",
        "dni", "cuit", "contact_identification", "identification"
    ])
    doc_type = arca_deep_find(raw_all, ["document_type", "doc_type", "identification_type"])
    iva_condition = arca_deep_find(raw_all, [
        "iva_condition", "condicion_iva", "taxpayer_type", "billing_iva_condition",
        "fiscal_condition"
    ])
    address = arca_deep_find(raw_all, [
        "billing_address", "address", "domicilio", "billing_address_street",
        "contact_address", "shipping_address"
    ])
    email = arca_deep_find(raw_all, ["email", "contact_email", "billing_email"])

    doc_digits = arca_digits(doc_number)
    if not doc_type:
        doc_type = "CUIT" if len(doc_digits) == 11 else ("DNI" if len(doc_digits) in [7, 8] else "")
    if not iva_condition:
        # Sin dato fiscal confiable, no inventamos A: cae a Consumidor Final.
        iva_condition = "Consumidor Final"

    out = {
        "name": str(name or row.get("customer_name") or "Consumidor Final").strip(),
        "doc_type": str(doc_type or "").upper(),
        "doc_number": doc_digits,
        "iva_condition": str(iva_condition or "Consumidor Final").strip(),
        "address": str(address or "").strip(),
        "email": str(email or "").strip(),
    }

    if override:
        if override.name is not None:
            out["name"] = override.name
        if override.doc_type is not None:
            out["doc_type"] = override.doc_type.upper()
        if override.doc_number is not None:
            out["doc_number"] = arca_digits(override.doc_number)
        if override.iva_condition is not None:
            out["iva_condition"] = override.iva_condition
        if override.address is not None:
            out["address"] = override.address
        if override.email is not None:
            out["email"] = override.email

    return out


def arca_invoice_type_for_customer(customer: Dict[str, Any], force_type: Optional[str] = None) -> Dict[str, Any]:
    forced = normalizar(force_type or "")
    if forced == "a":
        return {"letter": "A", "code": 1, "label": "Factura A"}
    if forced == "b":
        return {"letter": "B", "code": 6, "label": "Factura B"}

    cond = normalizar(customer.get("iva_condition"))
    if "resp inscripto" in cond or "responsable inscripto" in cond:
        return {"letter": "A", "code": 1, "label": "Factura A"}
    # Responsable Inscripto emite B a Monotributo / Consumidor Final.
    return {"letter": "B", "code": 6, "label": "Factura B"}


def arca_gross_line_total(line: Dict[str, Any]) -> float:
    qty = arca_float(line.get("quantity") or line.get("qty") or 1, 1)
    unit = arca_float(line.get("unit_price_gross") or line.get("unit_price") or line.get("price") or 0, 0)
    return round(qty * unit, 2)


def arca_fetch_order_item_lines(order_id: str) -> List[Dict[str, Any]]:
    """
    Recupera líneas persistidas en order_items para facturación/impresión.
    Esto evita depender solo del raw_data del marketplace, que a veces llega incompleto
    o fue populado por SQL de prueba sin precios.
    """
    if not order_id:
        return []

    rows = (
        sb.table("order_items")
        .select("sku,quantity,unit_price,inventory_item_id")
        .eq("order_id", order_id)
        .order("created_at")
        .execute()
        .data
        or []
    )
    if not rows:
        return []

    inv_ids = sorted({r.get("inventory_item_id") for r in rows if r.get("inventory_item_id") is not None})
    inv_by_id = {}
    if inv_ids:
        invs = (
            sb.table("inventory_items")
            .select("id,sku,name")
            .in_("id", inv_ids)
            .execute()
            .data
            or []
        )
        inv_by_id = {i.get("id"): i for i in invs}

    out = []
    for r in rows:
        inv = inv_by_id.get(r.get("inventory_item_id")) or {}
        qty = arca_float(r.get("quantity") or 1, 1)
        unit = arca_float(r.get("unit_price") or 0, 0)
        out.append({
            "sku": r.get("sku") or inv.get("sku") or "",
            "description": inv.get("name") or r.get("sku") or "Producto",
            "quantity": qty,
            "unit_price_gross": unit,
            "discount_pct": 0,
            "iva_pct": ARCA_IVA_ALICUOTA,
            "source": "order_items",
        })
    return out


def arca_build_lines_from_order(row: Dict[str, Any]) -> List[Dict[str, Any]]:
    row = arca_consolidate_order_for_invoice(row)
    lines = arca_build_lines_from_single_order(row)

    # Si raw_data no trajo precios útiles, usamos la tabla order_items del ERP.
    if not lines and row.get("id"):
        try:
            lines = arca_fetch_order_item_lines(str(row.get("id")))
        except Exception:
            lines = []

    line_total = round(sum(arca_gross_line_total(x) for x in lines), 2)
    order_total = arca_float(row.get("total"), 0)

    # Regla fiscal: no prorrateamos ni inventamos precios.
    # Toda factura debe salir de líneas reales con precio real.
    diff = round(order_total - line_total, 2)
    ch = str(row.get("channel") or "").upper()

    # TN puede traer envío cobrado como diferencia de total.
    if lines and diff > 0.50 and ch == "TN":
        lines.append({
            "sku": "envio_tnube",
            "description": "Envío",
            "quantity": 1,
            "unit_price_gross": diff,
            "discount_pct": 0,
            "iva_pct": ARCA_IVA_ALICUOTA,
            "source": "shipping_diff_tn",
        })

    # ML no debe inventar envío por diferencia, pero sí debe facturar el envío si shipment
    # informa un costo real cobrado al comprador. Nunca copiamos el precio de un producto.
    if lines and ch == "ML":
        shipping_id = arca_ml_shipping_id_from_row(row)
        ml_ship_cost = arca_extract_ml_buyer_shipping_cost(shipping_id)
        already_has_shipping = any(str(x.get("sku") or "").lower().startswith("envio") for x in lines)
        if ml_ship_cost > 0.50 and not already_has_shipping:
            lines.append({
                "sku": "envio_me_buyer",
                "description": "Envío por Mercado Envíos",
                "quantity": 1,
                "unit_price_gross": ml_ship_cost,
                "discount_pct": 0,
                "iva_pct": ARCA_IVA_ALICUOTA,
                "source": "ml_shipment_buyer_cost",
            })

    # Diferencia negativa: la venta tiene descuento global respecto de la suma de líneas.
    # No tocamos precio de líneas. Lo dejamos como línea de bonificación global para que el total cierre.
    if lines and diff < -0.50:
        lines.append({
            "sku": "descuento",
            "description": "Descuento / bonificación de la venta",
            "quantity": 1,
            "unit_price_gross": diff,
            "discount_pct": 0,
            "iva_pct": ARCA_IVA_ALICUOTA,
            "source": "global_discount_diff",
        })

    return lines

def arca_calculate_invoice(lines: List[Dict[str, Any]], cbte_letter: str) -> Dict[str, Any]:
    out_lines = []
    total_gross = 0.0
    total_net = 0.0
    total_iva = 0.0

    for line in lines:
        qty = arca_float(line.get("quantity"), 1)
        gross_unit = arca_float(line.get("unit_price_gross"), 0)
        iva_pct = arca_float(line.get("iva_pct"), ARCA_IVA_ALICUOTA)
        gross_total = round(qty * gross_unit, 2)

        if cbte_letter == "A":
            net_unit = round(gross_unit / (1 + iva_pct / 100), 2)
            net_total = round(gross_total / (1 + iva_pct / 100), 2)
            iva_amount = round(gross_total - net_total, 2)
            display_unit = net_unit
            display_subtotal = net_total
        elif cbte_letter == "C":
            net_total = gross_total
            iva_amount = 0.0
            display_unit = gross_unit
            display_subtotal = gross_total
        else:
            net_total = gross_total
            iva_amount = round(gross_total - (gross_total / (1 + iva_pct / 100)), 2)
            display_unit = gross_unit
            display_subtotal = gross_total

        total_gross += gross_total
        total_net += net_total
        total_iva += iva_amount

        out_lines.append({
            **line,
            "quantity": qty,
            "unit_price_display": display_unit,
            "subtotal_display": display_subtotal,
            "subtotal_net": round(gross_total / (1 + iva_pct / 100), 2),
            "iva_amount": iva_amount,
            "total_gross": gross_total,
        })

    if cbte_letter == "A":
        return {
            "lines": out_lines,
            "importe_neto": round(sum(x["subtotal_net"] for x in out_lines), 2),
            "importe_iva": round(sum(x["iva_amount"] for x in out_lines), 2),
            "importe_total": round(sum(x["total_gross"] for x in out_lines), 2),
            "iva_contenido": None,
        }

    if cbte_letter == "C":
        total_gross = round(sum(x["total_gross"] for x in out_lines), 2)
        return {
            "lines": out_lines,
            "importe_neto": total_gross,
            "importe_iva": 0.0,
            "importe_total": total_gross,
            "iva_contenido": 0.0,
        }

    total_gross = round(sum(x["total_gross"] for x in out_lines), 2)
    iva_content = round(sum(x["iva_amount"] for x in out_lines), 2)
    return {
        "lines": out_lines,
        "importe_neto": total_gross,
        "importe_iva": 0.0,
        "importe_total": total_gross,
        "iva_contenido": iva_content,
    }


def arca_build_invoice_payload(
    row: Dict[str, Any],
    body: Optional[ArcaInvoiceDraftIn] = None,
) -> Dict[str, Any]:
    body = body or ArcaInvoiceDraftIn()
    row = arca_consolidate_order_for_invoice(row)
    customer = arca_guess_customer(row, body.customer)
    cbte = arca_invoice_type_for_customer(customer, body.force_type)
    lines = arca_build_lines_from_order(row)
    if not lines:
        raise HTTPException(
            status_code=400,
            detail=f"No se puede facturar {row.get('channel')} {arca_source_number(row)}: no hay líneas reales de venta."
        )

    calc = arca_calculate_invoice(lines, cbte["letter"])
    if not calc.get("lines") or arca_float(calc.get("importe_total"), 0) <= 0.50:
        raise HTTPException(
            status_code=400,
            detail=f"No se puede facturar {row.get('channel')} {arca_source_number(row)}: las líneas no tienen precios reales."
        )

    invoice_date = arca_safe_invoice_date(body.invoice_date)

    raw = row_raw_dict(row)
    source_meta = build_sync_source_meta(
        channel=row.get("channel") or "",
        external_order_id=row.get("external_order_id") or row.get("id") or "",
        raw_payload=raw,
        customer_name=row.get("customer_name"),
        customer_phone=row.get("customer_phone"),
        erp_order_id=row.get("id"),
    )

    return {
        "status": "draft",
        "environment": ARCA_ENV,
        "source_channel": row.get("channel"),
        "source_order_id": row.get("external_order_id") or row.get("id"),
        "source_order_number": source_meta.get("source_order_number") or arca_source_number(row),
        "source_order_api_id": source_meta.get("source_order_api_id"),
        "source_pack_id": source_meta.get("source_pack_id"),
        "source_shipping_id": source_meta.get("source_shipping_id"),
        "source_customer_name": row.get("customer_name"),
        "source_created_at": source_meta.get("source_created_at"),
        "invoice_date": invoice_date,
        "concept": body.concept or ARCA_DEFAULT_CONCEPTO,
        "cbte_tipo": cbte["code"],
        "cbte_letra": cbte["letter"],
        "cbte_tipo_label": cbte["label"],
        "pto_vta": ARCA_PTO_VTA,
        "cbte_nro": None,
        "cae": None,
        "cae_vto": None,
        "customer_name": customer.get("name"),
        "customer_doc_type": customer.get("doc_type"),
        "customer_doc_number": customer.get("doc_number"),
        "customer_iva_condition": customer.get("iva_condition"),
        "customer_address": customer.get("address"),
        "customer_email": customer.get("email"),
        "importe_neto": calc["importe_neto"],
        "importe_iva": calc["importe_iva"],
        "importe_total": calc["importe_total"],
        "iva_contenido": calc["iva_contenido"],
        "currency": "ARS",
        "lines": calc["lines"],
        "notes": body.notes,
        "raw_data": {
            "order": row,
            "source_meta": source_meta,
            "built_at": now_iso(),
            "v0_warning": "Borrador ERP. No tiene CAE hasta emitir con la conexión ARCA del tenant.",
        },
        "created_at": now_iso(),
        "updated_at": now_iso(),
    }



# ============================================================
# ARCA WSAA / WSFE - emisión real CAE
# ============================================================

def arca_env_is_prod() -> bool:
    return normalizar(ARCA_ENV) in ["prod", "produccion", "producción", "production"]


def arca_wsaa_url() -> str:
    return ARCA_WSAA_URL_PROD if arca_env_is_prod() else ARCA_WSAA_URL_HOMO


def arca_wsfe_url() -> str:
    return ARCA_WSFE_URL_PROD if arca_env_is_prod() else ARCA_WSFE_URL_HOMO


def arca_secret_to_pem(value: str, value_b64: str = "", file_path: str = "") -> bytes:
    if value:
        txt = value.replace("\\n", "\n").strip()
        return txt.encode("utf-8")
    if value_b64:
        return base64.b64decode(value_b64)
    if file_path:
        with open(file_path, "rb") as f:
            return f.read()
    return b""


def arca_ws_ready() -> Dict[str, Any]:
    cert = bool(ARCA_CERT_PEM or ARCA_CERT_BASE64 or ARCA_CERT_FILE)
    key = bool(ARCA_KEY_PEM or ARCA_KEY_BASE64 or ARCA_KEY_FILE)
    cuit = bool(arca_digits(ARCA_EMISOR_CUIT))
    ready = bool(cert and key and cuit and ARCA_PTO_VTA)
    return {
        "ready": ready,
        "emit_enabled": ARCA_EMIT_ENABLED,
        "auto_invoice_enabled": ARCA_AUTO_INVOICE_ENABLED,
        "environment": ARCA_ENV,
        "is_production": arca_env_is_prod(),
        "pto_vta": ARCA_PTO_VTA,
        "cert_configurado": cert,
        "key_configurada": key,
        "cuit_configurado": cuit,
        "wsaa_url": arca_wsaa_url(),
        "wsfe_url": arca_wsfe_url(),
        "service": ARCA_WSAA_SERVICE,
    }


def arca_localname(tag: str) -> str:
    return str(tag or "").split("}")[-1].split(":")[-1]


def arca_find_text_by_localname(root: ET.Element, name: str) -> str:
    wanted = name.lower()
    for el in root.iter():
        if arca_localname(el.tag).lower() == wanted:
            return (el.text or "").strip()
    return ""


def arca_wsaa_tra_xml(service: str = "wsfe") -> bytes:
    tz_ar = timezone(timedelta(hours=-3))
    now = datetime.now(tz_ar)
    gen = (now - timedelta(minutes=10)).replace(microsecond=0).isoformat()
    exp = (now + timedelta(hours=12)).replace(microsecond=0).isoformat()
    unique_id = str(int(time.time()))
    xml = f"""<?xml version="1.0" encoding="UTF-8"?>
<loginTicketRequest version="1.0">
  <header>
    <uniqueId>{unique_id}</uniqueId>
    <generationTime>{gen}</generationTime>
    <expirationTime>{exp}</expirationTime>
  </header>
  <service>{service}</service>
</loginTicketRequest>"""
    return xml.encode("utf-8")


def arca_wsaa_sign_cms(tra_xml: bytes) -> str:
    cert_pem = arca_secret_to_pem(ARCA_CERT_PEM, ARCA_CERT_BASE64, ARCA_CERT_FILE)
    key_pem = arca_secret_to_pem(ARCA_KEY_PEM, ARCA_KEY_BASE64, ARCA_KEY_FILE)
    if not cert_pem or not key_pem:
        raise HTTPException(status_code=400, detail="Faltan ARCA_CERT_PEM/BASE64/FILE o ARCA_KEY_PEM/BASE64/FILE")
    cert = x509.load_pem_x509_certificate(cert_pem)
    key = serialization.load_pem_private_key(key_pem, password=None)
    cms = (
        pkcs7.PKCS7SignatureBuilder()
        .set_data(tra_xml)
        .add_signer(cert, key, hashes.SHA256())
        .sign(serialization.Encoding.DER, [pkcs7.PKCS7Options.Binary])
    )
    return base64.b64encode(cms).decode("ascii")


class ArcaLegacySSLAdapter(HTTPAdapter):
    """Adapter SSL solo para ARCA/WSFE cuando el host usa DH débil.

    AFIP/ARCA producción puede responder con un handshake que OpenSSL moderno
    rechaza como DH_KEY_TOO_SMALL. Bajamos SECLEVEL solo para esta sesión ARCA,
    sin afectar TN, ML, WhatsApp ni otros requests del ERP.
    """

    def init_poolmanager(self, connections, maxsize, block=False, **pool_kwargs):
        ctx = ssl.create_default_context()
        try:
            ctx.set_ciphers("DEFAULT:@SECLEVEL=1")
        except Exception:
            pass
        # En algunos OpenSSL nuevos esto habilita compatibilidad con servidores legacy.
        if hasattr(ssl, "OP_LEGACY_SERVER_CONNECT"):
            try:
                ctx.options |= ssl.OP_LEGACY_SERVER_CONNECT
            except Exception:
                pass
        pool_kwargs["ssl_context"] = ctx
        self.poolmanager = PoolManager(
            num_pools=connections,
            maxsize=maxsize,
            block=block,
            **pool_kwargs,
        )


_ARCA_LEGACY_SSL_SESSION: Optional[requests.Session] = None


def arca_http_session_for_url(url: str) -> requests.Session:
    global _ARCA_LEGACY_SSL_SESSION
    if "servicios1.afip.gov.ar" in str(url) or "/wsfev1/" in str(url):
        if _ARCA_LEGACY_SSL_SESSION is None:
            sess = requests.Session()
            sess.mount("https://", ArcaLegacySSLAdapter())
            _ARCA_LEGACY_SSL_SESSION = sess
        return _ARCA_LEGACY_SSL_SESSION
    return requests.Session()


def arca_soap_post(url: str, soap_action: str, body: str) -> str:
    headers = {
        "Content-Type": "text/xml; charset=utf-8",
        "SOAPAction": soap_action,
    }
    sess = arca_http_session_for_url(url)
    try:
        r = sess.post(url, data=body.encode("utf-8"), headers=headers, timeout=ARCA_WS_TIMEOUT_SECONDS)
    except requests.exceptions.SSLError as e:
        raise HTTPException(status_code=502, detail=f"ARCA SSL ERROR: {str(e)}")
    except requests.exceptions.RequestException as e:
        raise HTTPException(status_code=502, detail=f"ARCA REQUEST ERROR: {str(e)}")
    if r.status_code >= 400:
        raise HTTPException(status_code=502, detail=f"ARCA HTTP {r.status_code}: {r.text[:1200]}")
    return r.text


def arca_wsaa_login_ticket(force_refresh: bool = False, service_override: Optional[str] = None) -> Dict[str, Any]:
    service = service_override or ARCA_WSAA_SERVICE or "wsfe"
    cache_key = f"{ARCA_ENV}:{service}:{ARCA_EMISOR_CUIT}"
    cached = ARCA_WSAA_TA_CACHE.get(cache_key) or {}
    exp_txt = cached.get("expiration_time")
    if cached and not force_refresh and exp_txt:
        try:
            exp = datetime.fromisoformat(exp_txt.replace("Z", "+00:00"))
            if datetime.now(timezone.utc) < (exp.astimezone(timezone.utc) - timedelta(minutes=10)):
                return cached
        except Exception:
            pass

    cms_b64 = arca_wsaa_sign_cms(arca_wsaa_tra_xml(service))
    soap = f"""<?xml version="1.0" encoding="UTF-8"?>
<soapenv:Envelope xmlns:soapenv="http://schemas.xmlsoap.org/soap/envelope/" xmlns:wsaa="http://wsaa.view.sua.dvadac.desein.afip.gov">
  <soapenv:Header/>
  <soapenv:Body>
    <wsaa:loginCms>
      <wsaa:in0>{cms_b64}</wsaa:in0>
    </wsaa:loginCms>
  </soapenv:Body>
</soapenv:Envelope>"""
    response = arca_soap_post(arca_wsaa_url(), "", soap)
    root = ET.fromstring(response)
    returned = arca_find_text_by_localname(root, "loginCmsReturn")
    if not returned:
        raise HTTPException(status_code=502, detail=f"ARCA WSAA sin loginCmsReturn: {response[:1200]}")
    returned = html_parser.unescape(returned)
    ta_root = ET.fromstring(returned)
    token = arca_find_text_by_localname(ta_root, "token")
    sign = arca_find_text_by_localname(ta_root, "sign")
    expiration = arca_find_text_by_localname(ta_root, "expirationTime")
    generation = arca_find_text_by_localname(ta_root, "generationTime")
    if not token or not sign:
        raise HTTPException(status_code=502, detail=f"ARCA WSAA TA incompleto: {returned[:1200]}")
    ta = {
        "token": token,
        "sign": sign,
        "generation_time": generation,
        "expiration_time": expiration,
        "service": service,
        "environment": ARCA_ENV,
        "cached_at": now_iso(),
    }
    ARCA_WSAA_TA_CACHE[cache_key] = ta
    return ta


def arca_padron_url() -> str:
    return ARCA_PADRON_URL_PROD if arca_env_is_prod() else ARCA_PADRON_URL_HOMO


def arca_padron_auth(service: Optional[str] = None) -> Dict[str, Any]:
    effective_service = service or ARCA_PADRON_SERVICE or "ws_sr_constancia_inscripcion"
    tenant_id = str(get_effective_tenant_id() or "").strip()
    if tenant_id and tenant_id != str(DEFAULT_TENANT_ID):
        runtime = arca_tenant_emission_context(service=effective_service)
        client = runtime["client"]
        client.auth()
        return {
            "token": str(client._token or ""),
            "sign": str(client._sign or ""),
            "cuit_representada": runtime["issuer"]["cuit"],
            "service": effective_service,
            "environment": "produccion",
            "tenant_id": tenant_id,
            "config_source": "tenant_db",
        }
    return arca_wsaa_login_ticket(service_override=effective_service)


def arca_xml_values_by_localname(root: ET.Element) -> Dict[str, List[str]]:
    out: Dict[str, List[str]] = {}
    for el in root.iter():
        name = arca_localname(el.tag)
        txt = (el.text or "").strip()
        if txt:
            out.setdefault(name, []).append(txt)
    return out


def arca_first_xml_value(values: Dict[str, List[str]], keys: List[str]) -> Optional[str]:
    lower_map = {str(k).lower(): v for k, v in values.items()}
    for key in keys:
        vals = lower_map.get(str(key).lower()) or []
        for v in vals:
            if str(v).strip():
                return str(v).strip()
    return None



def arca_cuit_check_digit(first10: str) -> str:
    digits = arca_digits(first10)
    if len(digits) != 10:
        raise ValueError("first10 debe tener 10 dígitos")
    weights = [5, 4, 3, 2, 7, 6, 5, 4, 3, 2]
    total = sum(int(d) * w for d, w in zip(digits, weights))
    mod = total % 11
    dv = 11 - mod
    if dv == 11:
        dv = 0
    if dv == 10:
        # En CUIT/CUIL de personas físicas, el caso 10 suele resolverse con prefijo 23.
        # Igual nosotros probamos varios prefijos, por eso devolvemos 9 como fallback técnico
        # solo para no romper el cálculo en casos no estándar.
        dv = 9
    return str(dv)


def arca_cuit_candidates_from_doc(doc_type: str, doc_number: str) -> List[str]:
    digits = arca_digits(doc_number)
    dtype = (doc_type or "").strip().upper()
    if not digits:
        return []
    if dtype in ["CUIT", "CUIL"] or len(digits) == 11:
        return [digits]
    if len(digits) > 8:
        return [digits]
    dni = digits.zfill(8)
    candidates: List[str] = []
    for prefix in ["20", "27", "23", "24"]:
        first10 = prefix + dni
        cuit = first10 + arca_cuit_check_digit(first10)
        if cuit not in candidates:
            candidates.append(cuit)
    return candidates


def arca_padron_fiscal_name_from_values(values: Dict[str, List[str]]) -> Optional[str]:
    razon = arca_first_xml_value(values, ["razonSocial", "razonsocial", "denominacion", "descripcionPersona"])
    nombre = arca_first_xml_value(values, ["nombre", "nombres"])
    apellido = arca_first_xml_value(values, ["apellido", "apellidos"])
    fiscal_name = razon or " ".join([x for x in [nombre, apellido] if x]).strip()
    return fiscal_name or None


def arca_names_match(a: Any, b: Any) -> bool:
    na = normalizar(pc_clean_str(a))
    nb = normalizar(pc_clean_str(b))
    if not na or not nb:
        return False
    if na == nb or na in nb or nb in na:
        return True
    ta = set(na.split())
    tb = set(nb.split())
    return bool(ta and tb and len(ta.intersection(tb)) >= min(2, len(ta), len(tb)))


def arca_values_list(values: Dict[str, List[str]], key: str) -> List[str]:
    if not isinstance(values, dict):
        return []
    v = values.get(key)
    if v is None:
        return []
    if isinstance(v, list):
        return [pc_clean_str(x) for x in v if pc_clean_str(x)]
    txt = pc_clean_str(v)
    return [txt] if txt else []


def arca_values_has_errors(values: Dict[str, List[str]]) -> bool:
    return bool(arca_values_list(values, "error"))


def arca_values_has_fiscal_address(values: Dict[str, List[str]]) -> bool:
    # ARCA puede devolver dirección, localidad/provincia y CP en nodos separados.
    direccion = arca_first_xml_value(values, ["direccion", "domicilio", "domicilioFiscal"])
    localidad = arca_first_xml_value(values, ["localidad", "ciudad"])
    provincia = arca_first_xml_value(values, ["descripcionProvincia", "provincia"])
    cp = arca_first_xml_value(values, ["codPostal", "codigoPostal", "zip"])
    return bool(pc_clean_str(direccion) and (pc_clean_str(localidad) or pc_clean_str(provincia) or pc_clean_str(cp)))


def arca_candidate_is_active(values: Dict[str, List[str]]) -> bool:
    estado = normalizar(arca_first_xml_value(values, ["estadoClave", "estado"]))
    return not estado or "activo" in estado


def arca_choose_best_padron_candidate(successes: List[Dict[str, Any]], preferred_name: Optional[str] = None) -> Optional[Dict[str, Any]]:
    """Elige automáticamente un candidato DNI cuando ARCA devuelve más de uno.

    Regla operativa Planeta Casa:
    - Preferir ARCA sobre ML.
    - Para DNI ambiguo, elegir el candidato con nombre compatible, sin errores y domicilio fiscal completo.
    - Si no hay una única opción fuerte, no adivinar.
    """
    scored = []
    for result in successes or []:
        values = result.get("values") or {}
        fiscal_name = result.get("candidate_fiscal_name") or arca_padron_fiscal_name_from_values(values)
        name_match = bool(preferred_name and arca_names_match(fiscal_name, preferred_name))
        no_errors = not arca_values_has_errors(values)
        has_address = arca_values_has_fiscal_address(values)
        active = arca_candidate_is_active(values)

        score = 0
        if name_match:
            score += 100
        elif not preferred_name:
            score += 20
        if no_errors:
            score += 40
        if has_address:
            score += 40
        if active:
            score += 10

        scored.append({
            "score": score,
            "result": result,
            "name_match": name_match,
            "no_errors": no_errors,
            "has_address": has_address,
            "active": active,
            "fiscal_name": fiscal_name,
        })

    strong = [x for x in scored if x["no_errors"] and x["has_address"] and (x["name_match"] or not preferred_name)]
    if len(strong) == 1:
        chosen = strong[0]["result"]
        chosen["candidate_match_source"] = "preferred_name_complete_no_errors" if preferred_name else "complete_no_errors"
        chosen["candidate_score"] = strong[0]["score"]
        return chosen

    scored.sort(key=lambda x: x["score"], reverse=True)
    if len(scored) >= 2:
        top, second = scored[0], scored[1]
        if top["score"] >= 160 and top["score"] >= second["score"] + 40:
            chosen = top["result"]
            chosen["candidate_match_source"] = "best_scored_candidate"
            chosen["candidate_score"] = top["score"]
            return chosen
    elif len(scored) == 1 and scored[0]["score"] >= 80:
        chosen = scored[0]["result"]
        chosen["candidate_match_source"] = "single_scored_candidate"
        chosen["candidate_score"] = scored[0]["score"]
        return chosen

    return None


def arca_is_cf_condition(value: Any) -> bool:
    return "consumidor" in normalizar(pc_clean_str(value)) and "final" in normalizar(pc_clean_str(value))


def arca_apply_fiscal_fallbacks(fiscal: Dict[str, Any], fallback: Optional[Dict[str, Any]], padron: Dict[str, Any]) -> Dict[str, Any]:
    """Completa datos faltantes sin pisar datos fuertes de ARCA.

    Prioridad:
    - Nombre y condición: ARCA.
    - Documento: para Monotributo/RI/Exento usar CUIT/CUIL consultado; para CF con DNI de ML, conservar DNI.
    - Domicilio: ARCA; si falta, ML billing/shipping como fallback auditado.
    """
    out = dict(fiscal or {})
    fallback = fallback or {}
    fallback_used: List[str] = []

    queried = pc_clean_str((padron or {}).get("queried_id_persona"))
    condition = pc_clean_str(out.get("iva_condition"))
    if queried and len(arca_digits(queried)) == 11 and not arca_is_cf_condition(condition):
        out["doc_type"] = "CUIT"
        out["doc_number"] = arca_digits(queried)
        fallback_used.append("doc_from_arca_queried_id_persona_for_non_cf")

    for key in ["address", "city", "province", "zip"]:
        if not pc_clean_str(out.get(key)) and pc_clean_str(fallback.get(key)):
            out[key] = pc_clean_str(fallback.get(key))
            fallback_used.append(f"{key}_from_channel_fallback")

    if not pc_clean_str(out.get("fiscal_name")) and pc_clean_str(fallback.get("fiscal_name")):
        out["fiscal_name"] = pc_clean_str(fallback.get("fiscal_name"))
        fallback_used.append("fiscal_name_from_channel_fallback")

    raw_data = out.get("raw_data") if isinstance(out.get("raw_data"), dict) else {}
    raw_data.setdefault("fiscal_quality", {})
    raw_data["fiscal_quality"].update({
        "has_arca_name": bool(pc_clean_str(fiscal.get("fiscal_name") if fiscal else None)),
        "has_arca_address": bool(pc_clean_str(fiscal.get("address") if fiscal else None)),
        "has_final_address": bool(pc_clean_str(out.get("address"))),
        "fallback_used": fallback_used,
        "fallback_source": "marketplace_billing_or_shipping" if fallback_used else None,
    })
    out["raw_data"] = raw_data
    return out


def arca_padron_get_persona_for_doc(doc_type: str, doc_number: str, service: Optional[str] = None, preferred_name: Optional[str] = None) -> Dict[str, Any]:
    """Consulta Constancia/Padrón.

    El WS de Constancia espera idPersona como CUIT/CUIL/CDI. MercadoLibre muchas veces
    entrega DNI. Para DNI probamos CUIT/CUIL candidatos típicos de persona física.
    Si más de un candidato existe, solo elegimos automáticamente si matchea el nombre
    fiscal/canal; si no, devolvemos ambigüedad para evitar asociar mal una factura.
    """
    candidates = arca_cuit_candidates_from_doc(doc_type, doc_number)
    if not candidates:
        raise HTTPException(status_code=400, detail="doc_number vacío")

    errors: List[Dict[str, Any]] = []
    successes: List[Dict[str, Any]] = []
    for ident in candidates:
        try:
            result = arca_padron_get_persona(ident, service=service)
            result["input_doc_type"] = (doc_type or "").strip().upper()
            result["input_doc_number"] = arca_digits(doc_number)
            result["queried_id_persona"] = ident
            result["candidate_ids_tried"] = candidates
            result["candidate_fiscal_name"] = arca_padron_fiscal_name_from_values(result.get("values") or {})
            successes.append(result)
        except HTTPException as exc:
            errors.append({"idPersona": ident, "status_code": exc.status_code, "detail": exc.detail})
            continue
        except Exception as exc:
            errors.append({"idPersona": ident, "status_code": 500, "detail": str(exc)})
            continue

    if not successes:
        raise HTTPException(
            status_code=502,
            detail={
                "arca_padron_error": "No se encontró persona en Constancia/Padrón con los identificadores candidatos",
                "input_doc_type": (doc_type or "").strip().upper(),
                "input_doc_number": arca_digits(doc_number),
                "candidate_ids_tried": candidates,
                "errors": errors[-10:],
            },
        )

    if len(successes) == 1:
        successes[0]["candidate_ids_found"] = [successes[0].get("queried_id_persona")]
        return successes[0]

    chosen = arca_choose_best_padron_candidate(successes, preferred_name=preferred_name)
    if chosen:
        chosen["candidate_ids_found"] = [x.get("queried_id_persona") for x in successes]
        chosen["candidate_preferred_name"] = preferred_name
        return chosen

    matched = []
    for result in successes:
        if preferred_name and arca_names_match(result.get("candidate_fiscal_name"), preferred_name):
            matched.append(result)
    if len(matched) == 1:
        matched[0]["candidate_ids_found"] = [x.get("queried_id_persona") for x in successes]
        matched[0]["candidate_match_source"] = "preferred_name"
        matched[0]["candidate_preferred_name"] = preferred_name
        return matched[0]

    raise HTTPException(
        status_code=409,
        detail={
            "arca_padron_error": "DNI ambiguo: más de un CUIT/CUIL válido para el mismo DNI",
            "input_doc_type": (doc_type or "").strip().upper(),
            "input_doc_number": arca_digits(doc_number),
            "preferred_name": preferred_name,
            "candidate_ids_found": [x.get("queried_id_persona") for x in successes],
            "candidates": [
                {
                    "idPersona": x.get("queried_id_persona"),
                    "fiscal_name": x.get("candidate_fiscal_name"),
                    "values": x.get("values"),
                }
                for x in successes
            ],
        },
    )


def arca_padron_get_persona(doc_number: str, service: Optional[str] = None) -> Dict[str, Any]:
    doc_digits = arca_digits(doc_number)
    if not doc_digits:
        raise HTTPException(status_code=400, detail="doc_number vacío")

    ta = arca_padron_auth(service=service)
    url = arca_padron_url()
    token = html_lib.escape(str(ta.get("token") or ""))
    sign = html_lib.escape(str(ta.get("sign") or ""))
    cuit = html_lib.escape(arca_digits(ta.get("cuit_representada") or ARCA_EMISOR_CUIT))
    ident = html_lib.escape(doc_digits)

    # ws_sr_constancia_inscripcion / personaServiceA5.
    # getPersona_v2 recibe token, sign, cuitRepresentada e idPersona.
    soap = f"""<?xml version="1.0" encoding="UTF-8"?>
<soapenv:Envelope xmlns:soapenv="http://schemas.xmlsoap.org/soap/envelope/" xmlns:a5="http://a5.soap.ws.server.puc.sr/">
  <soapenv:Header/>
  <soapenv:Body>
    <a5:getPersona_v2>
      <token>{token}</token>
      <sign>{sign}</sign>
      <cuitRepresentada>{cuit}</cuitRepresentada>
      <idPersona>{ident}</idPersona>
    </a5:getPersona_v2>
  </soapenv:Body>
</soapenv:Envelope>"""

    txt = arca_soap_post(url, "", soap)
    root = ET.fromstring(txt)
    values = arca_xml_values_by_localname(root)

    error_text = arca_first_xml_value(values, ["error", "faultstring", "descripcionError", "mensaje", "message"])
    if error_text and not arca_first_xml_value(values, ["idPersona", "razonSocial", "nombre", "apellido"]):
        raise HTTPException(status_code=502, detail={"arca_padron_error": error_text, "doc_number": doc_digits})

    return {
        "ok": True,
        "service": service or ARCA_PADRON_SERVICE,
        "url": url,
        "doc_number": doc_digits,
        "values": values,
        "raw_xml_preview": txt[:4000],
    }


def arca_padron_pick_fiscal_data(doc_type: str, doc_number: str, padron: Dict[str, Any]) -> Dict[str, Any]:
    values = padron.get("values") or {}

    fiscal_name = arca_padron_fiscal_name_from_values(values)

    address = arca_first_xml_value(values, ["direccion", "domicilio", "calle", "address"])
    city = arca_first_xml_value(values, ["localidad", "descripcionLocalidad", "ciudad", "city"])
    province = arca_first_xml_value(values, ["descripcionProvincia", "provincia", "state", "province"])
    zip_code = arca_first_xml_value(values, ["codigoPostal", "codPostal", "zip", "zipcode"])

    joined = " | ".join([str(x) for vals in values.values() for x in vals]).lower()
    iva_condition = None
    if "monotrib" in joined:
        iva_condition = "Monotributo"
    elif "responsable inscrip" in joined or "iva" in joined:
        iva_condition = "Responsable Inscripto"
    if not iva_condition:
        iva_condition = "Consumidor Final"

    return {
        "fiscal_name": fiscal_name or None,
        "doc_type": (doc_type or ("CUIT" if len(arca_digits(doc_number)) == 11 else "DNI")).upper(),
        "doc_number": arca_digits(doc_number),
        "iva_condition": iva_condition,
        "address": address,
        "city": city,
        "province": province,
        "zip": zip_code,
        "raw_data": {"arca_padron": padron},
    }


def arca_upsert_customer_from_padron_order(item: ArcaPadronFiscalOrderIn, dry_run: bool = True) -> Dict[str, Any]:
    channel = (item.channel or "ML").strip().upper()
    external_order_id = str(item.external_order_id).strip().replace("#", "")
    doc_digits = arca_digits(item.doc_number)
    tenant_id = str(get_effective_tenant_id() or DEFAULT_TENANT_ID)
    if not external_order_id or not doc_digits:
        raise HTTPException(status_code=400, detail="external_order_id y doc_number son obligatorios")

    order = get_order_row(channel, external_order_id)
    if not order:
        return {"ok": False, "external_order_id": external_order_id, "error": "Venta no encontrada en orders"}

    raw_order = order.get("raw_data") or {}
    if not isinstance(raw_order, dict):
        raw_order = {"previous_raw_data": raw_order}

    channel_fallback_customer: Dict[str, Any] = {}
    if channel == "ML":
        ml_raw = raw_order.get("ml_raw") or {}
        if isinstance(ml_raw, dict) and ml_raw:
            billing_id = ml_billing_id_from_order(ml_raw)
            billing_detail = ml_get_billing_info_safe(ml_raw.get("id") or external_order_id, billing_id)
            shipment = None
            shipping_id = ((ml_raw.get("shipping") or {}).get("id") if isinstance(ml_raw.get("shipping"), dict) else None) or raw_order.get("ml_shipping_id")
            if shipping_id:
                shipment = ml_get_shipment_safe(shipping_id)
            try:
                channel_fallback_customer = pc_customer_from_ml_order(ml_raw, shipment=shipment, billing_detail=billing_detail)
            except Exception:
                channel_fallback_customer = {}
    elif channel == "TN":
        tn_raw = raw_order.get("tn_raw") or {}
        if isinstance(tn_raw, dict) and tn_raw:
            try:
                channel_fallback_customer = pc_customer_from_tn_order(tn_raw)
            except Exception:
                channel_fallback_customer = {}

    preferred_name = pc_first_nonempty(channel_fallback_customer.get("fiscal_name"))
    padron = arca_padron_get_persona_for_doc(item.doc_type, doc_digits, preferred_name=preferred_name)
    fiscal = arca_padron_pick_fiscal_data(item.doc_type, doc_digits, padron)
    fiscal = arca_apply_fiscal_fallbacks(fiscal, channel_fallback_customer, padron)

    ml_user_id = None
    if channel == "ML":
        ml_user_id = pc_clean_str(((raw_order.get("ml_raw") or {}).get("buyer") or {}).get("id"))
    tn_customer_id = None
    if channel == "TN":
        tn_customer_id = pc_clean_str(((raw_order.get("tn_order") or raw_order).get("customer") or {}).get("id"))

    customer_candidate = {
        "tenant_id": tenant_id,
        "source_origin": channel,
        "source_label": "MercadoLibre" if channel == "ML" else ("TiendaNube" if channel == "TN" else channel),
        "source_customer_id": ml_user_id or tn_customer_id,
        "name": channel_fallback_customer.get("fiscal_name"),
        "fiscal_name": channel_fallback_customer.get("fiscal_name"),
        "doc_type": fiscal.get("doc_type"),
        "doc_number": fiscal.get("doc_number"),
        "iva_condition": fiscal.get("iva_condition"),
        "email": None,
        "phone": order.get("customer_phone"),
        "address": fiscal.get("address"),
        "city": fiscal.get("city"),
        "province": fiscal.get("province"),
        "zip": fiscal.get("zip"),
        "ml_user_id": ml_user_id,
        "tn_customer_id": tn_customer_id,
        "last_order_channel": channel,
        "last_order_id": external_order_id,
        "last_order_date": pc_clean_str(raw_order.get("ml_date_closed") or raw_order.get("ml_date_created") or order.get("created_at")),
        "notes": "Datos fiscales reparados desde ARCA Padrón/A5",
        "raw_data": {
            "fiscal_repair": {
                "at": now_iso(),
                "source": "arca_constancia_inscripcion",
                "customer_name_source": "arca",
                "channel": channel,
                "external_order_id": external_order_id,
                "doc_type": fiscal.get("doc_type"),
                "doc_number": fiscal.get("doc_number"),
                "fiscal_name": fiscal.get("fiscal_name"),
                "address": fiscal.get("address"),
                "city": fiscal.get("city"),
                "province": fiscal.get("province"),
                "zip": fiscal.get("zip"),
                "iva_condition": fiscal.get("iva_condition"),
                "padron_values": padron.get("values"),
                "queried_id_persona": padron.get("queried_id_persona"),
                "candidate_ids_tried": padron.get("candidate_ids_tried"),
                "candidate_ids_found": padron.get("candidate_ids_found"),
                "fiscal_quality": (fiscal.get("raw_data") or {}).get("fiscal_quality"),
            }
        },
    }

    existing_rows = (
        sb.table("erp_customers")
        .select("*")
        .eq("tenant_id", tenant_id)
        .eq("last_order_channel", channel)
        .eq("last_order_id", external_order_id)
        .limit(1)
        .execute()
        .data
        or []
    )
    if not existing_rows and fiscal.get("doc_number"):
        existing_rows = (
            sb.table("erp_customers")
            .select("*")
            .eq("tenant_id", tenant_id)
            .eq("doc_number", fiscal.get("doc_number"))
            .limit(1)
            .execute()
            .data
            or []
        )
    if not existing_rows and ml_user_id:
        existing_rows = (
            sb.table("erp_customers")
            .select("*")
            .eq("tenant_id", tenant_id)
            .eq("ml_user_id", ml_user_id)
            .limit(1)
            .execute()
            .data
            or []
        )
    if not existing_rows and tn_customer_id:
        existing_rows = (
            sb.table("erp_customers")
            .select("*")
            .eq("tenant_id", tenant_id)
            .eq("tn_customer_id", tn_customer_id)
            .limit(1)
            .execute()
            .data
            or []
        )

    existing = existing_rows[0] if existing_rows else None
    overwrite_payload = {
        "tenant_id": tenant_id,
        "source_origin": customer_candidate["source_origin"],
        "source_label": customer_candidate["source_label"],
        "source_customer_id": customer_candidate.get("source_customer_id"),
        "name": customer_candidate.get("name"),
        "fiscal_name": customer_candidate.get("fiscal_name"),
        "doc_type": customer_candidate.get("doc_type"),
        "doc_number": customer_candidate.get("doc_number"),
        "iva_condition": customer_candidate.get("iva_condition"),
        "phone": customer_candidate.get("phone"),
        "address": customer_candidate.get("address"),
        "city": customer_candidate.get("city"),
        "province": customer_candidate.get("province"),
        "zip": customer_candidate.get("zip"),
        "ml_user_id": customer_candidate.get("ml_user_id"),
        "tn_customer_id": customer_candidate.get("tn_customer_id"),
        "last_order_channel": channel,
        "last_order_id": external_order_id,
        "last_order_date": customer_candidate.get("last_order_date"),
        "notes": customer_candidate.get("notes"),
        "updated_at": now_iso(),
    }
    overwrite_payload = {k: v for k, v in overwrite_payload.items() if v not in [None, ""]}

    raw_existing = (existing or {}).get("raw_data") or {}
    if not isinstance(raw_existing, dict):
        raw_existing = {"previous_raw_data": raw_existing}
    raw_existing.setdefault("sources", [])
    raw_existing["sources"].append(customer_candidate.get("raw_data") or {})
    raw_existing["sources"] = raw_existing["sources"][-20:]
    overwrite_payload["raw_data"] = raw_existing

    if existing:
        action = "would_update" if dry_run else "updated"
        if not dry_run:
            (
                sb.table("erp_customers")
                .update(overwrite_payload)
                .eq("id", existing.get("id"))
                .eq("tenant_id", tenant_id)
                .execute()
            )
        customer_id = existing.get("id")
    else:
        row = {
            "id": str(uuid.uuid4()),
            "tenant_id": tenant_id,
            "company_id": "planetacasa",
            **overwrite_payload,
            "email": None,
            "marketing_email_opt_in": False,
            "marketing_whatsapp_opt_in": False,
            "created_at": now_iso(),
        }
        action = "would_insert" if dry_run else "inserted"
        if not dry_run:
            sb.table("erp_customers").insert(row).execute()
        customer_id = row["id"]

    if not dry_run:
        raw_order["fiscal_enrichment"] = {
            "at": now_iso(),
            "source": "arca_constancia_inscripcion",
            "erp_customer_id": customer_id,
            "doc_type": fiscal.get("doc_type"),
            "doc_number": fiscal.get("doc_number"),
            "fiscal_name": fiscal.get("fiscal_name"),
            "address": fiscal.get("address"),
            "city": fiscal.get("city"),
            "province": fiscal.get("province"),
            "zip": fiscal.get("zip"),
            "iva_condition": fiscal.get("iva_condition"),
            "queried_id_persona": padron.get("queried_id_persona"),
            "fiscal_quality": (fiscal.get("raw_data") or {}).get("fiscal_quality"),
        }
        order_update = {
            "raw_data": raw_order,
            "updated_at": now_iso(),
        }
        if channel != "ML" and customer_candidate.get("name"):
            order_update["customer_name"] = customer_candidate.get("name")
        (
            sb.table("orders")
            .update({k: v for k, v in order_update.items() if v not in [None, ""]})
            .eq("id", order.get("id"))
            .eq("tenant_id", tenant_id)
            .execute()
        )

    return {
        "ok": True,
        "action": action,
        "dry_run": dry_run,
        "channel": channel,
        "external_order_id": external_order_id,
        "customer_id": customer_id,
        "before": existing,
        "update": overwrite_payload,
        "fiscal": fiscal,
    }


def arca_wsfe_auth_xml(ta: Dict[str, Any]) -> str:
    return f"""<ar:Auth>
  <ar:Token>{html_lib.escape(str(ta.get("token") or ""))}</ar:Token>
  <ar:Sign>{html_lib.escape(str(ta.get("sign") or ""))}</ar:Sign>
  <ar:Cuit>{arca_digits(ARCA_EMISOR_CUIT)}</ar:Cuit>
</ar:Auth>"""


def arca_wsfe_request(method: str, inner_xml: str) -> ET.Element:
    ta = arca_wsaa_login_ticket()
    soap_action = f"http://ar.gov.afip.dif.FEV1/{method}"
    soap = f"""<?xml version="1.0" encoding="UTF-8"?>
<soapenv:Envelope xmlns:soapenv="http://schemas.xmlsoap.org/soap/envelope/" xmlns:ar="http://ar.gov.afip.dif.FEV1/">
  <soapenv:Header/>
  <soapenv:Body>
    <ar:{method}>
      {arca_wsfe_auth_xml(ta)}
      {inner_xml}
    </ar:{method}>
  </soapenv:Body>
</soapenv:Envelope>"""
    txt = arca_soap_post(arca_wsfe_url(), soap_action, soap)
    return ET.fromstring(txt)


def arca_wsfe_last_voucher(cbte_tipo: int) -> int:
    inner = f"""<ar:PtoVta>{ARCA_PTO_VTA}</ar:PtoVta>
<ar:CbteTipo>{cbte_tipo}</ar:CbteTipo>"""
    root = arca_wsfe_request("FECompUltimoAutorizado", inner)
    errors = arca_wsfe_errors(root)
    if errors:
        raise HTTPException(status_code=502, detail={"arca_errors": errors})
    nro = arca_find_text_by_localname(root, "CbteNro")
    return int(arca_digits(nro) or "0")


def arca_wsfe_errors(root: ET.Element) -> List[Dict[str, Any]]:
    out = []
    for err in root.iter():
        if arca_localname(err.tag).lower() in ["err", "obs"]:
            code = arca_find_text_by_localname(err, "Code") or arca_find_text_by_localname(err, "CodeMsg")
            msg = arca_find_text_by_localname(err, "Msg")
            if code or msg:
                out.append({"code": code, "msg": msg})
    return out


def arca_doc_tipo_nro(customer: Dict[str, Any], cbte_letter: str) -> Dict[str, int]:
    doc_digits = arca_digits(customer.get("doc_number"))
    doc_type = normalizar(customer.get("doc_type"))
    iva = normalizar(customer.get("iva_condition"))
    if len(doc_digits) == 11 or doc_type == "cuit" or "responsable" in iva or "monotrib" in iva:
        if len(doc_digits) != 11:
            raise HTTPException(status_code=400, detail="Factura A / cliente fiscal requiere CUIT de 11 dígitos")
        return {"doc_tipo": 80, "doc_nro": int(doc_digits)}
    if len(doc_digits) in [7, 8] or doc_type == "dni":
        return {"doc_tipo": 96, "doc_nro": int(doc_digits)}
    return {"doc_tipo": 99, "doc_nro": 0}


def arca_wsfe_amounts(payload: Dict[str, Any]) -> Dict[str, float]:
    lines = payload.get("lines") or []
    net = round(sum(arca_float(x.get("subtotal_net"), 0) for x in lines), 2)
    iva = round(sum(arca_float(x.get("iva_amount"), 0) for x in lines), 2)
    total = round(sum(arca_float(x.get("total_gross"), 0) for x in lines), 2)
    if total <= 0 or net <= 0:
        raise HTTPException(status_code=400, detail="Factura sin importes válidos para WSFE")
    if str(payload.get("cbte_letra") or "").upper() == "C":
        return {"net": total, "iva": 0.0, "total": total}
    iva = round(total - net, 2)
    return {"net": net, "iva": iva, "total": total}


def arca_concept_id(value: Any) -> int:
    text = normalizar(value or "productos")
    if "productos y servicios" in text or "productos servicios" in text:
        return 3
    if "servicio" in text:
        return 2
    return 1


def arca_wsfe_request_cae_extended(
    client: Any,
    *,
    cbte_tipo: int,
    concepto: int,
    doc_tipo: int,
    doc_nro: Any,
    amounts: Dict[str, float],
    condicion_iva_receptor_id: int,
    cbte_nro: int,
    cbte_fch: str,
    cbtes_asoc: Optional[List[Dict[str, Any]]] = None,
    service_date_from: Optional[str] = None,
    service_date_to: Optional[str] = None,
    payment_due_date: Optional[str] = None,
) -> Dict[str, Any]:
    """FECAESolicitar completo para NC/ND/C y conceptos de servicios.

    El cliente mínimo histórico no exponía CbtesAsoc ni fechas de servicio. Este
    helper conserva su autenticación/certificado y sólo amplía el detalle WSFE.
    """
    client.auth()

    def money(value: Any) -> str:
        return f"{float(value or 0):.2f}"

    def ymd(value: Any) -> str:
        return arca_safe_invoice_date(value)[:10].replace("-", "")

    service_block = ""
    if int(concepto) in [2, 3]:
        if not (service_date_from and service_date_to and payment_due_date):
            raise HTTPException(status_code=400, detail="Servicios requiere período desde/hasta y vencimiento de pago")
        service_block = (
            f"<FchServDesde>{ymd(service_date_from)}</FchServDesde>"
            f"<FchServHasta>{ymd(service_date_to)}</FchServHasta>"
            f"<FchVtoPago>{ymd(payment_due_date)}</FchVtoPago>"
        )

    assoc_rows = []
    for assoc in cbtes_asoc or []:
        assoc_date = ""
        if assoc.get("fecha"):
            raw_date = str(assoc.get("fecha") or "")
            digits_date = arca_digits(raw_date)
            assoc_date = digits_date[:8] if len(digits_date) >= 8 else ymd(raw_date)
        assoc_rows.append(
            "<CbteAsoc>"
            f"<Tipo>{int(assoc.get('tipo') or 0)}</Tipo>"
            f"<PtoVta>{int(assoc.get('pto_vta') or 0)}</PtoVta>"
            f"<Nro>{int(assoc.get('nro') or 0)}</Nro>"
            f"{f'<CbteFch>{assoc_date}</CbteFch>' if assoc_date else ''}"
            "</CbteAsoc>"
        )
    assoc_block = f"<CbtesAsoc>{''.join(assoc_rows)}</CbtesAsoc>" if assoc_rows else ""

    iva_block = ""
    if float(amounts.get("iva") or 0) != 0:
        iva_block = (
            "<Iva><AlicIva>"
            "<Id>5</Id>"
            f"<BaseImp>{money(amounts.get('net'))}</BaseImp>"
            f"<Importe>{money(amounts.get('iva'))}</Importe>"
            "</AlicIva></Iva>"
        )

    envelope = f"""<?xml version="1.0" encoding="utf-8"?>
<soap:Envelope xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" xmlns:xsd="http://www.w3.org/2001/XMLSchema" xmlns:soap="http://schemas.xmlsoap.org/soap/envelope/">
  <soap:Body>
    <FECAESolicitar xmlns="http://ar.gov.afip.dif.FEV1/">
      <Auth><Token>{html_lib.escape(str(client._token or ''))}</Token><Sign>{html_lib.escape(str(client._sign or ''))}</Sign><Cuit>{html_lib.escape(str(client.config.cuit))}</Cuit></Auth>
      <FeCAEReq>
        <FeCabReq><CantReg>1</CantReg><PtoVta>{int(client.config.pto_vta)}</PtoVta><CbteTipo>{int(cbte_tipo)}</CbteTipo></FeCabReq>
        <FeDetReq><FECAEDetRequest>
          <Concepto>{int(concepto)}</Concepto><DocTipo>{int(doc_tipo)}</DocTipo><DocNro>{arca_digits(doc_nro) or '0'}</DocNro>
          <CbteDesde>{int(cbte_nro)}</CbteDesde><CbteHasta>{int(cbte_nro)}</CbteHasta><CbteFch>{cbte_fch}</CbteFch>
          <ImpTotal>{money(amounts.get('total'))}</ImpTotal><ImpTotConc>0.00</ImpTotConc><ImpNeto>{money(amounts.get('net'))}</ImpNeto><ImpOpEx>0.00</ImpOpEx><ImpIVA>{money(amounts.get('iva'))}</ImpIVA><ImpTrib>0.00</ImpTrib>
          {service_block}<MonId>PES</MonId><MonCotiz>1.000000</MonCotiz>{assoc_block}{iva_block}<CondicionIVAReceptorId>{int(condicion_iva_receptor_id)}</CondicionIVAReceptorId>
        </FECAEDetRequest></FeDetReq>
      </FeCAEReq>
    </FECAESolicitar>
  </soap:Body>
</soap:Envelope>"""
    xml = client._wsfe_post(envelope, "FECAESolicitar")
    root = ET.fromstring(xml.encode("utf-8"))
    cae = arca_find_text_by_localname(root, "CAE")
    resultado = arca_find_text_by_localname(root, "Resultado")
    return {
        "ok": bool(cae) and resultado == "A",
        "env": client.config.env,
        "pto_vta": int(client.config.pto_vta),
        "cbte_tipo": int(cbte_tipo),
        "cbte_desde": int(cbte_nro),
        "cbte_hasta": int(cbte_nro),
        "resultado": resultado,
        "cae": cae,
        "cae_vto": arca_find_text_by_localname(root, "CAEFchVto"),
        "observations": arca_wsfe_errors(root),
        "raw_xml": xml,
    }


def arca_cbte_letter_from_tipo(cbte_tipo: int) -> str:
    t = int(cbte_tipo or 0)
    if t in [1, 2, 3]:
        return "A"
    if t in [6, 7, 8]:
        return "B"
    if t in [11, 12, 13, 15]:
        return "C"
    if t == 19:
        return "E"
    return ""


def arca_cbte_base_label_from_tipo(cbte_tipo: int) -> str:
    t = int(cbte_tipo or 0)
    if t in [1, 6, 11, 19]:
        return "Factura"
    if t in [2, 7, 12]:
        return "Nota de Débito"
    if t in [3, 8, 13]:
        return "Nota de Crédito"
    if t == 15:
        return "Recibo"
    return "Comprobante"


def arca_cbte_label_from_tipo(cbte_tipo: int) -> str:
    letter = arca_cbte_letter_from_tipo(cbte_tipo)
    base = arca_cbte_base_label_from_tipo(cbte_tipo)
    return f"{base} {letter}".strip()


def arca_build_manual_test_payload(body: ArcaEmitirTestIn) -> Dict[str, Any]:
    cbte_tipo = int(body.cbte_tipo or 6)
    if cbte_tipo not in [1, 6]:
        raise HTTPException(status_code=400, detail="Por ahora emitir_test solo soporta 1=Factura A y 6=Factura B")

    cbte_letra = arca_cbte_letter_from_tipo(cbte_tipo)
    qty = round(float(body.quantity or 1), 4)
    unit_gross = float(body.unit_price_gross) if body.unit_price_gross is not None else None
    gross = float(body.total_gross) if body.total_gross is not None else None
    if gross is None and unit_gross is not None:
        gross = qty * unit_gross
    gross = round(float(gross or 0), 2)
    iva_pct = round(float(body.iva_pct or ARCA_IVA_ALICUOTA), 2)
    if qty <= 0:
        raise HTTPException(status_code=400, detail="quantity debe ser mayor a cero")
    if gross <= 0:
        raise HTTPException(status_code=400, detail="total_gross debe ser mayor a cero o debe venir unit_price_gross")
    unit_gross = round(float(unit_gross if unit_gross is not None else gross / qty), 2)
    line_sku = norm_sku(body.sku) or "ARCA_MANUAL"
    if cbte_tipo == 1 and not arca_digits(body.customer_doc_number):
        raise HTTPException(status_code=400, detail="Factura A requiere CUIT del cliente")

    # Para RI con IVA discriminado: neto + IVA = total.
    net = round(gross / (1 + iva_pct / 100), 2)
    iva_amount = round(gross - net, 2)
    source_id = f"ARCA-MANUAL-{datetime.now(timezone(timedelta(hours=-3))).strftime('%Y%m%d-%H%M%S')}-{uuid.uuid4().hex[:8]}"
    invoice_date = body.invoice_date or datetime.now(timezone(timedelta(hours=-3))).date().isoformat()

    return {
        "status": "draft",
        "environment": ARCA_ENV,
        "source_channel": "ARCA_MANUAL",
        "source_order_id": source_id,
        "source_order_number": source_id,
        "source_order_api_id": source_id,
        "source_pack_id": None,
        "source_shipping_id": None,
        "source_customer_name": body.customer_name,
        "source_created_at": now_iso(),
        "invoice_date": invoice_date,
        "concept": body.concept or ARCA_DEFAULT_CONCEPTO,
        "cbte_tipo": cbte_tipo,
        "cbte_letra": cbte_letra,
        "cbte_tipo_label": f"Factura {cbte_letra}",
        "pto_vta": ARCA_PTO_VTA,
        "cbte_nro": None,
        "cae": None,
        "cae_vto": None,
        "customer_name": body.customer_name,
        "customer_doc_type": body.customer_doc_type,
        "customer_doc_number": body.customer_doc_number,
        "customer_iva_condition": body.customer_iva_condition,
        "customer_address": body.customer_address,
        "customer_email": body.customer_email,
        "importe_neto": net,
        "importe_iva": iva_amount,
        "importe_total": gross,
        "iva_contenido": 0.0,
        "currency": "ARS",
        "lines": [{
            "sku": line_sku,
            "description": body.description or "Venta manual ERP Planeta Casa",
            "quantity": qty,
            "unit_price_gross": unit_gross,
            "discount_pct": 0,
            "total_gross": gross,
            "subtotal_net": net,
            "iva_pct": iva_pct,
            "iva_amount": iva_amount,
            "source": "manual_erp",
        }],
        "notes": body.notes,
        "raw_data": {
            "manual_erp": True,
            "built_at": now_iso(),
            "input": body.model_dump(),
            "safety": "dry_run=true no emite; para emitir requiere dry_run=false y confirmar=true",
        },
        "created_at": now_iso(),
        "updated_at": now_iso(),
    }



def arca_location_text(value: Any) -> str:
    """Normaliza una localidad sin convertir diccionarios completos en texto."""
    if value is None:
        return ""
    if isinstance(value, str):
        text = value.strip()
        if text.lower() in {"", "none", "null", "{}", "[]"}:
            return ""
        return text
    if isinstance(value, dict):
        for key in ("name", "value", "label", "description", "city_name", "localidad", "locality"):
            text = arca_location_text(value.get(key))
            if text:
                return text
        return ""
    if isinstance(value, (list, tuple)):
        for item in value:
            text = arca_location_text(item)
            if text:
                return text
        return ""
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        return str(value).strip()
    return ""


def arca_nested_value(data: Any, *path: str) -> Any:
    current = data
    for key in path:
        if not isinstance(current, dict):
            return None
        current = current.get(key)
    return current


def arca_additional_info_value(data: Any, wanted_type: str) -> str:
    """Busca un valor tipado de billing_info sin tomar ciudades del remitente."""
    wanted = str(wanted_type or "").strip().upper()
    if isinstance(data, dict):
        if str(data.get("type") or "").strip().upper() == wanted:
            return arca_location_text(data.get("value"))
        for value in data.values():
            found = arca_additional_info_value(value, wanted)
            if found:
                return found
    elif isinstance(data, (list, tuple)):
        for value in data:
            found = arca_additional_info_value(value, wanted)
            if found:
                return found
    return ""


def arca_customer_localidad_from_raw(inv_or_payload: Dict[str, Any]) -> str:
    """Devuelve sólo la localidad del comprador, nunca la del remitente/logística."""
    # 1) Datos explícitos del comprobante/payload.
    for key in ("customer_localidad", "localidad", "customer_city"):
        text = arca_location_text(inv_or_payload.get(key))
        if text:
            return text

    raw = inv_or_payload.get("raw_data") or {}
    if not isinstance(raw, dict):
        raw = {}

    # 2) Datos fiscales explícitos persistidos con la factura.
    customer_fiscal = raw.get("customer_fiscal") or {}
    if isinstance(customer_fiscal, dict):
        for key in ("localidad", "city", "locality", "location"):
            text = arca_location_text(customer_fiscal.get(key))
            if text:
                return text

    order = raw.get("order") if isinstance(raw.get("order"), dict) else {}
    order_raw = order.get("raw_data") if isinstance(order.get("raw_data"), dict) else {}

    # 3) Cliente maestro: es la fuente normalizada y evita confundir sender_address.city.
    customer_id_candidates = [
        inv_or_payload.get("customer_id"),
        raw.get("customer_id"),
        arca_nested_value(order_raw, "customer_enrichment", "customer_id"),
        arca_nested_value(raw, "customer_enrichment", "customer_id"),
    ]
    tenant_id = str(inv_or_payload.get("tenant_id") or get_effective_tenant_id() or "").strip()
    if _sb_raw:
        for customer_id in customer_id_candidates:
            customer_id = str(customer_id or "").strip()
            if not customer_id:
                continue
            try:
                query = _sb_raw.table("erp_customers").select("city").eq("id", customer_id)
                if tenant_id:
                    query = query.eq("tenant_id", tenant_id)
                rows = query.limit(1).execute().data or []
                if rows:
                    text = arca_location_text((rows[0] or {}).get("city"))
                    if text:
                        return text
            except Exception as exc:
                print(f"[ARCA PDF] No pude leer localidad customer_id={customer_id}: {exc}", flush=True)

    # 4) Billing info de ML: CITY_NAME es del comprador.
    for source in (raw, order_raw):
        text = arca_additional_info_value(source, "CITY_NAME")
        if text:
            return text

    # 5) Dirección receptora del envío, nunca sender_address.
    receiver_city_candidates = [
        arca_nested_value(order_raw, "ml_shipping_last_snapshot", "receiver_address", "city"),
        arca_nested_value(order_raw, "ml_shipment", "receiver_address", "city"),
        arca_nested_value(raw, "receiver_address", "city"),
    ]
    for value in receiver_city_candidates:
        text = arca_location_text(value)
        if text:
            return text

    # 6) Fallbacks con nombres inequívocos; se excluye el genérico "city".
    for key in ("customer_localidad", "localidad", "customer_city", "contact_city", "shipping_city", "billing_city"):
        value = arca_deep_find(raw, [key])
        text = arca_location_text(value)
        if text:
            return text
    return ""


def arca_normalize_manual_localidad(iva_condition: Any, localidad: Any) -> str:
    loc = str(localidad or "").strip()
    if loc:
        return loc
    cond = normalizar(iva_condition or "")
    if "consumidor final" in cond or cond in ["cf", "cons final"]:
        return "Ciudad Autónoma de Buenos Aires"
    raise HTTPException(status_code=400, detail="La localidad del receptor es obligatoria. Para Consumidor Final manual se puede dejar vacía y se usa Ciudad Autónoma de Buenos Aires.")


def arca_build_manual_comprobante_payload(body: ArcaComprobanteManualIn) -> Dict[str, Any]:
    cbte_tipo = int(body.cbte_tipo or 6)
    if cbte_tipo == 19:
        raise HTTPException(
            status_code=400,
            detail="Factura de Exportación (019) usa WSFEX y requiere país destino, moneda e incoterm. No puede emitirse desde el formulario WSFE doméstico.",
        )
    if cbte_tipo not in [1, 2, 3, 6, 7, 8, 11, 12, 13]:
        raise HTTPException(status_code=400, detail="Comprobante manual soportado: Factura, Nota de Débito y Nota de Crédito A/B/C")

    cbte_letra = arca_cbte_letter_from_tipo(cbte_tipo)
    cbte_tipo_label = arca_cbte_label_from_tipo(cbte_tipo)
    customer_name = str(body.customer_name or "").strip()
    if not customer_name:
        raise HTTPException(status_code=400, detail="El nombre / razón social del receptor es obligatorio")

    localidad = arca_normalize_manual_localidad(body.customer_iva_condition, body.customer_localidad)
    doc_digits = arca_digits(body.customer_doc_number)
    if cbte_letra == "A":
        if len(doc_digits) != 11:
            raise HTTPException(status_code=400, detail="Comprobantes A requieren CUIT del receptor de 11 dígitos")
        body.customer_doc_type = "CUIT"

    cbtes_asoc = []
    if cbte_tipo in [2, 3, 7, 8, 12, 13]:
        if not (body.associated_cbte_tipo and body.associated_pto_vta and body.associated_cbte_nro):
            raise HTTPException(status_code=400, detail="Para Nota de Crédito / Débito falta comprobante original asociado")
        cbtes_asoc.append({
            "tipo": int(body.associated_cbte_tipo),
            "pto_vta": int(body.associated_pto_vta),
            "nro": int(body.associated_cbte_nro),
            "fecha": arca_safe_invoice_date(body.associated_invoice_date)[:10].replace("-", "") if body.associated_invoice_date else None,
            "cae": body.associated_cae,
            "invoice_id": body.associated_invoice_id,
        })

    out_lines: List[Dict[str, Any]] = []
    total_gross = 0.0
    total_net = 0.0
    total_iva = 0.0
    for idx, line in enumerate(body.lines or [], start=1):
        qty = round(float(line.quantity or 1), 4)
        unit = float(line.unit_price_gross) if line.unit_price_gross is not None else None
        gross = float(line.total_gross) if line.total_gross is not None else None
        if gross is None and unit is not None:
            gross = qty * unit
        gross = round(float(gross or 0), 2)
        iva_pct = round(float(line.iva_pct or ARCA_IVA_ALICUOTA), 2)
        discount_pct = round(float(line.discount_pct or 0), 2)
        if qty <= 0:
            raise HTTPException(status_code=400, detail=f"Línea {idx}: quantity debe ser mayor a cero")
        if gross <= 0:
            raise HTTPException(status_code=400, detail=f"Línea {idx}: total_gross debe ser mayor a cero o debe venir unit_price_gross")
        unit = round(float(unit if unit is not None else gross / qty), 2)
        if cbte_letra == "C":
            net = gross
            iva_amount = 0.0
        else:
            net = round(gross / (1 + iva_pct / 100), 2)
            iva_amount = round(gross - net, 2)
        total_gross = round(total_gross + gross, 2)
        total_net = round(total_net + net, 2)
        total_iva = round(total_iva + iva_amount, 2)
        out_lines.append({
            "sku": norm_sku(line.sku) or "ARCA_MANUAL",
            "description": str(line.description or "Producto").strip(),
            "quantity": qty,
            "unit_price_gross": unit,
            "discount_pct": discount_pct,
            "total_gross": gross,
            "subtotal_net": net,
            "iva_pct": iva_pct,
            "iva_amount": iva_amount,
            "source": "manual_erp",
        })

    source_id = body.source_order_id or f"ARCA-MANUAL-{datetime.now(timezone(timedelta(hours=-3))).strftime('%Y%m%d-%H%M%S')}-{uuid.uuid4().hex[:8]}"
    invoice_date = body.invoice_date or datetime.now(timezone(timedelta(hours=-3))).date().isoformat()
    concept_id = arca_concept_id(body.concept)
    if concept_id in [2, 3] and not (body.service_date_from and body.service_date_to and body.payment_due_date):
        raise HTTPException(status_code=400, detail="Servicios requiere período desde/hasta y vencimiento de pago")
    raw_input = body.model_dump()

    return {
        "status": "draft",
        "environment": ARCA_ENV,
        "source_channel": norm_sku(body.source_channel) or "ARCA_MANUAL",
        "source_order_id": source_id,
        "source_order_number": body.source_order_number or source_id,
        "source_order_api_id": source_id,
        "source_pack_id": None,
        "source_shipping_id": None,
        "source_customer_name": customer_name,
        "source_created_at": now_iso(),
        "invoice_date": invoice_date,
        "concept": body.concept or ARCA_DEFAULT_CONCEPTO,
        "concepto": concept_id,
        "service_date_from": body.service_date_from,
        "service_date_to": body.service_date_to,
        "payment_due_date": body.payment_due_date,
        "cbte_tipo": cbte_tipo,
        "cbte_letra": cbte_letra,
        "cbte_tipo_label": cbte_tipo_label,
        "pto_vta": ARCA_PTO_VTA,
        "cbte_nro": None,
        "cae": None,
        "cae_vto": None,
        "customer_name": customer_name,
        "customer_doc_type": body.customer_doc_type,
        "customer_doc_number": body.customer_doc_number,
        "customer_iva_condition": body.customer_iva_condition,
        "customer_address": body.customer_address,
        "customer_email": body.customer_email,
        "importe_neto": total_net,
        "importe_iva": total_iva,
        "importe_total": total_gross,
        "iva_contenido": 0.0,
        "currency": "ARS",
        "lines": out_lines,
        "cbtes_asoc": cbtes_asoc,
        "notes": body.notes,
        "raw_data": {
            "manual_erp": True,
            "built_at": now_iso(),
            "input": raw_input,
            "associated_invoice": cbtes_asoc[0] if cbtes_asoc else None,
            "customer_fiscal": {
                "name": customer_name,
                "doc_type": body.customer_doc_type,
                "doc_number": body.customer_doc_number,
                "iva_condition": body.customer_iva_condition,
                "address": body.customer_address,
                "localidad": localidad,
                "email": body.customer_email,
            },
            "safety": "dry_run=true no emite; para emitir requiere dry_run=false y confirmar=true",
        },
        "created_at": now_iso(),
        "updated_at": now_iso(),
    }


def arca_manual_upsert_customer(payload: Dict[str, Any], invoice: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
    doc_number = pc_doc_norm(payload.get("customer_doc_number"))
    email = pc_email_norm(payload.get("customer_email"))
    if not doc_number and not email:
        return {"skipped": True, "reason": "sin_documento_ni_email"}

    raw = payload.get("raw_data") or {}
    fiscal = raw.get("customer_fiscal") if isinstance(raw, dict) else {}
    if not isinstance(fiscal, dict):
        fiscal = {}
    invoice = invoice or {}
    incoming = {
        "source_origin": "ARCA_MANUAL",
        "source_label": "Comprobante manual ARCA",
        "source_customer_id": doc_number or email,
        "name": payload.get("customer_name") or payload.get("source_customer_name"),
        "fiscal_name": payload.get("customer_name") or payload.get("source_customer_name"),
        "doc_type": payload.get("customer_doc_type"),
        "doc_number": doc_number,
        "iva_condition": payload.get("customer_iva_condition"),
        "email": email,
        "phone": None,
        "address": payload.get("customer_address"),
        "city": fiscal.get("localidad") or arca_customer_localidad_from_raw(payload),
        "province": None,
        "zip": None,
        "ml_user_id": None,
        "tn_customer_id": None,
        "last_order_channel": payload.get("source_channel") or "ARCA_MANUAL",
        "last_order_id": payload.get("source_order_id"),
        "last_order_date": payload.get("invoice_date") or now_iso(),
        "notes": "Origen: comprobante manual ARCA",
        "raw_data": {
            "source": "arca_manual_comprobante",
            "invoice_id": invoice.get("id"),
            "source_channel": payload.get("source_channel"),
            "source_order_id": payload.get("source_order_id"),
            "cbte_tipo": payload.get("cbte_tipo"),
            "cbte_nro": payload.get("cbte_nro"),
            "cae": payload.get("cae"),
        },
    }
    return pc_upsert_customer(incoming, dry_run=False)


def arca_emit_manual_comprobante(body: ArcaComprobanteManualIn) -> Dict[str, Any]:
    runtime = arca_tenant_emission_context()
    client = runtime["client"]
    issuer = runtime["issuer"]
    payload = arca_build_manual_comprobante_payload(body)
    payload["environment"] = "produccion"
    payload["env"] = "produccion"
    payload["cuit_emisor"] = issuer["cuit"]
    payload["pto_vta"] = issuer["pto_vta"]
    payload.setdefault("raw_data", {})
    payload["raw_data"]["tenant_emitter"] = issuer
    try:
        last = client.get_last_voucher(int(payload["cbte_tipo"]))
        ultimo = int(last.get("cbte_nro") or 0)
    except HTTPException:
        raise
    except Exception as exc:
        raise HTTPException(
            status_code=502,
            detail={
                "ok": False,
                "error": "ARCA no respondió al consultar el próximo número",
                "stage": "manual_get_last_voucher",
                "message": str(exc),
                "cbte_tipo": int(payload["cbte_tipo"]),
            },
        )
    proximo = ultimo + 1
    preview = {
        "ok": True,
        "version": APP_VERSION,
        "dry_run": bool(body.dry_run),
        "confirmar": bool(body.confirmar),
        "environment": "produccion",
        "is_production": True,
        "tenant_id": runtime["tenant_id"],
        "config_source": "tenant_db",
        "emit_enabled": True,
        "auto_invoice_enabled": ARCA_AUTO_INVOICE_ENABLED,
        "pto_vta": issuer["pto_vta"],
        "cbte_tipo": payload.get("cbte_tipo"),
        "cbte_letra": payload.get("cbte_letra"),
        "ultimo": ultimo,
        "proximo": proximo,
        "importe_total": payload.get("importe_total"),
        "importe_neto": payload.get("importe_neto"),
        "importe_iva": payload.get("importe_iva"),
        "customer_name": payload.get("customer_name"),
        "customer_doc_type": payload.get("customer_doc_type"),
        "customer_doc_number": payload.get("customer_doc_number"),
        "customer_localidad": arca_customer_localidad_from_raw(payload),
        "lines": payload.get("lines"),
        "stock_preview": apply_manual_comprobante_stock_movements({}, payload, dry_run=True) if bool(body.modifica_stock) else {"enabled": False},
        "payload": payload,
    }
    if body.dry_run or not body.confirmar:
        preview["nota"] = "PREVIEW: no emitió. Para emitir real: dry_run=false y confirmar=true."
        return preview
    # Este circuito SaaS ya queda protegido por sesión + tenant, certificado propio,
    # vista previa y confirmación explícita. ARCA_EMIT_ENABLED pertenece a los endpoints
    # legacy globales y no debe bloquear la emisión manual tenant-aware.
    wsfe = arca_wsfe_issue_cae(payload)
    payload.update({
        "environment": "produccion",
        "env": "produccion",
        "cuit_emisor": wsfe.get("cuit_emisor") or payload.get("cuit_emisor"),
        "pto_vta": wsfe.get("pto_vta") or payload.get("pto_vta"),
        "status": "issued",
        "cbte_nro": wsfe.get("cbte_nro"),
        "cae": wsfe.get("cae"),
        "cae_vto": wsfe.get("cae_vto"),
        "resultado": wsfe.get("resultado"),
        "updated_at": now_iso(),
    })
    payload.setdefault("raw_data", {})
    payload["raw_data"]["wsfe"] = wsfe
    payload["raw_data"]["issued_at"] = now_iso()
    save_result = None
    save_error = None
    try:
        save_result = arca_save_issued_invoice(payload)
    except Exception as exc:
        # El CAE ya fue otorgado: devolvemos siempre el número y el CAE para impedir
        # que un error local de guardado induzca al usuario a emitirlo otra vez.
        save_error = str(exc)
    invoice = (save_result or {}).get("invoice") or {}
    invoice_saved_for_dispatch = (save_result or {}).get("invoice") if isinstance(save_result, dict) else None
    customer_upsert = {"skipped": True, "reason": "invoice_not_saved"}
    if invoice:
        try:
            customer_upsert = arca_manual_upsert_customer(payload, invoice)
        except Exception as exc:
            customer_upsert = {"ok": False, "error": str(exc)}
    if bool(body.modifica_stock) and invoice:
        stock_result = apply_manual_comprobante_stock_movements(invoice, payload, dry_run=False)
    elif bool(body.modifica_stock):
        stock_result = {
            "enabled": True,
            "skipped": True,
            "reason": "invoice_not_saved",
            "note": "ARCA emitió el comprobante, pero no se modificó stock porque falló el guardado local.",
        }
    else:
        stock_result = {"enabled": False}

    # En comprobantes manuales/NC/ND no ejecutamos despacho pesado dentro de la emisión.
    # Motivo: la emisión fiscal ya terminó; si PDF/email/storage falla o cuelga, el navegador ve
    # "Failed to fetch" y el usuario puede reintentar y duplicar comprobantes.
    # El PDF queda disponible bajo demanda por /admin/arca/facturas/{id}/pdf.
    manual_channel = str((invoice_saved_for_dispatch or invoice or {}).get("source_channel") or payload.get("source_channel") or "").upper() in ["MANUAL", "ARCA_MANUAL"]
    if save_error:
        post_issue_dispatch = {
            "ok": False,
            "skipped": True,
            "reason": "invoice_not_saved",
            "note": "ARCA emitió el comprobante; el guardado local requiere revisión.",
            "at": now_iso(),
            "version": APP_VERSION,
        }
    elif manual_channel:
        post_issue_dispatch = {
            "ok": True,
            "skipped": True,
            "reason": "manual_comprobante_dispatch_deferred",
            "note": "Comprobante manual emitido; PDF/email/storage se resuelven bajo demanda para no bloquear la respuesta.",
            "invoice_id": (invoice_saved_for_dispatch or invoice or {}).get("id"),
            "source_channel": (invoice_saved_for_dispatch or invoice or {}).get("source_channel") or payload.get("source_channel"),
            "at": now_iso(),
            "version": APP_VERSION,
        }
        try:
            if (invoice_saved_for_dispatch or invoice or {}).get("id"):
                arca_update_invoice_raw_dispatch((invoice_saved_for_dispatch or invoice).get("id"), post_issue_dispatch)
        except Exception as e:
            post_issue_dispatch["raw_update_error"] = str(e)
    else:
        post_issue_dispatch = arca_after_issue_dispatch(invoice_saved_for_dispatch) if isinstance(invoice_saved_for_dispatch, dict) else {"ok": False, "skipped": True, "reason": "invoice not saved"}

    return {
        "ok": True,
        "version": APP_VERSION,
        "emitted": True,
        "customer_upsert": customer_upsert,
        "stock_result": stock_result,
        "post_issue_dispatch": post_issue_dispatch,
        "environment": "produccion",
        "is_production": True,
        "tenant_id": runtime["tenant_id"],
        "config_source": "tenant_db",
        "pto_vta": issuer["pto_vta"],
        "cbte_tipo": payload.get("cbte_tipo"),
        "cbte_letra": payload.get("cbte_letra"),
        "cbte_nro": wsfe.get("cbte_nro"),
        "cae": wsfe.get("cae"),
        "cae_vto": wsfe.get("cae_vto"),
        "resultado": wsfe.get("resultado"),
        "importe_total": payload.get("importe_total"),
        "invoice": invoice,
        "invoice_id": invoice.get("id"),
        "html_path": f"/admin/arca/facturas/{invoice.get('id')}/html" if invoice.get("id") else None,
        "save_result": save_result,
        "save_error": save_error,
        "wsfe": wsfe,
        "nota": "EMISIÓN REAL REALIZADA. Verificar en ARCA.",
    }

def arca_build_registered_issued_payload(body: ArcaRegistrarEmitidaIn) -> Dict[str, Any]:
    cbte_tipo = int(body.cbte_tipo or 6)
    if cbte_tipo not in [1, 6]:
        raise HTTPException(status_code=400, detail="Por ahora registrar_emitida solo soporta 1=Factura A y 6=Factura B")

    cbte_letra = arca_cbte_letter_from_tipo(cbte_tipo)
    qty = round(float(body.quantity or 1), 4)
    unit_gross = float(body.unit_price_gross) if body.unit_price_gross is not None else None
    gross = float(body.total_gross) if body.total_gross is not None else None
    if gross is None and unit_gross is not None:
        gross = qty * unit_gross
    gross = round(float(gross or 0), 2)
    iva_pct = round(float(body.iva_pct or ARCA_IVA_ALICUOTA), 2)
    if qty <= 0:
        raise HTTPException(status_code=400, detail="quantity debe ser mayor a cero")
    if gross <= 0:
        raise HTTPException(status_code=400, detail="total_gross debe ser mayor a cero o debe venir unit_price_gross")
    unit_gross = round(float(unit_gross if unit_gross is not None else gross / qty), 2)

    net = round(gross / (1 + iva_pct / 100), 2)
    iva_amount = round(gross - net, 2)
    invoice_date = body.invoice_date or datetime.now(timezone(timedelta(hours=-3))).date().isoformat()
    cbte_nro = int(body.cbte_nro)
    source_id = body.source_order_id or f"ARCA-{cbte_letra}-{ARCA_PTO_VTA:05d}-{cbte_nro:08d}"

    return arca_normalize_invoice_payload_for_db({
        "status": "issued",
        "environment": ARCA_ENV,
        "source_channel": norm_sku(body.source_channel) or "ARCA_MANUAL",
        "source_order_id": source_id,
        "source_order_number": source_id,
        "source_order_api_id": source_id,
        "source_pack_id": None,
        "source_shipping_id": None,
        "source_customer_name": body.customer_name,
        "source_created_at": now_iso(),
        "invoice_date": invoice_date,
        "concept": body.concept or ARCA_DEFAULT_CONCEPTO,
        "cbte_tipo": cbte_tipo,
        "cbte_letra": cbte_letra,
        "cbte_tipo_label": f"Factura {cbte_letra}",
        "pto_vta": ARCA_PTO_VTA,
        "cbte_nro": cbte_nro,
        "cae": str(body.cae),
        "cae_vto": str(body.cae_vto),
        "customer_name": body.customer_name,
        "customer_doc_type": body.customer_doc_type,
        "customer_doc_number": body.customer_doc_number,
        "customer_iva_condition": body.customer_iva_condition,
        "customer_address": body.customer_address,
        "customer_email": body.customer_email,
        "importe_neto": net,
        "importe_iva": iva_amount,
        "importe_total": gross,
        "iva_contenido": 0.0,
        "currency": "ARS",
        "lines": [{
            "sku": norm_sku(body.sku),
            "description": body.description or "Producto",
            "quantity": qty,
            "unit_price_gross": unit_gross,
            "discount_pct": 0,
            "total_gross": gross,
            "subtotal_net": net,
            "iva_pct": iva_pct,
            "iva_amount": iva_amount,
            "source": "manual_registered",
        }],
        "notes": body.notes,
        "raw_data": {
            "manual_registered": True,
            "registered_at": now_iso(),
            "input": body.model_dump(),
            "wsfe": {
                "cae": str(body.cae),
                "cae_vto": str(body.cae_vto),
                "cbte_nro": cbte_nro,
                "resultado": body.resultado,
                "registered_from_erp": True,
            },
        },
        "created_at": now_iso(),
        "updated_at": now_iso(),
    })


# ====== MODULO ARCA EMISION TENANT PRODUCCION ======
def arca_tenant_emission_context(
    *,
    require_connected: bool = True,
    service: str = "wsfe",
) -> Dict[str, Any]:
    """Resuelve configuración fiscal real del tenant autenticado, sin fallback global.

    La emisión manual sólo queda habilitada cuando el mismo tenant ya validó WSAA/WSFE,
    tiene certificado + clave privada propios y un punto de venta válido.
    """
    tenant_id = str(get_effective_tenant_id() or "").strip()
    if not tenant_id:
        raise HTTPException(status_code=401, detail="Sesión XelerIA sin tenant válido para ARCA.")

    row = _tenant_settings_row(tenant_id)
    settings = _settings_blob(row)
    connected = _boolish(
        settings.get("arca_connected") if "arca_connected" in settings else row.get("arca_connected"),
        False,
    )
    if require_connected and not connected:
        raise HTTPException(
            status_code=400,
            detail="ARCA todavía no figura conectado para este comercio. Ejecutá Probar conexión ARCA.",
        )

    cuit = _clean_cuit(settings.get("fiscal_cuit") or row.get("fiscal_cuit"))
    if len(cuit) != 11:
        raise HTTPException(status_code=400, detail="El tenant no tiene un CUIT ARCA válido de 11 dígitos.")

    try:
        pto_vta = int(settings.get("fiscal_pos_arca") or row.get("fiscal_pos_arca") or 0)
    except Exception:
        pto_vta = 0
    if pto_vta <= 0:
        raise HTTPException(status_code=400, detail="El tenant no tiene un punto de venta ARCA válido.")

    token_rows = (
        _sb_raw.table("api_tokens")
        .select("*")
        .eq("tenant_id", tenant_id)
        .eq("provider", f"arca_cert:{tenant_id}")
        .limit(1)
        .execute()
        .data
        or []
    ) if _sb_raw else []
    token_row = token_rows[0] if token_rows else {}
    cert_pem = str(token_row.get("refresh_token") or "")
    encrypted_key = str(token_row.get("access_token") or "")
    if "BEGIN CERTIFICATE" not in cert_pem or not encrypted_key:
        raise HTTPException(
            status_code=400,
            detail="Falta el certificado o la clave privada ARCA de este comercio.",
        )

    try:
        from arca_certificate_admin import _decrypt_private_key
        from arca_client import ArcaConfig, ArcaWSFEClient
        key_pem = _decrypt_private_key(tenant_id, encrypted_key)
        client = ArcaWSFEClient(
            config=ArcaConfig(
                env="prod",
                cuit=cuit,
                pto_vta=pto_vta,
                cert_pem=cert_pem,
                key_pem=key_pem,
                service=str(service or "wsfe"),
                timeout_seconds=int(os.getenv("ARCA_WS_TIMEOUT_SECONDS") or 40),
            )
        )
    except HTTPException:
        raise
    except Exception as exc:
        raise HTTPException(status_code=500, detail=f"No pude preparar la conexión ARCA del tenant: {exc}")

    issuer = {
        "tenant_id": tenant_id,
        "environment": "produccion",
        "cuit": cuit,
        "pto_vta": pto_vta,
        "razon_social": settings.get("fiscal_razon_social") or row.get("fiscal_razon_social") or "",
        "iva_condition": settings.get("fiscal_iva_condition") or row.get("fiscal_iva_condition") or "",
        "address": settings.get("fiscal_address") or row.get("fiscal_address") or "",
        "display_name": settings.get("display_name") or row.get("display_name") or "",
    }
    return {
        "tenant_id": tenant_id,
        "client": client,
        "issuer": issuer,
        "settings": settings,
        "service": str(service or "wsfe"),
    }


def arca_wsfe_issue_cae(payload: Dict[str, Any]) -> Dict[str, Any]:
    """Emite CAE en producción con certificado, CUIT y punto de venta del tenant actual.

    Las consultas de último comprobante se reintentan una vez porque son de sólo lectura.
    La solicitud de CAE nunca se reintenta a ciegas: ante una caída de red se informa
    exactamente la etapa para evitar una posible emisión duplicada.
    """
    runtime = arca_tenant_emission_context()
    client = runtime["client"]
    issuer = runtime["issuer"]

    cbte_tipo = int(payload.get("cbte_tipo") or 0)
    cbte_letter = str(payload.get("cbte_letra") or "").upper()
    supported_wsfe_types = [1, 2, 3, 6, 7, 8, 11, 12, 13]
    if cbte_tipo not in supported_wsfe_types:
        raise HTTPException(
            status_code=400,
            detail=(
                "Factura de Exportación 019 requiere el servicio WSFEX y datos aduaneros específicos."
                if cbte_tipo == 19
                else f"Tipo de comprobante WSFE no soportado: {cbte_tipo}"
            ),
        )

    customer = {
        "doc_type": payload.get("customer_doc_type"),
        "doc_number": payload.get("customer_doc_number"),
        "iva_condition": payload.get("customer_iva_condition"),
    }
    doc = arca_doc_tipo_nro(customer, cbte_letter)
    amounts = arca_wsfe_amounts(payload)

    last = None
    last_error = None
    for attempt in range(2):
        try:
            last = client.get_last_voucher(cbte_tipo)
            break
        except Exception as exc:
            last_error = exc
            if attempt == 0:
                time.sleep(1.2)
    if last is None:
        raise HTTPException(
            status_code=502,
            detail={
                "ok": False,
                "error": "ARCA no respondió al consultar el último comprobante",
                "stage": "get_last_voucher",
                "retryable": True,
                "message": str(last_error or "Sin detalle"),
                "cbte_tipo": cbte_tipo,
                "cbte_letra": cbte_letter,
            },
        )

    cbte_nro = int(last.get("cbte_nro") or 0) + 1
    inv_date = arca_safe_invoice_date(payload.get("invoice_date"))
    concept_id = int(payload.get("concepto") or arca_concept_id(payload.get("concept")))

    iva_receptor = normalizar(customer.get("iva_condition"))
    if "responsable" in iva_receptor and "no responsable" not in iva_receptor:
        condicion_iva_receptor_id = 1
    elif "monotrib" in iva_receptor:
        condicion_iva_receptor_id = 6
    elif "exent" in iva_receptor:
        condicion_iva_receptor_id = 4
    elif "no alcanz" in iva_receptor:
        condicion_iva_receptor_id = 15
    else:
        condicion_iva_receptor_id = 5

    try:
        needs_extended_request = bool(payload.get("cbtes_asoc")) or concept_id != 1 or cbte_tipo not in [1, 6]
        if needs_extended_request:
            issued = arca_wsfe_request_cae_extended(
                client,
                cbte_tipo=cbte_tipo,
                concepto=concept_id,
                doc_tipo=int(doc.get("doc_tipo") or 99),
                doc_nro=str(doc.get("doc_nro") or "0"),
                amounts=amounts,
                condicion_iva_receptor_id=condicion_iva_receptor_id,
                cbte_nro=cbte_nro,
                cbte_fch=inv_date[:10].replace("-", ""),
                cbtes_asoc=payload.get("cbtes_asoc") or [],
                service_date_from=payload.get("service_date_from"),
                service_date_to=payload.get("service_date_to"),
                payment_due_date=payload.get("payment_due_date"),
            )
        else:
            issued = client.request_cae(
                cbte_tipo=cbte_tipo,
                concepto=concept_id,
                doc_tipo=int(doc.get("doc_tipo") or 99),
                doc_nro=str(doc.get("doc_nro") or "0"),
                imp_total=f"{amounts['total']:.2f}",
                imp_neto=f"{amounts['net']:.2f}",
                imp_iva=f"{amounts['iva']:.2f}",
                imp_exento="0.00",
                imp_tot_conc="0.00",
                imp_op_ex="0.00",
                imp_trib="0.00",
                iva_id=5,
                condicion_iva_receptor_id=condicion_iva_receptor_id,
                cbte_desde=cbte_nro,
                cbte_hasta=cbte_nro,
                cbte_fch=inv_date[:10].replace("-", ""),
            )
    except Exception as exc:
        # No reintentamos FECAESolicitar. Si la respuesta se perdió después de que
        # ARCA procesó la solicitud, un reintento ciego puede generar confusión.
        last_after_error = None
        try:
            time.sleep(0.8)
            last_after_error = client.get_last_voucher(cbte_tipo)
        except Exception:
            pass
        raise HTTPException(
            status_code=502,
            detail={
                "ok": False,
                "error": "Se cortó la comunicación durante la solicitud de CAE",
                "stage": "request_cae",
                "ambiguous": bool(
                    last_after_error
                    and int(last_after_error.get("cbte_nro") or 0) >= cbte_nro
                ),
                "expected_cbte_nro": cbte_nro,
                "last_voucher_after_error": (
                    int(last_after_error.get("cbte_nro") or 0)
                    if last_after_error else None
                ),
                "cbte_tipo": cbte_tipo,
                "cbte_letra": cbte_letter,
                "message": str(exc),
                "instruction": "No reintentar hasta volver a consultar el último comprobante del mismo tipo.",
            },
        )

    if not issued.get("ok") or not issued.get("cae"):
        raise HTTPException(
            status_code=502,
            detail={
                "error": "ARCA no autorizó el comprobante",
                "stage": "arca_rejected",
                "resultado": issued.get("resultado"),
                "arca_errors": issued.get("observations") or [],
            },
        )

    payload["environment"] = "produccion"
    payload["env"] = "produccion"
    payload["cuit_emisor"] = issuer["cuit"]
    payload["pto_vta"] = issuer["pto_vta"]
    payload.setdefault("raw_data", {})
    payload["raw_data"]["tenant_emitter"] = issuer

    return {
        "ok": True,
        "tenant_id": runtime["tenant_id"],
        "config_source": "tenant_db",
        "environment": "produccion",
        "cae": issued.get("cae"),
        "cae_vto": issued.get("cae_vto"),
        "cbte_nro": int(issued.get("cbte_desde") or cbte_nro),
        "resultado": issued.get("resultado"),
        "arca_errors": issued.get("observations") or [],
        "wsfe_amounts": amounts,
        "pto_vta": issuer["pto_vta"],
        "cuit_emisor": issuer["cuit"],
    }


def arca_wsfe_consult_voucher(client: Any, cbte_tipo: int, cbte_nro: int) -> Dict[str, Any]:
    """Consulta un comprobante ya autorizado mediante FECompConsultar.

    Se usa sólo para recuperar un CAE que ARCA emitió pero que no llegó a guardarse
    localmente. Nunca emite ni modifica comprobantes.
    """
    client.auth()
    envelope = f"""<?xml version="1.0" encoding="utf-8"?>
<soap:Envelope xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" xmlns:xsd="http://www.w3.org/2001/XMLSchema" xmlns:soap="http://schemas.xmlsoap.org/soap/envelope/">
  <soap:Body>
    <FECompConsultar xmlns="http://ar.gov.afip.dif.FEV1/">
      <Auth>
        <Token>{html_lib.escape(str(client._token or ""))}</Token>
        <Sign>{html_lib.escape(str(client._sign or ""))}</Sign>
        <Cuit>{client.config.cuit}</Cuit>
      </Auth>
      <FeCompConsReq>
        <CbteTipo>{int(cbte_tipo)}</CbteTipo>
        <CbteNro>{int(cbte_nro)}</CbteNro>
        <PtoVta>{int(client.config.pto_vta)}</PtoVta>
      </FeCompConsReq>
    </FECompConsultar>
  </soap:Body>
</soap:Envelope>"""
    xml = client._wsfe_post(envelope, "FECompConsultar")
    try:
        root = ET.fromstring(xml.encode("utf-8"))
    except Exception as exc:
        raise HTTPException(
            status_code=502,
            detail={
                "ok": False,
                "error": "ARCA respondió un XML inválido al consultar el comprobante",
                "stage": "recover_fecomp_consultar",
                "message": str(exc),
            },
        )

    def txt(name: str) -> str:
        return arca_find_text_by_localname(root, name)

    errors = []
    for node in root.iter():
        if arca_localname(node.tag).lower() in {"err", "evt", "obs"}:
            item = {}
            for child in list(node):
                item[arca_localname(child.tag)] = (child.text or "").strip()
            if item:
                errors.append(item)

    def num(value: Any, default: float = 0.0) -> float:
        try:
            return float(str(value or "").replace(",", "."))
        except Exception:
            return float(default)

    cae = txt("CodAutorizacion") or txt("CAE")
    resultado = txt("Resultado")
    return {
        "ok": bool(cae) and resultado == "A",
        "environment": "produccion",
        "pto_vta": int(txt("PtoVta") or client.config.pto_vta),
        "cbte_tipo": int(txt("CbteTipo") or cbte_tipo),
        "cbte_nro": int(txt("CbteDesde") or txt("CbteNro") or cbte_nro),
        "cbte_hasta": int(txt("CbteHasta") or txt("CbteDesde") or cbte_nro),
        "cbte_fch": txt("CbteFch"),
        "doc_tipo": int(txt("DocTipo") or 99),
        "doc_nro": txt("DocNro") or "0",
        "concepto": int(txt("Concepto") or 1),
        "importe_total": num(txt("ImpTotal")),
        "importe_neto": num(txt("ImpNeto")),
        "importe_iva": num(txt("ImpIVA")),
        "importe_tot_conc": num(txt("ImpTotConc")),
        "importe_op_ex": num(txt("ImpOpEx")),
        "importe_trib": num(txt("ImpTrib")),
        "moneda_id": txt("MonId") or "PES",
        "moneda_ctz": num(txt("MonCotiz"), 1.0),
        "resultado": resultado,
        "cae": cae,
        "cae_vto": txt("FchVto") or txt("CAEFchVto"),
        "condicion_iva_receptor_id": int(txt("CondicionIVAReceptorId") or 0) or None,
        "errors": errors,
        "raw_xml": xml,
    }


def arca_update_order_diagnostics(
    row: Dict[str, Any],
    updates: Optional[Dict[str, Any]] = None,
    clear_keys: Optional[List[str]] = None,
) -> Dict[str, Any]:
    """Actualiza diagnósticos en todas las filas que representan la misma venta.

    En ML un pack puede estar dividido en varias orders API. Es imprescindible dejar
    el bloqueo de recuperación en todas para que ninguna variante vuelva a pedir CAE.
    """
    targets = arca_get_ml_group_orders(row) if str((row or {}).get("channel") or "").upper() == "ML" else [row]
    result = {"attempted": len(targets), "updated_ids": [], "errors": []}
    for target in targets:
        target_id = (target or {}).get("id")
        if not target_id:
            result["errors"].append({"id": None, "error": "order_without_id"})
            continue
        try:
            raw = dict(row_raw_dict(target or {}))
            for key in clear_keys or []:
                raw.pop(str(key), None)
            for key, value in (updates or {}).items():
                if value is None:
                    raw.pop(str(key), None)
                else:
                    raw[str(key)] = value
            sb.table("orders").update({"raw_data": raw, "updated_at": now_iso()}).eq("id", target_id).execute()
            result["updated_ids"].append(str(target_id))
        except Exception as exc:
            result["errors"].append({"id": str(target_id), "error": str(exc)})
    result["ok"] = bool(result["updated_ids"]) and not result["errors"]
    result["persisted"] = bool(result["updated_ids"])
    return result


def arca_recovery_pending_marker(row: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    targets = arca_get_ml_group_orders(row) if str((row or {}).get("channel") or "").upper() == "ML" else [row]
    markers = []
    for target in targets:
        marker = row_raw_dict(target or {}).get("arca_recovery_pending")
        if isinstance(marker, dict):
            markers.append(dict(marker))
    if not markers:
        return None

    identities = {
        (int(marker.get("cbte_tipo") or 0), int(marker.get("cbte_nro") or 0))
        for marker in markers
    }
    if len(identities) > 1:
        raise HTTPException(
            status_code=409,
            detail={
                "ok": False,
                "critical": True,
                "error": "La venta tiene más de un comprobante pendiente de recuperar",
                "stage": "recover_marker_conflict",
                "markers": markers,
                "instruction": "No volver a emitir. Revisar manualmente los comprobantes marcados.",
            },
        )
    return markers[0]


def arca_recover_pending_invoice(
    row: Dict[str, Any],
    payload: Dict[str, Any],
    operation_id: str,
) -> Optional[Dict[str, Any]]:
    """Recupera un comprobante ya emitido, sin volver a pedir CAE.

    Sólo se activa cuando la orden tiene un marcador explícito arca_recovery_pending,
    creado después de comprobar que ARCA emitió y el guardado local falló.
    """
    marker = arca_recovery_pending_marker(row)
    if not marker:
        return None

    expected_tipo = int(payload.get("cbte_tipo") or 0)
    marked_tipo = int(marker.get("cbte_tipo") or 0)
    marked_nro = int(marker.get("cbte_nro") or 0)
    marked_cae = str(marker.get("cae") or "").strip()
    if marked_tipo != expected_tipo or marked_nro <= 0:
        raise HTTPException(
            status_code=409,
            detail={
                "ok": False,
                "critical": True,
                "error": "El comprobante pendiente de recuperar no coincide con esta factura",
                "stage": "recover_marker_validation",
                "operation_id": operation_id,
                "marker": marker,
                "expected_cbte_tipo": expected_tipo,
                "instruction": "No volver a emitir. Revisar el comprobante pendiente.",
            },
        )

    runtime = arca_tenant_emission_context()
    consulted = arca_wsfe_consult_voucher(runtime["client"], marked_tipo, marked_nro)
    customer = {
        "doc_type": payload.get("customer_doc_type"),
        "doc_number": payload.get("customer_doc_number"),
        "iva_condition": payload.get("customer_iva_condition"),
    }
    expected_doc = arca_doc_tipo_nro(customer, str(payload.get("cbte_letra") or ""))
    expected_amounts = arca_wsfe_amounts(payload)

    mismatches = []
    if not consulted.get("ok"):
        mismatches.append("ARCA no devolvió el comprobante como autorizado")
    if int(consulted.get("pto_vta") or 0) != int(runtime["issuer"]["pto_vta"]):
        mismatches.append("punto de venta")
    if int(consulted.get("cbte_tipo") or 0) != marked_tipo:
        mismatches.append("tipo de comprobante")
    if int(consulted.get("cbte_nro") or 0) != marked_nro:
        mismatches.append("número de comprobante")
    if marked_cae and str(consulted.get("cae") or "") != marked_cae:
        mismatches.append("CAE")
    if int(consulted.get("doc_tipo") or 0) != int(expected_doc.get("doc_tipo") or 99):
        mismatches.append("tipo de documento del receptor")
    if arca_digits(consulted.get("doc_nro")) != arca_digits(expected_doc.get("doc_nro")):
        mismatches.append("documento del receptor")
    if abs(float(consulted.get("importe_total") or 0) - float(expected_amounts.get("total") or 0)) > 0.01:
        mismatches.append("importe total")

    if mismatches:
        raise HTTPException(
            status_code=409,
            detail={
                "ok": False,
                "critical": True,
                "error": "El comprobante encontrado en ARCA no coincide completamente con la venta",
                "stage": "recover_compare",
                "operation_id": operation_id,
                "mismatches": mismatches,
                "marker": marker,
                "arca_voucher": {k: v for k, v in consulted.items() if k != "raw_xml"},
                "instruction": "No volver a emitir. Revisar manualmente antes de continuar.",
            },
        )

    cbte_fch = str(consulted.get("cbte_fch") or "")
    payload.update({
        "environment": "produccion",
        "env": "produccion",
        "cuit_emisor": runtime["issuer"]["cuit"],
        "pto_vta": runtime["issuer"]["pto_vta"],
        "status": "issued",
        "cbte_nro": marked_nro,
        "cae": consulted.get("cae"),
        "cae_vto": consulted.get("cae_vto"),
        "resultado": consulted.get("resultado") or "A",
        "invoice_date": (
            f"{cbte_fch[0:4]}-{cbte_fch[4:6]}-{cbte_fch[6:8]}"
            if len(cbte_fch) == 8
            else payload.get("invoice_date")
        ),
    })
    payload.setdefault("raw_data", {})
    payload["raw_data"]["tenant_emitter"] = runtime["issuer"]
    payload["raw_data"]["wsfe"] = consulted
    payload["raw_data"]["recovered_from_arca"] = True
    payload["raw_data"]["recovery_marker"] = marker
    payload["raw_data"]["recovered_at"] = now_iso()
    payload["raw_data"]["issue_operation_id"] = operation_id

    saved = arca_save_issued_invoice(payload)
    invoice_saved = saved.get("invoice") or payload

    try:
        recovery_summary = {
            "invoice_id": invoice_saved.get("id") if isinstance(invoice_saved, dict) else None,
            "cbte_tipo": marked_tipo,
            "cbte_nro": marked_nro,
            "cae": consulted.get("cae"),
            "recovered_at": now_iso(),
            "operation_id": operation_id,
        }
        diagnostic_update = arca_update_order_diagnostics(
            row,
            updates={"arca_recovered_invoice": recovery_summary},
            clear_keys=["arca_recovery_pending", "arca_auto_invoice_last_error"],
        )
        if not diagnostic_update.get("ok"):
            print(f"[ARCA RECOVER {operation_id}] warning clear_marker={diagnostic_update}", flush=True)
    except Exception as exc:
        print(f"[ARCA RECOVER {operation_id}] warning clear_marker={exc}", flush=True)

    print(
        f"[ARCA RECOVER {operation_id}] recovered invoice_id={invoice_saved.get('id') if isinstance(invoice_saved, dict) else None} "
        f"cbte={marked_nro} cae={consulted.get('cae')}",
        flush=True,
    )
    return {
        "ok": True,
        "operation_id": operation_id,
        "recovered": True,
        "duplicate": False,
        "inserted": saved.get("inserted"),
        "updated": saved.get("updated"),
        "invoice": invoice_saved,
        "invoice_id": invoice_saved.get("id") if isinstance(invoice_saved, dict) else None,
        "wsfe": consulted,
        "message": "Comprobante recuperado desde ARCA sin volver a emitir.",
    }

# ====== FIN MODULO ARCA EMISION TENANT PRODUCCION ======


def arca_normalize_invoice_payload_for_db(payload: Dict[str, Any]) -> Dict[str, Any]:
    """
    Normaliza payload ARCA antes de guardar en PostgreSQL.

    Mantiene compatibilidad con columnas históricas y nuevas:
    - environment/env
    - importe_neto/imp_neto
    - importe_iva/imp_iva
    - importe_total
    - doc_tipo/doc_nro
    - resultado

    Regla clave: nunca mandar bool a columnas numeric.
    """
    p = dict(payload or {})

    # Ambiente: algunas vistas viejas leen env y las nuevas leen environment.
    env = str(p.get("environment") or p.get("env") or ARCA_ENV or "prod")
    p["environment"] = env
    p["env"] = env

    # Emisor: la emisión SaaS ya deja el CUIT del tenant; el global es sólo fallback legacy.
    p.setdefault("cuit_emisor", arca_digits(ARCA_EMISOR_CUIT) or None)

    # Resultado ARCA aprobado/rechazado. Puede venir en raw_data.wsfe si no quedó arriba.
    raw = p.get("raw_data") or {}
    if isinstance(raw, dict):
        wsfe = raw.get("wsfe") or {}
        if isinstance(wsfe, dict) and not p.get("resultado"):
            p["resultado"] = wsfe.get("resultado")

    # Documento receptor para ARCA.
    cbte_letter = str(p.get("cbte_letra") or arca_cbte_letter_from_tipo(int(p.get("cbte_tipo") or 0))).upper()
    try:
        doc = arca_doc_tipo_nro({
            "doc_type": p.get("customer_doc_type"),
            "doc_number": p.get("customer_doc_number"),
            "iva_condition": p.get("customer_iva_condition"),
        }, cbte_letter)
        p["doc_tipo"] = int(doc.get("doc_tipo") or 99)
        p["doc_nro"] = str(doc.get("doc_nro") or "0")
    except Exception:
        # No bloqueamos guardado si el comprobante ya salió; dejamos fallback visible.
        p.setdefault("doc_tipo", 99)
        p.setdefault("doc_nro", "0")

    # Duplicar importes en nombres legacy y nuevos para reportes/PDF.
    if p.get("importe_neto") is None and p.get("imp_neto") is not None:
        p["importe_neto"] = p.get("imp_neto")
    if p.get("importe_iva") is None and p.get("imp_iva") is not None:
        p["importe_iva"] = p.get("imp_iva")
    # La tabla real no tiene imp_total; solo importe_total.
    p["imp_neto"] = p.get("importe_neto") or 0
    p["imp_iva"] = p.get("importe_iva") or 0
    p.setdefault("imp_tot_conc", 0)
    p.setdefault("imp_op_ex", 0)
    p.setdefault("imp_trib", 0)
    p.setdefault("moneda_id", "PES")
    p.setdefault("moneda_ctz", 1)
    p.setdefault("concepto", 1)

    numeric_fields = [
        "importe_neto", "importe_iva", "importe_total",
        "imp_neto", "imp_iva", "imp_tot_conc", "imp_op_ex", "imp_trib",
        "iva_contenido", "pto_vta", "cbte_tipo", "cbte_nro", "doc_tipo", "moneda_ctz", "concepto",
    ]
    for field in numeric_fields:
        if field not in p:
            continue
        if isinstance(p.get(field), bool):
            p[field] = 1 if p[field] else 0
        if p.get(field) is None:
            if field in ["iva_contenido", "imp_neto", "imp_iva", "imp_tot_conc", "imp_op_ex", "imp_trib"]:
                p[field] = 0
            continue
        try:
            if field in ["pto_vta", "cbte_tipo", "cbte_nro", "doc_tipo", "concepto"]:
                p[field] = int(float(str(p.get(field)).replace(",", ".")))
            else:
                p[field] = float(str(p.get(field)).replace(",", "."))
        except Exception:
            # Lo dejamos como está para que el error sea explícito si hay algo raro.
            pass

    # Campos que conviene guardar como texto.
    for field in ["cae", "cae_vto", "doc_nro", "customer_doc_number"]:
        if p.get(field) is not None:
            p[field] = str(p.get(field))

    # La tabla real arca_invoices NO tiene columna cbtes_asoc.
    # Para NC/ND, CbtesAsoc se usa para pedir CAE a ARCA, pero se conserva
    # dentro de raw_data/wsfe o raw_data/associated_invoice, no como columna top-level.
    # Si lo dejamos top-level, la capa de escritura corta el insert por columna no esperada.
    if "cbtes_asoc" in p:
        raw_data = p.get("raw_data")
        if not isinstance(raw_data, dict):
            raw_data = {}
        raw_data.setdefault("cbtes_asoc", p.get("cbtes_asoc") or [])
        p["raw_data"] = raw_data
        p.pop("cbtes_asoc", None)

    service_fields = {
        key: p.get(key)
        for key in ("service_date_from", "service_date_to", "payment_due_date")
        if p.get(key)
    }
    if service_fields:
        raw_data = p.get("raw_data") if isinstance(p.get("raw_data"), dict) else {}
        raw_data["service_period"] = service_fields
        p["raw_data"] = raw_data
    for key in ("service_date_from", "service_date_to", "payment_due_date"):
        p.pop(key, None)

    return p


def arca_save_issued_invoice(payload: Dict[str, Any]) -> Dict[str, Any]:
    payload = arca_normalize_invoice_payload_for_db(payload)
    existing = arca_existing_invoice(payload["source_channel"], payload["source_order_id"])
    payload["updated_at"] = now_iso()
    if existing:
        if existing.get("cae"):
            return {"inserted": False, "updated": False, "invoice": existing, "duplicate": True}
        updated = sb.table("arca_invoices").update(payload).eq("id", existing.get("id")).execute().data or []
        return {"inserted": False, "updated": True, "invoice": updated[0] if updated else {**existing, **payload}, "duplicate": False}
    inserted = sb.table("arca_invoices").insert(payload).execute().data or []
    return {"inserted": True, "updated": False, "invoice": inserted[0] if inserted else payload, "duplicate": False}

def arca_existing_invoice(source_channel: str, source_order_id: str) -> Optional[Dict[str, Any]]:
    rows = (
        sb.table("arca_invoices")
        .select("*")
        .eq("source_channel", source_channel)
        .eq("source_order_id", str(source_order_id))
        .limit(1)
        .execute()
        .data
        or []
    )
    return rows[0] if rows else None


def arca_insert_invoice(payload: Dict[str, Any]) -> Dict[str, Any]:
    # ARCA_DRAFT_SCHEMA_FIX_V10:
    # Normalizar también los borradores antes de persistir.
    # Sin esto, el HTML podía verse correcto usando customer_* pero la fila quedaba
    # con doc_tipo=99/doc_nro=0 para WSFE.
    payload = arca_normalize_invoice_payload_for_db(payload)

    existing = arca_existing_invoice(payload["source_channel"], payload["source_order_id"])
    if existing:
        # Si ya existe borrador sin CAE, lo refrescamos con los datos fiscales actuales.
        # Si ya tiene CAE, no se toca.
        if existing.get("cae"):
            return {"inserted": False, "updated": False, "invoice": existing, "duplicate": True}
        payload["updated_at"] = now_iso()
        updated = sb.table("arca_invoices").update(payload).eq("id", existing.get("id")).execute().data or []
        return {"inserted": False, "updated": True, "invoice": updated[0] if updated else {**existing, **payload}, "duplicate": False}

    inserted = sb.table("arca_invoices").insert(payload).execute().data or []
    return {"inserted": True, "updated": False, "invoice": inserted[0] if inserted else payload, "duplicate": False}




def arca_invoice_lookup_keys_for_order(row: Dict[str, Any]) -> List[str]:
    """Claves posibles para saber si una venta ya tiene comprobante ARCA.

    ML puede venir como order_id hijo, pack_id visible o shipping_id. No alcanza con
    comparar solo external_order_id.
    """
    raw = row_raw_dict(row or {})
    keys = []
    for v in [
        (row or {}).get("external_order_id"),
        (row or {}).get("id"),
        raw.get("ml_order_id"),
        raw.get("ml_pack_id"),
        raw.get("ml_sale_number"),
        raw.get("ml_shipping_id"),
        raw.get("tn_order_id"),
        raw.get("tn_order_number"),
    ]:
        if v is None:
            continue
        txt = str(v).strip()
        if txt and txt.lower() != "null" and txt not in keys:
            keys.append(txt)
    return keys


def arca_existing_invoice_for_order(row: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    ch = str((row or {}).get("channel") or "").upper().strip()
    keys = arca_invoice_lookup_keys_for_order(row)
    if not ch or not keys:
        return None

    # Pocas claves por venta; hacerlo explicito evita depender de sintaxis OR poco portable.
    fields = ["source_order_id", "source_order_number", "source_order_api_id", "source_pack_id", "source_shipping_id"]
    for key in keys:
        for field in fields:
            try:
                rows = (
                    sb.table("arca_invoices")
                    .select("*")
                    .eq("source_channel", ch)
                    .eq(field, str(key))
                    .order("created_at", desc=True)
                    .limit(1)
                    .execute()
                    .data
                    or []
                )
                if rows:
                    return rows[0]
            except Exception:
                continue
    return None


def arca_source_key_for_pending(row: Dict[str, Any]) -> str:
    """Clave única operativa para no facturar dos veces packs ML en un batch."""
    ch = str((row or {}).get("channel") or "").upper().strip()
    raw = row_raw_dict(row or {})
    if ch == "ML":
        pack_id = raw.get("ml_pack_id")
        if pack_id not in [None, "", "null"]:
            return f"ML:PACK:{pack_id}"
    return f"{ch}:ORDER:{(row or {}).get('external_order_id') or (row or {}).get('id')}"


def arca_issue_order_core(
    channel: str,
    order_id: str,
    body: Optional[ArcaInvoiceDraftIn] = None,
    *,
    allow_existing: bool = True,
    run_post_issue_dispatch: bool = True,
) -> Dict[str, Any]:
    """Emite CAE real para una orden/pack y guarda la factura.

    La emisión fiscal y el guardado son la operación principal. PDF/storage/carga al
    canal pueden ejecutarse después para que una demora externa no corte la respuesta.
    """
    operation_id = str(uuid.uuid4())
    stage = "load_order"
    row: Optional[Dict[str, Any]] = None
    payload: Optional[Dict[str, Any]] = None
    print(
        f"[ARCA ISSUE {operation_id}] start tenant={get_effective_tenant_id()} "
        f"channel={channel} order_id={order_id}",
        flush=True,
    )
    try:
        row = arca_get_order(channel, order_id)
        stage = "check_existing"
        existing = arca_existing_invoice_for_order(row)
        if existing and existing.get("cae") and allow_existing:
            print(f"[ARCA ISSUE {operation_id}] already_issued invoice_id={existing.get('id')}", flush=True)
            return {
                "ok": True,
                "operation_id": operation_id,
                "duplicate": True,
                "already_issued": True,
                "invoice": existing,
                "invoice_id": existing.get("id"),
                "source_order_id": order_id,
                "message": "Ya existía comprobante emitido para esta venta.",
            }

        stage = "build_payload"
        payload = arca_build_invoice_payload(row, body or ArcaInvoiceDraftIn())

        # XELERIA_ARCA_RECOVER_ISSUED_CAE_V196
        # Si ARCA emitió pero el guardado local falló, recuperamos el comprobante exacto
        # mediante FECompConsultar. Nunca pedimos un CAE nuevo para esa orden.
        stage = "recover_pending"
        recovered = arca_recover_pending_invoice(row, payload, operation_id)
        if recovered is not None:
            return recovered

        stage = "request_cae"
        wsfe = arca_wsfe_issue_cae(payload)
        payload.update({
            "environment": "produccion",
            "env": "produccion",
            "cuit_emisor": wsfe.get("cuit_emisor") or payload.get("cuit_emisor"),
            "pto_vta": wsfe.get("pto_vta") or payload.get("pto_vta"),
            "status": "issued",
            "cbte_nro": wsfe.get("cbte_nro"),
            "cae": wsfe.get("cae"),
            "cae_vto": wsfe.get("cae_vto"),
            "resultado": wsfe.get("resultado"),
        })
        payload.setdefault("raw_data", {})
        payload["raw_data"]["wsfe"] = wsfe
        payload["raw_data"]["issued_at"] = now_iso()
        payload["raw_data"]["issue_operation_id"] = operation_id

        stage = "save_invoice"
        save_error = None
        saved = None
        for attempt in range(2):
            try:
                saved = arca_save_issued_invoice(payload)
                break
            except Exception as exc:
                save_error = exc
                if attempt == 0:
                    time.sleep(0.5)
        if saved is None:
            recovery_marker = build_recovery_marker(
                payload,
                wsfe,
                operation_id,
                now_iso(),
                reason="save_invoice_after_cae",
            )
            marker_write = arca_update_order_diagnostics(
                row,
                updates={"arca_recovery_pending": recovery_marker},
            )
            raise HTTPException(
                status_code=500,
                detail={
                    "ok": False,
                    "critical": True,
                    "error": "ARCA emitió el CAE pero XelerIA no pudo guardar la factura",
                    "stage": "save_invoice_after_cae",
                    "operation_id": operation_id,
                    "cbte_tipo": payload.get("cbte_tipo"),
                    "cbte_letra": payload.get("cbte_letra"),
                    "cbte_nro": wsfe.get("cbte_nro"),
                    "cae": wsfe.get("cae"),
                    "message": str(save_error or "Sin detalle"),
                    "recovery_marker_persisted": bool(marker_write.get("persisted")),
                    "recovery_marker_write": marker_write,
                    "instruction": "No volver a emitir. Revisar y recuperar el comprobante ya autorizado.",
                },
            )

        invoice_saved = saved.get("invoice") or payload
        if saved.get("duplicate"):
            post_issue_dispatch = {
                "ok": True,
                "skipped": True,
                "reason": "duplicate invoice already issued",
            }
        elif run_post_issue_dispatch:
            stage = "post_issue_dispatch"
            post_issue_dispatch = arca_after_issue_dispatch(invoice_saved)
        else:
            source_channel = str(invoice_saved.get("source_channel") or channel or "").upper()
            post_issue_dispatch = {
                "ok": True,
                "queued": True,
                "reason": "post_issue_dispatch_background",
                "channel_action": (
                    "ml_upload_invoice_pdf" if source_channel == "ML"
                    else "tn_upload_invoice_metafield" if source_channel == "TN"
                    else "none"
                ),
            }
            if source_channel == "ML":
                post_issue_dispatch["ml_upload"] = {
                    "ok": False,
                    "skipped": True,
                    "reason": "PDF en procesamiento en segundo plano",
                }

        print(
            f"[ARCA ISSUE {operation_id}] issued invoice_id={invoice_saved.get('id') if isinstance(invoice_saved, dict) else None} "
            f"cbte={wsfe.get('cbte_nro')} cae={bool(wsfe.get('cae'))}",
            flush=True,
        )
        return {
            "ok": True,
            "operation_id": operation_id,
            "duplicate": bool(saved.get("duplicate")),
            "inserted": saved.get("inserted"),
            "updated": saved.get("updated"),
            "invoice": invoice_saved,
            "invoice_id": invoice_saved.get("id") if isinstance(invoice_saved, dict) else None,
            "wsfe": wsfe,
            "post_issue_dispatch": post_issue_dispatch,
        }
    except HTTPException as exc:
        detail = exc.detail
        if not isinstance(detail, dict):
            detail = {
                "ok": False,
                "error": str(detail),
                "stage": stage,
                "operation_id": operation_id,
            }
        else:
            detail = dict(detail)
            detail.setdefault("operation_id", operation_id)
            detail.setdefault("stage", stage)

        # Si FECAESolicitar pudo haber llegado a ARCA, el próximo ingreso sólo puede
        # consultar y recuperar ese número; nunca solicitar uno nuevo a ciegas.
        if (
            row is not None
            and payload is not None
            and detail.get("stage") == "request_cae"
            and bool(detail.get("ambiguous"))
        ):
            recovery_marker = build_recovery_marker(
                payload,
                detail,
                operation_id,
                now_iso(),
                reason="request_cae_ambiguous",
            )
            marker_write = arca_update_order_diagnostics(
                row,
                updates={"arca_recovery_pending": recovery_marker},
            )
            detail["critical"] = True
            detail["recovery_marker_persisted"] = bool(marker_write.get("persisted"))
            detail["recovery_marker_write"] = marker_write
            detail["instruction"] = (
                "No volver a solicitar CAE. El próximo intento debe consultar y recuperar el comprobante marcado."
            )
        print(f"[ARCA ISSUE {operation_id}] http_error stage={stage}", flush=True)
        raise HTTPException(status_code=exc.status_code, detail=detail)
    except Exception as exc:
        print(
            f"[ARCA ISSUE {operation_id}] unexpected stage={stage} "
            f"type={exc.__class__.__name__} error={str(exc)}",
            flush=True,
        )
        raise HTTPException(
            status_code=502 if stage in {"request_cae", "post_issue_dispatch"} else 500,
            detail={
                "ok": False,
                "error": "No se pudo completar la emisión",
                "stage": stage,
                "operation_id": operation_id,
                "exception_type": exc.__class__.__name__,
                "message": str(exc),
            },
        )


def arca_after_issue_dispatch_for_tenant(
    tenant_id: str,
    invoice: Dict[str, Any],
) -> None:
    """Ejecuta PDF/despacho en segundo plano conservando el tenant correcto."""
    tenant_ctx = set_current_tenant_id(str(tenant_id))
    try:
        result = arca_after_issue_dispatch(invoice)
        print(
            f"[ARCA DISPATCH] tenant={tenant_id} invoice_id={invoice.get('id')} "
            f"ok={bool(result.get('ok'))}",
            flush=True,
        )
    except Exception as exc:
        print(
            f"[ARCA DISPATCH] tenant={tenant_id} invoice_id={invoice.get('id')} "
            f"error={str(exc)}",
            flush=True,
        )
    finally:
        reset_current_tenant_id(tenant_ctx)


def tn_closed_order_counts_as_delivered(raw: Dict[str, Any]) -> bool:
    """TN no siempre expone delivered; archived/closed paid+shipped libera facturacion."""
    raw = raw if isinstance(raw, dict) else {}
    tn_raw = raw.get("tn_raw") if isinstance(raw.get("tn_raw"), dict) else {}
    status = str(raw.get("tn_status") or tn_raw.get("status") or "").strip().lower()
    payment_status = str(raw.get("tn_payment_status") or tn_raw.get("payment_status") or "").strip().lower()
    shipping_status = str(raw.get("tn_shipping_status") or tn_raw.get("shipping_status") or "").strip().lower()
    closed_at = raw.get("tn_closed_at") or tn_raw.get("closed_at")
    return bool(status == "closed" and payment_status == "paid" and shipping_status in ["shipped", "delivered"] and closed_at)


def arca_order_is_delivered_for_auto_invoice(channel: str, row: Dict[str, Any]) -> bool:
    """Sólo habilita auto-factura cuando la venta figura Entregada."""
    ch = norm_sku(channel).upper()
    if ch == "ML":
        return ml_existing_order_shipping_is_delivered(row)
    raw = row_raw_dict(row)
    if bool(raw.get("tn_manual_delivered")):
        return True
    if tn_closed_order_counts_as_delivered(raw):
        return True
    values = [
        row.get("delivery_status"),
        row.get("tn_delivery_status"),
        row.get("tn_shipping_status"),
        raw.get("delivery_status"),
        raw.get("tn_delivery_status"),
        raw.get("tn_shipping_status"),
    ]
    return shipping_state_is_delivered(values)


# Una única cola fiscal evita que ARCA y la generación pesada de PDF compitan por
# recursos. Los CAE visibles se encolan primero; los PDF quedan detrás y no frenan
# la pantalla ni la siguiente solicitud de comprobante.
_ARCA_EMISSION_EXECUTOR = ThreadPoolExecutor(max_workers=1, thread_name_prefix="arca-emission")
_ARCA_EMISSION_QUEUE_LOCK = threading.Lock()
_ARCA_EMISSION_INFLIGHT = set()


def arca_auto_invoice_order_safe(channel: str, order_id: str) -> Dict[str, Any]:
    """Auto-facturación SaaS por tenant, idempotente y sólo para ventas entregadas."""
    ch = norm_sku(channel).upper()
    tenant_id = str(get_effective_tenant_id() or DEFAULT_TENANT_ID)
    diagnostic_operation_id = str(uuid.uuid4())
    row: Optional[Dict[str, Any]] = None
    try:
        settings_row = _tenant_settings_row(tenant_id)
        settings = _settings_blob(settings_row)
        status = _tenant_arca_status_from_settings(settings)
        enabled_key = "auto_invoice_ml" if ch == "ML" else "auto_invoice_tn" if ch == "TN" else ""
        if not enabled_key:
            return {"ok": True, "skipped": True, "reason": "unsupported_channel", "channel": ch}
        if not _boolish(status.get("arca_connected"), False):
            return {"ok": True, "skipped": True, "reason": "arca_not_connected", "tenant_id": tenant_id, "channel": ch}
        if not _boolish(settings.get(enabled_key), False):
            return {"ok": True, "skipped": True, "reason": "tenant_auto_invoice_disabled", "tenant_id": tenant_id, "channel": ch}

        row = arca_get_order(ch, order_id)
        existing = arca_existing_invoice_for_order(row)
        if existing and existing.get("cae"):
            arca_update_order_diagnostics(
                row,
                clear_keys=["arca_recovery_pending", "arca_auto_invoice_last_error"],
            )
            return {"ok": True, "skipped": True, "reason": "already_issued", "invoice_id": existing.get("id")}
        if not arca_order_is_delivered_for_auto_invoice(ch, row):
            return {"ok": True, "skipped": True, "reason": "shipping_not_delivered", "channel": ch, "order_id": str(order_id)}

        if ch == "ML":
            fiscal_documents = arca_ml_check_order_fiscal_documents(row)
            if not fiscal_documents.get("ok"):
                raise HTTPException(
                    status_code=503,
                    detail={
                        "ok": False,
                        "critical": True,
                        "stage": "ml_fiscal_documents_check",
                        "error": "No se pudo verificar si Mercado Libre ya tiene una factura adjunta",
                        "status_code": fiscal_documents.get("status_code"),
                        "message": fiscal_documents.get("error") or fiscal_documents.get("reason"),
                        "instruction": "No se emitio un comprobante nuevo. Reintentar la verificacion.",
                    },
                )
            if fiscal_documents.get("present"):
                arca_update_order_diagnostics(
                    row,
                    updates={"ml_fiscal_documents_check": fiscal_documents.get("marker")},
                    clear_keys=["arca_auto_invoice_last_error"],
                )
                return {
                    "ok": True,
                    "skipped": True,
                    "reason": "ml_fiscal_document_present",
                    "channel": ch,
                    "order_id": str(order_id),
                    "document_count": fiscal_documents.get("document_count"),
                }

        result = arca_issue_order_core(
            ch,
            order_id,
            ArcaInvoiceDraftIn(),
            allow_existing=True,
            run_post_issue_dispatch=False,
        )
        invoice = result.get("invoice") if isinstance(result, dict) else None
        if isinstance(invoice, dict) and invoice.get("cae") and not result.get("duplicate"):
            _ARCA_EMISSION_EXECUTOR.submit(
                arca_after_issue_dispatch_for_tenant,
                tenant_id,
                dict(invoice),
            )
        if isinstance(result, dict) and result.get("ok"):
            arca_update_order_diagnostics(
                row,
                clear_keys=["arca_auto_invoice_last_error"],
            )
        return result
    except Exception as e:
        error = pc_exception_detail(e)
        diagnostic = build_auto_invoice_error(
            error,
            channel=ch,
            order_id=str(order_id),
            operation_id=diagnostic_operation_id,
            created_at=now_iso(),
        )
        diagnostic_write = None
        if row is not None:
            diagnostic_write = arca_update_order_diagnostics(
                row,
                updates={"arca_auto_invoice_last_error": diagnostic},
            )
        return {
            "ok": False,
            "error": error,
            "diagnostic": diagnostic,
            "diagnostic_persisted": bool((diagnostic_write or {}).get("persisted")),
            "tenant_id": tenant_id,
            "channel": ch,
            "order_id": str(order_id),
        }


# El dispatcher multiusuario reemplaza temporalmente el nombre global de la
# función para impedir facturación sincrónica durante la captura. La cola debe
# conservar la referencia real: puede empezar antes de que termine ese bloque.
_ARCA_AUTO_INVOICE_REAL_FN = arca_auto_invoice_order_safe


def _arca_auto_invoice_background_worker(
    tenant_id: str,
    channel: str,
    order_id: str,
    queue_key: str,
) -> None:
    tenant_ctx = set_current_tenant_id(str(tenant_id))
    try:
        result = _ARCA_AUTO_INVOICE_REAL_FN(channel, order_id)
        invoice = result.get("invoice") if isinstance(result.get("invoice"), dict) else {}
        result_summary = {
            "at": now_iso(),
            "ok": bool(result.get("ok")),
            "skipped": bool(result.get("skipped")),
            "duplicate": bool(result.get("duplicate")),
            "reason": result.get("reason"),
            "error": result.get("error"),
            "invoice_id": result.get("invoice_id") or invoice.get("id"),
            "cbte_nro": invoice.get("cbte_nro"),
            "cae": invoice.get("cae"),
        }
        try:
            diagnostic_row = arca_get_order(channel, order_id)
            arca_update_order_diagnostics(
                diagnostic_row,
                updates={"arca_auto_invoice_last_result": result_summary},
            )
        except Exception:
            pass
        print(
            f"[ARCA QUEUE] tenant={tenant_id} channel={channel} order_id={order_id} "
            f"ok={bool(result.get('ok'))} queued_key={queue_key}",
            flush=True,
        )
    except Exception as exc:
        try:
            diagnostic_row = arca_get_order(channel, order_id)
            arca_update_order_diagnostics(
                diagnostic_row,
                updates={
                    "arca_auto_invoice_last_result": {
                        "at": now_iso(),
                        "ok": False,
                        "unexpected": True,
                        "error": str(exc)[:1200],
                    }
                },
            )
        except Exception:
            pass
        print(
            f"[ARCA QUEUE] tenant={tenant_id} channel={channel} order_id={order_id} "
            f"unexpected={exc}",
            flush=True,
        )
    finally:
        reset_current_tenant_id(tenant_ctx)
        with _ARCA_EMISSION_QUEUE_LOCK:
            _ARCA_EMISSION_INFLIGHT.discard(queue_key)


def arca_queue_auto_invoice_order(channel: str, order_id: str) -> Dict[str, Any]:
    """Encola una factura sin hacer esperar a la actualización de ventas."""
    ch = norm_sku(channel).upper()
    tenant_id = str(get_effective_tenant_id() or DEFAULT_TENANT_ID)
    source_id = str(order_id or "").strip()
    queue_key = f"{tenant_id}:{ch}:{source_id}"
    if not source_id:
        return {"ok": False, "queued": False, "error": "order_id_missing"}

    with _ARCA_EMISSION_QUEUE_LOCK:
        if queue_key in _ARCA_EMISSION_INFLIGHT:
            return {
                "ok": True,
                "queued": True,
                "newly_queued": False,
                "reason": "already_queued",
                "channel": ch,
                "order_id": source_id,
            }
        _ARCA_EMISSION_INFLIGHT.add(queue_key)

    try:
        _ARCA_EMISSION_EXECUTOR.submit(
            _arca_auto_invoice_background_worker,
            tenant_id,
            ch,
            source_id,
            queue_key,
        )
    except Exception as exc:
        with _ARCA_EMISSION_QUEUE_LOCK:
            _ARCA_EMISSION_INFLIGHT.discard(queue_key)
        return {"ok": False, "queued": False, "error": str(exc), "channel": ch, "order_id": source_id}

    return {
        "ok": True,
        "queued": True,
        "newly_queued": True,
        "channel": ch,
        "order_id": source_id,
    }

def arca_find_pending_orders(channel: str = "ML", hours: int = 48, limit: int = 20) -> List[Dict[str, Any]]:
    ch = norm_sku(channel).upper()
    lim = max(1, min(int(limit or 20), 100))
    cutoff = (datetime.now(timezone.utc) - timedelta(hours=max(1, int(hours or 48)))).isoformat()
    rows = (
        sb.table("orders")
        .select("*")
        .eq("channel", ch)
        .eq("status", "paid")
        .gte("created_at", cutoff)
        .order("created_at", desc=True)
        .limit(500)
        .execute()
        .data
        or []
    )

    pending = []
    seen = set()
    for row in rows:
        key = arca_source_key_for_pending(row)
        if key in seen:
            continue
        seen.add(key)
        inv = arca_existing_invoice_for_order(row)
        if inv and inv.get("cae"):
            continue
        raw = row_raw_dict(row)
        ml_fiscal_check = raw.get("ml_fiscal_documents_check")
        if ch == "ML" and isinstance(ml_fiscal_check, dict) and ml_fiscal_check.get("present") is True:
            continue
        if not arca_order_is_delivered_for_auto_invoice(ch, row):
            continue
        pending.append(row)
        if len(pending) >= lim:
            break
    return pending

def arca_auto_invoice_backfill_tenant(
    tenant_id: str,
    channels: List[str],
    hours: int = 720,
    limit_per_channel: int = 50,
) -> Dict[str, Any]:
    """Procesa al activar la automática sólo ventas entregadas y sin CAE.

    Corre como BackgroundTask, fija explícitamente el tenant y es idempotente:
    arca_auto_invoice_order_safe vuelve a comprobar conexión, switch, entrega y CAE.
    """
    ctx = set_current_tenant_id(str(tenant_id))
    summary: Dict[str, Any] = {
        "tenant_id": str(tenant_id),
        "channels": {},
        "started_at": now_iso(),
    }
    try:
        for channel in [norm_sku(x).upper() for x in (channels or [])]:
            if channel not in ("ML", "TN"):
                continue
            rows = arca_find_pending_orders(channel=channel, hours=hours, limit=limit_per_channel)
            channel_result = {"found_pending": len(rows), "eligible_delivered": 0, "issued": 0, "skipped": 0, "errors": 0, "items": []}
            for row in rows:
                if not arca_order_is_delivered_for_auto_invoice(channel, row):
                    channel_result["skipped"] += 1
                    continue
                channel_result["eligible_delivered"] += 1
                raw = row_raw_dict(row)
                source_id = str(raw.get("ml_pack_id") or row.get("external_order_id") or row.get("id"))
                result = arca_auto_invoice_order_safe(channel, source_id)
                if result.get("ok") and not result.get("skipped"):
                    channel_result["issued"] += 1
                elif result.get("ok"):
                    channel_result["skipped"] += 1
                else:
                    channel_result["errors"] += 1
                channel_result["items"].append({
                    "source_id": source_id,
                    "external_order_id": row.get("external_order_id"),
                    "result": result,
                })
            summary["channels"][channel] = channel_result
        summary["finished_at"] = now_iso()
        print(f"[ARCA AUTO BACKFILL] {json.dumps(summary, ensure_ascii=False, default=str)}", flush=True)
        return summary
    except Exception as exc:
        summary["error"] = pc_exception_detail(exc)
        summary["finished_at"] = now_iso()
        print(f"[ARCA AUTO BACKFILL ERROR] {json.dumps(summary, ensure_ascii=False, default=str)}", flush=True)
        return summary
    finally:
        reset_current_tenant_id(ctx)


def arca_recent_orders_for_preview(channel: str, limit: int = 10) -> List[Dict[str, Any]]:
    """
    Trae últimas ventas pagadas para probar armado de facturas SIN CAE.
    No filtra por facturación existente porque se usa únicamente para layout/control,
    no como bandeja fiscal real de pendientes.
    """
    ch = norm_sku(channel).upper()
    lim = max(1, min(int(limit or 10), 50))
    rows = (
        sb.table("orders")
        .select("*")
        .eq("channel", ch)
        .eq("status", "paid")
        .order("created_at", desc=True)
        .limit(lim)
        .execute()
        .data
        or []
    )
    return rows


def arca_preview_payload_for_order(row: Dict[str, Any], force_type: Optional[str] = None) -> Dict[str, Any]:
    body = ArcaInvoiceDraftIn(
        concept=ARCA_DEFAULT_CONCEPTO,
        force_type=force_type,
        notes="Vista previa sin CAE para control de importes/layout. No tiene validez fiscal.",
    )
    payload = arca_build_invoice_payload(row, body)
    payload["status"] = "preview_no_cae"
    payload["cbte_nro"] = None
    payload["cae"] = None
    payload["cae_vto"] = None
    payload["raw_data"]["preview_no_cae"] = True
    payload["raw_data"]["preview_warning"] = "No insertado. No emitido. Solo prueba visual/fiscal previa."
    return payload


def arca_preview_summary_from_payload(payload: Dict[str, Any]) -> Dict[str, Any]:
    lines = payload.get("lines") or []
    return {
        "source_channel": payload.get("source_channel"),
        "source_order_id": payload.get("source_order_id"),
        "source_order_number": payload.get("source_order_number"),
        "invoice_date": payload.get("invoice_date"),
        "cbte_letra": payload.get("cbte_letra"),
        "cbte_tipo": payload.get("cbte_tipo"),
        "cbte_tipo_label": payload.get("cbte_tipo_label"),
        "customer_name": payload.get("customer_name"),
        "customer_doc_type": payload.get("customer_doc_type"),
        "customer_doc_number": payload.get("customer_doc_number"),
        "customer_iva_condition": payload.get("customer_iva_condition"),
        "importe_neto": payload.get("importe_neto"),
        "importe_iva": payload.get("importe_iva"),
        "iva_contenido": payload.get("iva_contenido"),
        "importe_total": payload.get("importe_total"),
        "line_count": len(lines),
        "status": payload.get("status"),
    }


def arca_get_invoice(invoice_id: str) -> Dict[str, Any]:
    rows = (
        sb.table("arca_invoices")
        .select("*")
        .eq("id", invoice_id)
        .limit(1)
        .execute()
        .data
        or []
    )
    if not rows:
        raise HTTPException(status_code=404, detail=f"No existe factura {invoice_id}")
    return arca_enrich_invoice_report_row(rows[0])


def arca_format_date(value: Any) -> str:
    txt = str(value or "").strip()
    if not txt:
        return ""
    # Mantiene DD/MM/AAAA si ya viene así; convierte YYYY-MM-DD o YYYYMMDD.
    try:
        if re.match(r"^\d{8}$", txt):
            return f"{txt[6:8]}/{txt[4:6]}/{txt[0:4]}"
        if re.match(r"^\d{4}-\d{2}-\d{2}", txt):
            return datetime.fromisoformat(txt[:10]).strftime("%d/%m/%Y")
    except Exception:
        pass
    return txt


def arca_invoice_total(inv: Dict[str, Any]) -> float:
    total = arca_float(inv.get("importe_total"), 0)
    if total > 0:
        return total
    raw = inv.get("raw_data") or {}
    if isinstance(raw, dict):
        order = raw.get("order") or {}
        if isinstance(order, dict):
            total = arca_float(order.get("total"), 0)
            if total > 0:
                return total
    return 0.0


def arca_rebuild_lines_from_invoice_source(inv: Dict[str, Any], letter: str) -> List[Dict[str, Any]]:
    """Intenta reconstruir líneas desde orders, agrupando packs ML si aplica."""
    try:
        ch = str(inv.get("source_channel") or "").upper()
        raw = inv.get("raw_data") or {}
        raw_order = raw.get("order") if isinstance(raw, dict) else None

        candidate_ids = []
        if ch == "ML":
            for v in [
                inv.get("source_pack_id"),
                inv.get("source_order_number"),
                inv.get("source_order_id"),
                inv.get("source_order_api_id"),
            ]:
                if v and str(v).lstrip("#") not in candidate_ids:
                    candidate_ids.append(str(v).lstrip("#"))
            if isinstance(raw_order, dict):
                rr = row_raw_dict(raw_order)
                for v in [rr.get("ml_pack_id"), rr.get("ml_order_id"), raw_order.get("external_order_id")]:
                    if v and str(v).lstrip("#") not in candidate_ids:
                        candidate_ids.append(str(v).lstrip("#"))
        else:
            for v in [inv.get("source_order_id"), inv.get("source_order_api_id")]:
                if v and str(v) not in candidate_ids:
                    candidate_ids.append(str(v))

        for oid in candidate_ids:
            try:
                order = arca_get_order(ch, oid)
            except Exception:
                continue
            order = arca_consolidate_order_for_invoice(order)
            lines = arca_build_lines_from_order(order)
            calc = arca_calculate_invoice(lines, letter)
            if arca_float(calc.get("importe_total"), 0) > 0.50:
                return calc.get("lines") or []

        if isinstance(raw_order, dict) and raw_order:
            order = arca_consolidate_order_for_invoice(raw_order)
            lines = arca_build_lines_from_order(order)
            calc = arca_calculate_invoice(lines, letter)
            if arca_float(calc.get("importe_total"), 0) > 0.50:
                return calc.get("lines") or []
    except Exception:
        return []
    return []


def arca_lines_from_invoice_or_raw(inv: Dict[str, Any], letter: str) -> List[Dict[str, Any]]:
    """
    Devuelve líneas listas para imprimir.
    Soporta:
    - facturas nuevas con arca_invoices.lines cargado;
    - facturas test/draft con líneas incompletas;
    - facturas viejas donde quedó raw_data.order;
    - fallback compacto para facturas ya emitidas sin detalle persistido.
    """
    # Para borradores/test de ML, siempre intentamos reconstruir desde el pack completo antes
    # de confiar en líneas guardadas viejas que pueden representar una sola order parcial.
    if str(inv.get("source_channel") or "").upper() == "ML" and not inv.get("cae"):
        rebuilt_first = arca_rebuild_lines_from_invoice_source(inv, letter)
        if rebuilt_first:
            return rebuilt_first

    raw_lines = inv.get("lines") or []
    if isinstance(raw_lines, list) and len(raw_lines) > 0:
        if any(("unit_price_display" not in x or "total_gross" not in x) for x in raw_lines if isinstance(x, dict)):
            normalized = []
            for x in raw_lines:
                if not isinstance(x, dict):
                    continue
                normalized.append({
                    "sku": x.get("sku") or x.get("code") or "",
                    "description": x.get("description") or x.get("name") or x.get("title") or x.get("product_name") or x.get("sku") or "Producto",
                    "quantity": arca_float(x.get("quantity") or x.get("qty") or 1, 1),
                    "unit_price_gross": arca_float(x.get("unit_price_gross") or x.get("unit_price") or x.get("price") or 0, 0),
                    "discount_pct": arca_float(x.get("discount_pct") or 0, 0),
                    "iva_pct": arca_float(x.get("iva_pct") or ARCA_IVA_ALICUOTA, ARCA_IVA_ALICUOTA),
                    "source": x.get("source") or "invoice_line",
                })
            calc = arca_calculate_invoice(normalized, letter)
            if arca_float(calc.get("importe_total"), 0) > 0.50:
                return calc.get("lines") or []
            # Si las líneas existen pero tienen importes cero, seguimos a raw/order fallback.
        else:
            calc_existing = arca_calculate_invoice(raw_lines, letter)
            if arca_float(calc_existing.get("importe_total"), 0) > 0.50:
                return raw_lines

    raw = inv.get("raw_data") or {}
    if isinstance(raw, dict):
        order = raw.get("order") or {}
        if isinstance(order, dict) and order:
            try:
                lines = arca_build_lines_from_order(order)
                calc = arca_calculate_invoice(lines, letter)
                if calc.get("lines"):
                    return calc["lines"]
            except Exception:
                pass

    # Si hay source_channel/source_order_id, intentamos reconstruir desde orders + order_items.
    try:
        ch = str(inv.get("source_channel") or "").upper()
        oid = str(inv.get("source_order_id") or inv.get("source_order_api_id") or "")
        if ch and oid:
            order = arca_get_order(ch, oid)
            lines = arca_build_lines_from_order(order)
            calc = arca_calculate_invoice(lines, letter)
            if calc.get("lines"):
                return calc["lines"]
    except Exception:
        pass

    # Regla fiscal: si no se pudieron reconstruir líneas reales, no inventamos una línea resumen.
    return []

def arca_effective_totals(inv: Dict[str, Any], lines: List[Dict[str, Any]], letter: str) -> Dict[str, Any]:
    calc = arca_calculate_invoice(lines, letter) if lines else {}
    calc_total = arca_float(calc.get("importe_total"), 0)
    inv_total = arca_float(inv.get("importe_total"), 0)
    is_mutable_preview = (not inv.get("cae")) or str(inv.get("status") or "").lower() in ["draft", "test", "preview"]

    if is_mutable_preview and calc_total > 0.50:
        if letter == "A":
            return {
                "importe_neto": arca_float(calc.get("importe_neto"), 0),
                "importe_iva": arca_float(calc.get("importe_iva"), 0),
                "importe_total": calc_total,
                "iva_contenido": None,
            }
        if letter == "C":
            return {
                "importe_neto": calc_total,
                "importe_iva": 0.0,
                "importe_total": calc_total,
                "iva_contenido": 0.0,
            }
        return {
            "importe_neto": calc_total,
            "importe_iva": 0.0,
            "importe_total": calc_total,
            "iva_contenido": arca_float(calc.get("iva_contenido"), 0),
        }

    total = inv_total or calc_total
    if letter == "A":
        neto = arca_float(inv.get("importe_neto"), 0) or arca_float(calc.get("importe_neto"), 0)
        iva = arca_float(inv.get("importe_iva"), 0) or arca_float(calc.get("importe_iva"), 0)
        if total and (not neto or not iva):
            neto = round(total / (1 + ARCA_IVA_ALICUOTA / 100), 2)
            iva = round(total - neto, 2)
        return {"importe_neto": neto, "importe_iva": iva, "importe_total": total, "iva_contenido": None}

    if letter == "C":
        return {"importe_neto": total, "importe_iva": 0.0, "importe_total": total, "iva_contenido": 0.0}

    iva_cont = arca_float(inv.get("iva_contenido"), 0) or arca_float(calc.get("iva_contenido"), 0)
    if total and not iva_cont:
        iva_cont = round(total - (total / (1 + ARCA_IVA_ALICUOTA / 100)), 2)
    return {"importe_neto": total, "importe_iva": 0.0, "importe_total": total, "iva_contenido": iva_cont}



ARCA_TEMPLATE_LAST_INFO: Dict[str, Any] = {}


def arca_factura_template_info() -> Dict[str, Any]:
    template_path = os.path.join(os.path.dirname(__file__), "templates", "arca_factura.html")
    info = {
        "app_version": APP_VERSION,
        "cwd": os.getcwd(),
        "module_file": __file__,
        "module_dir": os.path.dirname(__file__),
        "template_path": template_path,
        "template_exists": os.path.exists(template_path),
        "template_source": "fallback_internal",
        "template_size": 0,
        "template_mtime": None,
        "error": None,
    }
    try:
        if info["template_exists"]:
            st = os.stat(template_path)
            info["template_size"] = st.st_size
            info["template_mtime"] = datetime.fromtimestamp(st.st_mtime).isoformat()
            info["template_source"] = "external_file"
    except Exception as e:
        info["error"] = str(e)
        info["template_source"] = "fallback_internal"
    return info


def arca_factura_template_html() -> str:
    """Carga la plantilla HTML editable de comprobantes ARCA.
    Si no existe el archivo externo, usa fallback interno pero lo marca visible.
    """
    global ARCA_TEMPLATE_LAST_INFO
    info = arca_factura_template_info()
    ARCA_TEMPLATE_LAST_INFO = info
    template_path = info["template_path"]
    if info.get("template_source") == "external_file":
        try:
            with open(template_path, "r", encoding="utf-8") as f:
                return f.read()
        except Exception as e:
            info["error"] = str(e)
            info["template_source"] = "fallback_internal"
            ARCA_TEMPLATE_LAST_INFO = info
            print(f"[ARCA] No pude leer plantilla externa {template_path}: {e}")
    else:
        print(f"[ARCA] Plantilla externa NO encontrada: {template_path}")
    return ARCA_FACTURA_TEMPLATE_INTERNAL


def arca_template_debug_banner(info: Dict[str, Any]) -> str:
    source = str(info.get("template_source") or "")
    path = html_lib.escape(str(info.get("template_path") or ""))
    exists = html_lib.escape(str(info.get("template_exists")))
    version = html_lib.escape(str(info.get("app_version") or APP_VERSION))
    if source == "external_file":
        return f"<!-- ARCA_TEMPLATE source=external_file path={path} exists={exists} version={version} -->"
    error = html_lib.escape(str(info.get("error") or ""))
    return (
        '<div class="noPrint" style="width:210mm;margin:6px auto 0 auto;text-align:left;'
        'background:#ffe5e5;border:2px solid #b42318;color:#7a0000;padding:8px;'
        'font-family:Arial;font-size:12px;font-weight:700">'
        f'ARCA TEMPLATE: USANDO FALLBACK INTERNO - no se encontró templates/arca_factura.html.<br>'
        f'path: {path} · exists: {exists} · version: {version} · error: {error}'
        '</div>'
    )



def arca_qr_invoice_date_yyyy_mm_dd(inv: Dict[str, Any]) -> str:
    """Fecha para JSON QR ARCA: YYYY-MM-DD."""
    raw = inv.get("invoice_date") or inv.get("fecha_cbte") or inv.get("created_at") or datetime.now(timezone.utc).date().isoformat()
    txt = str(raw).strip()
    if not txt:
        return datetime.now(timezone.utc).date().isoformat()
    # ISO: 2026-05-30 o 2026-05-30T...
    m = re.match(r"^(\d{4}-\d{2}-\d{2})", txt)
    if m:
        return m.group(1)
    # dd/mm/yyyy
    m = re.match(r"^(\d{2})/(\d{2})/(\d{4})$", txt)
    if m:
        return f"{m.group(3)}-{m.group(2)}-{m.group(1)}"
    return datetime.now(timezone.utc).date().isoformat()


def arca_qr_doc_tipo_nro(inv: Dict[str, Any]) -> Dict[str, int]:
    """Mapeo para QR ARCA. CUIT/CUIL=80, DNI=96, Consumidor Final=99/0."""
    doc_type = str(inv.get("customer_doc_type") or inv.get("doc_type") or "").strip().upper()
    doc_num_digits = arca_digits(inv.get("customer_doc_number") or inv.get("doc_nro") or "")
    if doc_type in ["CUIT", "CUIL"] and len(doc_num_digits) == 11:
        return {"tipoDocRec": 80, "nroDocRec": int(doc_num_digits)}
    if doc_type in ["DNI", "DU"] and 7 <= len(doc_num_digits) <= 8:
        return {"tipoDocRec": 96, "nroDocRec": int(doc_num_digits)}
    if len(doc_num_digits) == 11:
        return {"tipoDocRec": 80, "nroDocRec": int(doc_num_digits)}
    if 7 <= len(doc_num_digits) <= 8:
        return {"tipoDocRec": 96, "nroDocRec": int(doc_num_digits)}
    return {"tipoDocRec": 99, "nroDocRec": 0}


def arca_qr_url(inv: Dict[str, Any], totals: Dict[str, Any], pto_vta: int, cbte_tipo: int, cbte_nro: Any, cae: str) -> str:
    """URL oficial de consulta QR ARCA para un comprobante ya autorizado."""
    if not cae or not cbte_tipo or not cbte_nro:
        return ""
    try:
        import urllib.parse
        doc = arca_qr_doc_tipo_nro(inv)
        payload = {
            "ver": 1,
            "fecha": arca_qr_invoice_date_yyyy_mm_dd(inv),
            "cuit": int(arca_digits(inv.get("cuit_emisor") or ARCA_EMISOR_CUIT)),
            "ptoVta": int(pto_vta),
            "tipoCmp": int(cbte_tipo),
            "nroCmp": int(cbte_nro),
            "importe": round(float(arca_float(totals.get("importe_total"), 0)), 2),
            "moneda": str(inv.get("moneda") or inv.get("currency") or "PES"),
            "ctz": float(inv.get("moneda_ctz") or inv.get("currency_rate") or 1),
            "tipoDocRec": int(doc["tipoDocRec"]),
            "nroDocRec": int(doc["nroDocRec"]),
            "tipoCodAut": "E",
            "codAut": int(arca_digits(cae)),
        }
        raw_json = json.dumps(payload, separators=(",", ":"), ensure_ascii=False)
        p64 = base64.b64encode(raw_json.encode("utf-8")).decode("ascii")
        return "https://www.arca.gob.ar/fe/qr/?p=" + urllib.parse.quote(p64, safe="")
    except Exception as e:
        print(f"[ARCA QR] Error armando URL QR: {e}")
        return ""


def arca_qr_html(inv: Dict[str, Any], totals: Dict[str, Any], pto_vta: int, cbte_tipo: int, cbte_nro: Any, cae: str) -> str:
    """
    Devuelve el QR ARCA como PNG inline base64.

    Importante para PDF: no alcanza con mostrar un link. El HTML imprimible
    debe llevar la imagen embebida para que el PDF adjunto al cliente conserve
    el QR aunque se genere/abra offline.

    Requiere en requirements.txt:
      qrcode
      Pillow
    """
    if not cae:
        return "QR<br>pendiente"

    qr_url = arca_qr_url(inv, totals, pto_vta, cbte_tipo, cbte_nro, cae)
    if not qr_url:
        return "QR<br>no disponible"

    safe_url = html_lib.escape(qr_url, quote=True)

    try:
        import qrcode
        from qrcode.constants import ERROR_CORRECT_M

        qr = qrcode.QRCode(
            version=None,
            error_correction=ERROR_CORRECT_M,
            box_size=10,
            border=2,
        )
        qr.add_data(qr_url)
        qr.make(fit=True)
        img = qr.make_image(fill_color="black", back_color="white").convert("RGB")

        buf = io.BytesIO()
        img.save(buf, format="PNG", optimize=True)
        data = base64.b64encode(buf.getvalue()).decode("ascii")

        return (
            f'<a href="{safe_url}" target="_blank" title="Ver comprobante en ARCA" '
            f'style="display:block;width:28mm;height:28mm">'
            f'<img alt="QR ARCA" src="data:image/png;base64,{data}" '
            f'style="display:block;width:28mm;height:28mm;object-fit:contain;border:0" />'
            f'</a>'
        )
    except Exception as e:
        # Fallback deliberado: no rompe la factura HTML, pero deja visible en logs
        # que falta qrcode/Pillow o que hubo un problema generando PNG.
        print(f"[ARCA QR] ERROR generando PNG inline. Revisar requirements qrcode/Pillow. Detalle: {e}")
        return (
            f'<a href="{safe_url}" target="_blank" '
            f'style="font-size:7px;line-height:1.1;word-break:break-all;color:#111;text-decoration:none">'
            f'QR ARCA<br>abrir validación<br><small>PNG no disponible</small></a>'
        )


# XELERIA_ARCA_PDF_TENANT_BRANDING_V198
# XELERIA_ARCA_PDF_FINAL_LAYOUT_V199
def arca_invoice_tenant_logo_url(inv: Dict[str, Any]) -> str:
    """Devuelve el logo del tenant en formato seguro para HTML/PDF.

    Prioriza el logo persistido en tenant_settings. Acepta data URL de imagen o URL
    http(s). Nunca mezcla el logo global legacy de otro comercio dentro del SaaS.
    """
    raw = inv.get("raw_data") if isinstance(inv.get("raw_data"), dict) else {}
    tenant_emitter = raw.get("tenant_emitter") if isinstance(raw.get("tenant_emitter"), dict) else {}
    tenant_id = str(
        inv.get("tenant_id")
        or tenant_emitter.get("tenant_id")
        or get_effective_tenant_id()
        or ""
    ).strip()

    candidates: List[Any] = [
        tenant_emitter.get("logo_png_500_base64"),
        tenant_emitter.get("logo_url"),
        raw.get("logo_png_500_base64"),
        raw.get("logo_url"),
    ]

    if tenant_id and _sb_raw:
        try:
            rows = (
                _sb_raw.table("tenant_settings")
                .select("logo_png_500_base64,settings")
                .eq("tenant_id", tenant_id)
                .limit(1)
                .execute()
                .data
                or []
            )
            if rows:
                row = rows[0] or {}
                settings = _settings_blob(row)
                candidates = [
                    row.get("logo_png_500_base64"),
                    settings.get("logo_png_500_base64"),
                    settings.get("logo_url"),
                    *candidates,
                ]
        except Exception as exc:
            print(f"[ARCA PDF] No pude leer logo tenant={tenant_id}: {exc}", flush=True)

    for value in candidates:
        logo = str(value or "").strip()
        if not logo:
            continue
        lower = logo.lower()
        if lower.startswith("data:image/") and ";base64," in lower[:80]:
            return logo
        if lower.startswith("https://") or lower.startswith("http://"):
            return logo
    return ""


def arca_invoice_html(inv: Dict[str, Any]) -> str:
    from string import Template

    raw_data = inv.get("raw_data") if isinstance(inv.get("raw_data"), dict) else {}
    tenant_emitter = raw_data.get("tenant_emitter") if isinstance(raw_data.get("tenant_emitter"), dict) else {}
    raw_letter = str(inv.get("cbte_letra") or "").strip().upper()
    cbte_tipo = int(inv.get("cbte_tipo") or 0)
    letter = raw_letter or ("A" if cbte_tipo in (1, 2, 3, 4) else "B" if cbte_tipo in (6, 7, 8, 9) else "C" if cbte_tipo in (11, 12, 13, 15) else "B")
    tipo_base = str(inv.get("cbte_tipo_label") or "Factura").strip()
    upper_label = tipo_base.upper()
    if "NOTA" in upper_label and "CRED" in upper_label:
        tipo_base = "Nota de Crédito"
    elif "NOTA" in upper_label and "DEB" in upper_label:
        tipo_base = "Nota de Débito"
    elif "RECIB" in upper_label:
        tipo_base = "Recibo"
    elif "REMIT" in upper_label:
        tipo_base = "Remito"
    else:
        tipo_base = "Factura" if "FACT" in upper_label or not tipo_base else tipo_base.replace(f" {letter}", "")
    title = f"{tipo_base} {letter}".strip()

    status = inv.get("status") or "draft"
    cae = inv.get("cae") or ""
    cae_vto = inv.get("cae_vto") or ""
    cbte_nro = inv.get("cbte_nro")
    pto_vta = int(inv.get("pto_vta") or ARCA_PTO_VTA)
    nro = f"{pto_vta:04d}-{int(cbte_nro or 0):08d}" if cbte_nro else f"{pto_vta:04d}-BORRADOR"
    is_a = letter == "A"
    is_c = letter == "C"
    is_fiscal = tipo_base.lower() != "remito"

    lines = arca_lines_from_invoice_or_raw(inv, letter)
    totals = arca_effective_totals(inv, lines, letter)

    item_rows = []
    for line in lines[:14]:
        qty = arca_float(line.get("quantity"), 0)
        unit = arca_float(line.get("unit_price_display"), 0)
        subtotal = arca_float(line.get("subtotal_display"), 0)
        discount_pct = arca_float(line.get("discount_pct"), 0)
        gross = round(qty * unit, 2)
        discount_amount = max(0.0, round(gross - subtotal, 2))
        iva_cell = '<td class="r">21%</td>' if is_a else ''
        item_rows.append(f"""
        <tr>
          <td class="code">{html_lib.escape(str(line.get('sku') or ''))}</td>
          <td class="desc">{html_lib.escape(str(line.get('description') or ''))}</td>
          <td class="c">{qty:g}</td>
          <td class="c">unidades</td>
          <td class="r">{arca_money(unit)}</td>
          <td class="r">{discount_pct:.0f}%</td>
          <td class="r">{arca_money(subtotal)}</td>
          {iva_cell}
        </tr>
        """)

    col_count = 8 if is_a else 7
    for _ in range(max(0, 12 - len(item_rows))):
        item_rows.append(f"<tr class='empty'><td colspan='{col_count}'>&nbsp;</td></tr>")

    headers_extra = "<th>IVA</th>" if is_a else ""
    if is_a:
        totals_block = f"""
          <div class="tot-row"><span>Subtotal:</span><b>{arca_money(totals.get('importe_neto'))}</b></div>
          <div class="tot-row"><span>IVA 21%:</span><b>{arca_money(totals.get('importe_iva'))}</b></div>
          <div class="tot-row"><span>Importe Otros Tributos:</span><b>{arca_money(0)}</b></div>
          <div class="tot-row grand"><span>Importe Total:</span><b>{arca_money(totals.get('importe_total'))}</b></div>
        """
        fiscal_block = ""
    else:
        totals_block = f"""
          <div class="tot-row"><span>Subtotal:</span><b>{arca_money(totals.get('importe_total'))}</b></div>
          <div class="tot-row"><span>Importe Otros Tributos:</span><b>{arca_money(0)}</b></div>
          <div class="tot-row grand"><span>Importe Total:</span><b>{arca_money(totals.get('importe_total'))}</b></div>
        """
        fiscal_block = "" if is_c else f"""
          <div class="transparency-title">Régimen de Transparencia Fiscal al Consumidor (Ley 27.743)</div>
          <div class="tax-line"><span>IVA Contenido:</span><b>{arca_money(totals.get('iva_contenido'))}</b></div>
          <div class="tax-line"><span>Otros Impuestos Nacionales Directos:</span><b>{arca_money(0)}</b></div>
        """

    template_info_for_marker = arca_factura_template_info()
    factura_desde = "HTML" if template_info_for_marker.get("template_exists") else "PY"
    warning = "" if cae else f"<div class='draft-stamp'>BORRADOR ERP - NO FISCAL / SIN CAE · Factura desde {factura_desde}</div>"
    qr = arca_qr_html(inv, totals, pto_vta, cbte_tipo, cbte_nro, cae)
    invoice_date = arca_format_date(inv.get("invoice_date"))
    cae_vto_print = arca_format_date(cae_vto)
    customer_name = str(inv.get("customer_name") or "")
    doc_type = str(inv.get("customer_doc_type") or "").strip()
    doc_num = str(inv.get("customer_doc_number") or "").strip()
    doc_full = f"{doc_type} {doc_num}".strip()
    customer_address = str(inv.get("customer_address") or "")
    customer_localidad = arca_customer_localidad_from_raw(inv)
    source_channel = arca_display_channel_label(inv.get("source_channel"))
    source_number = str(inv.get("source_order_number") or inv.get("source_order_id") or "")
    notes = str(inv.get("notes") or "")
    # Limpieza de notas técnicas internas: no deben salir en el comprobante para cliente/PDF.
    internal_note_markers = [
        "fallo de save",
        "guardado posterior",
        "0.1.57",
        "0.1.58",
        "save_error",
    ]
    if any(marker in notes.lower() for marker in internal_note_markers):
        notes = ""
    if warning and notes:
        notes_html = f"{html_lib.escape(notes)}<br>{warning}"
    elif warning:
        notes_html = warning
    else:
        notes_html = html_lib.escape(notes)

    cond_pago = ""
    comprobante_autorizado = "Comprobante Autorizado" if cae else "Comprobante pendiente de autorización"
    cae_label = "CAE Nº:" if is_fiscal else "Código interno:"
    cae_vto_label = "Fecha de Vto. CAE:" if is_fiscal else ""
    legal_note = "Esta Agencia no se responsabiliza por los datos ingresados en el detalle de la operación" if is_fiscal else "Documento interno no fiscal. No reemplaza factura ni comprobante fiscal."

    ctx = {
        "page_title": html_lib.escape(f"{title} {nro}"),
        "logo_url": html_lib.escape(arca_invoice_tenant_logo_url(inv), quote=True),
        "letter": html_lib.escape(letter),
        "cbte_codigo": f"{cbte_tipo:02d}" if cbte_tipo else "--",
        "title": html_lib.escape(title.upper()),
        "original_label": "ORIGINAL" if is_fiscal else "NO FISCAL",
        "emisor_razon": html_lib.escape(str(tenant_emitter.get("razon_social") or tenant_emitter.get("display_name") or ARCA_EMISOR_RAZON_SOCIAL)),
        "emisor_cuit": html_lib.escape(str(inv.get("cuit_emisor") or tenant_emitter.get("cuit") or ARCA_EMISOR_CUIT)),
        "emisor_cond_iva": html_lib.escape(str(tenant_emitter.get("iva_condition") or ARCA_EMISOR_COND_IVA)),
        "emisor_dom": html_lib.escape(str(tenant_emitter.get("address") or ARCA_EMISOR_DOMICILIO)),
        "emisor_iibb": html_lib.escape(ARCA_EMISOR_IIBB),
        "emisor_inicio": html_lib.escape(ARCA_EMISOR_INICIO),
        "emisor_email": html_lib.escape(ARCA_EMISOR_EMAIL),
        "emisor_web": html_lib.escape(ARCA_EMISOR_WEB),
        "pto_vta": f"{pto_vta:04d}",
        "nro": html_lib.escape(nro),
        "invoice_date": html_lib.escape(invoice_date),
        "periodo_desde": html_lib.escape(str(inv.get("periodo_desde") or "")),
        "periodo_hasta": html_lib.escape(str(inv.get("periodo_hasta") or "")),
        "fecha_vto_pago": html_lib.escape(str(inv.get("fecha_vto_pago") or "")),
        "customer_name": html_lib.escape(customer_name),
        "customer_doc": html_lib.escape(doc_full),
        "customer_iva": html_lib.escape(str(inv.get("customer_iva_condition") or "")),
        "customer_address": html_lib.escape(customer_address),
        "customer_localidad": html_lib.escape(customer_localidad),
        "cond_pago": html_lib.escape(cond_pago),
        "concept": html_lib.escape(str(inv.get("concept") or "Productos")),
        "source_channel": html_lib.escape(source_channel),
        "source_number": html_lib.escape(source_number),
        "headers_extra": headers_extra,
        "item_rows": "".join(item_rows),
        "notes_html": notes_html,
        "fiscal_block": fiscal_block,
        "totals_block": totals_block,
        "qr": qr,
        "comprobante_autorizado": html_lib.escape(comprobante_autorizado),
        "status": html_lib.escape(str(status)),
        "cae_label": html_lib.escape(cae_label),
        "cae": html_lib.escape(str(cae)),
        "cae_vto_label": html_lib.escape(cae_vto_label),
        "cae_vto": html_lib.escape(str(cae_vto_print)),
        "legal_note": html_lib.escape(legal_note),
    }
    template_html = arca_factura_template_html()
    debug_banner = arca_template_debug_banner(ARCA_TEMPLATE_LAST_INFO)
    if "<body>" in template_html:
        template_html = template_html.replace("<body>", "<body>" + debug_banner, 1)
    else:
        template_html = debug_banner + template_html
    return Template(template_html).safe_substitute(ctx)


