def pc_slug_file(value: Any, default: str = "factura") -> str:
    txt = str(value or "").strip()
    if not txt:
        txt = default
    txt = re.sub(r"[^A-Za-z0-9_.-]+", "-", txt)
    txt = re.sub(r"-+", "-", txt).strip("-_.")
    return txt or default


def arca_invoice_filename(invoice: Dict[str, Any]) -> str:
    """Nombre fiscal estable: CUIT-CCC-PPPP-NNNNNNNN.pdf."""
    try:
        cbte_tipo = int(invoice.get("cbte_tipo") or 0)
    except Exception:
        cbte_tipo = 0

    raw = invoice.get("raw_data") if isinstance(invoice.get("raw_data"), dict) else {}
    emitter = raw.get("tenant_emitter") if isinstance(raw.get("tenant_emitter"), dict) else {}
    cuit = arca_digits(invoice.get("cuit_emisor") or emitter.get("cuit") or ARCA_EMISOR_CUIT)
    cuit = cuit or "CUIT"
    tipo = str(cbte_tipo).zfill(3)
    pto = str(int(invoice.get("pto_vta") or ARCA_PTO_VTA)).zfill(4)
    nro_raw = invoice.get("cbte_nro")
    try:
        nro = str(int(nro_raw)).zfill(8) if nro_raw not in [None, ""] else "BORRADOR"
    except Exception:
        nro = pc_slug_file(nro_raw, "BORRADOR").upper().replace("-", "_")
    return f"{cuit}-{tipo}-{pto}-{nro}.pdf"


def arca_invoice_pdf_bytes(invoice: Dict[str, Any]) -> bytes:
    """Genera PDF A4 desde el mismo HTML final que ve el usuario."""
    html = arca_invoice_html(invoice)
    try:
        from weasyprint import HTML  # type: ignore
        return HTML(string=html, base_url=os.getcwd()).write_pdf()
    except Exception as e:
        raise HTTPException(status_code=500, detail=f"No se pudo generar PDF de factura: {e}")


def arca_pdf_storage_path(invoice: Dict[str, Any]) -> str:
    channel = pc_slug_file(invoice.get("source_channel") or "ERP", "ERP")
    source = pc_slug_file(invoice.get("source_pack_id") or invoice.get("source_order_id") or invoice.get("id"), "sin-operacion")
    return f"{ARCA_PDF_STORAGE_PREFIX}/{channel}/{source}/{arca_invoice_filename(invoice)}"


def arca_s3_client() -> Any:
    try:
        import boto3  # type: ignore
    except Exception as exc:
        raise RuntimeError("boto3 no disponible para AWS S3") from exc
    kwargs: Dict[str, Any] = {}
    if ARCA_PDF_S3_REGION:
        kwargs["region_name"] = ARCA_PDF_S3_REGION
    return boto3.client("s3", **kwargs)


def arca_store_invoice_pdf(invoice: Dict[str, Any], pdf_bytes: bytes) -> Dict[str, Any]:
    if not ARCA_PDF_S3_BUCKET:
        return {"ok": False, "skipped": True, "reason": "ARCA_PDF_S3_BUCKET no configurado"}
    path = arca_pdf_storage_path(invoice)
    try:
        arca_s3_client().put_object(
            Bucket=ARCA_PDF_S3_BUCKET,
            Key=path,
            Body=pdf_bytes,
            ContentType="application/pdf",
        )
        return {"ok": True, "bucket": ARCA_PDF_S3_BUCKET, "path": path, "provider": "aws_s3"}
    except Exception as e:
        return {"ok": False, "bucket": ARCA_PDF_S3_BUCKET, "path": path, "provider": "aws_s3", "error": str(e)}


def arca_update_invoice_raw_dispatch(invoice_id: Any, dispatch: Dict[str, Any]) -> None:
    try:
        current = arca_get_invoice(str(invoice_id))
        raw = current.get("raw_data") if isinstance(current.get("raw_data"), dict) else {}
        raw = dict(raw or {})
        raw["post_issue_dispatch"] = dispatch
        raw["post_issue_dispatch_at"] = now_iso()
        sb.table("arca_invoices").update({"raw_data": raw, "updated_at": now_iso()}).eq("id", invoice_id).execute()
    except Exception:
        # Nunca rompemos una factura ya emitida por fallas accesorias de auditoría.
        pass


def arca_storage_signed_url(path: str, expires_seconds: Optional[int] = None) -> Dict[str, Any]:
    """Devuelve una URL firmada para un PDF en AWS S3 sin hacer publico el bucket.

    Es una URL bearer/no indexable: cualquiera con el link puede verla mientras no venza,
    pero el bucket sigue privado. Para Tienda Nube necesitamos un link alcanzable desde afuera.
    """
    path = str(path or "").strip().lstrip("/")
    if not ARCA_PDF_S3_BUCKET:
        return {"ok": False, "reason": "ARCA_PDF_S3_BUCKET no configurado"}
    if not path:
        return {"ok": False, "reason": "path vacío"}
    ttl = int(expires_seconds or ARCA_TN_SIGNED_URL_SECONDS or 315360000)
    try:
        url = arca_s3_client().generate_presigned_url(
            "get_object",
            Params={"Bucket": ARCA_PDF_S3_BUCKET, "Key": path},
            ExpiresIn=ttl,
        )
        if not url:
            return {"ok": False, "bucket": ARCA_PDF_S3_BUCKET, "path": path, "expires_seconds": ttl, "reason": "AWS S3 no devolvio signed URL"}
        return {"ok": True, "bucket": ARCA_PDF_S3_BUCKET, "path": path, "expires_seconds": ttl, "url": url, "provider": "aws_s3"}
    except Exception as e:
        return {"ok": False, "bucket": ARCA_PDF_S3_BUCKET, "path": path, "expires_seconds": ttl, "provider": "aws_s3", "error": str(e)}


def arca_send_email_with_pdf(to_email: str, invoice: Dict[str, Any], pdf_bytes: bytes) -> Dict[str, Any]:
    to_email = str(to_email or "").strip()
    if not to_email:
        return {"ok": False, "skipped": True, "reason": "cliente sin email"}
    if not SMTP_HOST or not SMTP_FROM:
        return {"ok": False, "skipped": True, "reason": "SMTP no configurado"}
    try:
        import smtplib
        from email.message import EmailMessage
        msg = EmailMessage()
        nro = f"{str(invoice.get('pto_vta') or ARCA_PTO_VTA).zfill(4)}-{str(invoice.get('cbte_nro') or '').zfill(8)}"
        msg["From"] = SMTP_FROM
        msg["To"] = to_email
        msg["Subject"] = f"Factura {invoice.get('cbte_letra') or ''} {nro} - Planeta Casa"
        msg.set_content(
            "Hola, adjuntamos el comprobante fiscal correspondiente a tu compra.\n\n"
            "Muchas gracias.\nPlaneta Casa\n"
        )
        msg.add_attachment(pdf_bytes, maintype="application", subtype="pdf", filename=arca_invoice_filename(invoice))
        with smtplib.SMTP(SMTP_HOST, SMTP_PORT, timeout=30) as smtp:
            if SMTP_TLS:
                smtp.starttls()
            if SMTP_USER:
                smtp.login(SMTP_USER, SMTP_PASSWORD)
            smtp.send_message(msg)
        return {"ok": True, "to": to_email}
    except Exception as e:
        return {"ok": False, "to": to_email, "error": str(e)}


def arca_ml_pack_or_order_id_for_invoice(invoice: Dict[str, Any]) -> str:
    """Devuelve el ID que requiere ML para /packs/{id}/fiscal_documents.

    Documentación ML: si pack_id es null, usar order_id manteniendo el recurso /packs.
    Para packs reales usamos source_pack_id; para ventas simples source_order_id/source_order_api_id.
    """
    raw = invoice.get("raw_data") if isinstance(invoice.get("raw_data"), dict) else {}
    source_meta = raw.get("source_meta") if isinstance(raw.get("source_meta"), dict) else {}
    candidates = [
        invoice.get("source_pack_id"),
        source_meta.get("source_pack_id"),
        invoice.get("source_order_id"),
        invoice.get("source_order_api_id"),
        source_meta.get("source_order_id"),
        source_meta.get("source_order_api_id"),
    ]
    for c in candidates:
        v = str(c or "").strip()
        if v and v.lower() not in ["none", "null"]:
            return v
    return ""


def arca_ml_parse_json_response(r: requests.Response) -> Any:
    try:
        return r.json()
    except Exception:
        return r.text[:3000]


def arca_ml_get_fiscal_documents(pack_or_order_id: str) -> Dict[str, Any]:
    """Consulta documentos fiscales ya cargados en ML para un pack/order.
    Usado para idempotencia cuando ML responde 409 por factura ya existente.
    """
    if not ML_ACCESS_TOKEN and not ml_can_refresh():
        return {"ok": False, "skipped": True, "reason": "ML_ACCESS_TOKEN o refresh no configurado"}
    url = f"https://api.mercadolibre.com/packs/{pack_or_order_id}/fiscal_documents"

    def do_get() -> requests.Response:
        return requests.get(url, headers={"Authorization": f"Bearer {ML_ACCESS_TOKEN}"}, timeout=45)

    try:
        r = do_get()
        if r.status_code == 401 and ml_can_refresh():
            ml_refresh_access_token()
            r = do_get()
        parsed = arca_ml_parse_json_response(r)
        return {
            "ok": 200 <= r.status_code < 300,
            "status_code": r.status_code,
            "pack_or_order_id": pack_or_order_id,
            "url_used": url,
            "response": parsed,
        }
    except Exception as e:
        return {"ok": False, "pack_or_order_id": pack_or_order_id, "url_used": url, "error": str(e)}


# XELERIA_ML_INVOICE_UPLOAD_MULTITENANT_V1
def arca_ml_tenant_credentials(invoice: Dict[str, Any]) -> Dict[str, Any]:
    tenant_id = str(invoice.get("tenant_id") or get_effective_tenant_id() or "").strip()
    if not tenant_id:
        raise HTTPException(status_code=400, detail="No se pudo determinar tenant para subir factura a ML")
    if not _sb_raw:
        raise HTTPException(status_code=500, detail="DATABASE_URL/AWS Postgres no configurado")
    from xeleria_tenant_context import get_channel_token
    row = get_channel_token(_sb_raw, tenant_id, "ml") or {}
    access = str(row.get("access_token") or row.get("token") or "").strip()
    refresh = str(row.get("refresh_token") or "").strip()
    if not access and not refresh:
        raise HTTPException(status_code=400, detail="El tenant no tiene Mercado Libre conectado")
    return {"tenant_id": tenant_id, "access_token": access, "refresh_token": refresh, "token_row": row}


def arca_ml_refresh_tenant_credentials(credentials: Dict[str, Any]) -> Dict[str, Any]:
    tenant_id = str(credentials.get("tenant_id") or "").strip()
    refresh_token = str(credentials.get("refresh_token") or "").strip()
    if not refresh_token:
        raise HTTPException(status_code=401, detail="ML devolvió 401 y el tenant no tiene refresh_token")
    if not ML_CLIENT_ID or not ML_CLIENT_SECRET:
        raise HTTPException(status_code=500, detail="Faltan credenciales de la app ML para refrescar OAuth")
    r = requests.post("https://api.mercadolibre.com/oauth/token", data={"grant_type":"refresh_token","client_id":ML_CLIENT_ID,"client_secret":ML_CLIENT_SECRET,"refresh_token":refresh_token}, headers={"accept":"application/json","content-type":"application/x-www-form-urlencoded"}, timeout=45)
    try:
        body = r.json()
    except Exception:
        body = {"raw": r.text[:2000]}
    if r.status_code not in (200, 201) or not body.get("access_token"):
        raise HTTPException(status_code=502, detail={"message":"ML refresh token del tenant falló","status_code":r.status_code,"response":body})
    token_row = dict(credentials.get("token_row") or {})
    provider = str(token_row.get("provider") or token_row.get("matched_provider") or f"ml:{tenant_id}")
    payload = {"tenant_id":tenant_id,"provider":provider,"access_token":body.get("access_token"),"refresh_token":body.get("refresh_token") or refresh_token,"expires_at":(_utcnow()+timedelta(seconds=int(body.get("expires_in") or 21600))).isoformat(),"updated_at":_utcnow().isoformat()}
    if token_row.get("id"):
        _sb_raw.table("api_tokens").update(payload).eq("id", token_row.get("id")).eq("tenant_id", tenant_id).execute()
    else:
        existing = _sb_raw.table("api_tokens").select("id").eq("tenant_id", tenant_id).eq("provider", provider).limit(1).execute().data or []
        if existing:
            _sb_raw.table("api_tokens").update(payload).eq("id", existing[0].get("id")).eq("tenant_id", tenant_id).execute()
        else:
            _sb_raw.table("api_tokens").insert(payload).execute()
    return {"tenant_id":tenant_id,"access_token":payload["access_token"],"refresh_token":payload["refresh_token"],"token_row":{**token_row,**payload}}


def arca_ml_get_fiscal_documents_tenant(
    pack_or_order_id: str,
    tenant_id: Optional[str] = None,
) -> Dict[str, Any]:
    """Consulta documentos fiscales de ML con OAuth del tenant.

    Un 404 es una respuesta valida: significa que el pack no tiene documento.
    Cualquier falla de autenticacion o red queda como no verificada para bloquear
    una eventual emision duplicada.
    """
    source_id = str(pack_or_order_id or "").strip()
    if not source_id:
        return {"ok": False, "reason": "pack_or_order_id_missing"}

    credentials = arca_ml_tenant_credentials({
        "tenant_id": str(tenant_id or get_effective_tenant_id() or "").strip(),
    })
    url = f"https://api.mercadolibre.com/packs/{source_id}/fiscal_documents"

    def do_get(token: str) -> requests.Response:
        return requests.get(
            url,
            headers={"Authorization": f"Bearer {token}"},
            timeout=45,
        )

    try:
        response = do_get(credentials.get("access_token") or "")
        refreshed = False
        if response.status_code == 401:
            credentials = arca_ml_refresh_tenant_credentials(credentials)
            refreshed = True
            response = do_get(credentials.get("access_token") or "")

        parsed = arca_ml_parse_json_response(response)
        normalized = normalize_ml_fiscal_documents_response(response.status_code, parsed)
        normalized.update({
            "pack_or_order_id": source_id,
            "token_refreshed": refreshed,
        })
        if not normalized.get("ok"):
            normalized["error"] = str(parsed)[:1000]
        return normalized
    except Exception as exc:
        return {
            "ok": False,
            "present": None,
            "pack_or_order_id": source_id,
            "error": str(exc)[:1000],
        }


def arca_ml_check_order_fiscal_documents(row: Dict[str, Any]) -> Dict[str, Any]:
    raw = row_raw_dict(row or {})
    pack_or_order_id = str(
        raw.get("ml_pack_id")
        or raw.get("ml_order_id")
        or (row or {}).get("external_order_id")
        or ""
    ).strip()
    result = arca_ml_get_fiscal_documents_tenant(pack_or_order_id)
    marker = {
        "checked_at": now_iso(),
        "present": result.get("present"),
        "document_count": int(result.get("document_count") or 0),
        "status_code": result.get("status_code"),
        "pack_or_order_id": pack_or_order_id,
    }
    result["marker"] = marker
    if result.get("ok"):
        arca_update_order_diagnostics(
            row,
            updates={"ml_fiscal_documents_check": marker},
        )
    return result


def arca_ml_upload_invoice_pdf(invoice: Dict[str, Any], pdf_bytes: bytes) -> Dict[str, Any]:
    """Sube PDF fiscal a ML usando exclusivamente OAuth del tenant dueño."""
    pack_or_order_id = arca_ml_pack_or_order_id_for_invoice(invoice)
    if not pack_or_order_id:
        return {"ok":False,"skipped":True,"reason":"No hay source_pack_id/source_order_id para ML"}
    filename = arca_invoice_filename(invoice)
    size = len(pdf_bytes or b"")
    if size <= 0:
        return {"ok":False,"pack_or_order_id":pack_or_order_id,"reason":"PDF vacío"}
    if size > 1024*1024:
        return {"ok":False,"pack_or_order_id":pack_or_order_id,"pdf_size_bytes":size,"reason":"PDF supera máximo ML de 1 MB"}
    url = f"https://api.mercadolibre.com/packs/{pack_or_order_id}/fiscal_documents"
    credentials = arca_ml_tenant_credentials(invoice)
    def do_post(token: str) -> requests.Response:
        return requests.post(url, headers={"Authorization":f"Bearer {token}"}, files={"fiscal_document":(filename,pdf_bytes,"application/pdf")}, timeout=60)
    try:
        r = do_post(credentials.get("access_token") or "")
        refreshed = False
        if r.status_code == 401:
            credentials = arca_ml_refresh_tenant_credentials(credentials)
            refreshed = True
            r = do_post(credentials.get("access_token") or "")
        parsed = arca_ml_parse_json_response(r)
        ok = 200 <= r.status_code < 300
        result = {"ok":ok,"official_api":True,"multitenant":True,"tenant_id":credentials.get("tenant_id"),"token_provider":(credentials.get("token_row") or {}).get("provider") or (credentials.get("token_row") or {}).get("matched_provider"),"token_refreshed":refreshed,"status_code":r.status_code,"pack_or_order_id":pack_or_order_id,"url_used":url,"field":"fiscal_document","filename":filename,"pdf_size_bytes":size,"response":parsed}
        if ok and isinstance(parsed,dict):
            result["fiscal_document_ids"] = parsed.get("ids") or []
        if r.status_code == 409:
            check = requests.get(url, headers={"Authorization":f"Bearer {credentials.get('access_token') or ''}"}, timeout=45)
            existing = arca_ml_parse_json_response(check)
            result["existing_documents"] = {"status_code":check.status_code,"response":existing}
            docs = existing.get("fiscal_documents") if isinstance(existing,dict) else []
            if docs:
                result.update({"ok":True,"already_uploaded":True,"fiscal_documents":docs})
        return result
    except Exception as e:
        return {"ok":False,"official_api":True,"multitenant":True,"tenant_id":credentials.get("tenant_id") if isinstance(credentials,dict) else None,"pack_or_order_id":pack_or_order_id,"url_used":url,"filename":filename,"pdf_size_bytes":size,"error":str(e)}

def arca_invoice_customer_email(invoice: Dict[str, Any]) -> str:
    # Primero campo directo del borrador/factura.
    direct = pc_email_norm(invoice.get("customer_email"))
    if direct:
        return direct
    raw = invoice.get("raw_data") if isinstance(invoice.get("raw_data"), dict) else {}
    return pc_first_email(raw) or ""


def arca_tn_order_id_for_invoice(invoice: Dict[str, Any]) -> str:
    raw = invoice.get("raw_data") if isinstance(invoice.get("raw_data"), dict) else {}
    source_meta = raw.get("source_meta") if isinstance(raw.get("source_meta"), dict) else {}
    nested_source_meta = source_meta.get("source_meta") if isinstance(source_meta.get("source_meta"), dict) else {}
    candidates = [
        invoice.get("source_order_api_id"),
        source_meta.get("source_order_api_id"),
        invoice.get("source_order_id"),
        source_meta.get("source_order_id"),
        nested_source_meta.get("tn_order_id"),
    ]
    order_raw = raw.get("order") if isinstance(raw.get("order"), dict) else {}
    if isinstance(order_raw, dict):
        candidates.append(order_raw.get("external_order_id"))
        order_raw_data = order_raw.get("raw_data") if isinstance(order_raw.get("raw_data"), dict) else {}
        candidates.append(order_raw_data.get("tn_order_id"))
        tn_raw = order_raw_data.get("tn_raw") if isinstance(order_raw_data.get("tn_raw"), dict) else {}
        candidates.append(tn_raw.get("id"))
    for c in candidates:
        v = str(c or "").strip().lstrip("#")
        if v and v.lower() not in ["none", "null"] and v.isdigit():
            return v
    return ""


def arca_tn_invoice_key(invoice: Dict[str, Any]) -> str:
    letra = str(invoice.get("cbte_letra") or "B").strip() or "B"
    pto = str(invoice.get("pto_vta") or ARCA_PTO_VTA).zfill(4)
    nro = str(invoice.get("cbte_nro") or "").zfill(8)
    cae = str(invoice.get("cae") or "").strip()
    base = f"FAC-{letra}-{pto}-{nro}"
    return f"{base}-CAE-{cae}" if cae else base


def arca_tn_parse_metafield_value(value: Any) -> List[Dict[str, Any]]:
    if value is None:
        return []
    if isinstance(value, list):
        return [x for x in value if isinstance(x, dict)]
    try:
        parsed = json.loads(str(value or "[]"))
        if isinstance(parsed, list):
            return [x for x in parsed if isinstance(x, dict)]
    except Exception:
        pass
    return []


def arca_tn_metafield_get(order_id: str) -> Dict[str, Any]:
    if not TN_ORDERS_STORE_ID or not TN_TOKEN:
        return {"ok": False, "reason": "Faltan TN_USER_ID/TN_STORE_ID o TN_TOKEN"}
    url = f"https://api.tiendanube.com/v1/{TN_ORDERS_STORE_ID}/metafields/orders"
    params = {"per_page": 1, "owner_id": order_id, "namespace": "nfe", "key": "list", "fields": "id,value"}
    try:
        r = requests.get(url, headers=tn_headers(), params=params, timeout=45)
        parsed = arca_ml_parse_json_response(r)
        return {"ok": 200 <= r.status_code < 300, "status_code": r.status_code, "url_used": url, "params": params, "response": parsed}
    except Exception as e:
        return {"ok": False, "url_used": url, "params": params, "error": str(e)}


def arca_tn_metafield_upsert(order_id: str, invoice_entry: Dict[str, Any]) -> Dict[str, Any]:
    current = arca_tn_metafield_get(order_id)
    if not current.get("ok"):
        return {"ok": False, "step": "get_metafield", "order_id": order_id, "current": current}

    response = current.get("response")
    existing = response[0] if isinstance(response, list) and response else None
    entries: List[Dict[str, Any]] = []
    metafield_id = None
    if isinstance(existing, dict):
        metafield_id = existing.get("id")
        entries = arca_tn_parse_metafield_value(existing.get("value"))

    key = str(invoice_entry.get("key") or "").strip()
    entries = [e for e in entries if str(e.get("key") or "").strip() != key]
    entries.append(invoice_entry)
    value = json.dumps(entries, ensure_ascii=False)

    if metafield_id:
        url = f"https://api.tiendanube.com/v1/{TN_ORDERS_STORE_ID}/metafields/{metafield_id}"
        payload = {"value": value, "description": "Lista de comprobantes fiscales"}
        method = "PUT"
        req = requests.put
    else:
        url = f"https://api.tiendanube.com/v1/{TN_ORDERS_STORE_ID}/metafields"
        payload = {
            "namespace": "nfe",
            "key": "list",
            "value": value,
            "description": "Lista de comprobantes fiscales",
            "owner_resource": "Order",
            "owner_id": order_id,
        }
        method = "POST"
        req = requests.post
    try:
        r = req(url, headers=tn_headers(), data=json.dumps(payload), timeout=45)
        parsed = arca_ml_parse_json_response(r)
        return {
            "ok": 200 <= r.status_code < 300,
            "method": method,
            "status_code": r.status_code,
            "order_id": order_id,
            "metafield_id": metafield_id,
            "url_used": url,
            "entry_key": key,
            "entries_count": len(entries),
            "response": parsed,
        }
    except Exception as e:
        return {"ok": False, "method": method, "order_id": order_id, "url_used": url, "entry_key": key, "error": str(e)}


def arca_tn_upload_invoice_metafield(invoice: Dict[str, Any], storage_result: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
    """Asocia factura emitida a una orden TN usando el formato oficial nfe/list.

    No hace publico el bucket: genera signed URL larga de S3 y guarda ese link
    en el metafield de TN.
    """
    if not TN_ORDERS_STORE_ID or not TN_TOKEN:
        return {"ok": False, "skipped": True, "reason": "Faltan TN_USER_ID/TN_STORE_ID o TN_TOKEN"}
    order_id = arca_tn_order_id_for_invoice(invoice)
    if not order_id:
        return {"ok": False, "skipped": True, "reason": "No hay ID API de orden TN para metafield"}

    storage = storage_result if isinstance(storage_result, dict) else {}
    path = str(storage.get("path") or arca_pdf_storage_path(invoice)).strip()
    signed = arca_storage_signed_url(path)
    if not signed.get("ok"):
        return {"ok": False, "order_id": order_id, "step": "signed_url", "signed_url": {k: v for k, v in signed.items() if k != "url"}}

    entry = {
        "key": arca_tn_invoice_key(invoice),
        "link": signed.get("url"),
    }
    upsert = arca_tn_metafield_upsert(order_id, entry)
    return {
        "ok": bool(upsert.get("ok")),
        "official_format": "nfe/list",
        "privacy": "bucket_privado_signed_url",
        "order_id": order_id,
        "entry_key": entry.get("key"),
        "pdf_path": path,
        "signed_url_expires_seconds": signed.get("expires_seconds"),
        "metafield": upsert,
    }


def arca_after_issue_dispatch(invoice: Dict[str, Any]) -> Dict[str, Any]:
    """Genera PDF y ejecuta la acción post-emisión correspondiente al canal.

    Es idempotente y no debe romper la emisión fiscal ya realizada.
    """
    dispatch: Dict[str, Any] = {
        "ok": True,
        "version": APP_VERSION,
        "at": now_iso(),
        "invoice_id": invoice.get("id"),
        "source_channel": invoice.get("source_channel"),
        "source_order_id": invoice.get("source_order_id"),
        "source_pack_id": invoice.get("source_pack_id"),
    }
    try:
        pdf = arca_invoice_pdf_bytes(invoice)
        dispatch["pdf_generated"] = True
        dispatch["pdf_size_bytes"] = len(pdf)
        dispatch["filename"] = arca_invoice_filename(invoice)
        dispatch["storage"] = arca_store_invoice_pdf(invoice, pdf)
        ch = str(invoice.get("source_channel") or "").upper()
        if ch == "ML":
            dispatch["channel_action"] = "ml_upload_invoice_pdf"
            dispatch["ml_upload"] = arca_ml_upload_invoice_pdf(invoice, pdf)
        elif ch == "TN":
            dispatch["channel_action"] = "tn_upload_invoice_metafield"
            dispatch["tn_invoice_metafield"] = arca_tn_upload_invoice_metafield(invoice, dispatch.get("storage"))
        elif ch in ["MANUAL", "ARCA_MANUAL"]:
            dispatch["channel_action"] = "email_invoice_pdf"
            dispatch["email"] = arca_send_email_with_pdf(arca_invoice_customer_email(invoice), invoice, pdf)
        else:
            dispatch["channel_action"] = "none"
            dispatch["note"] = "Canal sin acción post-emisión configurada"
    except Exception as e:
        dispatch["ok"] = False
        dispatch["error"] = str(e)
    if invoice.get("id"):
        arca_update_invoice_raw_dispatch(invoice.get("id"), dispatch)
    return dispatch


# XELERIA_ARCA_INVOICE_VIEW_SESSION_V200
# Lectura segura de comprobantes desde la sesión SaaS del tenant. Conserva ADMIN_TOKEN
# únicamente como compatibilidad legacy/debug.
def arca_invoice_for_request(
    invoice_id: str,
    request: Request,
    session_token: Optional[str] = None,
    x_session_token: Optional[str] = None,
    authorization: Optional[str] = None,
    token: Optional[str] = None,
    x_admin_token: Optional[str] = None,
) -> Dict[str, Any]:
    auth = arca_session_or_admin_auth(
        request,
        session_token=session_token,
        x_session_token=x_session_token,
        authorization=authorization,
        token=token,
        x_admin_token=x_admin_token,
    )
    tenant_id = str((auth or {}).get("tenant_id") or "").strip()
    if not tenant_id:
        raise HTTPException(status_code=401, detail="Sesión XelerIA sin tenant válido")
    ctx = set_current_tenant_id(tenant_id)
    try:
        return arca_get_invoice(invoice_id)
    finally:
        reset_current_tenant_id(ctx)


