@router.post("/admin/arca/facturas/{invoice_id}/tn_upload_metafield")
def arca_invoice_tn_upload_metafield_endpoint(
    invoice_id: str,
    token: Optional[str] = Query(default=None),
    x_admin_token: Optional[str] = Header(default=None),
):
    require_admin(token, x_admin_token)
    invoice = arca_get_invoice(invoice_id)
    if str(invoice.get("source_channel") or "").upper() != "TN":
        raise HTTPException(status_code=400, detail="La factura no corresponde a Tienda Nube.")
    if not invoice.get("cae"):
        raise HTTPException(status_code=400, detail="La factura todavía no tiene CAE; no se sube a TN.")
    # Reutiliza PDF ya guardado si existe; si no, lo genera/guarda antes de crear signed URL.
    raw = invoice.get("raw_data") if isinstance(invoice.get("raw_data"), dict) else {}
    dispatch = raw.get("post_issue_dispatch") if isinstance(raw.get("post_issue_dispatch"), dict) else {}
    storage = dispatch.get("storage") if isinstance(dispatch.get("storage"), dict) else None
    if not storage or not storage.get("ok"):
        pdf = arca_invoice_pdf_bytes(invoice)
        storage = arca_store_invoice_pdf(invoice, pdf)
    result = arca_tn_upload_invoice_metafield(invoice, storage)
    # Guardamos el resultado dentro del dispatch existente sin pisar la emisión.
    new_dispatch = dict(dispatch or {})
    new_dispatch.update({
        "ok": bool(result.get("ok")),
        "version": APP_VERSION,
        "at": now_iso(),
        "invoice_id": invoice.get("id"),
        "source_channel": invoice.get("source_channel"),
        "source_order_id": invoice.get("source_order_id"),
        "channel_action": "tn_upload_invoice_metafield",
        "storage": storage,
        "tn_invoice_metafield": result,
    })
    arca_update_invoice_raw_dispatch(invoice.get("id"), new_dispatch)
    return {"ok": bool(result.get("ok")), "result": result}


