@router.get("/admin/arca/orders/pending")
def arca_pending_orders_endpoint(
    channel: str = Query("ML"),
    hours: int = Query(48, ge=1, le=720),
    limit: int = Query(20, ge=1, le=100),
    token: Optional[str] = Query(default=None),
    x_admin_token: Optional[str] = Header(default=None),
):
    """Lista ventas pagas capturadas sin comprobante ARCA emitido."""
    require_admin(token, x_admin_token)
    rows = arca_find_pending_orders(channel=channel, hours=hours, limit=limit)
    items = []
    for row in rows:
        raw = row_raw_dict(row)
        payload = None
        preview_error = None
        try:
            payload = arca_build_invoice_payload(row, ArcaInvoiceDraftIn())
        except Exception as e:
            preview_error = pc_exception_detail(e)
        items.append({
            "channel": row.get("channel"),
            "erp_order_id": row.get("id"),
            "external_order_id": row.get("external_order_id"),
            "pack_id": raw.get("ml_pack_id"),
            "ml_order_id": raw.get("ml_order_id"),
            "customer_name": row.get("customer_name"),
            "total": row.get("total"),
            "created_at": row.get("created_at"),
            "invoice_key": arca_source_key_for_pending(row),
            "preview_error": preview_error,
            "invoice_preview": arca_preview_summary_from_payload(payload) if payload else None,
        })
    return {
        "ok": True,
        "version": APP_VERSION,
        "channel": norm_sku(channel).upper(),
        "hours": hours,
        "limit": limit,
        "count": len(items),
        "items": items,
    }


@router.post("/admin/arca/orders/pending/issue")
def arca_issue_pending_orders_endpoint(
    channel: str = Query("ML"),
    hours: int = Query(48, ge=1, le=720),
    limit: int = Query(20, ge=1, le=100),
    dry_run: bool = Query(True),
    confirmar: bool = Query(False),
    token: Optional[str] = Query(default=None),
    x_admin_token: Optional[str] = Header(default=None),
):
    """Factura ventas pendientes por lote.

    - dry_run=true: no emite, solo muestra qué facturaría.
    - dry_run=false&confirmar=true: emite CAE real y despacha PDF según canal.
    """
    require_admin(token, x_admin_token)
    rows = arca_find_pending_orders(channel=channel, hours=hours, limit=limit)
    items = []
    issued = 0
    errors = 0

    if not dry_run and not confirmar:
        raise HTTPException(status_code=400, detail="Para emitir pendientes debe venir dry_run=false y confirmar=true")
    if not dry_run and not ARCA_EMIT_ENABLED:
        raise HTTPException(status_code=400, detail="ARCA_EMIT_ENABLED=false. Emisión real bloqueada por seguridad.")

    for row in rows:
        raw = row_raw_dict(row)
        source_id = str(raw.get("ml_pack_id") or row.get("external_order_id") or row.get("id"))
        item = {
            "channel": row.get("channel"),
            "erp_order_id": row.get("id"),
            "external_order_id": row.get("external_order_id"),
            "pack_id": raw.get("ml_pack_id"),
            "source_id_used": source_id,
            "customer_name": row.get("customer_name"),
            "total": row.get("total"),
            "created_at": row.get("created_at"),
        }
        try:
            if dry_run:
                payload = arca_build_invoice_payload(row, ArcaInvoiceDraftIn())
                item["action"] = "dry_run_preview"
                item["invoice_preview"] = arca_preview_summary_from_payload(payload)
            else:
                res = arca_issue_order_core(row.get("channel") or channel, source_id, ArcaInvoiceDraftIn(), allow_existing=True)
                item["action"] = "issued" if res.get("ok") and not res.get("duplicate") else "already_issued"
                item["result"] = res
                if res.get("ok") and not res.get("duplicate"):
                    issued += 1
            items.append(item)
        except Exception as e:
            errors += 1
            item["action"] = "error"
            item["error"] = pc_exception_detail(e)
            items.append(item)

    return {
        "ok": errors == 0,
        "version": APP_VERSION,
        "dry_run": dry_run,
        "confirmar": confirmar,
        "channel": norm_sku(channel).upper(),
        "hours": hours,
        "limit": limit,
        "found_pending": len(rows),
        "issued": issued,
        "errors": errors,
        "items": items,
    }


