@router.get("/admin/arca/status")
def arca_status_endpoint(
    token: Optional[str] = Query(default=None),
    x_admin_token: Optional[str] = Header(default=None),
):
    """Diagnóstico ARCA seguro: no emite, no hace WSAA, no muestra secretos."""
