@router.get("/admin/arca/ultimo")
def arca_ultimo_endpoint(
    tipo: int = Query(6, description="Tipo de comprobante ARCA: 1=Factura A, 6=Factura B"),
    token: Optional[str] = Query(default=None),
    x_admin_token: Optional[str] = Header(default=None),
):
    """Consulta FECompUltimoAutorizado en WSFE. No emite comprobantes."""
    require_admin(token, x_admin_token)
    if tipo not in [1, 6, 11]:
        raise HTTPException(status_code=400, detail="Tipo no soportado en este test. Usar 1=Factura A, 6=Factura B o 11=Factura C.")
    ready = arca_ws_ready()
    if not ready.get("ready"):
        raise HTTPException(status_code=400, detail={"error": "ARCA no está listo", "ready": ready})

    ultimo = arca_wsfe_last_voucher(int(tipo))
    return {
        "ok": True,
        "version": APP_VERSION,
        "environment": ARCA_ENV,
        "is_production": arca_env_is_prod(),
        "pto_vta": ARCA_PTO_VTA,
        "cbte_tipo": int(tipo),
        "ultimo": ultimo,
        "proximo": ultimo + 1,
        "emit_enabled": ARCA_EMIT_ENABLED,
        "auto_invoice_enabled": ARCA_AUTO_INVOICE_ENABLED,
        "nota": "Consulta segura: FECompUltimoAutorizado. No emite comprobantes.",
    }



