@router.post("/admin/arca/emitir_test")
def arca_emitir_test_endpoint(
    body: Optional[ArcaEmitirTestIn] = None,
    token: Optional[str] = Query(default=None),
    x_admin_token: Optional[str] = Header(default=None),
):
    """Emisión manual controlada.

    - dry_run=true: solo arma payload y consulta próximo número. No emite.
    - dry_run=false + confirmar=true: emite CAE real si ARCA_EMIT_ENABLED=true.
    - ARCA_AUTO_INVOICE_ENABLED no interviene: esto es manual.
    """
    require_admin(token, x_admin_token)
    body = body or ArcaEmitirTestIn()
    ready = arca_ws_ready()
    if not ready.get("ready"):
        raise HTTPException(status_code=400, detail={"error": "ARCA no está listo", "ready": ready})

    payload = arca_build_manual_test_payload(body)
    ultimo = arca_wsfe_last_voucher(int(payload["cbte_tipo"]))
    proximo = ultimo + 1

    preview = {
        "ok": True,
        "version": APP_VERSION,
        "dry_run": bool(body.dry_run),
        "confirmar": bool(body.confirmar),
        "environment": ARCA_ENV,
        "is_production": arca_env_is_prod(),
        "emit_enabled": ARCA_EMIT_ENABLED,
        "auto_invoice_enabled": ARCA_AUTO_INVOICE_ENABLED,
        "pto_vta": ARCA_PTO_VTA,
        "cbte_tipo": payload.get("cbte_tipo"),
        "cbte_letra": payload.get("cbte_letra"),
        "ultimo": ultimo,
        "proximo": proximo,
        "importe_total": payload.get("importe_total"),
        "importe_neto": payload.get("importe_neto"),
        "importe_iva": payload.get("importe_iva"),
        "customer_name": payload.get("customer_name"),
        "customer_doc_type": payload.get("customer_doc_type"),
        "customer_doc_number": payload.get("customer_doc_number"),
        "lines": payload.get("lines"),
        "payload": payload,
    }

    if body.dry_run or not body.confirmar:
        preview["nota"] = "PREVIEW: no emitió. Para emitir real: dry_run=false y confirmar=true."
        return preview

    if not ARCA_EMIT_ENABLED:
        raise HTTPException(status_code=400, detail="ARCA_EMIT_ENABLED=false. Emisión real bloqueada por seguridad.")

    wsfe = arca_wsfe_issue_cae(payload)
    payload.update({
        "environment": "produccion",
        "env": "produccion",
        "cuit_emisor": wsfe.get("cuit_emisor") or payload.get("cuit_emisor"),
        "pto_vta": wsfe.get("pto_vta") or payload.get("pto_vta"),
        "status": "issued",
        "cbte_nro": wsfe.get("cbte_nro"),
        "cae": wsfe.get("cae"),
        "cae_vto": wsfe.get("cae_vto"),
        "resultado": wsfe.get("resultado"),
        "updated_at": now_iso(),
    })
    payload.setdefault("raw_data", {})
    payload["raw_data"]["wsfe"] = wsfe
    payload["raw_data"]["issued_at"] = now_iso()

    save_result = None
    save_error = None
    try:
        save_result = arca_save_issued_invoice(payload)
    except Exception as e:
        # La factura ya pudo haberse emitido en ARCA. No ocultamos el CAE por una falla de guardado local.
        save_error = str(e)

    return {
        "ok": True,
        "version": APP_VERSION,
        "emitted": True,
        "environment": ARCA_ENV,
        "is_production": arca_env_is_prod(),
        "pto_vta": ARCA_PTO_VTA,
        "cbte_tipo": payload.get("cbte_tipo"),
        "cbte_letra": payload.get("cbte_letra"),
        "cbte_nro": wsfe.get("cbte_nro"),
        "cae": wsfe.get("cae"),
        "cae_vto": wsfe.get("cae_vto"),
        "resultado": wsfe.get("resultado"),
        "importe_total": payload.get("importe_total"),
        "invoice": (save_result or {}).get("invoice") if isinstance(save_result, dict) else None,
        "save_result": save_result,
        "save_error": save_error,
        "wsfe": wsfe,
        "nota": "EMISIÓN REAL REALIZADA. Verificar en ARCA.",
    }


