def arca_session_or_admin_auth(
    request: Request,
    session_token: Optional[str] = None,
    x_session_token: Optional[str] = None,
    authorization: Optional[str] = None,
    token: Optional[str] = None,
    x_admin_token: Optional[str] = None,
) -> Dict[str, Any]:
    """Mismo patrón probado en /admin/arca/check: sesión XelerIA primero, admin legacy al final."""
    session = getattr(getattr(request, "state", None), "xeleria_session", None)
    if isinstance(session, dict) and session.get("tenant_id"):
        return session

    try:
        session = require_session(request, session_token, x_session_token, authorization)
        if isinstance(session, dict) and session.get("tenant_id"):
            try:
                request.state.xeleria_session = dict(session)
            except Exception:
                pass
            return session
    except HTTPException:
        if not (token or x_admin_token):
            raise

    require_admin(token, x_admin_token)
    return {"tenant_id": get_effective_tenant_id(), "admin": True}


@router.post("/admin/arca/orders/{channel}/{order_id}/issue")
def arca_order_issue_endpoint(
    channel: str,
    order_id: str,
    request: Request,
    background_tasks: BackgroundTasks,
    body: Optional[ArcaInvoiceDraftIn] = None,
    session_token: Optional[str] = Query(default=None),
    x_session_token: Optional[str] = Header(default=None),
    authorization: Optional[str] = Header(default=None),
    token: Optional[str] = Query(default=None),
    x_admin_token: Optional[str] = Header(default=None),
):
    # XELERIA_ARCA_ISSUE_NETWORK_DETAIL_V195
    # La respuesta termina al guardar CAE/factura. PDF y carga al canal van en background.
    auth = arca_session_or_admin_auth(
        request,
        session_token=session_token,
        x_session_token=x_session_token,
        authorization=authorization,
        token=token,
        x_admin_token=x_admin_token,
    )

    tenant_id = str((auth or {}).get("tenant_id") or "").strip()
    if not tenant_id:
        raise HTTPException(
            status_code=401,
            detail="Sesión XelerIA sin tenant válido",
        )

    tenant_ctx = set_current_tenant_id(tenant_id)
    try:
        result = arca_issue_order_core(
            channel,
            order_id,
            body or ArcaInvoiceDraftIn(),
            allow_existing=True,
            run_post_issue_dispatch=False,
        )
        invoice = result.get("invoice") if isinstance(result, dict) else None
        if (
            isinstance(invoice, dict)
            and invoice.get("cae")
            and not result.get("duplicate")
        ):
            background_tasks.add_task(
                arca_after_issue_dispatch_for_tenant,
                tenant_id,
                dict(invoice),
            )
        return result
    except HTTPException:
        raise
    except Exception as exc:
        # Evita que una excepción sin manejar se convierta en "Failed to fetch"
        # por una respuesta 500 sin detalle/CORS en el navegador.
        raise HTTPException(
            status_code=500,
            detail={
                "ok": False,
                "error": "Error inesperado al emitir la factura",
                "stage": "issue_endpoint",
                "exception_type": exc.__class__.__name__,
                "message": str(exc),
            },
        )
    finally:
        reset_current_tenant_id(tenant_ctx)


@router.post("/admin/arca/orders/{channel}/{order_id}/recover-issued")
def arca_order_recover_issued_endpoint(
    channel: str,
    order_id: str,
    body: ArcaRecoverIssuedIn,
    request: Request,
    session_token: Optional[str] = Query(default=None),
    x_session_token: Optional[str] = Header(default=None),
    authorization: Optional[str] = Header(default=None),
    token: Optional[str] = Query(default=None),
    x_admin_token: Optional[str] = Header(default=None),
):
    """Reconcilia una venta con un comprobante existente en ARCA, sin emitir."""
    auth = arca_session_or_admin_auth(
        request,
        session_token=session_token,
        x_session_token=x_session_token,
        authorization=authorization,
        token=token,
        x_admin_token=x_admin_token,
    )
    tenant_id = str((auth or {}).get("tenant_id") or "").strip()
    if not tenant_id:
        raise HTTPException(status_code=401, detail="Sesion XelerIA sin tenant valido")
    if not body.confirmar:
        raise HTTPException(
            status_code=400,
            detail="La recuperacion requiere confirmar=true. No se emitio ningun comprobante.",
        )
    if int(body.cbte_tipo) not in (1, 6):
        raise HTTPException(status_code=400, detail="cbte_tipo debe ser 1 o 6")

    tenant_ctx = set_current_tenant_id(tenant_id)
    try:
        row = arca_get_order(channel, order_id)
        existing = arca_existing_invoice_for_order(row)
        if existing and existing.get("cae"):
            return {
                "ok": True,
                "recovered": False,
                "duplicate": True,
                "invoice": existing,
                "message": "La venta ya tiene un comprobante registrado.",
            }

        operation_id = str(uuid.uuid4())
        payload = arca_build_invoice_payload(row, ArcaInvoiceDraftIn())
        marker = build_recovery_marker(
            payload,
            {
                "cbte_tipo": int(body.cbte_tipo),
                "cbte_nro": int(body.cbte_nro),
                "pto_vta": int(payload.get("pto_vta") or 0),
            },
            operation_id,
            now_iso(),
            reason="manual_reconcile_existing_arca_voucher",
        )
        marker_write = arca_update_order_diagnostics(
            row,
            updates={"arca_recovery_pending": marker},
        )
        if not marker_write.get("persisted"):
            raise HTTPException(
                status_code=500,
                detail={
                    "ok": False,
                    "critical": True,
                    "stage": "persist_recovery_marker",
                    "error": "No se pudo bloquear la venta antes de consultar ARCA",
                    "instruction": "No se emitio ningun comprobante.",
                },
            )

        result = arca_issue_order_core(
            channel,
            order_id,
            ArcaInvoiceDraftIn(),
            allow_existing=True,
            run_post_issue_dispatch=False,
        )
        result["reconciliation_requested"] = True
        result["message"] = "Comprobante recuperado desde ARCA sin volver a emitir."
        return result
    finally:
        reset_current_tenant_id(tenant_ctx)


@router.get("/admin/migration/table-stats")
def migration_table_stats_endpoint(
    request: Request,
    table: Optional[str] = Query(default=None),
    include_digest: bool = Query(default=False),
    session_token: Optional[str] = Query(default=None),
    x_session_token: Optional[str] = Header(default=None),
    authorization: Optional[str] = Header(default=None),
    token: Optional[str] = Query(default=None),
    x_admin_token: Optional[str] = Header(default=None),
):
    """Exact read-only statistics for migration verification.

    Counts all tables quickly. A full content hash is available only for one
    explicitly selected table, keeping production load bounded. Row contents
    are never returned.
    """
    auth = arca_session_or_admin_auth(
        request,
        session_token=session_token,
        x_session_token=x_session_token,
        authorization=authorization,
        token=token,
        x_admin_token=x_admin_token,
    )
    tenant_id = str((auth or {}).get("tenant_id") or "").strip()
    if not tenant_id:
        raise HTTPException(status_code=401, detail="Sesion XelerIA sin tenant valido")
    if not DATABASE_URL:
        raise HTTPException(status_code=500, detail="DATABASE_URL/AWS Postgres no configurado")

    import psycopg
    from psycopg import sql as pg_sql
    from psycopg.rows import dict_row

    stats = []
    with psycopg.connect(DATABASE_URL, row_factory=dict_row) as conn:
        with conn.cursor() as cur:
            cur.execute("set transaction read only")
            cur.execute("set local statement_timeout = '120s'")
            cur.execute(
                """
                select t.table_name, c.column_name, c.ordinal_position
                from information_schema.tables t
                left join information_schema.columns c
                  on c.table_schema=t.table_schema and c.table_name=t.table_name
                where t.table_schema='public' and t.table_type='BASE TABLE'
                order by t.table_name, c.ordinal_position
                """
            )
            columns_by_table: Dict[str, List[str]] = {}
            for item in cur.fetchall():
                table_name = str(item.get("table_name") or "")
                column_name = str(item.get("column_name") or "")
                if table_name:
                    columns_by_table.setdefault(table_name, [])
                    if column_name:
                        columns_by_table[table_name].append(column_name)

            cur.execute(
                """
                select tc.table_name, array_agg(kcu.column_name order by kcu.ordinal_position) as pk_columns
                from information_schema.table_constraints tc
                join information_schema.key_column_usage kcu
                  on kcu.constraint_name=tc.constraint_name
                 and kcu.table_schema=tc.table_schema
                 and kcu.table_name=tc.table_name
                where tc.table_schema='public' and tc.constraint_type='PRIMARY KEY'
                group by tc.table_name
                """
            )
            primary_keys = {
                str(item.get("table_name")): list(item.get("pk_columns") or [])
                for item in cur.fetchall()
            }

            requested_table = str(table or "").strip()
            if requested_table and requested_table not in columns_by_table:
                raise HTTPException(status_code=404, detail="Tabla publica inexistente")
            if include_digest and not requested_table:
                raise HTTPException(
                    status_code=422,
                    detail="include_digest requiere seleccionar una tabla",
                )
            selected_tables = (
                {requested_table: columns_by_table[requested_table]}
                if requested_table
                else columns_by_table
            )

            time_priority = [
                "updated_at",
                "created_at",
                "imported_at",
                "saved_at",
                "finished_at",
                "invoice_date",
                "last_message_at",
            ]
            for table_name, columns in selected_tables.items():
                time_columns = [name for name in time_priority if name in columns]
                aggregates = [
                    pg_sql.SQL("count(*)::bigint as row_count"),
                ]
                if include_digest:
                    aggregates.append(pg_sql.SQL(
                        "md5(coalesce(string_agg(md5(to_jsonb(t)::text), ',' "
                        "order by md5(to_jsonb(t)::text)), '')) as content_digest"
                    ))
                for column_name in time_columns:
                    aggregates.append(
                        pg_sql.SQL("max({})::text as {}").format(
                            pg_sql.Identifier(column_name),
                            pg_sql.Identifier(column_name),
                        )
                    )
                query = pg_sql.SQL("select {} from {}.{} t").format(
                    pg_sql.SQL(", ").join(aggregates),
                    pg_sql.Identifier("public"),
                    pg_sql.Identifier(table_name),
                )
                cur.execute(query)
                row = dict(cur.fetchone() or {})
                stats.append({
                    "table_name": table_name,
                    "row_count": int(row.get("row_count") or 0),
                    "content_digest": row.get("content_digest") if include_digest else None,
                    "column_count": len(columns),
                    "primary_key": primary_keys.get(table_name) or [],
                    "latest": {
                        name: row.get(name)
                        for name in time_columns
                        if row.get(name) is not None
                    },
                })

    return {
        "ok": True,
        "version": APP_VERSION,
        "database": "xeleria_app",
        "scope": "public",
        "read_only": True,
        "include_digest": bool(include_digest),
        "table_filter": str(table or "").strip() or None,
        "table_count": len(stats),
        "generated_at": now_iso(),
        "tables": stats,
    }


