@router.post("/admin/bundles/component")
def add_bundle_component(
    req: BundleComponentIn,
    token: Optional[str] = Query(default=None),
    x_admin_token: Optional[str] = Header(default=None),
):
    require_admin(token, x_admin_token)

    bundle_sku = norm_sku(req.bundle_sku)
    component_sku = norm_sku(req.component_sku)

    if bundle_sku == component_sku:
        raise HTTPException(status_code=400, detail="Un combo no puede componerse de sí mismo")

    bundle = get_item_by_sku(bundle_sku)
    if not bundle:
        raise HTTPException(status_code=404, detail=f"No existe SKU combo: {bundle_sku}")

    component = get_item_by_sku(component_sku)
    component = require_simple_active_component(component, component_sku)

    existing = (
        sb.table("bundle_components")
        .select("*")
        .eq("bundle_item_id", bundle["id"])
        .eq("component_item_id", component["id"])
        .limit(1)
        .execute()
        .data
        or []
    )

    if existing:
        row_id = existing[0]["id"]
        sb.table("bundle_components").update({
            "quantity": req.quantity,
        }).eq("id", row_id).execute()
        action = "updated"
    else:
        sb.table("bundle_components").insert({
            "bundle_item_id": bundle["id"],
            "component_item_id": component["id"],
            "quantity": req.quantity,
            "created_at": now_iso(),
        }).execute()
        action = "inserted"

    mark_as_bundle_if_needed(bundle["id"])
    recalc = recalc_and_sync_bundle(bundle, dry_run=False)

    return {
        "ok": True,
        "action": action,
        "bundle_sku": bundle_sku,
        "component_sku": component_sku,
        "quantity": req.quantity,
        "recalc": recalc,
    }


@router.delete("/admin/bundles/component")
def delete_bundle_component(
    req: DeleteBundleComponentIn,
    token: Optional[str] = Query(default=None),
    x_admin_token: Optional[str] = Header(default=None),
):
    require_admin(token, x_admin_token)

    bundle = get_item_by_sku(req.bundle_sku)
    if not bundle:
        raise HTTPException(status_code=404, detail=f"No existe SKU combo: {req.bundle_sku}")

    component = get_item_by_sku(req.component_sku)
    if not component:
        raise HTTPException(status_code=404, detail=f"No existe SKU componente: {req.component_sku}")

    rows = (
        sb.table("bundle_components")
        .select("*")
        .eq("bundle_item_id", bundle["id"])
        .eq("component_item_id", component["id"])
        .execute()
        .data
        or []
    )

    if not rows:
        return {"ok": True, "deleted": 0, "message": "No había componente para eliminar"}

    for r in rows:
        sb.table("bundle_components").delete().eq("id", r["id"]).execute()

    recalc = recalc_and_sync_bundle(bundle, dry_run=False)

    return {
        "ok": True,
        "deleted": len(rows),
        "bundle_sku": req.bundle_sku,
        "component_sku": req.component_sku,
        "recalc": recalc,
    }


@router.post("/admin/bundles/{bundle_sku}/recalc")
def recalc_bundle_endpoint(
    bundle_sku: str,
    dry_run: bool = False,
    token: Optional[str] = Query(default=None),
    x_admin_token: Optional[str] = Header(default=None),
):
    require_admin(token, x_admin_token)
    bundle = get_item_by_sku(bundle_sku)
    if not bundle:
        raise HTTPException(status_code=404, detail=f"No existe SKU combo: {bundle_sku}")
    result = recalc_and_sync_bundle(bundle, dry_run=dry_run)
    return {"ok": True, "result": result}



# ============================================================
# MERCADO LIBRE FULL - ENVÍOS A BODEGA POR PDF
# ============================================================

def ml_full_inbound_extract_pdf_text(raw: bytes) -> str:
    """Extrae texto de PDF de instrucciones de preparación ML Full.

    Se importa opcionalmente para no romper el backend si la dependencia no está instalada
    hasta que se use esta función.
    """
    try:
        from pypdf import PdfReader
    except Exception as e:
        raise HTTPException(status_code=500, detail=f"Falta dependencia pypdf para leer PDF: {str(e)}")
    try:
        reader = PdfReader(io.BytesIO(raw))
        return "\n".join((page.extract_text() or "") for page in reader.pages)
    except Exception as e:
        raise HTTPException(status_code=400, detail=f"No pude leer el PDF: {str(e)}")


def ml_full_inbound_parse_pdf(raw: bytes, filename: str = "") -> Dict[str, Any]:
    text = ml_full_inbound_extract_pdf_text(raw)
    envio_m = re.search(r"Envío\s*#\s*(\d+)", text, re.IGNORECASE)
    shipment_id = envio_m.group(1) if envio_m else ""
    summary_m = re.search(r"Productos\s+del\s+envío:\s*(\d+)\s*\|\s*Total\s+de\s+unidades:\s*(\d+)", text, re.IGNORECASE)
    expected_products = int(summary_m.group(1)) if summary_m else None
    expected_units = int(summary_m.group(2)) if summary_m else None

    products: List[Dict[str, Any]] = []
    units: List[int] = []

    pages = re.split(r"(?=Código\s+ML:|Envío\s+#)", text)
    # Mejor por bloques de página lógica: tomamos grupos antes/después del encabezado PRODUCTO UNIDADES.
    chunks = re.split(r"PRODUCTO\s+UNIDADES\s+IDENTIFICACIÓN\s+INSTRUCCIONES\s+DE\s+PREPARACIÓN", text, flags=re.IGNORECASE)
    # El primer chunk contiene header + productos de página 1; los siguientes empiezan con unidades y luego productos de página siguiente.
    # Para preservar orden real, extraemos productos de todo el texto y unidades de cada bloque después del encabezado.
    pattern = re.compile(
        r"Código\s+ML:\s*(.*?)\s+Código\s+universal:\s*.*?SKU:\s*\n\s*([^\n]+)\s*\n(.*?)\n\s*Etiquetado",
        re.IGNORECASE | re.DOTALL,
    )
    for m in pattern.finditer(text):
        code = re.sub(r"\s+", "", str(m.group(1) or "")).strip()
        sku = norm_sku(m.group(2))
        name = re.sub(r"\s+", " ", str(m.group(3) or "")).strip()
        if sku:
            products.append({"ml_code": code, "sku": sku, "name": name})

    for part in re.split(r"PRODUCTO\s+UNIDADES\s+IDENTIFICACIÓN\s+INSTRUCCIONES\s+DE\s+PREPARACIÓN", text, flags=re.IGNORECASE)[1:]:
        # Cortar en el próximo Código ML para que no tome números del bloque de producto siguiente.
        unit_part = re.split(r"Código\s+ML:", part, maxsplit=1, flags=re.IGNORECASE)[0]
        for n in re.findall(r"(?m)^\s*(\d+)\b", unit_part):
            try:
                units.append(int(n))
            except Exception:
                pass

    items = []
    for idx, prod in enumerate(products):
        qty = units[idx] if idx < len(units) else None
        row = dict(prod)
        row["quantity"] = qty
        item = get_item_by_sku(row["sku"])
        row["exists"] = bool(item)
        row["inventory_item_id"] = item.get("id") if item else None
        row["old_stock"] = int(float(item.get("stock") or 0)) if item else None
        row["new_stock"] = (row["old_stock"] - int(qty)) if item and qty is not None else None
        row["insufficient_stock"] = bool(item and qty is not None and row["new_stock"] < 0)
        items.append(row)

    total_units = sum(int(x.get("quantity") or 0) for x in items)
    errors = []
    if expected_products is not None and expected_products != len(items):
        errors.append(f"El PDF declara {expected_products} productos pero detecté {len(items)}")
    if expected_units is not None and expected_units != total_units:
        errors.append(f"El PDF declara {expected_units} unidades pero detecté {total_units}")
    missing = [x["sku"] for x in items if not x.get("exists")]
    if missing:
        errors.append("SKUs no encontrados en inventario: " + ", ".join(missing[:20]))
    no_qty = [x["sku"] for x in items if x.get("quantity") is None]
    if no_qty:
        errors.append("SKUs sin cantidad detectada: " + ", ".join(no_qty[:20]))

    return {
        "ok": len(errors) == 0,
        "shipment_id": shipment_id,
        "filename": filename,
        "expected_products": expected_products,
        "expected_units": expected_units,
        "detected_products": len(items),
        "detected_units": total_units,
        "items": items,
        "errors": errors,
    }




def ml_full_inbound_existing_movements(shipment_id: Any) -> Dict[str, Any]:
    sid = str(shipment_id or "").strip()
    if not sid:
        return {"exists": False, "count": 0, "items": []}
    tenant_id = str(get_effective_tenant_id() or DEFAULT_TENANT_ID)
    try:
        resp = (
            sb.table("stock_movements")
            .select("id,sku,quantity,previous_stock,new_stock,created_at,notes")
            .eq("tenant_id", tenant_id)
            .eq("movement_type", "full_inbound")
            .eq("channel", "ML_FULL")
            .eq("reference_type", "ml_full_inbound_pdf")
            .eq("reference_id", sid)
            .limit(500)
            .execute()
        )
        items = resp.data or []
        return {"exists": len(items) > 0, "count": len(items), "items": items}
    except Exception as e:
        return {"exists": False, "count": 0, "items": [], "error": str(e)}


@router.post("/admin/ml/full-inbound/pdf/preview")
async def admin_ml_full_inbound_pdf_preview(
    request: Request,
    file: UploadFile = File(...),
    token: Optional[str] = Query(default=None),
    x_admin_token: Optional[str] = Header(default=None),
    x_session_token: Optional[str] = Header(default=None),
    session_token: Optional[str] = Query(default=None),
    authorization: Optional[str] = Header(default=None),
):
    session = _inventory_auth_session_or_admin(
        request,
        token,
        x_admin_token,
        x_session_token,
        session_token,
        authorization,
    )
    tenant_id = str(
        (session or {}).get("tenant_id")
        or tenant_id_from_request(request)
        or get_effective_tenant_id()
        or DEFAULT_TENANT_ID
    )
    set_current_tenant_id(tenant_id)
    raw = await file.read()
    parsed = ml_full_inbound_parse_pdf(raw, filename=file.filename or "full_inbound.pdf")
    return {"ok": True, "version": APP_VERSION, "tenant_id": tenant_id, "preview": parsed}


@router.post("/admin/ml/full-inbound/pdf/apply")
async def admin_ml_full_inbound_pdf_apply(
    request: Request,
    file: UploadFile = File(...),
    dry_run: bool = Query(default=True),
    token: Optional[str] = Query(default=None),
    x_admin_token: Optional[str] = Header(default=None),
    x_session_token: Optional[str] = Header(default=None),
    session_token: Optional[str] = Query(default=None),
    authorization: Optional[str] = Header(default=None),
):
    session = _inventory_auth_session_or_admin(
        request,
        token,
        x_admin_token,
        x_session_token,
        session_token,
        authorization,
    )
    tenant_id = str(
        (session or {}).get("tenant_id")
        or tenant_id_from_request(request)
        or get_effective_tenant_id()
        or DEFAULT_TENANT_ID
    )
    set_current_tenant_id(tenant_id)
    raw = await file.read()
    parsed = ml_full_inbound_parse_pdf(raw, filename=file.filename or "full_inbound.pdf")
    if parsed.get("errors"):
        return {"ok": False, "version": APP_VERSION, "tenant_id": tenant_id, "dry_run": dry_run, "preview": parsed, "errors": parsed.get("errors")}

    shipment_id = parsed.get("shipment_id") or str(uuid.uuid4())
    duplicate_check = ml_full_inbound_existing_movements(shipment_id)
    if duplicate_check.get("error") and not dry_run:
        return {
            "ok": False,
            "version": APP_VERSION,
            "tenant_id": tenant_id,
            "dry_run": dry_run,
            "shipment_id": shipment_id,
            "error_type": "dedupe_check_failed",
            "error": duplicate_check.get("error"),
            "message": "No pude verificar si este envío Full ya fue aplicado. No descuento stock para evitar duplicados.",
        }
    if duplicate_check.get("exists") and not dry_run:
        return {
            "ok": True,
            "version": APP_VERSION,
            "tenant_id": tenant_id,
            "dry_run": dry_run,
            "shipment_id": shipment_id,
            "duplicate": True,
            "already_applied": True,
            "items_applied": 0,
            "units_applied": 0,
            "existing_movements_count": duplicate_check.get("count", 0),
            "existing_movements": duplicate_check.get("items", []),
            "message": f"Este envío Full #{shipment_id} ya fue aplicado. No se volvió a descontar stock.",
        }

    applied = []
    sync_summary = []
    for row in parsed.get("items") or []:
        sku = norm_sku(row.get("sku"))
        qty = int(row.get("quantity") or 0)
        item = get_item_by_sku(sku)
        if not item or qty <= 0:
            continue
        old_stock = int(float(item.get("stock") or 0))
        new_stock = old_stock - qty
        result = {
            "sku": sku,
            "quantity": qty,
            "old_stock": old_stock,
            "new_stock": new_stock,
            "insufficient_stock": new_stock < 0,
        }
        if not dry_run:
            stock_write = adjust_stock(
                sb,
                tenant_id=tenant_id,
                sku=sku,
                quantity=-qty,
                movement_type="full_inbound",
                channel="ML_FULL",
                reference_id=str(shipment_id),
                reference_type="ml_full_inbound_pdf",
                notes=f"Envío a Mercado Libre Full #{shipment_id} · {file.filename or ''}".strip(),
            )
            result["old_stock"] = int(stock_write.get("previous_stock") or 0)
            result["new_stock"] = int(stock_write.get("new_stock") or 0)
            result["insufficient_stock"] = result["new_stock"] < 0
            result["stock_write"] = stock_write
            source_meta = {
                "source_channel": "ML_FULL",
                "source_order_id": str(shipment_id),
                "source_order_number": f"Full #{shipment_id}",
                "source_order_api_id": str(shipment_id),
                "source_pack_id": None,
                "source_shipping_id": str(shipment_id),
                "source_customer_name": "Mercado Libre Full",
                "source_created_at": now_iso(),
                "source_meta": {"action": "full_inbound_pdf", "filename": file.filename or "", "ml_code": row.get("ml_code"), "qty_to_full": qty},
            }
            sync = create_sync_jobs_for_sku(sku, result["new_stock"], source_meta=source_meta, skip_full_listings=True)
            result["sync_jobs"] = sync
            sync_summary.append({"sku": sku, **(sync or {})})
            affected = affected_bundle_recalcs_for_component(item["id"], dry_run=False)
            result["affected_bundles"] = affected
        applied.append(result)

    return {
        "ok": True,
        "version": APP_VERSION,
        "tenant_id": tenant_id,
        "dry_run": dry_run,
        "shipment_id": shipment_id,
        "already_applied": bool(duplicate_check.get("exists")),
        "existing_movements_count": duplicate_check.get("count", 0),
        "items_applied": len(applied),
        "units_applied": sum(int(x.get("quantity") or 0) for x in applied),
        "applied": applied,
        "sync_summary": sync_summary,
    }

