@router.get("/admin/dashboard/summary")
def admin_dashboard_summary_endpoint(
    request: Request,
    invoice_hours: int = Query(168, ge=1, le=2160),
    shipping_days: int = Query(14, ge=1, le=90),
    sync_jobs_limit: int = Query(5, ge=1, le=50),
    sync_jobs_offset: int = Query(0, ge=0),
    token: Optional[str] = Query(default=None),
    x_admin_token: Optional[str] = Header(default=None),
    x_session_token: Optional[str] = Header(default=None),
    session_token: Optional[str] = Query(default=None),
    authorization: Optional[str] = Header(default=None),
):
    _inventory_auth_session_or_admin(request, token, x_admin_token, x_session_token, session_token, authorization)

    channels = ["ML", "TN"]
    all_items: Dict[str, List[Dict[str, Any]]] = {}
    today = {
        "date_ar": pc_local_today_ar().isoformat(),
        "count": 0,
        "total_amount": 0.0,
        "channels": {},
        "items": [],
    }
    pending_shipping = {
        "days": shipping_days,
        "count": 0,
        "total_amount": 0.0,
        "channels": {},
        "items": [],
    }

    cutoff_ship = datetime.now(timezone.utc) - timedelta(days=int(shipping_days or 14))

    for ch in channels:
        try:
            items = pc_dashboard_fetch_items(ch, limit=5000)
        except Exception as e:
            items = []
            pending_shipping.setdefault("errors", []).append({"channel": ch, "error": pc_exception_detail(e)})
        all_items[ch] = items
        today["channels"].setdefault(ch, {"count": 0, "total_amount": 0.0})
        pending_shipping["channels"].setdefault(ch, {"count": 0, "total_amount": 0.0, "types": {}})

        for it in items:
            amount = pc_to_float(it.get("total"))
            if pc_item_is_today_ar(it):
                today["count"] += 1
                today["total_amount"] += amount
                today["channels"][ch]["count"] += 1
                today["channels"][ch]["total_amount"] += amount
                if len(today["items"]) < 20:
                    today["items"].append(pc_dashboard_item_summary(it, ch))

            dt = pc_item_dt_for_dashboard(it)
            if dt and dt < cutoff_ship:
                continue
            if pc_dashboard_is_pending_shipping(it, ch):
                typ = pc_dashboard_logistic_type(it, ch)
                pending_shipping["count"] += 1
                pending_shipping["total_amount"] += amount
                chbox = pending_shipping["channels"][ch]
                chbox["count"] += 1
                chbox["total_amount"] += amount
                chbox["types"].setdefault(typ, {"count": 0, "total_amount": 0.0})
                chbox["types"][typ]["count"] += 1
                chbox["types"][typ]["total_amount"] += amount
                if len(pending_shipping["items"]) < 30:
                    pending_shipping["items"].append(pc_dashboard_item_summary(it, ch))

    inv_by_channel = {ch: pc_dashboard_invoice_pending(ch, invoice_hours, 100) for ch in channels}
    pending_invoices = {
        "hours": invoice_hours,
        "count": sum(v["count"] for v in inv_by_channel.values()),
        "total_amount": sum(v["total_amount"] for v in inv_by_channel.values()),
        "channels": inv_by_channel,
        "items": [],
    }
    for ch in channels:
        pending_invoices["items"].extend(inv_by_channel[ch]["items"][:20])
    pending_invoices["items"] = sorted(pending_invoices["items"], key=lambda x: str(x.get("created_at") or ""), reverse=True)[:30]

    return {
        "ok": True,
        "version": APP_VERSION,
        "generated_at": now_iso(),
        "arca": {
            "emit_enabled": ARCA_EMIT_ENABLED,
            "auto_invoice_enabled": ARCA_AUTO_INVOICE_ENABLED,
            "environment": ARCA_ENV,
            "pto_vta": ARCA_PTO_VTA,
        },
        "pollers": {
            "tn_auto_poll_enabled": TN_AUTO_POLL_ENABLED,
            "ml_auto_poll_enabled": ML_AUTO_POLL_ENABLED,
            "erp_auto_sync_enabled": ERP_AUTO_SYNC_ENABLED,
            "whatsapp_admin_configurado": bool(WHATSAPP_TOKEN and WHATSAPP_PHONE_NUMBER_ID and HUMAN_NOTIFY_PHONE),
        },
        "pending_invoices": pending_invoices,
        "today": today,
        "pending_shipping": pending_shipping,
        "failures": pc_dashboard_failures_summary(pending_invoices, sync_jobs_limit=sync_jobs_limit, sync_jobs_offset=sync_jobs_offset),
    }



# ============================================================
# REFRESH LOGÍSTICO ACOTADO - VENTAS NO ENTREGADAS
# ============================================================

def pc_parse_dt_safe(value: Any) -> Optional[datetime]:
    if not value:
        return None
    try:
        txt = str(value).replace("Z", "+00:00")
        dt = datetime.fromisoformat(txt)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        return dt
    except Exception:
        return None


def pc_row_within_days(row: Dict[str, Any], days: int) -> bool:
    dt = pc_parse_dt_safe(row.get("created_at") or row_raw_dict(row).get("ml_date_created") or row_raw_dict(row).get("tn_created_at"))
    if not dt:
        return True
    return dt >= (datetime.now(timezone.utc) - timedelta(days=int(days or 30)))


def pc_raw_is_delivered_or_cancelled(raw: Dict[str, Any], channel: str) -> bool:
    ch = str(channel or "").upper()
    if not isinstance(raw, dict):
        raw = {}
    if ch == "TN" and raw.get("tn_manual_delivered"):
        return True
    if ch == "TN" and tn_closed_order_counts_as_delivered(raw):
        return True
    vals: List[str] = []
    if ch == "ML":
        ml_raw = raw.get("ml_raw") if isinstance(raw.get("ml_raw"), dict) else {}
        shipping = ml_raw.get("shipping") if isinstance(ml_raw.get("shipping"), dict) else {}
        vals += [
            raw.get("ml_shipping_status"),
            raw.get("ml_shipping_substatus"),
            raw.get("ml_status"),
            ml_raw.get("status"),
            shipping.get("status"),
        ]
    else:
        tn_raw = raw.get("tn_raw") if isinstance(raw.get("tn_raw"), dict) else {}
        vals += [
            raw.get("tn_shipping_status"),
            raw.get("tn_status"),
            raw.get("tn_payment_status"),
            tn_raw.get("shipping_status"),
            tn_raw.get("status"),
            tn_raw.get("payment_status"),
        ]
    return shipping_state_is_terminal(ch, vals)


def pc_update_order_raw_data(row_id: Any, raw: Dict[str, Any]) -> None:
    sb.table("orders").update({"raw_data": raw, "updated_at": now_iso()}).eq("id", str(row_id)).execute()


def pc_ml_fetch_order_live(order_id: str) -> Optional[Dict[str, Any]]:
    oid = pc_clean_str(order_id)
    if not oid:
        return None
    r = ml_request("GET", f"https://api.mercadolibre.com/orders/{oid}", timeout=30)
    if r.status_code != 200:
        raise HTTPException(status_code=502, detail=f"ML order {oid} {r.status_code}: {r.text[:800]}")
    data = r.json()
    return data if isinstance(data, dict) else None


def pc_ml_fetch_shipment_live(shipping_id: str) -> Dict[str, Any]:
    sid = pc_clean_str(shipping_id)
    if not sid:
        return {}
    r = ml_request("GET", f"https://api.mercadolibre.com/shipments/{sid}", timeout=30)
    if r.status_code != 200:
        raise HTTPException(status_code=502, detail=f"ML shipment {sid} {r.status_code}: {r.text[:800]}")
    data = r.json()
    if isinstance(data, dict):
        _ML_SHIPMENT_CACHE[sid] = data
        return data
    return {}


def pc_ml_shipping_subtype_from_logistic(logistic_type: Any) -> Optional[str]:
    lt = pc_clean_str(logistic_type).lower()
    if lt == "fulfillment":
        return "full"
    if lt == "self_service":
        return "flex"
    if lt:
        return "normal"
    return None


def pc_ml_shipping_is_final_status(status: Any) -> bool:
    st = pc_clean_str(status).lower()
    return st in ["delivered", "cancelled", "canceled", "returned"]


def pc_apply_ml_shipping_canonical_fields(raw: Dict[str, Any]) -> Dict[str, Any]:
    shipping_id = pc_clean_str(raw.get("ml_shipping_id"))
    status = raw.get("ml_shipping_status")
    logistic_type = raw.get("ml_shipping_logistic_type")

    if not shipping_id and not pc_clean_str(logistic_type):
        raw["ml_shipping_type"] = "to_agree"
        raw["ml_shipping_subtype"] = None
        raw["ml_shipping_label"] = "Entrega a acordar con el comprador"
        raw["ml_stock_affects_master"] = True
        raw["ml_shipping_ui_status"] = "Entregado" if pc_ml_shipping_is_final_status(status) else "Entrega a acordar"
    else:
        subtype = pc_ml_shipping_subtype_from_logistic(logistic_type)
        raw["ml_shipping_type"] = "envio_ml"
        raw["ml_shipping_subtype"] = subtype or "normal"
        if subtype == "full":
            raw["ml_shipping_label"] = "Mercado Envíos Full"
            raw["ml_stock_affects_master"] = False
        elif subtype == "flex":
            raw["ml_shipping_label"] = "Mercado Envíos Flex"
            raw["ml_stock_affects_master"] = True
        else:
            raw["ml_shipping_label"] = "Mercado Envíos"
            raw["ml_stock_affects_master"] = True

    raw["ml_shipping_is_final"] = pc_ml_shipping_is_final_status(status)
    raw["ml_shipping_normalized_at"] = now_iso()
    return raw


def pc_refresh_ml_order_shipping(row: Dict[str, Any]) -> Dict[str, Any]:
    raw = row_raw_dict(row)
    ml_raw = raw.get("ml_raw") if isinstance(raw.get("ml_raw"), dict) else {}
    shipping = ml_raw.get("shipping") if isinstance(ml_raw.get("shipping"), dict) else {}
    external_id = pc_clean_str(row.get("external_order_id") or raw.get("ml_order_id"))
    live_order = None

    shipping_id = pc_clean_str(raw.get("ml_shipping_id") or shipping.get("id"))
    if not shipping_id and external_id:
        live_order = pc_ml_fetch_order_live(external_id)
        if live_order:
            raw["ml_raw"] = live_order
            raw["ml_status"] = live_order.get("status")
            raw["ml_date_created"] = live_order.get("date_created") or raw.get("ml_date_created")
            raw["ml_date_closed"] = live_order.get("date_closed") or raw.get("ml_date_closed")
            ship = live_order.get("shipping") if isinstance(live_order.get("shipping"), dict) else {}
            shipping_id = pc_clean_str(ship.get("id"))

    if not shipping_id:
        # Caso válido ML: Entrega a acordar con el comprador.
        # Igual consultamos /orders/{id} en cada refresh hasta que llegue a estado final,
        # porque no existe /shipments/{id} para consultar.
        live_status = (live_order or {}).get("status") if isinstance(live_order, dict) else None
        live_fulfilled = (live_order or {}).get("fulfilled") is True if isinstance(live_order, dict) else False
        raw["ml_shipping_id"] = None
        raw["ml_fulfilled"] = bool(live_fulfilled)
        raw["ml_shipping_status"] = "delivered" if live_fulfilled else (live_status or raw.get("ml_shipping_status") or raw.get("ml_status"))
        raw["ml_shipping_substatus"] = None
        raw["ml_shipping_logistic_type"] = None
        raw["ml_shipping_mode"] = None
        raw["ml_shipping_tags"] = []
        raw["ml_shipping_last_snapshot"] = {
            "id": None,
            "source": "orders",
            "status": raw.get("ml_shipping_status"),
            "substatus": None,
            "logistic_type": None,
            "mode": None,
            "fulfilled": bool(live_fulfilled),
            "date_updated": (live_order or {}).get("last_updated") or (live_order or {}).get("date_last_updated"),
        }
        raw["ml_shipping_refreshed_at"] = now_iso()
        raw.pop("ml_shipping_refresh_error", None)
        pc_apply_ml_shipping_canonical_fields(raw)
        if live_fulfilled:
            raw["ml_shipping_ui_status"] = "Entregado"
            raw["shipping_ui_status"] = "Entregado"
            raw["ml_shipping_is_final"] = True
            raw["ml_shipping_tracking_done"] = True
        pc_update_order_raw_data(row.get("id"), raw)
        return {
            "order_id": external_id,
            "shipping_id": None,
            "shipping_type": raw.get("ml_shipping_type"),
            "status": raw.get("ml_shipping_status"),
            "ui_status": raw.get("ml_shipping_ui_status"),
            "is_final": raw.get("ml_shipping_is_final"),
            "reason": "to_agree",
        }

    shipment = pc_ml_fetch_shipment_live(shipping_id)
    shipping_option = shipment.get("shipping_option") if isinstance(shipment.get("shipping_option"), dict) else {}
    tags = shipment.get("tags") or []
    if not isinstance(tags, list):
        tags = [tags]

    raw["ml_shipping_id"] = shipping_id
    raw["ml_shipping_status"] = shipment.get("status") or raw.get("ml_shipping_status")
    raw["ml_shipping_substatus"] = shipment.get("substatus") or shipment.get("sub_status") or raw.get("ml_shipping_substatus")
    raw["ml_shipping_logistic_type"] = shipment.get("logistic_type") or shipping_option.get("logistic_type") or raw.get("ml_shipping_logistic_type")
    raw["ml_shipping_mode"] = shipment.get("mode") or raw.get("ml_shipping_mode")
    raw["ml_shipping_tags"] = tags
    raw["ml_shipping_last_snapshot"] = {
        "id": shipping_id,
        "status": shipment.get("status"),
        "substatus": shipment.get("substatus") or shipment.get("sub_status"),
        "logistic_type": shipment.get("logistic_type") or shipping_option.get("logistic_type"),
        "mode": shipment.get("mode"),
        "date_updated": shipment.get("last_updated") or shipment.get("date_updated"),
    }
    raw["ml_shipping_refreshed_at"] = now_iso()
    raw["ml_shipping_ui_status"] = pc_ml_shipping_ui_status_from_labels({
        "ml_shipping_status": raw.get("ml_shipping_status"),
        "ml_shipping_substatus": raw.get("ml_shipping_substatus"),
        "ml_shipping_logistic_type": raw.get("ml_shipping_logistic_type"),
        "ml_shipping_mode": raw.get("ml_shipping_mode"),
        "ml_shipping_tags": raw.get("ml_shipping_tags"),
        "ml_shipping_refreshed_at": raw.get("ml_shipping_refreshed_at"),
        "ml_shipping_last_snapshot": raw.get("ml_shipping_last_snapshot"),
    })
    pc_apply_ml_shipping_canonical_fields(raw)
    raw.pop("ml_shipping_refresh_error", None)
    pc_update_order_raw_data(row.get("id"), raw)
    return {"order_id": external_id, "shipping_id": shipping_id, "status": raw.get("ml_shipping_status"), "substatus": raw.get("ml_shipping_substatus"), "logistic_type": raw.get("ml_shipping_logistic_type"), "ui_status": raw.get("ml_shipping_ui_status")}


def pc_refresh_tn_order_shipping(row: Dict[str, Any]) -> Dict[str, Any]:
    raw = row_raw_dict(row)
    external_id = pc_clean_str(row.get("external_order_id") or raw.get("tn_order_id"))
    if not external_id:
        return {"skipped": True, "reason": "sin external_order_id TN"}
    live_order = tn_get_order(external_id)
    shipping_option = live_order.get("shipping_option")
    raw["tn_raw"] = live_order
    raw["tn_status"] = live_order.get("status")
    raw["tn_payment_status"] = live_order.get("payment_status")
    raw["tn_shipping_status"] = live_order.get("shipping_status")
    raw["tn_order_number"] = live_order.get("number") or raw.get("tn_order_number")
    raw["tn_updated_at"] = live_order.get("updated_at") or raw.get("tn_updated_at")
    raw["tn_shipping_option"] = shipping_option
    raw["tn_next_action"] = live_order.get("next_action")
    raw["tn_closed_at"] = live_order.get("closed_at")
    raw["tn_shipping_ui_status"] = tn_shipping_ui_status(
        raw.get("tn_shipping_status"),
        existing=raw.get("tn_shipping_ui_status") or raw.get("shipping_ui_status"),
        manual_delivered=bool(raw.get("tn_manual_delivered")),
    )
    raw["shipping_ui_status"] = raw.get("tn_shipping_ui_status")
    if shipping_state_is_delivered(raw.get("tn_shipping_status")):
        raw["delivery_status"] = "delivered"
        raw["tn_delivery_status"] = "delivered"
    if tn_closed_order_counts_as_delivered(raw):
        raw["delivery_status"] = "delivered"
        raw["tn_delivery_status"] = "delivered"
        raw["tn_shipping_ui_status"] = "Entregado"
        raw["shipping_ui_status"] = "Entregado"
    # Si el ERP ya marcó una moto como entregada, no dejamos que el refresh de TN
    # vuelva visualmente a shipped/En camino. TN no genera delivered para envíos personalizados.
    if raw.get("tn_manual_delivered") or str(raw.get("delivery_status") or raw.get("tn_delivery_status") or "").lower() in ["delivered", "manual_delivered"]:
        raw["tn_shipping_ui_status"] = "Entregado"
        raw["shipping_ui_status"] = "Entregado"
        raw["delivery_status"] = "delivered"
        raw["tn_delivery_status"] = "delivered"
    raw["tn_shipping_refreshed_at"] = now_iso()
    pc_update_order_raw_data(row.get("id"), raw)
    return {"order_id": external_id, "status": raw.get("tn_status"), "payment_status": raw.get("tn_payment_status"), "shipping_status": raw.get("tn_shipping_status"), "shipping_ui_status": raw.get("tn_shipping_ui_status")}


class VisibleSalesShippingRefreshIn(BaseModel):
    order_ids: List[str] = Field(default_factory=list)


try:
    VISIBLE_SALES_REFRESH_CONCURRENCY = max(
        1,
        min(int(os.getenv("VISIBLE_SALES_REFRESH_CONCURRENCY", "4")), 6),
    )
except Exception:
    VISIBLE_SALES_REFRESH_CONCURRENCY = 4

_VISIBLE_SALES_REFRESH_LOCK = threading.Lock()
_VISIBLE_SALES_REFRESH_INFLIGHT = set()


def _visible_sales_order_ids(values: List[Any]) -> List[str]:
    out: List[str] = []
    seen = set()
    for value in values or []:
        clean = str(value or "").strip()[:120]
        if not clean or clean in seen:
            continue
        seen.add(clean)
        out.append(clean)
        if len(out) >= 50:
            break
    return out


def _visible_sales_invoice_source(channel: str, row: Dict[str, Any], raw: Dict[str, Any]) -> str:
    if str(channel or "").upper() == "ML":
        return str(raw.get("ml_pack_id") or row.get("external_order_id") or row.get("id") or "")
    return str(row.get("external_order_id") or raw.get("tn_order_id") or row.get("id") or "")


def _visible_ml_shipping_payload_for_tenant(row: Dict[str, Any], tenant_id: str) -> Dict[str, Any]:
    raw = row_raw_dict(row)
    order_id = str(row.get("external_order_id") or row.get("id") or "").strip()
    shipping_id = _ml_shipping_id_from_order_row(row)
    live_order: Dict[str, Any] = {}

    if not shipping_id and order_id:
        candidate = _ml_tenant_request_json(
            tenant_id,
            "GET",
            f"https://api.mercadolibre.com/orders/{order_id}",
            timeout=45,
        )
        live_order = candidate if isinstance(candidate, dict) else {}
        live_shipping = live_order.get("shipping") if isinstance(live_order.get("shipping"), dict) else {}
        shipping_id = str((live_shipping or {}).get("id") or "").strip()

    if shipping_id:
        shipment = _ml_tenant_request_json(
            tenant_id,
            "GET",
            f"https://api.mercadolibre.com/shipments/{shipping_id}",
            timeout=45,
        )
        payload = _ml_shipping_payload_from_snapshot(
            shipping_id,
            shipment if isinstance(shipment, dict) else {},
            source="ml_api_visible_page",
        )
        sale_from_shipment = ml_detect_sale_number_from_shipment(
            shipment if isinstance(shipment, dict) else {},
            child_order_ids=[order_id] if order_id else [],
        )
        if sale_from_shipment:
            payload["ml_sale_number_from_shipment"] = sale_from_shipment
        return payload

    now = _utcnow().isoformat()
    live_fulfilled = live_order.get("fulfilled") is True
    live_status = live_order.get("status") or raw.get("ml_status") or raw.get("ml_shipping_status")
    live_tags = live_order.get("tags") if isinstance(live_order.get("tags"), list) else []
    ui_status = "Entregado" if live_fulfilled else "A coordinar con comprador"
    return {
        "ml_raw": live_order or raw.get("ml_raw"),
        "ml_status": live_status,
        "ml_date_created": live_order.get("date_created") or raw.get("ml_date_created"),
        "ml_date_closed": live_order.get("date_closed") or raw.get("ml_date_closed"),
        "ml_fulfilled": bool(live_fulfilled),
        "ml_shipping_id": None,
        "ml_shipping_status": "delivered" if live_fulfilled else live_status,
        "ml_shipping_substatus": None,
        "ml_shipping_logistic_type": None,
        "ml_shipping_mode": None,
        "ml_shipping_tags": live_tags,
        "ml_shipping_ui_type": raw.get("ml_shipping_ui_type") or raw.get("shipping_type") or "A coordinar",
        "ml_shipping_ui_status": ui_status,
        "shipping_ui_status": ui_status,
        "ml_shipping_last_snapshot": {
            "id": None,
            "source": "orders",
            "status": "delivered" if live_fulfilled else live_status,
            "substatus": None,
            "logistic_type": None,
            "mode": None,
            "fulfilled": bool(live_fulfilled),
            "tags": live_tags,
            "date_updated": live_order.get("last_updated") or live_order.get("date_last_updated"),
        },
        "ml_shipping_refreshed_at": now,
        "ml_shipping_is_final": bool(live_fulfilled),
        "ml_shipping_tracking_done": bool(live_fulfilled),
        "ml_shipping_refresh_error": None,
    }


def _visible_tn_shipping_payload_for_tenant(row: Dict[str, Any], tenant_id: str) -> Dict[str, Any]:
    raw = row_raw_dict(row)
    external_id = str(row.get("external_order_id") or raw.get("tn_order_id") or "").strip()
    if not external_id:
        raise HTTPException(status_code=400, detail="Orden TN sin external_order_id")
    live_order = _tn_tenant_order_json(tenant_id, external_id, timeout=45)
    shipping_status = live_order.get("shipping_status")
    manual_delivered = bool(raw.get("tn_manual_delivered"))
    ui_status = tn_shipping_ui_status(
        shipping_status,
        existing=raw.get("tn_shipping_ui_status") or raw.get("shipping_ui_status"),
        manual_delivered=manual_delivered,
    )
    payload: Dict[str, Any] = {
        "tn_raw": live_order,
        "tn_status": live_order.get("status"),
        "tn_payment_status": live_order.get("payment_status"),
        "tn_shipping_status": shipping_status,
        "tn_order_number": live_order.get("number") or raw.get("tn_order_number"),
        "tn_updated_at": live_order.get("updated_at") or raw.get("tn_updated_at"),
        "tn_shipping_option": live_order.get("shipping_option"),
        "tn_next_action": live_order.get("next_action"),
        "tn_closed_at": live_order.get("closed_at"),
        "tn_shipping_ui_status": ui_status,
        "shipping_ui_status": ui_status,
        "tn_shipping_refreshed_at": now_iso(),
    }
    if manual_delivered or shipping_state_is_delivered(shipping_status) or tn_closed_order_counts_as_delivered(payload):
        payload["delivery_status"] = "delivered"
        payload["tn_delivery_status"] = "delivered"
        payload["tn_shipping_ui_status"] = "Entregado"
        payload["shipping_ui_status"] = "Entregado"
    return payload


def pc_refresh_visible_sales_shipping(tenant_id: str, channel: str, order_ids: List[Any]) -> Dict[str, Any]:
    ch = str(channel or "").strip().upper()
    if ch not in ["ML", "TN"]:
        raise HTTPException(status_code=400, detail="channel debe ser ML o TN")
    ids = _visible_sales_order_ids(order_ids)
    if not ids:
        return {
            "ok": True,
            "version": APP_VERSION,
            "tenant_id": tenant_id,
            "channel": ch,
            "requested_count": 0,
            "refreshed_count": 0,
            "skipped_count": 0,
            "invoice_issued_count": 0,
            "invoice_queued_count": 0,
            "invoice_skipped_count": 0,
            "errors_count": 0,
            "items": [],
        }
    if not _sb_raw:
        raise HTTPException(status_code=500, detail="DATABASE_URL/AWS Postgres no configurado")

    rows = (
        _sb_raw.table("orders")
        .select("*")
        .eq("tenant_id", str(tenant_id))
        .eq("channel", ch)
        .in_("external_order_id", ids)
        .limit(len(ids))
        .execute()
        .data
        or []
    )
    row_by_external = {str(row.get("external_order_id") or ""): row for row in rows}
    ordered_rows = [row_by_external[oid] for oid in ids if oid in row_by_external]

    claimed_rows: List[Dict[str, Any]] = []
    skipped: List[Dict[str, Any]] = []
    claim_keys = []
    with _VISIBLE_SALES_REFRESH_LOCK:
        for row in ordered_rows:
            external_id = str(row.get("external_order_id") or row.get("id") or "")
            key = (str(tenant_id), ch, external_id)
            if key in _VISIBLE_SALES_REFRESH_INFLIGHT:
                skipped.append({"order_id": external_id, "reason": "already_refreshing"})
                continue
            _VISIBLE_SALES_REFRESH_INFLIGHT.add(key)
            claim_keys.append(key)
            claimed_rows.append(row)

    refreshed: List[Dict[str, Any]] = []
    errors: List[Dict[str, Any]] = []
    invoice_results: List[Dict[str, Any]] = []
    invoice_sources = set()

    def maybe_invoice(row: Dict[str, Any], raw: Dict[str, Any]) -> Optional[Dict[str, Any]]:
        source_id = _visible_sales_invoice_source(ch, row, raw)
        if not source_id or source_id in invoice_sources:
            return None
        invoice_sources.add(source_id)
        existing_invoice = None
        try:
            existing_invoice = arca_existing_invoice_for_order(row)
        except Exception:
            existing_invoice = None
        if existing_invoice and (
            existing_invoice.get("cae")
            or str(existing_invoice.get("status") or "").lower() == "issued"
        ):
            result = {
                "ok": True,
                "queued": False,
                "newly_queued": False,
                "skipped": True,
                "duplicate": True,
                "reason": "already_invoiced",
                "invoice_id": existing_invoice.get("id"),
                "channel": ch,
                "order_id": source_id,
            }
        else:
            result = arca_queue_auto_invoice_order(ch, source_id)
        item = {"source_id": source_id, "order_id": row.get("external_order_id"), "result": result}
        invoice_results.append(item)
        if isinstance(result, dict) and not result.get("ok", False):
            errors.append({
                "order_id": row.get("external_order_id"),
                "stage": "auto_invoice",
                "error": result.get("error") or result,
            })
        return item

    try:
        pending_rows: List[Dict[str, Any]] = []
        for row in claimed_rows:
            raw = row_raw_dict(row)
            if arca_order_is_delivered_for_auto_invoice(ch, row):
                if ch == "TN" and tn_closed_order_counts_as_delivered(raw):
                    canonical = dict(raw)
                    canonical["delivery_status"] = "delivered"
                    canonical["tn_delivery_status"] = "delivered"
                    canonical["tn_shipping_ui_status"] = "Entregado"
                    canonical["shipping_ui_status"] = "Entregado"
                    if canonical != raw:
                        pc_update_order_raw_data(row.get("id"), canonical)
                        row["raw_data"] = canonical
                        raw = canonical
                maybe_invoice(row, raw)
                skipped.append({"order_id": row.get("external_order_id"), "reason": "already_delivered"})
                continue
            if pc_raw_is_delivered_or_cancelled(raw, ch):
                skipped.append({"order_id": row.get("external_order_id"), "reason": "terminal_not_delivered"})
                continue
            pending_rows.append(row)

        def fetch_live(row: Dict[str, Any]) -> Dict[str, Any]:
            if ch == "ML":
                return _visible_ml_shipping_payload_for_tenant(row, tenant_id)
            return _visible_tn_shipping_payload_for_tenant(row, tenant_id)

        if pending_rows:
            worker_count = min(VISIBLE_SALES_REFRESH_CONCURRENCY, len(pending_rows))
            with ThreadPoolExecutor(max_workers=worker_count, thread_name_prefix=f"sales-{ch.lower()}-visible") as pool:
                future_rows = {pool.submit(fetch_live, row): row for row in pending_rows}
                for future in as_completed(future_rows):
                    row = future_rows[future]
                    external_id = str(row.get("external_order_id") or row.get("id") or "")
                    try:
                        payload = future.result()
                        merged_raw = dict(row_raw_dict(row))
                        merged_raw.update(payload)
                        if ch == "ML" and merged_raw.get("ml_shipping_refresh_error") is None:
                            merged_raw.pop("ml_shipping_refresh_error", None)
                        pc_update_order_raw_data(row.get("id"), merged_raw)
                        updated_row = dict(row)
                        updated_row["raw_data"] = merged_raw
                        if arca_order_is_delivered_for_auto_invoice(ch, updated_row):
                            maybe_invoice(updated_row, merged_raw)
                        refreshed.append({
                            "order_id": external_id,
                            "shipping_status": merged_raw.get("ml_shipping_status") if ch == "ML" else merged_raw.get("tn_shipping_status"),
                            "shipping_ui_status": merged_raw.get("ml_shipping_ui_status") if ch == "ML" else merged_raw.get("tn_shipping_ui_status"),
                        })
                    except HTTPException as exc:
                        detail = exc.detail
                        failed_raw = dict(row_raw_dict(row))
                        failed_raw[f"{ch.lower()}_shipping_refresh_attempted_at"] = now_iso()
                        failed_raw[f"{ch.lower()}_shipping_refresh_error"] = detail
                        try:
                            pc_update_order_raw_data(row.get("id"), failed_raw)
                        except Exception:
                            pass
                        errors.append({"order_id": external_id, "error": detail})
                    except Exception as exc:
                        detail = pc_exception_detail(exc)
                        failed_raw = dict(row_raw_dict(row))
                        failed_raw[f"{ch.lower()}_shipping_refresh_attempted_at"] = now_iso()
                        failed_raw[f"{ch.lower()}_shipping_refresh_error"] = detail
                        try:
                            pc_update_order_raw_data(row.get("id"), failed_raw)
                        except Exception:
                            pass
                        errors.append({"order_id": external_id, "error": detail})
    finally:
        with _VISIBLE_SALES_REFRESH_LOCK:
            for key in claim_keys:
                _VISIBLE_SALES_REFRESH_INFLIGHT.discard(key)

    missing = [oid for oid in ids if oid not in row_by_external]
    skipped.extend({"order_id": oid, "reason": "not_found_for_tenant"} for oid in missing)
    issued_count = sum(
        1
        for item in invoice_results
        if isinstance(item.get("result"), dict)
        and item["result"].get("ok")
        and not item["result"].get("queued")
        and not item["result"].get("skipped")
        and not item["result"].get("duplicate")
    )
    queued_count = sum(
        1
        for item in invoice_results
        if isinstance(item.get("result"), dict)
        and item["result"].get("ok")
        and item["result"].get("queued")
    )
    skipped_invoice_count = sum(
        1
        for item in invoice_results
        if isinstance(item.get("result"), dict)
        and item["result"].get("ok")
        and item["result"].get("skipped")
    )
    return {
        "ok": len(errors) == 0,
        "version": APP_VERSION,
        "tenant_id": str(tenant_id),
        "channel": ch,
        "resource_mode": "visible_page_only_bounded_concurrency",
        "max_concurrency": VISIBLE_SALES_REFRESH_CONCURRENCY,
        "requested_count": len(ids),
        "matched_count": len(rows),
        "refreshed_count": len(refreshed),
        "skipped_count": len(skipped),
        "invoice_checked_count": len(invoice_results),
        "invoice_issued_count": issued_count,
        "invoice_queued_count": queued_count,
        "invoice_skipped_count": skipped_invoice_count,
        "errors_count": len(errors),
        "items": refreshed,
        "skipped": skipped,
        "invoice_results": invoice_results,
        "errors": errors,
    }


def pc_background_refresh_open_sales(
    tenant_id: str,
    channel: str,
    limit: int = 20,
    scan_limit: int = 300,
    lookback_days: int = 60,
) -> Dict[str, Any]:
    """Refresca un lote acotado de envíos abiertos sin depender de la pantalla.

    La consulta a nuestra base queda limitada a ventas recientes y las llamadas
    externas se hacen sólo para los candidatos elegidos. Las ventas terminales
    no vuelven a consultarse. Una entrega cuyo último intento fiscal falló se
    incluye para que la cola idempotente de ARCA pueda reintentarla.
    """
    ch = str(channel or "").strip().upper()
    if ch not in ["ML", "TN"]:
        raise HTTPException(status_code=400, detail="channel debe ser ML o TN")
    if not _sb_raw:
        raise HTTPException(status_code=500, detail="DATABASE_URL/AWS Postgres no configurado")

    bounded_limit = max(1, min(int(limit or 20), 50))
    bounded_scan = max(bounded_limit, min(int(scan_limit or 300), 500))
    bounded_days = max(7, min(int(lookback_days or 60), 180))
    cutoff = (datetime.now(timezone.utc) - timedelta(days=bounded_days)).isoformat()
    rows = (
        _sb_raw.table("orders")
        .select("id,external_order_id,channel,raw_data,created_at,updated_at")
        .eq("tenant_id", str(tenant_id))
        .eq("channel", ch)
        .gte("created_at", cutoff)
        .order("created_at", desc=True)
        .limit(bounded_scan)
        .execute()
        .data
        or []
    )

    candidates: List[Tuple[int, str, str]] = []
    seen_tracking_keys = set()
    open_count = 0
    fiscal_retry_count = 0
    recent_capture_cutoff = datetime.now(timezone.utc) - timedelta(minutes=15)
    for row in rows:
        raw = row_raw_dict(row)
        external_id = str(row.get("external_order_id") or "").strip()
        if not external_id:
            continue
        delivered = arca_order_is_delivered_for_auto_invoice(ch, row)
        fiscal_error = bool(raw.get("arca_auto_invoice_last_error"))
        captured_at = pc_parse_dt_safe(row.get("created_at"))
        recently_captured = bool(captured_at and captured_at >= recent_capture_cutoff)
        if delivered:
            if not fiscal_error and not recently_captured:
                continue
            fiscal_retry_count += 1
        elif pc_raw_is_delivered_or_cancelled(raw, ch):
            continue
        else:
            open_count += 1
        tracking_key = str(
            raw.get("ml_shipping_id")
            or raw.get("ml_pack_id")
            or raw.get("tn_order_id")
            or external_id
        )
        if tracking_key in seen_tracking_keys:
            continue
        seen_tracking_keys.add(tracking_key)
        refresh_markers = [
            str(value)
            for value in [
                raw.get("ml_shipping_refreshed_at"),
                raw.get("tn_shipping_refreshed_at"),
                raw.get("ml_shipping_refresh_attempted_at"),
                raw.get("tn_shipping_refresh_attempted_at"),
                raw.get("shipping_refreshed_at"),
            ]
            if value
        ]
        refreshed_at = max(refresh_markers) if refresh_markers else ""
        candidates.append((0 if delivered else 1, refreshed_at, external_id))

    # Los reintentos fiscales van primero. Dentro de cada grupo se elige al que
    # nunca fue revisado y luego al más antiguo, para que el lote rote con justicia.
    candidates.sort(key=lambda item: (item[0], bool(item[1]), item[1], item[2]))
    selected_ids = [item[2] for item in candidates[:bounded_limit]]
    if not selected_ids:
        return {
            "ok": True,
            "version": APP_VERSION,
            "tenant_id": str(tenant_id),
            "channel": ch,
            "resource_mode": "background_open_sales_bounded",
            "scanned_count": len(rows),
            "open_count": open_count,
            "fiscal_retry_count": fiscal_retry_count,
            "selected_count": 0,
            "refreshed_count": 0,
            "invoice_queued_count": 0,
            "errors_count": 0,
        }

    result = pc_refresh_visible_sales_shipping(tenant_id, ch, selected_ids)
    result["resource_mode"] = "background_open_sales_bounded"
    result["scanned_count"] = len(rows)
    result["open_count"] = open_count
    result["fiscal_retry_count"] = fiscal_retry_count
    result["selected_count"] = len(selected_ids)
    return result


