def pc_refresh_shipping_pending(channel: str, limit: int, days: int, scan_limit: int) -> Dict[str, Any]:
    ch = str(channel or "").upper().strip()
    if ch not in ["ML", "TN"]:
        raise HTTPException(status_code=400, detail="channel debe ser ML o TN")
    max_scan = max(int(limit or 50), min(int(scan_limit or 250), 1000))
    rows = (
        sb.table("orders")
        .select("*")
        .eq("channel", ch)
        .order("created_at", desc=True)
        .limit(max_scan)
        .execute()
        .data
        or []
    )
    refreshed = []
    skipped = []
    errors = []
    considered = 0
    for row in rows:
        if len(refreshed) >= int(limit or 50):
            break
        if is_test_order_row(row):
            skipped.append({"id": row.get("id"), "reason": "test"})
            continue
        if not pc_row_within_days(row, days):
            skipped.append({"id": row.get("id"), "reason": "fuera_de_rango"})
            continue
        raw = row_raw_dict(row)
        if arca_order_is_delivered_for_auto_invoice(ch, row):
            skipped.append({"id": row.get("id"), "reason": "terminal_delivered"})
            continue
        if pc_raw_is_delivered_or_cancelled(raw, ch):
            skipped.append({"id": row.get("id"), "reason": "terminal"})
            continue
        considered += 1
        try:
            if ch == "ML":
                refresh_result = pc_refresh_ml_order_shipping(row)
            else:
                refresh_result = pc_refresh_tn_order_shipping(row)
            if arca_order_is_delivered_for_auto_invoice(ch, row):
                source_id = _visible_sales_invoice_source(ch, row, row_raw_dict(row))
                refresh_result["auto_invoice"] = arca_auto_invoice_order_safe(ch, source_id) if source_id else None
            refreshed.append(refresh_result)
        except Exception as e:
            errors.append({"id": row.get("id"), "external_order_id": row.get("external_order_id"), "error": pc_exception_detail(e)})
    return {
        "ok": len(errors) == 0,
        "version": APP_VERSION,
        "channel": ch,
        "days": days,
        "limit": limit,
        "scan_limit": max_scan,
        "considered_non_delivered": considered,
        "refreshed_count": len(refreshed),
        "skipped_count": len(skipped),
        "error_count": len(errors),
        "refreshed": refreshed,
        "skipped_sample": skipped[:20],
        "errors": errors,
    }


