# ============================================================
# MERCADO LIBRE - PREGUNTAS / RESPUESTAS MANUALES
# ============================================================

class MLQuestionAnswerIn(BaseModel):
    text: str = Field(..., min_length=1, max_length=2000)
    greeting_enabled: bool = True
    signature_enabled: bool = True
    question: Optional[Dict[str, Any]] = None
    ai_answer: Optional[str] = None
    attempt_number: Optional[int] = None


ML_QUESTIONS_CACHE_TABLE = os.getenv("ML_QUESTIONS_CACHE_TABLE", "ml_questions_cache")


def ml_questions_setup_sql() -> str:
    return """
create table if not exists public.ml_questions_cache (
  tenant_id uuid not null references public.tenants(id) on delete cascade,
  id text not null,
  item_id text,
  seller_id text,
  status text,
  text text,
  date_created timestamptz,
  answer jsonb,
  from_data jsonb,
  item_data jsonb,
  raw_data jsonb,
  source text,
  is_mock boolean not null default false,
  last_seen_at timestamptz not null default now(),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  primary key (tenant_id, id)
);
create index if not exists idx_ml_questions_cache_status_date
  on public.ml_questions_cache(tenant_id, status, date_created desc);
create index if not exists idx_ml_questions_cache_item_id
  on public.ml_questions_cache(tenant_id, item_id);
""".strip()


def ml_questions_local_now_ar() -> datetime:
    return datetime.now(timezone(timedelta(hours=-3)))


def ml_questions_greeting() -> str:
    h = ml_questions_local_now_ar().hour
    m = h * 60 + ml_questions_local_now_ar().minute
    if (7 * 60 + 1) <= m <= (13 * 60):
        return "Buen día"
    if (13 * 60 + 1) <= m <= (20 * 60):
        return "Buenas tardes"
    return "Buenas noches"


def ml_questions_format_answer(text: str, greeting_enabled: bool = True, signature_enabled: bool = True) -> str:
    body = re.sub(r"\s+", " ", str(text or "").strip())
    if not body:
        raise HTTPException(status_code=400, detail="La respuesta no puede estar vacía")

    out = body
    if greeting_enabled:
        out = f"{ml_questions_greeting()}. {out}"
    if signature_enabled:
        out = f"{out} / PLANETA CASA"
    return out.strip()


def ml_questions_item_summary(item_id: str) -> Dict[str, Any]:
    if not item_id:
        return {}
    try:
        item = ml_get_json(f"https://api.mercadolibre.com/items/{item_id}", timeout=30)
        return {
            "id": item.get("id"),
            "title": item.get("title"),
            "permalink": item.get("permalink"),
            "price": item.get("price"),
            "status": item.get("status"),
            "thumbnail": item.get("thumbnail"),
            "seller_custom_field": item.get("seller_custom_field"),
            "seller_sku": item.get("seller_sku"),
            "available_quantity": item.get("available_quantity"),
            "shipping": item.get("shipping"),
            "listing_type_id": item.get("listing_type_id"),
            "logistic_type": ((item.get("shipping") or {}).get("logistic_type") if isinstance(item.get("shipping"), dict) else None),
            "mode": ((item.get("shipping") or {}).get("mode") if isinstance(item.get("shipping"), dict) else None),
        }
    except Exception as e:
        return {"id": item_id, "error": pc_exception_detail(e)}


def ml_questions_extract_id(payload: Dict[str, Any]) -> Optional[str]:
    """
    Acepta formatos típicos de notificaciones ML:
    - {"resource":"/questions/123", "topic":"questions"}
    - {"id":123, "topic":"questions"}
    - {"question_id":123}
    """
    if not isinstance(payload, dict):
        return None
    for k in ["question_id", "questionId", "id"]:
        v = payload.get(k)
        if v and re.search(r"\d+", str(v)):
            return re.search(r"\d+", str(v)).group(0)
    resource = str(payload.get("resource") or payload.get("url") or "")
    m = re.search(r"/questions/(\d+)", resource)
    if m:
        return m.group(1)
    return None


def ml_questions_fetch_by_id(question_id: str) -> Dict[str, Any]:
    """
    Consulta puntual por ID. Esto es el flujo que queremos usar con notificaciones,
    porque /questions/search?seller_id quedó bloqueado por PolicyAgent.
    """
    qid = str(question_id or "").strip()
    if not qid:
        raise HTTPException(status_code=400, detail="question_id vacío")
    tenant_id = str(get_effective_tenant_id() or DEFAULT_TENANT_ID)
    if _tenant_token_row(tenant_id, "ml"):
        r = _tenant_ml_request(
            tenant_id,
            "GET",
            f"https://api.mercadolibre.com/questions/{qid}",
            params={"api_version": 4},
            timeout=30,
        )
    else:
        r = ml_request(
            "GET",
            f"https://api.mercadolibre.com/questions/{qid}",
            params={"api_version": 4},
            timeout=30,
        )
    try:
        data = r.json()
    except Exception:
        data = {"raw_text": (r.text or "")[:4000]}
    if r.status_code != 200:
        raise HTTPException(status_code=502, detail={
            "message": "ML no devolvió la pregunta por ID",
            "question_id": qid,
            "status_code": r.status_code,
            "response": data,
        })
    return data


def ml_questions_normalize_question(q: Dict[str, Any], include_item: bool = True) -> Dict[str, Any]:
    item_raw = q.get("item") if isinstance(q.get("item"), dict) else {}
    item_id = q.get("item_id") or item_raw.get("id")
    out = {
        "id": q.get("id"),
        "text": q.get("text"),
        "status": q.get("status"),
        "item_id": item_id,
        "date_created": q.get("date_created"),
        "answer": q.get("answer"),
        "from": q.get("from"),
        "seller_id": q.get("seller_id"),
        "is_mock": bool(q.get("is_mock")),
        "source": q.get("source"),
        "raw": q,
    }
    if include_item:
        if isinstance(q.get("item_data"), dict) and q.get("item_data"):
            out["item"] = q.get("item_data")
        elif item_raw:
            out["item"] = item_raw
        elif item_id:
            out["item"] = ml_questions_item_summary(str(item_id))
    return out


def ml_questions_cache_row_from_question(q: Dict[str, Any], source: str = "ml_question_id", is_mock: bool = False) -> Dict[str, Any]:
    qid = str(q.get("id") or q.get("question_id") or "").strip()
    if not qid:
        raise HTTPException(status_code=400, detail="La pregunta no tiene ID")
    item_raw = q.get("item") if isinstance(q.get("item"), dict) else {}
    item_id = q.get("item_id") or item_raw.get("id")
    seller_id = q.get("seller_id") or q.get("seller", {}).get("id") if isinstance(q.get("seller"), dict) else q.get("seller_id")
    item_data = q.get("item_data") if isinstance(q.get("item_data"), dict) else {}
    if not item_data and item_id and not is_mock:
        item_data = ml_questions_item_summary(str(item_id))
    return {
        "id": qid,
        "item_id": str(item_id) if item_id else None,
        "seller_id": str(seller_id) if seller_id else str(ML_USER_ID or "") or None,
        "status": q.get("status") or "UNANSWERED",
        "text": q.get("text") or "",
        "date_created": q.get("date_created") or now_iso(),
        "answer": q.get("answer"),
        "from_data": q.get("from"),
        "item_data": item_data or None,
        "raw_data": q,
        "source": source,
        "is_mock": bool(is_mock),
        "last_seen_at": now_iso(),
        "updated_at": now_iso(),
    }


def ml_questions_cache_upsert(row: Dict[str, Any]) -> Dict[str, Any]:
    try:
        saved = (
            sb.table(ML_QUESTIONS_CACHE_TABLE)
            .upsert(row, on_conflict="tenant_id,id")
            .execute()
            .data
            or []
        )
        return {"ok": True, "row": saved[0] if saved else row}
    except Exception as e:
        return {
            "ok": False,
            "error": pc_exception_detail(e),
            "table": ML_QUESTIONS_CACHE_TABLE,
            "setup_sql": ml_questions_setup_sql(),
        }


def ml_questions_cache_list(status: str, limit: int, offset: int, include_item: bool = True) -> Dict[str, Any]:
    try:
        q = sb.table(ML_QUESTIONS_CACHE_TABLE).select("*", count="exact")
        if status and status.upper() != "ALL":
            q = q.eq("status", status)
        res = (
            q.order("date_created", desc=True)
            .range(offset, offset + limit - 1)
            .execute()
        )
        rows = res.data or []
        total = res.count if res.count is not None else len(rows)
        items = []
        for row in rows:
            raw = row.get("raw_data") if isinstance(row.get("raw_data"), dict) else {}
            merged = {
                **raw,
                "id": row.get("id"),
                "item_id": row.get("item_id"),
                "seller_id": row.get("seller_id"),
                "status": row.get("status"),
                "text": row.get("text"),
                "date_created": row.get("date_created"),
                "answer": row.get("answer"),
                "from": row.get("from_data"),
                "item_data": row.get("item_data"),
                "is_mock": row.get("is_mock"),
                "source": row.get("source"),
            }
            items.append(ml_questions_normalize_question(merged, include_item=include_item))
        return {
            "ok": True,
            "version": APP_VERSION,
            "source": "AWS Postgres ml_questions_cache",
            "status": status,
            "limit": limit,
            "offset": offset,
            "total": total,
            "has_more": (offset + len(rows)) < int(total or 0),
            "items": items,
        }
    except Exception as e:
        return {
            "ok": False,
            "version": APP_VERSION,
            "source": "AWS Postgres ml_questions_cache",
            "error": pc_exception_detail(e),
            "table": ML_QUESTIONS_CACHE_TABLE,
            "setup_sql": ml_questions_setup_sql(),
            "status": status,
            "limit": limit,
            "offset": offset,
            "total": 0,
            "has_more": False,
            "items": [],
        }


def ml_questions_live_search(status: str, limit: int, offset: int, include_item: bool = True, api_version: Optional[int] = None) -> Dict[str, Any]:
    """
    Consulta live a ML. ML no acepta status=ALL; para ALL combina UNANSWERED + ANSWERED.
    """
    ml_validate_config(require_user=True)
    st = str(status or "UNANSWERED").upper().strip()

    if st == "ALL":
        combined: List[Dict[str, Any]] = []
        totals: Dict[str, int] = {}
        errors: List[Dict[str, Any]] = []
        # Para ALL hacemos una lectura acotada de ambos estados y ordenamos por fecha.
        # Es para consulta/historial; la pantalla operativa no debe usar ALL.
        each_limit = max(1, min(int(limit or 20), 50))
        for sub_status in ["UNANSWERED", "ANSWERED"]:
            res = ml_questions_live_search(sub_status, each_limit, 0, include_item=include_item, api_version=api_version)
            totals[sub_status] = int(res.get("total") or 0)
            if not res.get("ok"):
                errors.append({"status": sub_status, "error": res.get("ml_error") or res.get("error")})
            combined.extend(res.get("items") or [])
        combined.sort(key=lambda q: str(q.get("date_created") or ""), reverse=True)
        page = combined[offset:offset + limit]
        return {
            "ok": len(errors) == 0,
            "version": APP_VERSION,
            "source": "ML questions/search live combined",
            "seller_id": ML_USER_ID,
            "status": "ALL",
            "limit": limit,
            "offset": offset,
            "include_item": include_item,
            "total": sum(totals.values()),
            "totals_by_status": totals,
            "has_more": (offset + len(page)) < len(combined),
            "items": page,
            "errors": errors,
        }

    params = {
        "seller_id": ML_USER_ID,
        "status": st,
        "limit": limit,
        "offset": offset,
        "sort_fields": "date_created",
        "sort_types": "DESC",
    }
    if api_version:
        params["api_version"] = api_version

    r = ml_request("GET", "https://api.mercadolibre.com/questions/search", params=params, timeout=25)
    body_text = r.text or ""
    try:
        data = r.json()
    except Exception:
        data = {"raw_text": body_text[:4000]}

    if r.status_code != 200:
        return {
            "ok": False,
            "version": APP_VERSION,
            "source": "ML questions/search live",
            "ml_status_code": r.status_code,
            "ml_error": data,
            "seller_id": ML_USER_ID,
            "status": st,
            "limit": limit,
            "offset": offset,
            "include_item": include_item,
            "api_version_sent": api_version,
            "params_sent": params,
            "items": [],
            "total": 0,
            "has_more": False,
        }

    questions = data.get("questions") or data.get("results") or []
    total = data.get("total") or data.get("paging", {}).get("total") or len(questions)
    return {
        "ok": True,
        "version": APP_VERSION,
        "source": "ML questions/search live",
        "seller_id": ML_USER_ID,
        "status": st,
        "limit": limit,
        "offset": offset,
        "include_item": include_item,
        "api_version_sent": api_version,
        "total": total,
        "has_more": (offset + len(questions)) < int(total or 0),
        "items": [ml_questions_normalize_question(q, include_item=include_item) for q in questions],
    }


def ml_questions_delete_mocks() -> Dict[str, Any]:
    """Borra mocks reales de la tabla de cache. No oculta: elimina filas."""
    try:
        rows = (
            sb.table(ML_QUESTIONS_CACHE_TABLE)
            .select("id,is_mock,source")
            .execute()
            .data
            or []
        )
        ids = []
        for r in rows:
            rid = str(r.get("id") or "")
            src = str(r.get("source") or "").lower()
            if bool(r.get("is_mock")) or src == "mock" or rid.startswith("mock-"):
                ids.append(rid)
        deleted = 0
        for rid in ids:
            sb.table(ML_QUESTIONS_CACHE_TABLE).delete().eq("id", rid).execute()
            deleted += 1
        return {"ok": True, "deleted": deleted, "ids": ids[:50]}
    except Exception as e:
        return {"ok": False, "error": pc_exception_detail(e), "table": ML_QUESTIONS_CACHE_TABLE}


def ml_questions_classify_for_description(q: Dict[str, Any]) -> List[str]:
    txt = normalizar((q.get("text") or "") + " " + ((q.get("item") or {}).get("title") or ""))
    cats = []
    if any(w in txt for w in ["envio", "envios", "costo", "cp", "codigo postal", "cuando lleg", "llegaria", "correo", "encomienda", "provincia"]):
        cats.append("envios_costos_tiempos")
    if any(w in txt for w in ["retirar", "retiro", "personalmente", "horario", "zona", "direccion", "local"]):
        cats.append("retiro_horarios_zona")
    if any(w in txt for w in ["medida", "medidas", "diametro", "alto", "altura", "ancho", "largo", "peso", "gramos", "entra en un auto"]):
        cats.append("medidas_peso_dimensiones")
    if any(w in txt for w in ["mano izquierda", "mano derecha", "ambas manos", "diestro", "zurdo", "zurdos", "diestros"]):
        cats.append("compatibilidad_mano")
    if any(w in txt for w in ["stock", "disponible", "tenes", "tendra", "color", "colores", "variante"]):
        cats.append("stock_variantes_colores")
    if any(w in txt for w in ["4 unidades", "cuatro unidades", "x4", "carrito", "pack", "cantidad", "unidades"]):
        cats.append("packs_cantidades")
    if any(w in txt for w in ["compuesto", "material", "fabrican", "tiza", "resina", "madera", "melamina"]):
        cats.append("material_composicion")
    return cats or ["otros"]


def ml_questions_recommendation_for_category(cat: str) -> str:
    mapping = {
        "envios_costos_tiempos": "Agregar en la descripción una sección clara de envíos: zonas, transportes usados, límites de cálculo previo y tiempos aproximados cuando aplique.",
        "retiro_horarios_zona": "Agregar bloque de retiro: zona aproximada, que no es local/showroom si corresponde, horario y requisito de coordinación previa.",
        "medidas_peso_dimensiones": "Agregar medidas visibles y peso real del producto/pack. En productos voluminosos, aclarar si entra en auto o requiere flete.",
        "compatibilidad_mano": "Agregar compatibilidad: mano izquierda/derecha, diestro/zurdo o si sirve para ambas manos.",
        "stock_variantes_colores": "Revisar variantes y descripción: colores disponibles, reemplazos posibles y cuándo consultar disponibilidad.",
        "packs_cantidades": "Crear o enlazar packs frecuentes y aclarar cómo comprar varias unidades sin carrito si conviene comercialmente.",
        "material_composicion": "Agregar material/composición o nivel de certeza. Si el dato no se conoce, aclarar lo que sí se sabe para evitar consultas repetidas.",
        "otros": "Revisar manualmente: no hay patrón fuerte, pero puede aportar ejemplos para respuestas rápidas.",
    }
    return mapping.get(cat, mapping["otros"])


def ml_questions_analyze_locally(items: List[Dict[str, Any]]) -> Dict[str, Any]:
    by_cat: Dict[str, Dict[str, Any]] = {}
    by_item: Dict[str, Dict[str, Any]] = {}
    for q in items:
        item = q.get("item") or {}
        item_id = str(q.get("item_id") or item.get("id") or "")
        title = item.get("title") or item_id or "Sin publicación"
        cats = ml_questions_classify_for_description(q)
        for cat in cats:
            bucket = by_cat.setdefault(cat, {"category": cat, "count": 0, "examples": [], "recommendation": ml_questions_recommendation_for_category(cat)})
            bucket["count"] += 1
            if len(bucket["examples"]) < 5:
                bucket["examples"].append({"question_id": q.get("id"), "item_id": item_id, "item_title": title, "text": q.get("text")})
        ib = by_item.setdefault(item_id or title, {"item_id": item_id, "item_title": title, "count": 0, "categories": {}, "examples": []})
        ib["count"] += 1
        for cat in cats:
            ib["categories"][cat] = ib["categories"].get(cat, 0) + 1
        if len(ib["examples"]) < 4:
            ib["examples"].append({"question_id": q.get("id"), "text": q.get("text")})
    categories = sorted(by_cat.values(), key=lambda x: x["count"], reverse=True)
    items_ranked = sorted(by_item.values(), key=lambda x: x["count"], reverse=True)[:15]
    return {"categories": categories, "items_ranked": items_ranked}


def ml_questions_openai_analysis(items: List[Dict[str, Any]], local: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    if not OPENAI_API_KEY:
        return None
    compact = []
    for q in items[:80]:
        item = q.get("item") or {}
        ans = q.get("answer") or {}
        compact.append({
            "id": q.get("id"),
            "question": q.get("text"),
            "answer": ans.get("text") if isinstance(ans, dict) else ans,
            "item_id": q.get("item_id") or item.get("id"),
            "item_title": item.get("title"),
        })
    prompt = (
        "Analizá preguntas respondidas de Mercado Libre para un vendedor argentino. "
        "Detectá preguntas repetidas que se podrían evitar mejorando descripciones/publicaciones. "
        "Devolvé JSON con: resumen, top_recomendaciones[{prioridad,motivo,accion,ejemplos}], "
        "publicaciones_a_mejorar[{item_id,titulo,problema,accion}], respuestas_rapidas_sugeridas. "
        "No inventes datos; basate solo en las preguntas/respuestas."
    )
    try:
        r = requests.post(
            "https://api.openai.com/v1/chat/completions",
            headers={"Authorization": f"Bearer {OPENAI_API_KEY}", "Content-Type": "application/json"},
            json={
                "model": OPENAI_MODEL or "gpt-4.1-mini",
                "response_format": {"type": "json_object"},
                "messages": [
                    {"role": "system", "content": prompt},
                    {"role": "user", "content": json.dumps({"questions": compact, "local_detection": local}, ensure_ascii=False)},
                ],
                "temperature": 0.2,
            },
            timeout=60,
        )
        data = r.json()
        if r.status_code >= 300:
            return {"ok": False, "status_code": r.status_code, "error": data}
        content = (((data.get("choices") or [{}])[0].get("message") or {}).get("content") or "{}").strip()
        try:
            parsed = json.loads(content)
        except Exception:
            parsed = {"raw": content}
        return {"ok": True, "model": OPENAI_MODEL, "analysis": parsed}
    except Exception as e:
        return {"ok": False, "error": pc_exception_detail(e)}


