@router.post("/admin/ml/questions/notifications")
@router.post("/admin/ml/notifications")
async def admin_ml_questions_notification_endpoint(request: Request):
    """
    Endpoint público para notificaciones de Mercado Libre.
    No exige ADMIN_TOKEN porque ML no lo manda. Solo procesa topic/resource de questions.
    URL sugerida en ML Developers:
      https://planeta-casa-erp.onrender.com/admin/ml/notifications
    """
    try:
        payload = await request.json()
    except Exception:
        payload = {}

    topic = str(payload.get("topic") or payload.get("type") or "").lower()
    resource = str(payload.get("resource") or "")
    is_question = ("question" in topic) or ("/questions/" in resource)
    question_id = ml_questions_extract_id(payload)

    if not is_question or not question_id:
        return {
            "ok": True,
            "version": APP_VERSION,
            "ignored": True,
            "reason": "No es notificación de pregunta ML o no trae question_id",
            "payload_preview": payload,
        }

    notification_user_id = str(payload.get("user_id") or "").strip()
    identity = select_existing_tenant(
        _oauth_identity_rows("ml"),
        "ml",
        notification_user_id,
    )
    tenant_id = str((identity or {}).get("tenant_id") or "").strip()
    if not tenant_id:
        return {
            "ok": True,
            "version": APP_VERSION,
            "ignored": True,
            "reason": "La notificacion no pertenece a una cuenta ML registrada",
        }

    subscription = _tenant_subscription_access(tenant_id)
    if not subscription.get("allowed"):
        return {
            "ok": True,
            "version": APP_VERSION,
            "ignored": True,
            "reason": "subscription_inactive",
        }

    fetched: Dict[str, Any]
    fetch_error = None
    tenant_ctx = set_current_tenant_id(tenant_id)
    try:
        try:
            fetched = ml_questions_fetch_by_id(question_id)
        except Exception as e:
            fetch_error = pc_exception_detail(e)
            fetched = {
                "id": question_id,
                "status": "UNKNOWN",
                "text": "",
                "date_created": now_iso(),
                "raw_notification": payload,
                "fetch_error": fetch_error,
            }

        row = ml_questions_cache_row_from_question(fetched, source="ml_notification", is_mock=False)
        if not isinstance(row.get("raw_data"), dict):
            row["raw_data"] = {}
        row["raw_data"] = {**(row.get("raw_data") or {}), "notification": payload, "fetch_error": fetch_error}
        result = ml_questions_cache_upsert(row)
    finally:
        reset_current_tenant_id(tenant_ctx)

    return {
        "ok": bool(result.get("ok")),
        "version": APP_VERSION,
        "question_id": question_id,
        "fetched_ok": fetch_error is None,
        "fetch_error": fetch_error,
        "cache_result": result,
    }


