def knowledge_setup_sql() -> str:
    return f"""
create table if not exists public.{KNOWLEDGE_SKU_TABLE} (
  sku text primary key,
  retiro_permitido boolean not null default false,
  lugar_retiro_codigo text,
  flex boolean not null default false,
  full boolean not null default false,
  mercado_envios boolean not null default false,
  correo_encomienda boolean not null default false,
  costo_envio_correo text,
  costo_envio_mercado_envios text,
  stock_fuente text not null default 'ERP',
  mostrar_stock_exacto boolean not null default false,
  modo_respuesta text not null default 'pre_respuesta',
  notas_ia text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.{KNOWLEDGE_PICKUP_TABLE} (
  codigo text primary key,
  nombre_interno text,
  texto_publico text,
  horario text,
  es_local_calle boolean not null default false,
  aclaracion text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.{KNOWLEDGE_PROMPTS_TABLE} (
  position int primary key,
  prompt_text text not null,
  active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists idx_{KNOWLEDGE_SKU_TABLE}_modo
  on public.{KNOWLEDGE_SKU_TABLE}(modo_respuesta);
""".strip()


def kb_bool(value: Any) -> bool:
    txt = normalizar(value)
    if txt in ["1", "true", "si", "sí", "s", "yes", "y", "x", "ok", "verdadero"]:
        return True
    if txt in ["0", "false", "no", "n", "none", "null", "falso", ""]:
        return False
    return False


def kb_text(value: Any) -> Optional[str]:
    if value is None:
        return None
    txt = str(value).strip()
    return txt if txt else None


def kb_safe_table_select(table: str, select: str = "*") -> List[Dict[str, Any]]:
    try:
        return sb.table(table).select(select).execute().data or []
    except Exception:
        return []


def kb_classify_db_error(e: Exception, scope: str = "") -> Dict[str, Any]:
    detail = pc_exception_detail(e)
    low = normalizar(detail)
    code = "db_error"
    severity = "error"
    retryable = False
    action = "Revisar detalle del error y corregir el dato o la tabla."

    if "pgrst205" in low or "could not find the table" in low or "schema cache" in low:
        code = "missing_table"
        severity = "schema"
        action = "Crear la tabla faltante mediante migración SQL en AWS Postgres."
    elif "resource temporarily unavailable" in low or "errno 11" in low or "temporarily unavailable" in low:
        code = "resource_temporarily_unavailable"
        severity = "transient"
        retryable = True
        action = "Reintentar la fila. Suele ser un bloqueo o recurso temporalmente no disponible."
    elif "timeout" in low or "timed out" in low or "connection" in low:
        code = "connection_timeout"
        severity = "transient"
        retryable = True
        action = "Reintentar. Si se repite, bajar tamaño de lote o revisar AWS Postgres."
    elif "duplicate" in low or "violates unique" in low:
        code = "unique_violation"
        severity = "data"
        action = "Revisar duplicados o conflicto de clave única."
    elif "violates not-null" in low or "null value" in low:
        code = "not_null_violation"
        severity = "data"
        action = "Completar el campo obligatorio que llega vacío."

    return {
        "scope": scope,
        "code": code,
        "severity": severity,
        "retryable": retryable,
        "action": action,
        "error": detail,
    }


def kb_upsert_with_retry(table: str, row: Dict[str, Any], on_conflict: str, attempts: int = 3) -> None:
    last_exc = None
    for i in range(max(1, attempts)):
        try:
            sb.table(table).upsert(row, on_conflict=on_conflict).execute()
            return
        except Exception as e:
            last_exc = e
            info = kb_classify_db_error(e)
            if info.get("retryable") and i < attempts - 1:
                time.sleep(0.35 * (i + 1))
                continue
            raise e
    if last_exc:
        raise last_exc



def kb_get_pickup_locations() -> Dict[str, Dict[str, Any]]:
    rows = kb_safe_table_select(KNOWLEDGE_PICKUP_TABLE, "*")
    return {str(r.get("codigo") or "").strip().upper(): r for r in rows if str(r.get("codigo") or "").strip()}


def kb_get_rule_by_sku(sku: str) -> Optional[Dict[str, Any]]:
    sku = norm_sku(sku)
    if not sku:
        return None
    try:
        rows = sb.table(KNOWLEDGE_SKU_TABLE).select("*").eq("sku", sku).limit(1).execute().data or []
        return rows[0] if rows else None
    except Exception:
        return None


def kb_find_sku_for_ml_item(item_id: str, item: Optional[Dict[str, Any]] = None) -> Optional[str]:
    item_id = str(item_id or "").strip()
    item = item or {}
    candidates = [
        item.get("seller_sku"),
        item.get("seller_custom_field"),
        item.get("sku"),
    ]
    for c in candidates:
        c = norm_sku(c)
        if c:
            return c

    if item_id:
        try:
            rows = (
                sb.table("marketplace_listings")
                .select("sku,marketplace,external_product_id,external_full_id,external_variant_id")
                .eq("marketplace", "ML")
                .eq("external_product_id", item_id)
                .limit(1)
                .execute()
                .data
                or []
            )
            if rows and rows[0].get("sku"):
                return norm_sku(rows[0].get("sku"))
        except Exception:
            pass
        try:
            rows = (
                sb.table("marketplace_listings")
                .select("sku,marketplace,external_product_id,external_full_id,external_variant_id")
                .eq("marketplace", "ML")
                .eq("external_full_id", item_id)
                .limit(1)
                .execute()
                .data
                or []
            )
            if rows and rows[0].get("sku"):
                return norm_sku(rows[0].get("sku"))
        except Exception:
            pass

    return None



# ============================================================
# ML PREGUNTAS - BUSQUEDA CRUZADA DE PRODUCTOS
# ============================================================

KB_CROSS_PRODUCT_STOPWORDS = {
    "hola", "buen", "buenas", "buenos", "dias", "dia", "tardes", "noches",
    "tenes", "tienen", "hay", "venden", "vendes", "hacen", "haciendo",
    "fabrican", "traen", "conseguis", "me", "te", "se", "lo", "la",
    "los", "las", "un", "una", "unos", "unas", "para", "por", "de", "del",
    "al", "a", "en", "y", "o", "si", "sabes", "saber", "quiero",
    "queria", "busco", "necesito", "consulta", "consulto", "gracias",
    "stock", "disponible", "disponibles", "producto", "productos",
}

# Sinónimos mínimos y explícitos. Esto después se generaliza al SaaS como tabla configurable.
KB_CROSS_PRODUCT_SYNONYMS = {
    "funda_taco": {
        "triggers": ["funda", "fundas", "estuche", "estuches", "porta taco", "portataco", "porta tacos"],
        "anchors": ["funda", "fundas", "estuche", "estuches", "porta taco", "portataco", "porta tacos"],
        "context": ["taco", "tacos", "pool", "billar"],
        "display": "fundas para tacos",
    },
}


def kb_cross_product_tokens(text: Any) -> List[str]:
    txt = normalizar(text)
    raw = [t for t in re.split(r"[\s_-]+", txt) if len(t) >= 3]
    tokens = []
    for t in raw:
        if t in KB_CROSS_PRODUCT_STOPWORDS:
            continue
        if t not in tokens:
            tokens.append(t)
    return tokens[:12]


def kb_norm_phrase(value: Any) -> str:
    return normalizar(value).replace(" ", "_")


def kb_text_has_term(text: str, term: str) -> bool:
    txt = normalizar(text)
    t = normalizar(term)
    if not txt or not t:
        return False
    if " " in t:
        return t in txt
    return re.search(r"(^|\s)" + re.escape(t) + r"(\s|$)", txt) is not None


def kb_cross_product_intent(question_text: str, current_title: str = "") -> Dict[str, Any]:
    qn = normalizar(question_text)
    title_n = normalizar(current_title)

    for intent_name, cfg in KB_CROSS_PRODUCT_SYNONYMS.items():
        triggers = cfg.get("triggers") or []
        anchors = cfg.get("anchors") or []
        context = cfg.get("context") or []
        q_has_trigger = any(kb_text_has_term(qn, t) for t in triggers)
        title_has_anchor = any(kb_text_has_term(title_n, a) for a in anchors)
        if q_has_trigger and not title_has_anchor:
            terms = []
            for v in list(anchors) + list(context):
                for tok in kb_cross_product_tokens(v):
                    if tok not in terms:
                        terms.append(tok)
            for tok in kb_cross_product_tokens(question_text):
                if tok not in terms:
                    terms.append(tok)
            return {
                "triggered": True,
                "intent": intent_name,
                "terms": terms[:12],
                "anchors": anchors,
                "display": cfg.get("display") or "ese producto",
                "reason": "pregunta por producto distinto a la publicación actual",
            }

    # Fallback genérico: solo cuando hay verbo comercial + tokens que no son del título.
    title_tokens = set(kb_cross_product_tokens(current_title))
    terms = [t for t in kb_cross_product_tokens(question_text) if t not in title_tokens]
    verb_signal = any(v in qn for v in [
        "tenes", "tienen", "hay", "venden", "vendes", "hacen", "fabrican",
        "traen", "conseguis", "busco", "necesito"
    ])
    if verb_signal and terms:
        return {
            "triggered": True,
            "intent": "generic_product_search",
            "terms": terms[:8],
            "anchors": [],
            "display": " ".join(terms[:4]) or "ese producto",
            "reason": "búsqueda genérica de producto",
        }

    return {"triggered": False, "terms": terms, "anchors": [], "reason": "sin señal de producto cruzado"}


def kb_listing_external_item_id(row: Dict[str, Any]) -> str:
    return str(
        row.get("external_product_id")
        or row.get("external_full_id")
        or row.get("item_id")
        or ""
    ).strip()


def kb_ml_listing_search_text(row: Dict[str, Any], inv_by_sku: Dict[str, Dict[str, Any]]) -> str:
    sku = norm_sku(row.get("sku"))
    inv = inv_by_sku.get(sku) or {}
    raw = row.get("raw_data") if isinstance(row.get("raw_data"), dict) else {}
    parts = [
        row.get("sku"),
        row.get("title"),
        row.get("url"),
        row.get("permalink"),
        row.get("status"),
        raw.get("title"),
        raw.get("name"),
        raw.get("permalink"),
        inv.get("name"),
        inv.get("variant_name"),
        inv.get("category"),
        inv.get("description"),
    ]
    return normalizar(" ".join(str(x or "") for x in parts))


def kb_score_cross_product_listing(row: Dict[str, Any], terms: List[str], anchors: List[str], inv_by_sku: Dict[str, Dict[str, Any]]) -> int:
    haystack = kb_ml_listing_search_text(row, inv_by_sku)
    if not haystack:
        return 0

    # Si hay anchors explícitos, exigimos al menos uno. Evita que "taco" matchee tizas/tacos/etc.
    if anchors and not any(kb_text_has_term(haystack, a) for a in anchors):
        return 0

    score = 0
    for term in terms:
        tn = normalizar(term)
        if not tn:
            continue
        if kb_text_has_term(haystack, tn):
            score += 4 if term in anchors else 2
        elif tn.endswith("s") and kb_text_has_term(haystack, tn[:-1]):
            score += 2

    status = normalizar(row.get("status"))
    if status in ["active", "activa", "activo"]:
        score += 2

    if kb_listing_external_item_id(row).startswith("MLA"):
        score += 3

    if not kb_listing_external_item_id(row):
        score -= 5

    return score


def kb_ml_find_cross_product_for_question(question: Dict[str, Any], current_item_id: str = "", current_sku: str = "") -> Dict[str, Any]:
    q = question or {}
    current_item = q.get("item") if isinstance(q.get("item"), dict) else {}
    intent = kb_cross_product_intent(str(q.get("text") or ""), str(current_item.get("title") or ""))
    if not intent.get("triggered"):
        return {"triggered": False, "matched": False, "intent": intent}

    terms = intent.get("terms") or []
    anchors = intent.get("anchors") or []
    display = intent.get("display") or "ese producto"

    try:
        inv_rows = sb.table("inventory_items").select("*").limit(2000).execute().data or []
    except Exception:
        inv_rows = []

    inv_by_sku = {norm_sku(r.get("sku")): r for r in inv_rows if norm_sku(r.get("sku"))}

    try:
        listing_rows = (
            sb.table("marketplace_listings")
            .select("*")
            .eq("marketplace", "ML")
            .limit(2000)
            .execute()
            .data
            or []
        )
    except Exception as e:
        return {
            "triggered": True,
            "matched": False,
            "terms": terms,
            "anchors": anchors,
            "display": display,
            "error": pc_exception_detail(e),
            "body": f"Por el momento no tenemos {display}.",
        }

    current_item_id = str(current_item_id or "").strip()
    current_sku = norm_sku(current_sku)
    candidates = []

    for row in listing_rows:
        item_id = kb_listing_external_item_id(row)
        sku = norm_sku(row.get("sku"))
        if current_item_id and item_id == current_item_id:
            continue
        if current_sku and sku == current_sku:
            continue

        score = kb_score_cross_product_listing(row, terms, anchors, inv_by_sku)
        if score >= 5:
            candidates.append({"score": score, "row": row, "item_id": item_id, "sku": sku})

    candidates.sort(key=lambda x: x.get("score", 0), reverse=True)

    if not candidates:
        return {
            "triggered": True,
            "matched": False,
            "terms": terms,
            "anchors": anchors,
            "display": display,
            "body": f"Por el momento no tenemos {display}.",
            "candidates": [],
        }

    best = candidates[0]
    row = best["row"]
    item_id = best.get("item_id") or ""
    sku = best.get("sku") or norm_sku(row.get("sku"))
    inv = inv_by_sku.get(sku) or {}

    live_item = {}
    live_error = None
    if item_id.startswith("MLA"):
        try:
            live_item = ml_get_json(f"https://api.mercadolibre.com/items/{item_id}", timeout=30)
        except Exception as e:
            live_error = pc_exception_detail(e)
            live_item = {}

    permalink = live_item.get("permalink") or row.get("permalink") or row.get("url") or ""

    qty = live_item.get("available_quantity")
    if qty is None:
        qty = row.get("available_quantity")
    if qty is None:
        qty = row.get("stock")
    if qty is None:
        qty = inv.get("stock")

    try:
        qty_num = float(qty) if qty is not None else None
    except Exception:
        qty_num = None

    title = live_item.get("title") or row.get("title") or inv.get("name") or sku or "el producto"

    if qty_num is not None and qty_num > 0:
        body = f"Sí, hay en stock. Te paso el link: {permalink}" if permalink else "Sí, hay en stock."
    else:
        body = "No tenemos stock en este momento, pero lo podemos traer a pedido."

    return {
        "triggered": True,
        "matched": True,
        "terms": terms,
        "anchors": anchors,
        "display": display,
        "score": best.get("score"),
        "sku": sku,
        "item_id": item_id,
        "title": title,
        "permalink": permalink,
        "available_quantity": qty,
        "ml_status": live_item.get("status") or row.get("status"),
        "live_error": live_error,
        "body": body,
        "candidates_count": len(candidates),
        "candidate_sample": [
            {
                "score": c.get("score"),
                "sku": c.get("sku"),
                "item_id": c.get("item_id"),
                "title": (c.get("row") or {}).get("title"),
            }
            for c in candidates[:5]
        ],
    }


def kb_ml_cross_product_answer(cross_product: Dict[str, Any]) -> str:
    body = str((cross_product or {}).get("body") or "").strip()
    return body or "Por el momento no tenemos ese producto."


def kb_stock_for_sku(sku: str, item_id: Optional[str] = None, item: Optional[Dict[str, Any]] = None, stock_fuente: str = "ERP") -> Dict[str, Any]:
    fuente = normalizar(stock_fuente or "ERP").upper()
    item = item or {}
    item_id = str(item_id or item.get("id") or "").strip()

    ml_qty = item.get("available_quantity")
    if ml_qty is None and item_id and ("ML" in fuente or fuente == "MERCADO LIBRE"):
        try:
            ml_item = ml_get_json(f"https://api.mercadolibre.com/items/{item_id}", timeout=25)
            ml_qty = ml_item.get("available_quantity")
            item.update({
                "available_quantity": ml_qty,
                "shipping": ml_item.get("shipping"),
                "logistic_type": ((ml_item.get("shipping") or {}).get("logistic_type") if isinstance(ml_item.get("shipping"), dict) else None),
                "mode": ((ml_item.get("shipping") or {}).get("mode") if isinstance(ml_item.get("shipping"), dict) else None),
            })
        except Exception:
            pass

    erp_item = get_item_by_sku(sku) if sku else None
    erp_qty = erp_item.get("stock") if erp_item else None

    if "ML" in fuente or fuente == "MERCADO LIBRE":
        qty = ml_qty if ml_qty is not None else erp_qty
        used = "ML" if ml_qty is not None else "ERP"
    else:
        qty = erp_qty if erp_qty is not None else ml_qty
        used = "ERP" if erp_qty is not None else "ML"

    return {
        "quantity": qty,
        "source_used": used,
        "erp_stock": erp_qty,
        "ml_available_quantity": ml_qty,
    }


def kb_rule_rows_for_download() -> List[Dict[str, Any]]:
    rules = {str(r.get("sku") or "").strip(): r for r in kb_safe_table_select(KNOWLEDGE_SKU_TABLE, "*")}
    items = kb_safe_table_select("inventory_items", "sku,name,stock,active,item_type")
    rows = []

    skus = []
    for r in rules.values():
        if r.get("sku"):
            skus.append(str(r.get("sku")))
    for it in items:
        if it.get("sku"):
            skus.append(str(it.get("sku")))
    skus = sorted(set(skus))

    if not skus:
        # Plantilla mínima inicial.
        skus = ["PCEXTCARBIMP2", "SMMR6_BLA"]

    for sku in skus:
        r = rules.get(sku) or {}
        sample_sm = (sku == "SMMR6_BLA")
        rows.append({
            "SKU": sku,
            "Retiro permitido": "Si" if r.get("retiro_permitido", True if sample_sm else "") else "No",
            "Código lugar retiro": r.get("lugar_retiro_codigo") or ("SM" if sample_sm else "PC"),
            "Flex": "Si" if r.get("flex") else ("No" if sample_sm else ""),
            "Full": "Si" if r.get("full") else "No",
            "Mercado Envíos": "Si" if r.get("mercado_envios") else ("No" if sample_sm else ""),
            "Correo / Encomienda propia": "Si" if r.get("correo_encomienda") else ("Si" if sample_sm else ""),
            "Costo envío Correo": r.get("costo_envio_correo") or ("Calcular sobre etiqueta" if sample_sm else ""),
            "Costo envío Mercado Envíos": r.get("costo_envio_mercado_envios") or ("Lo calcula Mercado Libre" if not sample_sm else "No aplica"),
            "Stock fuente": r.get("stock_fuente") or "ML",
            "Mostrar stock exacto": "Si" if r.get("mostrar_stock_exacto", True) else "No",
            "Modo respuesta": r.get("modo_respuesta") or "pre_respuesta",
            "Notas para IA": r.get("notas_ia") or ("No prometer fecha exacta; depende de Correo Argentino." if sample_sm else ""),
        })
    return rows


