def kb_prompt_rows_for_download() -> List[str]:
    rows = kb_safe_table_select(KNOWLEDGE_PROMPTS_TABLE, "position,prompt_text,active")
    out = []
    for r in sorted(rows, key=lambda x: int(x.get("position") or 0)):
        if r.get("active") is False:
            continue
        txt = str(r.get("prompt_text") or "").strip()
        if txt:
            out.append(txt)
    if not out:
        out = [
            "respondé amable pero corto",
            "si no te preguntan específicamente por algo no lo propongas",
            "no inventes costos, fechas ni disponibilidad",
        ]
    return out


def kb_global_prompt_text() -> str:
    return "\n".join(f"- {x}" for x in kb_prompt_rows_for_download() if str(x).strip())


def kb_workbook_bytes() -> bytes:
    try:
        from openpyxl import Workbook
        from openpyxl.styles import Font, PatternFill, Alignment
        from openpyxl.utils import get_column_letter
    except Exception as e:
        raise HTTPException(status_code=500, detail=f"Falta dependencia openpyxl para generar Excel: {str(e)}")

    wb = Workbook()
    ws = wb.active
    ws.title = "Reglas SKU"
    ws.append(KNOWLEDGE_SKU_HEADERS)
    for row in kb_rule_rows_for_download():
        ws.append([row.get(h, "") for h in KNOWLEDGE_SKU_HEADERS])

    ws2 = wb.create_sheet("Lugares retiro")
    ws2.append(KNOWLEDGE_PICKUP_HEADERS)
    for row in kb_pickup_rows_for_download():
        ws2.append([row.get(h, "") for h in KNOWLEDGE_PICKUP_HEADERS])

    ws_prompts = wb.create_sheet("Prompts IA")
    for txt in kb_prompt_rows_for_download():
        ws_prompts.append([txt])

    ws3 = wb.create_sheet("Ayuda")
    ws3.append(["Campo", "Uso"])
    ayuda = [
        ("Modo respuesta", "manual / pre_respuesta / auto_aprobada. En Planeta Casa por ahora usar pre_respuesta."),
        ("Mercado Envíos", "Si aplica, responder que Mercado Libre calcula costo y fecha en la publicación."),
        ("Correo / Encomienda propia", "Si aplica, responder que el costo se confirma al confeccionar etiqueta o coordinar despacho."),
        ("Stock fuente", "ERP o ML. Para preguntas de ML normalmente conviene ML."),
        ("Mostrar stock exacto", "Si/No. Si No, la IA dice que hay disponibilidad sin decir cantidad."),
        ("Notas para IA", "Reglas extra del SKU. La IA solo redacta el cuerpo; saludo y firma los agrega la app."),
    ]
    for r in ayuda:
        ws3.append(list(r))

    for sheet in wb.worksheets:
        for cell in sheet[1]:
            cell.font = Font(bold=True)
            cell.fill = PatternFill("solid", fgColor="DCC58F")
            cell.alignment = Alignment(horizontal="center")
        sheet.freeze_panes = "A2"
        for col in sheet.columns:
            max_len = max(len(str(c.value or "")) for c in col)
            sheet.column_dimensions[get_column_letter(col[0].column)].width = min(max(12, max_len + 2), 42)

    bio = io.BytesIO()
    wb.save(bio)
    return bio.getvalue()


def kb_sheet_rows(ws) -> List[Dict[str, Any]]:
    headers = [str(c.value or "").strip() for c in next(ws.iter_rows(min_row=1, max_row=1))]
    rows = []
    for row in ws.iter_rows(min_row=2):
        vals = [c.value for c in row]
        if not any(v is not None and str(v).strip() for v in vals):
            continue
        rows.append({headers[i]: vals[i] if i < len(vals) else None for i in range(len(headers))})
    return rows


def kb_upload_xlsx(content: bytes) -> Dict[str, Any]:
    try:
        from openpyxl import load_workbook
    except Exception as e:
        raise HTTPException(status_code=500, detail=f"Falta dependencia openpyxl para leer Excel: {str(e)}")

    try:
        wb = load_workbook(io.BytesIO(content), data_only=True)
    except Exception as e:
        raise HTTPException(status_code=400, detail=f"No pude leer el Excel: {str(e)}")

    if "Reglas SKU" not in wb.sheetnames or "Lugares retiro" not in wb.sheetnames:
        raise HTTPException(status_code=400, detail="El Excel debe tener hojas 'Reglas SKU' y 'Lugares retiro'")

    rules_rows = kb_sheet_rows(wb["Reglas SKU"])
    pickup_rows = kb_sheet_rows(wb["Lugares retiro"])
    prompt_rows = []
    if "Prompts IA" in wb.sheetnames:
        ws_prompts = wb["Prompts IA"]
        for row in ws_prompts.iter_rows():
            val = row[0].value if row else None
            txt = kb_text(val)
            if txt and normalizar(txt) not in ["prompt", "prompts", "instruccion", "instrucción"]:
                prompt_rows.append(txt)
    now = now_iso()

    up_rules = 0
    up_pickups = 0
    up_prompts = 0
    errors = []

    for r in rules_rows:
        sku = norm_sku(r.get("SKU"))
        if not sku:
            continue
        row = {
            "sku": sku,
            "retiro_permitido": kb_bool(r.get("Retiro permitido")),
            "lugar_retiro_codigo": (kb_text(r.get("Código lugar retiro")) or "").upper() or None,
            "flex": kb_bool(r.get("Flex")),
            "full": kb_bool(r.get("Full")),
            "mercado_envios": kb_bool(r.get("Mercado Envíos")),
            "correo_encomienda": kb_bool(r.get("Correo / Encomienda propia")),
            "costo_envio_correo": kb_text(r.get("Costo envío Correo")),
            "costo_envio_mercado_envios": kb_text(r.get("Costo envío Mercado Envíos")),
            "stock_fuente": kb_text(r.get("Stock fuente")) or "ERP",
            "mostrar_stock_exacto": kb_bool(r.get("Mostrar stock exacto")),
            "modo_respuesta": kb_text(r.get("Modo respuesta")) or "pre_respuesta",
            "notas_ia": kb_text(r.get("Notas para IA")),
            "updated_at": now,
        }
        try:
            kb_upsert_with_retry(KNOWLEDGE_SKU_TABLE, row, on_conflict="sku")
            up_rules += 1
        except Exception as e:
            err = kb_classify_db_error(e, scope="sku_rules")
            err.update({"sku": sku})
            errors.append(err)

    for r in pickup_rows:
        codigo = (kb_text(r.get("Código")) or "").upper()
        if not codigo:
            continue
        row = {
            "codigo": codigo,
            "nombre_interno": kb_text(r.get("Nombre interno")),
            "texto_publico": kb_text(r.get("Texto público")),
            "horario": kb_text(r.get("Horario")),
            "es_local_calle": kb_bool(r.get("Es local a la calle")),
            "aclaracion": kb_text(r.get("Aclaración")),
            "updated_at": now,
        }
        try:
            kb_upsert_with_retry(KNOWLEDGE_PICKUP_TABLE, row, on_conflict="codigo")
            up_pickups += 1
        except Exception as e:
            err = kb_classify_db_error(e, scope="pickup_locations")
            err.update({"codigo": codigo})
            errors.append(err)

    if prompt_rows:
        try:
            # Reemplazo simple: desactiva prompts viejos y sube los vigentes en orden.
            existing = kb_safe_table_select(KNOWLEDGE_PROMPTS_TABLE, "position")
            for ex in existing:
                try:
                    sb.table(KNOWLEDGE_PROMPTS_TABLE).update({"active": False, "updated_at": now}).eq("position", int(ex.get("position") or 0)).execute()
                except Exception:
                    pass
            for pos, txt in enumerate(prompt_rows, start=1):
                kb_upsert_with_retry(KNOWLEDGE_PROMPTS_TABLE, {"position": pos, "prompt_text": txt, "active": True, "updated_at": now}, on_conflict="position")
                up_prompts += 1
        except Exception as e:
            err = kb_classify_db_error(e, scope="prompts_ia")
            err.update({"prompts_ia": "Prompts IA"})
            errors.append(err)

    schema_errors = [e for e in errors if e.get("severity") == "schema"]
    transient_errors = [e for e in errors if e.get("severity") == "transient"]
    data_errors = [e for e in errors if e.get("severity") == "data"]
    partial_ok = bool(errors) and (up_rules > 0 or up_pickups > 0 or up_prompts > 0)
    return {
        "ok": len(errors) == 0,
        "partial_ok": partial_ok,
        "rules_upserted": up_rules,
        "pickup_locations_upserted": up_pickups,
        "prompts_upserted": up_prompts,
        "errors": errors[:50],
        "error_summary": {
            "total": len(errors),
            "schema": len(schema_errors),
            "transient": len(transient_errors),
            "data": len(data_errors),
            "other": len(errors) - len(schema_errors) - len(transient_errors) - len(data_errors),
        },
        "migration_required": [e for e in schema_errors[:10]],
        "retryable_errors": [e for e in transient_errors[:10]],
        "data_errors": [e for e in data_errors[:10]],
        "setup_sql": None,
        "setup_sql_endpoint": "/admin/knowledge/setup_sql",
    }


def kb_heuristic_body(question: Dict[str, Any], sku: str, rule: Optional[Dict[str, Any]], pickup: Optional[Dict[str, Any]], stock: Dict[str, Any]) -> str:
    text = normalizar(question.get("text") or "")
    rule = rule or {}
    qty = stock.get("quantity")
    show_qty = bool(rule.get("mostrar_stock_exacto"))
    has_stock = qty is None or float(qty or 0) > 0

    parts = []
    if "stock" in text or "disponible" in text or "tenes" in text or "tenés" in text or "hay" in text:
        if has_stock:
            if show_qty and qty is not None:
                parts.append(f"Sí, hay {int(float(qty))} unidades disponibles.")
            else:
                parts.append("Sí, hay disponibilidad.")
        else:
            parts.append("Por el momento no figura disponibilidad para este producto.")

    asks_pickup = any(w in text for w in ["retirar", "retiro", "buscar", "pasar", "personalmente"])
    if asks_pickup:
        if rule.get("retiro_permitido") and pickup:
            lugar = pickup.get("texto_publico") or pickup.get("nombre_interno") or rule.get("lugar_retiro_codigo")
            horario = pickup.get("horario")
            aclaracion = pickup.get("aclaracion")
            phrase = f"El retiro se realiza por {lugar}"
            if horario:
                phrase += f" de {horario[0].lower() + horario[1:] if horario else ''}"
            if aclaracion:
                phrase += f", {aclaracion[0].lower() + aclaracion[1:] if aclaracion else ''}"
            phrase += "."
            parts.append(phrase)
        elif rule.get("retiro_permitido") is False:
            parts.append("Este producto no tiene retiro personal disponible.")

    asks_shipping = any(w in text for w in ["envio", "envíos", "envio", "mandas", "mandás", "correo", "cp", "codigo postal", "código postal", "llega", "llegaria", "cuanto sale", "costo"])
    if asks_shipping:
        if rule.get("mercado_envios"):
            costo = rule.get("costo_envio_mercado_envios") or "Mercado Libre calcula el costo y la fecha estimada en esta misma publicación."
            parts.append(str(costo).rstrip(".") + ".")
        elif rule.get("correo_encomienda"):
            costo = rule.get("costo_envio_correo") or "El costo del envío se confirma al confeccionar la etiqueta o coordinar el despacho."
            if "calcular" in normalizar(costo) or "etiqueta" in normalizar(costo):
                parts.append("El costo del envío lo podemos confirmar al confeccionar la etiqueta. No podemos dar una fecha precisa de llegada porque depende de Correo Argentino y de la logística del destino.")
            else:
                parts.append(str(costo).rstrip(".") + ".")

    if not parts:
        notes = rule.get("notas_ia")
        if notes:
            parts.append(str(notes).strip())
        else:
            parts.append("Te confirmo la información y podemos coordinarlo sin problema.")

    # Cuerpo solamente: sin saludo ni firma.
    out = " ".join(parts)
    out = re.sub(r"\s+", " ", out).strip()
    return out[:1800]


def ai_learning_event_insert(row: Dict[str, Any]) -> Dict[str, Any]:
    """Guarda una enseñanza/corrección en ai_learning_events si la tabla existe."""
    if not sb:
        return {"ok": False, "error": "DATABASE_URL/AWS Postgres no configurado"}
    try:
        if row.get("question_text") is None and row.get("customer_message") is not None:
            row["question_text"] = row.get("customer_message")
        clean = {k: v for k, v in row.items() if v is not None}
        data = sb.table("ai_learning_events").insert(clean).execute().data or []
        return {"ok": True, "item": data[0] if data else None}
    except Exception as e:
        return {"ok": False, "error": pc_exception_detail(e)}


def kb_extract_learning_hint(question: Dict[str, Any], current_answer: str, correction_text: str) -> str:
    qtext = str((question or {}).get("text") or "").strip()
    item = (question or {}).get("item") if isinstance((question or {}).get("item"), dict) else {}
    title = str((item or {}).get("title") or "").strip()
    parts = []
    if title:
        parts.append(f"Publicación: {title}")
    if qtext:
        parts.append(f"Pregunta: {qtext}")
    if current_answer:
        parts.append(f"Respuesta previa: {current_answer}")
    parts.append(f"Corrección de Gonzalo: {correction_text}")
    return "\n".join(parts)[:4000]


def kb_openai_body(question: Dict[str, Any], sku: str, rule: Optional[Dict[str, Any]], pickup: Optional[Dict[str, Any]], stock: Dict[str, Any], local_body: str, correction_text: Optional[str] = None, current_answer: Optional[str] = None) -> Dict[str, Any]:
    if not OPENAI_API_KEY:
        return {"ok": False, "skipped": True, "reason": "OPENAI_API_KEY no configurado"}
    try:
        payload = {
            "sku": sku,
            "question_text": question.get("text"),
            "item": question.get("item"),
            "rule": rule,
            "pickup_location": pickup,
            "stock": stock,
            "local_draft": local_body,
            "current_answer": current_answer or "",
            "gonzalo_correction": correction_text or "",
        }
        global_prompts = kb_global_prompt_text()
        system = (
            "Sos un asistente de venta de Planeta Casa. Redactá SOLO el cuerpo de la respuesta para una pregunta de Mercado Libre. "
            "No agregues saludo inicial ni firma, porque la app los agrega después. "
            "Usá únicamente los datos del JSON. No inventes costos, fechas ni disponibilidad. "
            "Tono amable, claro, argentino, breve. "
            "Primero entendé la intención y el concepto; recién después uses producto/stock si corresponde. "
            "Si hay una corrección de Gonzalo, obedecela por encima del borrador anterior y usala para regenerar mejor. "
            + ("Instrucciones generales del vendedor:\n" + global_prompts + "\n" if global_prompts else "") +
            "Devolvé JSON con keys: body, confidence, needs_human, intent, decision, reasons, lesson_candidate."
        )
        r = requests.post(
            "https://api.openai.com/v1/chat/completions",
            headers={"Authorization": f"Bearer {OPENAI_API_KEY}", "Content-Type": "application/json"},
            json={
                "model": OPENAI_MODEL or "gpt-4.1-mini",
                "response_format": {"type": "json_object"},
                "messages": [
                    {"role": "system", "content": system},
                    {"role": "user", "content": json.dumps(payload, ensure_ascii=False)},
                ],
                "temperature": 0.2,
            },
            timeout=45,
        )
        data = r.json()
        if r.status_code >= 300:
            return {"ok": False, "status_code": r.status_code, "error": data}
        content = (((data.get("choices") or [{}])[0].get("message") or {}).get("content") or "{}").strip()
        parsed = json.loads(content)
        body = str(parsed.get("body") or "").strip()
        return {"ok": bool(body), "analysis": parsed, "body": body[:1800]}
    except Exception as e:
        return {"ok": False, "error": pc_exception_detail(e)}


def kb_build_preanswer(question: Dict[str, Any], use_ai: bool = True, correction_text: Optional[str] = None, current_answer: Optional[str] = None, attempt_number: Optional[int] = 1) -> Dict[str, Any]:
    q = ml_questions_normalize_question(question, include_item=True)
    item = q.get("item") or {}
    item_id = q.get("item_id") or item.get("id")
    sku = kb_find_sku_for_ml_item(str(item_id or ""), item=item)

    if not sku:
        return {
            "ok": False,
            "version": APP_VERSION,
            "reason": "No pude mapear la pregunta a un SKU",
            "question": q,
            "body": "",
            "needs_human": True,
        }

    rule = kb_get_rule_by_sku(sku)
    pickups = kb_get_pickup_locations()
    pickup = None
    if rule and rule.get("lugar_retiro_codigo"):
        pickup = pickups.get(str(rule.get("lugar_retiro_codigo")).upper())

    stock = kb_stock_for_sku(sku, item_id=str(item_id or ""), item=item, stock_fuente=(rule or {}).get("stock_fuente") or "ERP")

    # Antes de pedirle redacción a la IA, resolvemos búsquedas cruzadas de catálogo.
    # Ejemplo: pregunta en una publicación de tiza "¿tenés fundas para tacos?"
    # No debe responder desde la tiza; debe buscar funda/estuche/porta taco en ML.
    cross_product = kb_ml_find_cross_product_for_question(q, current_item_id=str(item_id or ""), current_sku=sku)
    if cross_product.get("triggered"):
        body = kb_ml_cross_product_answer(cross_product)
        mode = (rule or {}).get("modo_respuesta") or "pre_respuesta"
        needs_human = normalizar(mode) in ["manual", "humano", "human", "respuesta humana"]
        return {
            "ok": True,
            "version": APP_VERSION,
            "sku": sku,
            "item_id": item_id,
            "mode": mode,
            "needs_human": needs_human,
            "rule_found": bool(rule),
            "pickup_found": bool(pickup),
            "stock": stock,
            "rule": rule,
            "pickup_location": pickup,
            "body": body,
            "local_body": body,
            "ai": None,
            "cross_product": cross_product,
            "correction_applied": bool(correction_text),
            "attempt_number": attempt_number or 1,
            "question": q,
            "note": "Respuesta resuelta por búsqueda cruzada de catálogo. El body no incluye saludo ni firma.",
        }

    local_body = kb_heuristic_body(q, sku, rule, pickup, stock)

    ai = kb_openai_body(q, sku, rule, pickup, stock, local_body, correction_text=correction_text, current_answer=current_answer) if use_ai else None
    body = (ai or {}).get("body") if ai and ai.get("ok") else local_body
    mode = (rule or {}).get("modo_respuesta") or "pre_respuesta"
    needs_human = normalizar(mode) in ["manual", "humano", "human", "respuesta humana"]

    return {
        "ok": True,
        "version": APP_VERSION,
        "sku": sku,
        "item_id": item_id,
        "mode": mode,
        "needs_human": needs_human,
        "rule_found": bool(rule),
        "pickup_found": bool(pickup),
        "stock": stock,
        "rule": rule,
        "pickup_location": pickup,
        "body": body,
        "local_body": local_body,
        "ai": ai,
        "correction_applied": bool(correction_text),
        "attempt_number": attempt_number or 1,
        "question": q,
        "note": "El body no incluye saludo ni firma. La app los agrega al enviar.",
    }


